window.KNOWLEDGEWALK_SEARCH = [{"id": "venice-winged-lion", "title": "\ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\uc5d0\uac8c\ub3c4 \ub0a0\uac1c\uac00 \uc788\ub2e4", "summary": "\uad11\uc7a5\uc5d0\ub3c4, \uac74\ubb3c \ubcbd\uc5d0\ub3c4, \uae30\ub150\ud488 \uac00\uac8c\uc5d0\ub3c4. \ubca0\ub124\uce58\uc544\uc758 \uc0ac\uc790\ub294 \uc65c \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uacbc\uc744\uae4c\uc694?", "category": "cities", "category_title": "Cities", "subcategory": "Europe", "url": "stories/venice-winged-lion/index.html", "image": "media/venice-winged-lion.jpg", "alt": "\ud3bc\uce5c \ucc45\uc5d0 \uc55e\ubc1c\uc744 \uc5b9\uc740 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\uc758 \uc218\ucc44\ud654\ud48d \uc0bd\ud654", "text": "\ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\uc5d0\uac8c\ub3c4 \ub0a0\uac1c\uac00 \uc788\ub2e4 \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uae34 \uc0ac\uc790\uac00 \ub3c4\uc2dc\uc758 \uc5bc\uad74\uc774 \ub41c \uc0ac\uc5f0 \uad11\uc7a5\uc5d0\ub3c4, \uac74\ubb3c \ubcbd\uc5d0\ub3c4, \uae30\ub150\ud488 \uac00\uac8c\uc5d0\ub3c4. \ubca0\ub124\uce58\uc544\uc758 \uc0ac\uc790\ub294 \uc65c \ub0a0\uac1c\uc640 \ucc45\uc744 \ucc59\uacbc\uc744\uae4c\uc694? Europe \ub3c4\uc2dc \ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \uc0ac\uc790\ub97c \ub9cc\ub0a0 \uc900\ube44\ub97c \uc870\uae08 \ud574\uc57c \ud55c\ub2e4. \ub3d9\ubb3c\uc6d0\uc774 \uc544\ub2c8\ub77c \uad11\uc7a5\uacfc \uac74\ubb3c \ubcbd\uc5d0\uc11c \ub9d0\uc774\ub2e4. \uae30\ub150\ud488 \uac00\uac8c\uae4c\uc9c0 \ub4e4\uc5b4\uac00\uba74 \uc0ac\uc790\ub97c \ud53c\ud558\uae30\uac00 \ub354 \uc5b4\ub824\uc6cc\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ub3c4\uc2dc\uc758 \uc0ac\uc790\ub294 \uc900\ube44\ubb3c\uc774 \ub9ce\ub2e4. \ub4f1\uc5d0 \ub0a0\uac1c\ub97c \ub2ec\uc558\uace0, \uc55e\ubc1c\uc5d0\ub294 \ucc45\uae4c\uc9c0 \ucc59\uacbc\ub2e4. \uac08\uae30\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uc5d0 \ub74c \ud150\ub370, \uad73\uc774 \uc774 \ub450 \uac00\uc9c0\ub97c \ub354\ud588\ub2e4. \uc65c \ud558\ud544 \ub0a0\uac1c\uc640 \ucc45\uc77c\uae4c? \uc0ac\uc5f0\uc758 \uc8fc\uc778\uacf5\uc740 \uc131 \ub9c8\ub974\ucf54\ub2e4. \uadf8\ub9ac\uc2a4\ub3c4\uad50\uc5d0\uc11c \ub9c8\ub974\ucf54\ub294 \ubcf5\uc74c\uc11c \uc800\uc790\ub85c \uc804\ud574\uc9c0\ub294 \uc778\ubb3c\uc774\uba70, \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\ub294 \uadf8\ub97c \ub098\ud0c0\ub0b4\ub294 \uc0c1\uc9d5\uc774\ub2e4. \uc61b \uc885\uad50 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uc0ac\ub78c\uc758 \uc774\ub984\uc744 \ud06c\uac8c \uc368 \ubd99\uc774\ub294 \ub300\uc2e0, \ud2b9\uc815\ud55c \ub3d9\ubb3c\uc774\ub098 \ubb3c\uac74\uc73c\ub85c \ub204\uad6c\uc778\uc9c0 \uc54c\ub824\uc8fc\uace4 \ud588\ub2e4. \ub9c8\ub974\ucf54\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc0ac\uc790\uac00 \uadf8\ub7f0 \uc5ed\ud560\uc744 \ud588\ub2e4. \ub0a0\uac1c\ub294 \uc774 \uc0ac\uc790\uac00 \ucd08\uc6d0\uc5d0\uc11c \uc0ac\ub0e5\ud558\ub294 \ubcf4\ud1b5 \uc0ac\uc790\uac00 \uc544\ub2c8\ub77c, \uc885\uad50\uc801 \uc0c1\uc9d5\uc774\ub77c\ub294 \uac83\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uc870\uae08 \uba40\uac8c \ub290\uaef4\uc9c4\ub2e4\uba74 \uc774\ub984\ud45c\ub77c\uace0 \uc0dd\uac01\ud574\ub3c4 \uc88b\ub2e4. \uadf8\ub9bc \uc18d\uc5d0 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\uac00 \ub4f1\uc7a5\ud558\uba74, \uadf8\ub9ac\uc2a4\ub3c4\uad50\uc758 \uc0c1\uc9d5\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc740 \ub9c8\ub974\ucf54\ub97c \ub5a0\uc62c\ub9b4 \uc218 \uc788\uc5c8\ub2e4. \ubb3c\ub860 \ubaa8\ub4e0 \uc2dc\ub300\uc758 \ubaa8\ub4e0 \uc0ac\uc790\uac00 \uac19\uc740 \ub73b\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubca0\ub124\uce58\uc544\uc758 \uc774 \uc0ac\uc790\ub294 \uadf8 \uc804\ud1b5 \uc548\uc5d0 \uc788\ub2e4. \ubca0\ub124\uce58\uc544\ub294 \uc131 \ub9c8\ub974\ucf54\ub97c \ub3c4\uc2dc\uc758 \uc218\ud638\uc131\uc778\uc73c\ub85c \ubaa8\uc168\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \uad11\uc7a5\uacfc \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \u2018\ub9c8\ub974\ucf54\u2019\ub3c4 \uac19\uc740 \uc774\ub984\uc774\ub2e4. \uadf8\ub7ec\ub2c8 \uadf8\uc758 \uc0c1\uc9d5\uc778 \uc0ac\uc790\uac00 \ub3c4\uc2dc\uc758 \uc5bc\uad74\uc774 \ub41c \ub370\uc5d0\ub294 \ub098\ub984\uc758 \uc774\uc720\uac00 \uc788\uc5c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc131\uc778\uc744 \uac00\ub9ac\ud0a4\ub358 \uadf8\ub9bc\uc774, \ubca0\ub124\uce58\uc544\uc5d0\uc11c\ub294 \ub3c4\uc2dc\uc640 \uc61b \uacf5\ud654\uad6d\uc744 \uac00\ub9ac\ud0a4\ub294 \ud45c\uc9c0\uac00 \ub41c \uac83\uc774\ub2e4. \uc131 \ub9c8\ub974\ucf54\ub97c \ub530\ub77c\uc628 \uc0ac\uc790\uac00 \ub3c4\uc2dc \uc804\uccb4\uc758 \uac04\ud310\uae4c\uc9c0 \ub9e1\uac8c \ub41c \uc148\uc774\ub2e4. \ub0a0\uac1c\ubcf4\ub2e4 \ucc45\uc774 \ub354 \uad81\uae08\ud560 \uc218\ub3c4 \uc788\ub2e4. \uc0ac\uc790\ub294 \ucc45\uc744 \uc77d\ub294 \uc911\uc77c\uae4c, \uc544\ub2c8\uba74 \uc911\uc694\ud55c \ub0b4\uc6a9\uc744 \uc6b0\ub9ac\uc5d0\uac8c \ubcf4\uc5ec\uc8fc\ub294 \uc911\uc77c\uae4c? \ud3bc\uccd0\uc9c4 \ucc45\uc5d0\ub294 \ub9c8\ub974\ucf54\uc5d0\uac8c \ud3c9\ud654\ub97c \uc804\ud558\ub294 \ub73b\uc758 \ub77c\ud2f4\uc5b4 \ubb38\uad6c\uac00 \uc801\ud78c \uc608\uac00 \uc788\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \uacf5\uc2dd \uc124\uba85\uc5d0\uc11c\ub3c4 \uc774 \ubb38\uad6c\uc640 \ub0a0\uac1c \ub2ec\ub9b0 \uc0ac\uc790\ub97c \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \ub2e8\uc21c\ud788 \ubc15\uc2dd\ud55c \uc0ac\uc790\ub97c \ub9cc\ub4e4\ub824\uace0 \ucc45\uc744 \ubcf4\ud0e0 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc0ac\uc790\uc640 \ucc45\uc774 \ud568\uaed8 \uc788\uc5b4\uc57c \ub204\uad6c\uc758 \uc0c1\uc9d5\uc778\uc9c0 \ub354 \ubd84\uba85\ud574\uc9c4\ub2e4. \ucc45\uae4c\uc9c0 \uacc1\ub4e4\uc774\uba74 \uc0ac\uc790\uc758 \ubaa8\uc2b5\uc740 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \ud798\uc13c \ub3d9\ubb3c\uc5d0\uac8c \uc870\uc6a9\ud788 \uc77d\uc744\uac70\ub9ac\ub97c \uac74\ub128 \ub4ef \ubcf4\uc774\uc9c0\ub9cc, \uc0ac\uc2e4\uc740 \uc131\uc778\uc744 \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5ec\ub7ec \ud45c\uc2dc\uac00 \ud568\uaed8 \ub193\uc778 \uac83\uc774\ub2e4. \uc61b \uadf8\ub9bc\uacfc \uc870\uac01\uc5d0\uc11c\ub294 \uc774\ub7f0 \ubb3c\uac74 \ud558\ub098\uac00 \ub4f1\uc7a5\uc778\ubb3c\uc758 \uc774\ub984\uc744 \uc54c\ub824\uc8fc\uae30\ub3c4 \ud588\ub2e4. \ucc45\uc5d0 \uae00\uc528\uac00 \uc788\ub2e4\uba74 \ubb34\uc5c7\uc774 \uc801\ud614\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ub2e4\ub9cc \uae00\uc790\uac00 \ub0a1\uc544 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uac70\ub098, \ub192\uc774 \uc788\uc5b4 \uc77d\uae30 \uc5b4\ub824\uc6b8 \uc218\ub3c4 \uc788\ub2e4. \uadf8\ub7f4 \ub54c\ub294 \uac00\uae4c\uc774 \ub2e4\uac00\uac00\ub824 \uc560\uc4f0\uae30\ubcf4\ub2e4 \ud604\uc7a5\uc758 \uc548\ub0b4\ub098 \uc18c\uc7a5 \uae30\uad00\uc758 \uc124\uba85\uc744 \ucc3e\uc544\ubcf4\uba74 \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac10\uc0c1\uc774 \ubcf5\uc7a1\ud574\uc9c8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc45\uc774 \uc788\ub294\uc9c0, \ub0a0\uac1c\ub294 \uc5b4\ub5a4 \ubaa8\uc591\uc778\uc9c0, \ud45c\uc815\uc740 \uc5b4\ub5a4\uc9c0\ub9cc \ubcf4\uc544\ub3c4 \uc0ac\uc790\ub9c8\ub2e4 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \ubc1c\uacac\ud558\uac8c \ub41c\ub2e4. \uc815\ub2f5\uc744 \ub9de\ud788\ub294 \ub300\uc2e0 \ucc28\uc774\ub97c \ucc3e\ub294 \uad6c\uacbd\uc774\ub2e4. \uc0b0\ub9c8\ub974\ucf54 \ub300\uc131\ub2f9\uc758 \uc815\uba74\uc744 \uc62c\ub824\ub2e4\ubcf4\uba74 \uc7a5\uc2dd \uc0ac\uc774\uc5d0 \uc790\ub9ac \uc7a1\uc740 \uc0ac\uc790\ub97c \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \uc5ec\ub7ec \uc544\uce58 \uac00\uc6b4\ub370 \uc911\uc2ec\uc774 \ub418\ub294 \ubd80\ubd84 \uc704\ucabd\uc774\ub2e4. \uc131\uc778\uc744 \uc0c1\uc9d5\ud558\ub294 \uc0ac\uc790\uac00 \uadf8 \uc131\uc778\uc744 \ubaa8\uc2e0 \uac74\ubb3c\uc5d0\uc11c\ub3c4 \uc5bc\uad74\uc744 \ub0b4\ubc00\uace0 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub978 \uc0ac\uc790\ub4e4\uc740 \uac74\ubb3c\uc758 \ubcbd\uc774\ub098 \uc7a5\uc2dd \uc18d\uc5d0 \ub4e4\uc5b4\uac00 \uc788\ub2e4. \uc5b4\ub5a4 \uac83\uc740 \uc704\uc5c4 \uc788\uac8c \uc55e\uc744 \ubcf4\uace0, \uc5b4\ub5a4 \uac83\uc740 \uc606\ubaa8\uc2b5\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uae30\ub150\ud488 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \ubd84\uc704\uae30\uac00 \ud55c\uacb0 \ubd80\ub4dc\ub7ec\uc6cc\uc9c4\ub2e4. \ub098\ub77c\ub97c \ub300\ud45c\ud558\ub358 \uc0c1\uc9d5\uc774 \uc190\ubc14\ub2e5\ub9cc \ud55c \ubb3c\uac74\uc774 \ub418\uc5b4 \uc5ec\ud589 \uac00\ubc29\uc5d0 \uc2e4\ub824 \uac00\uae30\ub3c4 \ud55c\ub2e4. \uc0ac\uc790\ub97c \uc54c\uc544\ubcf4\ub294 \ub370 \uc775\uc219\ud574\uc9c0\uba74 \uac74\ubb3c\uc758 \uc7a5\uc2dd\ub3c4 \uc804\uacfc \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc5b4\ub5a4 \ub3d9\ubb3c\uc740 \uc774\uc57c\uae30\ub97c \ub098\ud0c0\ub0b4\uace0, \uc5b4\ub5a4 \ub3d9\ubb3c\uc740 \ud2b9\uc815 \uc778\ubb3c\uc744 \uc54c\ub824\uc900\ub2e4. \ubaa8\uc591\uc774 \ube44\uc2b7\ud574\ub3c4 \ub298 \uac19\uc740 \ub73b\uc740 \uc544\ub2c8\ub2c8, \ud2b9\ubcc4\ud788 \uad81\uae08\ud55c \uc870\uac01\uc740 \uadf8 \uac74\ubb3c\uc758 \uc124\uba85\uacfc \ud568\uaed8 \ubcf4\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc774 \uc815\ub3c4\ub9cc \uc54c\uace0 \uac78\uc5b4\ub3c4 \uc5ec\ud589\uc758 \ud48d\uacbd\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \ubc29\uae08 \uc9c0\ub098\uce5c \ubcbd\uc758 \uc7a5\uc2dd\uc774 \ub2e8\uc21c\ud55c \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c\ub294 \uac83\uc744 \uc54c\uc544\ubcf4\uac8c \ub41c\ub2e4. \uae00\uc790\ub97c \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uc791\uc740 \uadf8\ub9bc \ud558\ub098\uac00 \ub3c4\uc2dc\uc758 \uc774\ub984\uc744 \uc54c\ub824\uc8fc\ub294 \uc148\uc774\ub2e4. \ubca0\ub124\uce58\uc544\uc5d0 \uac04\ub2e4\uba74 \uc0ac\uc790 \ud55c \ub9c8\ub9ac\ucbe4\uc740 \ucc3e\uc544\ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc131\ub2f9\uc758 \ub192\uc740 \uacf3\uc5d0 \uc788\ub294 \uc0ac\uc790\uc5ec\ub3c4 \uc88b\uace0, \uac00\uac8c \uc9c4\uc5f4\uc7a5 \uc18d\uc758 \uc791\uc740 \uc0ac\uc790\uc5ec\ub3c4 \uc88b\ub2e4. \ub0a0\uac1c\uc640 \ucc45\uc744 \ud655\uc778\ud588\ub2e4\uba74, \ub9c8\uc9c0\ub9c9\uc5d0\ub294 \uc5bc\uad74\uc744 \ud55c\ubc88 \ubcf4\uc790. \ub3c4\uc2dc\ub97c \ub300\ud45c\ud558\ub294 \uc77c\uc774 \uc81c\ubc95 \uadfc\uc5c4\ud55c \uc77c\uc778\uc9c0, \uc544\ub2c8\uba74 \uae30\ub150\ud488 \uac00\uac8c \uadfc\ubb34\uac00 \ub354 \ub9c8\uc74c\uc5d0 \ub4dc\ub294\uc9c0. \uadf8 \ud45c\uc815\ub9cc\ud07c\uc740 \ubcf4\ub294 \uc0ac\ub78c\uc774 \uc870\uae08 \uc790\uc720\ub86d\uac8c \uc77d\uc5b4\ub3c4 \uad1c\ucc2e\ub2e4."}, {"id": "arpanet-first-node", "title": "\uc778\ud130\ub137\uc5d0\ub3c4 \uccab \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc788\uc5c8\ub2e4", "summary": "\uc5b4\ub514\uc5d0\ub098 \uc788\ub294 \uc778\ud130\ub137\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uba87\uba87 \ucef4\ud4e8\ud130\ub97c \uc787\ub294 \uc2e4\ud5d8\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "America", "url": "stories/arpanet-first-node/index.html", "image": "media/arpanet-first-node.jpg", "alt": "\ub450 \uc5f0\uad6c\uc2e4\uc758 \uc77c\ubc18\ud654\ud55c \ucd08\uae30 \ucef4\ud4e8\ud130\ub97c \uc120\uc73c\ub85c \uc5f0\uacb0\ud55c \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uc778\ud130\ub137\uc5d0\ub3c4 \uccab \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc788\uc5c8\ub2e4 1969\ub144, \uc5f0\uad6c\uc2e4\uc758 \ucef4\ud4e8\ud130\uac00 \uc5f0\uacb0\ub418\ub358 \ub54c \uc5b4\ub514\uc5d0\ub098 \uc788\ub294 \uc778\ud130\ub137\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uba87\uba87 \ucef4\ud4e8\ud130\ub97c \uc787\ub294 \uc2e4\ud5d8\uc5d0\uc11c \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4. America \uc5ed\uc0ac \uc778\ud130\ub137\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uac74\ubb3c \ud558\ub098\uac00 \uc544\ub2c8\uc5b4\uc11c \ucd9c\ubc1c\uc810\uc744 \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub2e4. \ud734\ub300\uc804\ud654\uc758 \ud654\uba74\uc744 \uc5f4\uba74 \uc774\ubbf8 \uadf8 \uc548\uc5d0 \uc788\uace0, \ub2e4\ub978 \ub098\ub77c\uc758 \uc18c\uc2dd\ub3c4 \uae08\uc138 \ub3c4\ucc29\ud55c\ub2e4. \uadf8\ub7f0\ub370 \uc624\ub298\uc758 \uc778\ud130\ub137\uc73c\ub85c \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub124\ud2b8\uc6cc\ud06c\uc5d0\ub294 \uc2e4\uc81c \ucef4\ud4e8\ud130\uac00 \ub193\uc778 \uc5f0\uad6c\uc2e4\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uadf8\uc911 \uccab \ubc88\uc9f8 \uc9c0\uc810\uc740 \ubbf8\uad6d UCLA\uc758 \ub808\ub108\ub4dc \ud074\ub77c\uc778\ub85d \uc5f0\uad6c\uc2e4\uc774\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uadf8 \uc5f0\uad6c\uc2e4\uc758 \ucef4\ud4e8\ud130\uac00 1969\ub144 9\uc6d4 ARPANET\uc758 \uccab \ub178\ub4dc\uac00 \ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub178\ub4dc\ub294 \uc5ec\uae30\uc11c \ub124\ud2b8\uc6cc\ud06c\uc5d0 \uc5f0\uacb0\ub418\ub294 \uc9c0\uc810\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub41c\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uae38\uc758 \uccab \uc815\uac70\uc7a5\uc5d0 \uc8fc\uc18c\uc9c0\uac00 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. ARPANET\uc740 \uc624\ub298\uc758 \uc778\ud130\ub137\uc73c\ub85c \uc774\uc5b4\uc9c4 \ucd08\uae30 \ub124\ud2b8\uc6cc\ud06c\ub2e4. \uc9c0\uae08\uc758 \uc6f9\uc0ac\uc774\ud2b8\uc640 \uba54\uc2e0\uc800\uac00 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc9c4 \uc0c1\ud0dc\ub85c \uc2dc\uc791\ud55c \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc6b0\uc120 \uc11c\ub85c \ub5a8\uc5b4\uc9c4 \ucef4\ud4e8\ud130\uac00 \uc815\ubcf4\ub97c \uc8fc\uace0\ubc1b\uc744 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \ud074\ub77c\uc778\ub85d\uc758 \uc5f0\uad6c\uc2e4\uc5d0\uc11c\ub294 \uccab \uc5f0\uacb0 \uc9c0\uc810\uc744 \ub9c8\ub828\ud55c \ub2e4\uc74c \ub2ec, \ub124\ud2b8\uc6cc\ud06c\ub97c \ud1b5\ud55c \uccab \uc804\uc1a1\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \ub2e4\ub978 \ub05d\uc5d0\ub294 \uce98\ub9ac\ud3ec\ub2c8\uc544 SRI\uc758 \uc5f0\uad6c\ud300\uc774 \uc788\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \ub354\uae00\ub7ec\uc2a4 \uc5e5\uac94\ubc14\ud2b8\uac00 \uc774\ub04c\ub358 \uc5f0\uad6c\uc18c\uac00 \ub450 \ubc88\uc9f8 \ud638\uc2a4\ud2b8\uac00 \ub418\uc5b4 UCLA\uc640 \ucd08\uae30 \uc804\uc1a1\uc744 \uc8fc\uace0\ubc1b\uc558\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \uc7a5\uc18c\uc758 \uc5f0\uad6c\uac00 \ud558\ub098\uc758 \uc5f0\uacb0 \uc548\uc5d0\uc11c \ub9cc\ub09c \uac83\uc774\ub2e4. \uc624\ub298\uc758 \uac10\uac01\uc73c\ub85c \ubcf4\uba74 \ucef4\ud4e8\ud130 \ub450 \uacf3\uc774 \ub300\ud654\ud558\ub294 \uc77c\uc740 \uc791\uc740 \uc131\uacfc\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uacb0\uc774 \ub2f9\uc5f0\ud558\uc9c0 \uc54a\uc558\ub358 \uc2dc\uc810\uc5d0\ub294, \uadf8 \ub300\ud654\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub3c4\ub85d \uc870\uac74\uc744 \ub9cc\ub4dc\ub294 \uc77c\ubd80\ud130 \ud544\uc694\ud588\ub2e4. \uc778\ud130\ub137\uc758 \uc2dc\uc791\uc744 \ud55c \uc0ac\ub78c\uc758 \uc0ac\uc9c4\uc73c\ub85c \uc124\uba85\ud558\ub824 \ud558\uba74 \uae08\uc138 \ub2e4\ub978 \uc774\ub984\ub4e4\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc5f0\uacb0\uc758 \uc6d0\ub9ac\ub97c \uc5f0\uad6c\ud55c \uc0ac\ub78c, \ucef4\ud4e8\ud130\ub97c \uc900\ube44\ud55c \uc0ac\ub78c, \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \ud1b5\uc2e0 \uaddc\uce59\uc744 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4. \ud074\ub77c\uc778\ub85d\uc740 \ud328\ud0b7 \ub124\ud2b8\uc6cc\ud06c\uc758 \uc218\ud559\uc801 \uc5f0\uad6c\ub85c\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc815\ubcf4\ub97c \uc77c\uc815\ud55c \ub2e8\uc704\ub85c \ub098\ub204\uc5b4 \ubcf4\ub0b4\ub294 \ubc29\uc2dd\uc774 \ub124\ud2b8\uc6cc\ud06c\ub97c \uc774\ud574\ud558\ub294 \uc911\uc694\ud55c \ubc14\ud0d5\uc774 \ub418\uc5c8\ub2e4\ub294 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc5b4\ub824\uc6b4 \uc218\uc2dd\uc744 \ub530\ub77c\uac08 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucef4\ud4e8\ud130\ub97c \uc5f0\uacb0\ud558\ub294 \ub370\uc5d0\ub3c4 \uc5f0\uad6c\uac00 \ud544\uc694\ud588\ub2e4\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \uccab \ubc88\uc9f8 \uc9c0\uc810\uc5d0 \uad00\uc2ec\uc744 \ub450\ub294 \uac83\uc740 \uadf8 \ud55c \uacf3\uc774 \ubaa8\ub4e0 \uac83\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \ub73b\uc774 \uc544\ub2c8\ub2e4. \uc5f0\uacb0\uc740 \uc0c1\ub300\uac00 \uc788\uc5b4\uc57c \uc131\ub9bd\ud55c\ub2e4. \uccab \uc815\uac70\uc7a5\uc774\ub77c\ub294 \ud45c\ud604\ub3c4 \ub450 \ubc88\uc9f8 \uc815\uac70\uc7a5\uc774 \uc0dd\uacbc\uc744 \ub54c \ube44\ub85c\uc18c \uc2e4\uac10\uc774 \ub09c\ub2e4. \uc774 \ucd08\uae30 \uc2e4\ud5d8\uacfc \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0ac\uc6a9\ud558\ub294 \uc778\ud130\ub137 \uc0ac\uc774\uc5d0\ub294 \uc624\ub79c \uac1c\ubc1c \uacfc\uc815\uc774 \uc788\ub2e4. \uadf8 \uc0ac\uc774\ub97c \ud55c \ubc88\uc758 \uc804\uc1a1\uc73c\ub85c \uac74\ub108\ub6f0\uba74 \uc791\uc740 \uc2dc\uc791\uc774 \uc624\ud788\ub824 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4. \ub124\ud2b8\uc6cc\ud06c\uac00 \uc810\uc810 \ub113\uc5b4\uc9c0\uae30 \uc804, \ub204\uad70\uac00\ub294 \ub2e4\ub978 \uc5f0\uad6c\uc2e4\uae4c\uc9c0 \uc2e0\ud638\uac00 \uc804\ub2ec\ub418\ub294\uc9c0 \ud655\uc778\ud558\uace0 \uc788\uc5c8\ub2e4. \uadf8\ub54c\uc758 \ucef4\ud4e8\ud130\uc640 \uc624\ub298\uc758 \ud734\ub300\uc804\ud654\ub294 \ubaa8\uc2b5\uc774 \ud06c\uac8c \ub2e4\ub974\uc9c0\ub9cc, \ub5a8\uc5b4\uc9c4 \uacf3\uc73c\ub85c \uc815\ubcf4\ub97c \ubcf4\ub0b8\ub2e4\ub294 \uc77c\uc740 \uc774\uc5b4\uc838 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uba40\ub9ac \uc788\ub294 \uc0ac\ub78c\uc5d0\uac8c \uba54\uc2dc\uc9c0\ub97c \ubcf4\ub0b8\ub2e4\uba74 \uc7a0\uae50 \uc61b \uc5f0\uad6c\uc2e4\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc6b0\ub9ac\uac00 \uc7a5\uc18c\ub97c \uc758\uc2dd\ud558\uc9c0 \uc54a\uace0 \uac74\ub108\uac00\ub294 \uae38\ub3c4, \ucc98\uc74c\uc5d0\ub294 \ucef4\ud4e8\ud130\uac00 \ub193\uc778 \uad6c\uccb4\uc801\uc778 \uc7a5\uc18c\uc5d0\uc11c \uc2dc\uc791\ub418\uc5c8\ub2e4."}, {"id": "clock-little-door-case", "title": "\uc2dc\uacc4\uc5d0\ub3c4 \uc791\uc740 \ubb38\uc774 \ub2ec\ub9b0 \uc9d1\uc774 \uc788\uc5c8\ub2e4", "summary": "\ubd89\uc740 \ubca8\ubcb3\uacfc \uac08\uc0c9 \uac00\uc8fd\uc73c\ub85c \uac10\uc2fc \uc61b \uc2dc\uacc4 \ud55c \uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Korea", "url": "stories/clock-little-door-case/index.html", "image": "media/clock-little-door-case.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc2dc\uacc4 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc2dc\uacc4\uc5d0\ub3c4 \uc791\uc740 \ubb38\uc774 \ub2ec\ub9b0 \uc9d1\uc774 \uc788\uc5c8\ub2e4 \ubb38\uc744 \uc5f4\uba74 \uc2dc\uac04\uc774 \ubcf4\uc774\ub294 \ubcf4\uad00\ud568 \ubd89\uc740 \ubca8\ubcb3\uacfc \uac08\uc0c9 \uac00\uc8fd\uc73c\ub85c \uac10\uc2fc \uc61b \uc2dc\uacc4 \ud55c \uc870\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Korea \uc5ed\uc0ac \uc0ac\uc9c4 \uc18d \uc791\uc740 \ubb38\uc774 \uc591\ucabd\uc73c\ub85c \uc5f4\ub824 \uc788\ub2e4. \uadf8 \uc548\uc5d0\ub294 \uc2dc\uacc4\uac00 \uc549\uc544 \uc788\ub2e4. \uc2dc\uacc4\ub97c \ub123\ub294 \uc0c1\uc790\uac00 \uc544\ub2c8\ub77c \uc2dc\uacc4\ub9cc\uc744 \uc704\ud574 \uc9c0\uc740 \uc791\uc740 \uc9d1\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc18c\uc7a5\ud488 \uc774\ub984\uc740 \uac04\ub2e8\ud788 \uc2dc\uacc4\ub2e4. \uc2dc\uacc4\uc640 \ubcf4\uad00 \ucf00\uc774\uc2a4\uac00 \ud55c \uc870\ub97c \uc774\ub8ec\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \uc2dc\uacc4\uc758 \ubc14\ub298\ub9cc \ud655\uc778\ud558\uace0 \uc9c0\ub098\uac14\ub2e4\uba74, \uc774\ubc88\uc5d0\ub294 \ubc14\uae65\uc758 \uc9d1\uae4c\uc9c0 \ucc9c\ucc9c\ud788 \ubcf4\uc790. \uc2dc\uacc4 \uc55e\uba74\uc758 \uc22b\uc790\ub294 \uc6b0\ub9ac\uc5d0\uac8c \uc775\uc219\ud55c \uc544\ub77c\ube44\uc544 \uc22b\uc790\ub2e4. \uadf8\uc911 12\ub9cc \ubd89\uace0 \ub098\uba38\uc9c0\ub294 \uac80\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ub611\uac19\uc740 \uc22b\uc790\ud310 \uc548\uc5d0\uc11c \uc704\ucabd \ud55c \uc790\ub9ac\uc5d0\ub9cc \uc0c9\uc744 \ub2ec\ub9ac \uc900 \uac83\uc774\ub2e4. \uc65c \uadf8 \uc22b\uc790\ub9cc \ubd89\uac8c \ud588\ub294\uc9c0\ub294 \uc774 \uc790\ub8cc\uc5d0 \uc801\ud600 \uc788\uc9c0 \uc54a\ub2e4. \ud2b9\ubcc4\ud55c \uc758\ubbf8\ub97c \ubd99\uc774\uae30\ubcf4\ub2e4 \uba3c\uc800 \uc2e4\uc81c \ucc28\uc774\ub97c \ub208\uc73c\ub85c \ucc3e\uc544\ubcf4\uba74 \uc88b\ub2e4. \uc124\uba85\uc744 \uc77d\uae30 \uc804\uc5d0\ub294 \uc9c0\ub098\ucce4\uc744 \uc791\uc740 \uc120\ud0dd\uc774 \uc2dc\uacc4\uc758 \uc5bc\uad74\uc744 \ubc14\uafbc\ub2e4. \ubcf4\uad00 \ucf00\uc774\uc2a4\uc758 \ubc14\uae65\uc5d0\ub294 \uac08\uc0c9 \uac00\uc8fd\uc774 \uc50c\uc6cc\uc838 \uc788\uace0 \uc548\uc5d0\ub294 \ubd89\uc740 \ubca8\ubcb3\uc774 \uc788\ub2e4. \uc2dc\uacc4\uac00 \ub4e4\uc5b4\uac00\ub294 \uacf5\uac04\ub3c4 \ud06c\uae30\uc5d0 \uaf2d \ub9de\ub3c4\ub85d \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \ud55c\ub2e4. \ubb38\uc740 \uc88c\uc6b0\ub85c \ud65c\uc9dd \uc5f4 \uc218 \uc788\ub294 \uad6c\uc870\ub2e4. \ubcf4\uad00\ud560 \ub54c\uc640 \ub4e4\uc5ec\ub2e4\ubcfc \ub54c\uc758 \ubaa8\uc591\uc774 \ub2e4\ub978 \ubb3c\uac74\uc774\ub2e4. \uc624\ub298\uc758 \uc774\uc5b4\ud3f0 \ucf00\uc774\uc2a4\ub97c \ub5a0\uc62c\ub824 \ubcfc \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc774\uac83\uc774 \uc5ec\ud589\uc6a9\uc774\uc5c8\ub2e4\uac70\ub098 \ucda9\uaca9\uc744 \ub9c9\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0\uae4c\uc9c0 \ub2e8\uc815\ud560 \uadfc\uac70\ub294 \uc5c6\ub2e4. \ub9de\ucda4 \uacf5\uac04\uacfc \uc5ec\ub2eb\uc774\ubb38 \uc790\uccb4\uac00 \ubcf4\uc5ec \uc8fc\ub294 \uc7ac\ubbf8\ub97c \uc990\uae30\uba74 \ucda9\ubd84\ud558\ub2e4. \ucf00\uc774\uc2a4 \ubb38\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uc6d0\ub798 \ubd99\uc5c8\ub358 \uc7a0\uae08\uc7a5\uce58\uac00 \uc5c6\uc5b4\uc84c\uace0, \uace0\uc815\ud558\ub358 \uc791\uc740 \uae08\uc18d\ud310\ub9cc \ub0a8\uc558\ub2e4\uace0 \ud55c\ub2e4. \uc624\ub798\ub41c \ubb3c\uac74\uc740 \uac16\ucd94\uc5b4\uc9c4 \ubd80\ubd84\ubfd0 \uc544\ub2c8\ub77c \ube60\uc9c4 \ubd80\ubd84\uc73c\ub85c\ub3c4 \uc790\uae30 \uc0c1\ud0dc\ub97c \uc54c\ub824 \uc900\ub2e4. \uc81c\uc791 \uc5f0\ub300\ub294 \ubc15\ubb3c\uad00 \uc815\ubcf4\uc5d0\uc11c\ub3c4 \ubbf8\uc0c1\uc774\ub2e4. \ub204\uad6c\uc758 \ucc45\uc0c1\uc5d0 \uc5b8\uc81c \ub193\uc600\ub294\uc9c0 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b0\uae30\ubcf4\ub2e4 \uc9c0\uae08 \ud655\uc778\ud560 \uc218 \uc788\ub294 \ubb38\uacfc \uc22b\uc790, \uac00\uc8fd\uacfc \ubca8\ubcb3\uc744 \ubcf4\uc790. \uc2dc\uac04\uc744 \uc54c\ub824 \uc8fc\ub358 \ubb3c\uac74\uc5d0 \ubcf4\uad00\ud558\ub294 \uc2dc\uac04\uae4c\uc9c0 \ud568\uaed8 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \ub290\ub08c\uc774 \ub4e0\ub2e4."}, {"id": "horn-bow-missing-string", "title": "\uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcfc \uc218 \uc788\uc744\uae4c", "summary": "\ud65c\uc2dc\uc704\uac00 \uc0ac\ub77c\uc838\ub3c4 \ub0a8\uc544 \uc788\ub294 \ub2e8\uc11c\ub294 \uc788\uc2b5\ub2c8\ub2e4. \uc791\uc740 \ud648\uacfc \uc190\uc7a1\uc774\ub97c \ub530\ub77c \uc61b \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Korea", "url": "stories/horn-bow-missing-string/index.html", "image": "media/horn-bow-missing-string.jpg", "alt": "\ud65c\uc2dc\uc704 \uc5c6\uc774 \uad7d\uc740 \ubab8\uccb4\uc640 \uac00\uc6b4\ub370 \ubd89\uc740 \uc190\uc7a1\uc774\uac00 \ub0a8\uc544 \uc788\ub294 \uac01\uad81 \uc0ac\uc9c4", "text": "\uc2dc\uc704 \uc5c6\ub294 \uc61b \ud65c\uc5d0\uc11c\ub294 \ubb34\uc5c7\uc744 \ubcfc \uc218 \uc788\uc744\uae4c \uac01\uad81\uc758 \uad7d\uc740 \ubab8\uccb4\uc5d0 \ub0a8\uc544 \uc788\ub294 \uc7ac\ub8cc\uc640 \ud648 \ud65c\uc2dc\uc704\uac00 \uc0ac\ub77c\uc838\ub3c4 \ub0a8\uc544 \uc788\ub294 \ub2e8\uc11c\ub294 \uc788\uc2b5\ub2c8\ub2e4. \uc791\uc740 \ud648\uacfc \uc190\uc7a1\uc774\ub97c \ub530\ub77c \uc61b \ubb3c\uac74\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Korea \uc5ed\uc0ac \ud65c\uc744 \ub5a0\uc62c\ub9ac\uba74 \ud33d\ud33d\ud55c \uc904\uacfc \ud654\uc0b4\uc744 \ub2f9\uae30\ub294 \ubaa8\uc2b5\ubd80\ud130 \uc0dd\uac01\ub09c\ub2e4. \uadf8\ub7f0\ub370 \ubc15\ubb3c\uad00\uc5d0 \ub193\uc778 \ud65c\uc5d0 \uc904\uc774 \uc5c6\ub2e4\uba74 \uc5b4\ub514\ub97c \ubcf4\uc544\uc57c \ud560\uae4c. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uac01\uad81 \ud55c \uc810\uc740 \ud65c\uc2dc\uc704 \uc5c6\uc774 \ub0a8\uc544 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc5d0\uc11c\ub294 \uad7d\uc740 \ubab8\uccb4\uac00 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc124\uba85\uc744 \uc77d\uc73c\uba74 \uadf8 \uace1\uc120\uc744 \ub530\ub77c \uc791\uc740 \ub2e8\uc11c\ub4e4\uc774 \ud558\ub098\uc529 \ubcf4\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4. \uac01\uad81\uc758 \u2018\uac01\u2019\uc740 \ubfd4\uc744 \ub73b\ud55c\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc6b0\ub9ac\ub098\ub77c\uc758 \ub300\ud45c\uc801\uc778 \uc2e4\uc804\uc6a9 \ud65c\uc774\ub77c\uace0 \uc18c\uac1c\ud558\uba70, \ud0c4\uc131\uc744 \ub192\uc774\uae30 \uc704\ud574 \ubb3c\uc18c\uc758 \ubfd4\uc744 \uc8fc\uc7ac\ub8cc\ub85c \uc0ac\uc6a9\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c\ub294 \uac00\ub298\uace0 \uad7d\uc740 \ubb3c\uac74 \ud558\ub098\uc9c0\ub9cc, \uadf8 \uc548\uc5d0\ub294 \uc7ac\ub8cc\ub97c \uace0\ub978 \uc774\uc720\uac00 \uc788\ub2e4. \uadf8\uc800 \ub2e8\ub2e8\ud558\uae30\ub9cc \ud55c \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ud718\uc5b4\uc9c0\ub294 \uc131\uc9c8\ub3c4 \uc0dd\uac01\ud574\uc57c \ud588\ub358 \uac83\uc774\ub2e4. \uc774 \uc720\ubb3c\uc758 \uc2dc\ub300\ub294 \uc870\uc120\uc73c\ub85c \uc18c\uac1c\ub418\uc5b4 \uc788\ub2e4. \uc624\ub298 \uacbd\uae30\uc7a5\uc5d0\uc11c \ubcf4\ub294 \ud65c\uc758 \ubaa8\uc2b5\uacfc \uace7\ubc14\ub85c \uacb9\uccd0 \ub193\uae30\ubcf4\ub2e4, \ub2f9\uc2dc\uc758 \ubb3c\uac74\uc5d0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uc37c\ub294\uc9c0\ubd80\ud130 \uc0b4\ud3b4\ubcf4\ub294 \ud3b8\uc774 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub0a8\uc544 \uc788\ub294 \ud65c\uc5d0\ub294 \uc2dc\uc704\uac00 \uc5c6\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc904\uacfc \uad00\uacc4\ub41c \ubd80\ubd84\uae4c\uc9c0 \ubaa8\ub450 \uc0ac\ub77c\uc9c4 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc591 \ub05d\uc5d0 \uc904\uc744 \ub9ec \uc218 \uc788\ub3c4\ub85d \ud648\uc774 \ud30c\uc5ec \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud65c\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uc190\uc7a1\uc774 \ubd80\ubd84\ub3c4 \uc788\ub2e4. \uc591 \ub05d\uc758 \ud648\uacfc \uac00\uc6b4\ub370\uc758 \uc190\uc7a1\uc774\ub97c \ub098\ub204\uc5b4 \ubcf4\uba74, \uae38\uac8c \uad7d\uc740 \ubab8\uccb4\uac00 \uc5b4\ub514\uc5d0\uc11c \uc190\uc5d0 \uc7a1\ud788\uace0 \uc5b4\ub514\uc5d0\uc11c \uc904\uacfc \ub9cc\ub0ac\ub294\uc9c0 \uc870\uae08\uc529 \uc77d\ud78c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc644\uc131\ub41c \uc0ac\uc6a9 \uc7a5\uba74\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ud754\uc801\uc740 \uc5ed\ud560\uc744 \uc54c\ub824\uc900\ub2e4. \ube60\uc9c4 \ubd80\ubd84\uc744 \ub9c8\uc74c\ub300\ub85c \ucc44\uc6cc \ub123\uae30\ubcf4\ub2e4, \ub0a8\uc740 \uc790\ub9ac\ub97c \ucc28\ub840\ub85c \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c \ubb3c\uac74\uacfc \uac00\uae4c\uc6cc\uc9c8 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc5d0\ub294 \ucc98\uc74c \ub9cc\ub4e4\uc5b4\uc9c4 \uc0c1\ud0dc \uadf8\ub300\ub85c\uc778 \ubb3c\uac74\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub5a4 \ubd80\ubd84\uc740 \ub0a8\uace0 \uc5b4\ub5a4 \ubd80\ubd84\uc740 \uc5c6\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc774\ub54c \uc5c6\ub294 \ubd80\ubd84\ub9cc \uc544\uc26c\uc6cc\ud558\uba74 \ub0a8\uc740 \ubd80\ubd84\uc758 \uc7ac\ubbf8\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uac01\uad81\uc5d0\uc11c\ub294 \uace1\uc120\uacfc \uc7ac\ub8cc, \uc190\uc7a1\uc774\uc640 \ud648\uc744 \ubcfc \uc218 \uc788\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc774 \ud55c \uc810\uc744 \ub2f9\uacbc\ub294\uc9c0\uae4c\uc9c0 \uc124\uba85\uc774 \uc54c\ub824\uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc2e0 \uc190\uc744 \ub300\ub358 \uc790\ub9ac\uc640 \uc904\uc774 \ub2ff\ub358 \uc790\ub9ac\ub77c\ub294 \uad6c\uccb4\uc801\uc778 \ub2e8\uc11c\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \ub3c4\uad6c\ub97c \ub9cc\ub0ac\ub294\ub370 \ud55c \ubd80\ubd84\uc774 \ube44\uc5b4 \uc788\ub2e4\uba74, \ub0a8\uc544 \uc788\ub294 \uac83\ubd80\ud130 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc790. \uc904\uc774 \uc5c6\ub294 \ud65c\ub3c4 \uc544\ubb34 \ub9d0 \uc5c6\ub294 \uace1\uc120\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uc791\uc740 \ud648 \ud558\ub098\uac00 \uc6d0\ub798\uc758 \uc4f0\uc784\uc744 \uc0dd\uac01\ud558\uac8c \ud574 \uc900\ub2e4."}, {"id": "mummy-museum-move", "title": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c", "summary": "\ubc15\ubb3c\uad00 \ubbf8\ub77c\uc758 \uc774\ub3d9\uc5d0\ub3c4 \ud3ec\uc7a5 \uc678\uc5d0 \ud655\uc778\ud560 \uc77c\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "America", "url": "stories/mummy-museum-move/index.html", "image": "media/mummy-museum-move.jpg", "alt": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\ubbf8\ub77c\uac00 \uc774\uc0ac\ud558\ub824\uba74 \ub204\uad6c\uc5d0\uac8c \ubb3c\uc5b4\ubd10\uc57c \ud560\uae4c \uc624\ub798\ub41c \uc720\ud574\ub97c \uc62e\uae30\uba70 \ubbf8\uc220\uad00\uc774 \ud655\uc778\ud55c \uac83 \ubc15\ubb3c\uad00 \ubbf8\ub77c\uc758 \uc774\ub3d9\uc5d0\ub3c4 \ud3ec\uc7a5 \uc678\uc5d0 \ud655\uc778\ud560 \uc77c\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. America \uc5ed\uc0ac \ubc15\ubb3c\uad00\uc758 \ubbf8\ub77c\ub97c \ub2e4\ub978 \ubbf8\uc220\uad00\uc73c\ub85c \uc62e\uae34\ub2e4\uace0 \ud574 \ubcf4\uc790. \uba3c\uc800 \ub5a0\uc624\ub974\ub294 \uac83\uc740 \ud3ec\uc7a5 \uc0c1\uc790\uc640 \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \uc6b4\uc1a1\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc5d0\uc11c\ub294 \uadf8\ubcf4\ub2e4 \uc55e\uc11c \ubc95\ub960\ud300\uc5d0 \uc9c8\ubb38\uc774 \ub3c4\ucc29\ud588\ub2e4. \uc0ac\ub78c\uc758 \uc720\ud574\ub97c \uc8fc \uacbd\uacc4 \ub108\uba38\ub85c \uc62e\uae38 \ub54c \uc54c\uc544\uc57c \ud560 \ubc95\uc774 \uc788\ub290\ub0d0\ub294 \ub0b4\uc6a9\uc774\uc5c8\ub2e4. \ud669\uae08\uc774\ub098 \ub3cc\ub85c \ub9cc\ub4e0 \uc720\ubb3c\uacfc \ub2ec\ub9ac \ubbf8\ub77c\ub294 \ud55c\ub54c \uc0b4\uc558\ub358 \uc0ac\ub78c\uc758 \ubab8\uc774\ub2e4. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \uc774\uc720\ub85c \uadf8 \ucc28\uc774\uac00 \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\uc5c8\ub2e4. \ubbf8\uc220\uad00\uc758 \uacf5\uc2dd \uae00\uc5d0 \ub530\ub974\uba74 \ubbf8\ub77c\uc640 \uad00\uc740 \ub2e4\ub978 \uc8fc\uc758 \ubc15\ubb3c\uad00\uc5d0 50\ub144 \ub118\uac8c \ub300\uc5ec\ub418\uc5b4 \uc788\uc5c8\ub2e4. \uc5f0\uad6c\uc640 \uc804\uc2dc\ub97c \uc704\ud574 \ub2e4\uc2dc \uac00\uc838\uc624\ub824\uba74\uc11c \uc6b4\uc1a1 \ubb38\uc81c\ub97c \uac80\ud1a0\ud558\uac8c \ub41c \uac83\uc774\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \ubc15\ubb3c\uad00 \uc18c\uc7a5\ud488\uc740 \ub298 \uac19\uc740 \uc790\ub9ac\uc5d0 \uc788\uc744 \uac83 \uac19\uc9c0\ub9cc \uc2e4\uc81c\ub85c\ub294 \ub300\uc5ec\uc640 \ubc18\ud658, \uc5f0\uad6c\ub97c \uc704\ud574 \uc6c0\uc9c1\uc778\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \uc6b0\ub9ac\uac00 \ubcf4\ub294 \ud55c \uc810\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uad00\uc5d0\uc11c \uc9c0\ub0b8 \uae34 \uc2dc\uac04\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00 \ubc95\ub960\ud300\uc740 \uad00\ub828 \uaddc\uc815\uacfc \ub2e4\ub978 \ubc15\ubb3c\uad00\uc758 \uc0ac\ub840\ub97c \uac80\ud1a0\ud588\ub2e4. \uc774 \uc0ac\ub840\uc5d0\uc11c\ub294 \uc6b4\uc1a1\uc5d0 \ubc95\uc801\uc778 \uc7a5\uc560\uac00 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\ub294 \ud310\ub2e8\uc744 \ub0b4\ub838\ub2e4\uace0 \uae00\uc740 \uc124\uba85\ud55c\ub2e4. \ubaa8\ub4e0 \ub098\ub77c\uc640 \ubaa8\ub4e0 \ubbf8\ub77c\uc5d0 \uadf8\ub300\ub85c \uc801\uc6a9\ub418\ub294 \uc548\ub0b4\ub294 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc62e\uae38 \uc218 \uc788\uaca0\uc9c0 \ud558\uace0 \ubc14\ub85c \uc0c1\uc790\uc5d0 \ub123\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810\uc774\ub2e4. \ubb3c\uac74\uc758 \uc7ac\ub8cc\uc640 \uc0c1\ud0dc\ub97c \ud655\uc778\ud558\ub294 \uc77c\ucc98\ub7fc, \uadf8\uac83\uc744 \uc5b4\ub5a4 \ub300\uc0c1\uc73c\ub85c \ub2e4\ub8e8\uc5b4\uc57c \ud558\ub294\uc9c0 \ubb3b\ub294 \uacfc\uc815\ub3c4 \uc774\ub3d9 \uc900\ube44\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \ubc18\ud658 \uacfc\uc815\uc5d0\uc11c\ub294 \ube4c\ub824 \uac04 \ubc15\ubb3c\uad00\uc774 \ubbf8\ub77c\uc640 \uad00\uc758 \ubcf5\uc81c\ud488\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub3c4\ub85d \ud569\uc758\ub3c4 \ud588\ub2e4. \ud55c\ucabd\uc5d0\uc11c\ub294 \uc5f0\uad6c\ud560 \uc6d0\ub798 \uc790\ub8cc\ub97c \ub3cc\ub824\ubc1b\uace0, \ub2e4\ub978 \ucabd\uc5d0\uc11c\ub294 \ubcf5\uc81c\ud488\uc744 \ub0a8\uae30\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uacf5\uc2dd \uae00\uc740 \ub3cc\uc544\uc628 \ub4a4\uc758 \uc5f0\uad6c\uac00 \uae30\uc874 \uc2e0\uc6d0 \uc774\ud574\uc5d0\ub3c4 \uc9c8\ubb38\uc744 \ub358\uc84c\ub2e4\uace0 \ub367\ubd99\uc778\ub2e4. \uc804\uc2dc\ud488 \uc124\uba85\uc740 \uc601\uc6d0\ud788 \uace0\uc815\ub41c \uc815\ub2f5\uc774 \uc544\ub2d0 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \ubbf8\ub77c\uc758 \uc774\uc0ac\ub294 \uc0c1\uc790 \ud558\ub098\ub97c \uc62e\uae30\ub294 \uc77c\uc744 \ub118\uc5b4, \ud55c \uc0ac\ub78c\uc758 \ud754\uc801\uc744 \uc5b4\ub5bb\uac8c \ubcf4\uad00\ud558\uace0 \uc774\ud574\ud560\uc9c0 \ub2e4\uc2dc \ubb3b\ub294 \uc77c\uc774\uc5c8\ub2e4."}, {"id": "newton-mint-work", "title": "\ub274\ud134\uc758 \ub610 \ub2e4\ub978 \uc77c\ud130\ub294 \uc870\ud3d0\uad6d\uc774\uc5c8\ub2e4", "summary": "\uacfc\ud559\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \uc870\ud3d0\uad6d\uc774\ub77c\ub294 \uc9c1\uc7a5\uc774 \ubd99\uc2b5\ub2c8\ub2e4. \ub274\ud134\uc740 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc744 \ud588\uc744\uae4c\uc694?", "category": "history", "category_title": "History", "subcategory": "Europe", "url": "stories/newton-mint-work/index.html", "image": "media/newton-mint-work.jpg", "alt": "\uae43\ud39c\uacfc \ube48 \uc7a5\ubd80, \uc740\ube5b \ub3d9\uc804, \uc791\uc740 \ud504\ub9ac\uc998\uc774 \ub193\uc778 \ucc45\uc0c1\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\ub274\ud134\uc758 \ub610 \ub2e4\ub978 \uc77c\ud130\ub294 \uc870\ud3d0\uad6d\uc774\uc5c8\ub2e4 \ub3d9\uc804\uc758 \ubb34\uac8c\ub97c \uc0b4\ud53c\ub358 \uacfc\ud559\uc790\uc758 \uc77c\uc0c1 \uacfc\ud559\uc790\uc758 \uc774\ub984 \uc606\uc5d0 \uc870\ud3d0\uad6d\uc774\ub77c\ub294 \uc9c1\uc7a5\uc774 \ubd99\uc2b5\ub2c8\ub2e4. \ub274\ud134\uc740 \uadf8\uacf3\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc744 \ud588\uc744\uae4c\uc694? Europe \uc5ed\uc0ac \ub274\ud134\uc774\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \uacfc\ud559\ucc45\uc758 \ucd08\uc0c1\ud654\ubd80\ud130 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uadf8\uc758 \uc774\ub825\uc5d0\ub294 \uc870\uae08 \ub2e4\ub978 \uc7a5\uc18c\ub3c4 \ub098\uc628\ub2e4. \uae08\uc18d\uc744 \ub179\uc774\uace0 \ub3d9\uc804\uc744 \ub9cc\ub4dc\ub294 \uc655\ub9bd\uc870\ud3d0\uad6d\uc774\ub2e4. \uc11c\ub958\uc5d0 \uc11c\uba85\ub9cc \ud558\ub7ec \uac00\ub054 \ub4e4\ub978 \uba85\uc608\uc9c1\uc774\uc5c8\uc744\uae4c. \uc601\uad6d \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc124\uba85\uc744 \uc77d\uc73c\uba74 \uaf64 \ubc14\uc05c \uc9c1\uc7a5\uc774\uc5c8\uc74c\uc744 \uc54c \uc218 \uc788\ub2e4. \ub274\ud134\uc740 1696\ub144 \uadf8\uacf3\uc5d0\uc11c \uc77c\uc744 \uc2dc\uc791\ud588\uace0, \ub3d9\uc804\uc758 \ubb34\uac8c\uc640 \ud488\uc9c8\uc744 \ud655\uc778\ud558\ub294 \ubb38\uc81c\uc5d0 \uae4a\uc774 \uad00\uc5ec\ud588\ub2e4. \uc2e4\ud5d8\uc2e4\uc744 \ub5a0\ub09c \ub4a4\uc5d0\ub3c4 \uc815\ud655\ud558\uac8c \uc7ac\uace0 \ud655\uc778\ud558\ub294 \uc77c\uc774 \uadf8\ub97c \uae30\ub2e4\ub838\ub358 \uc148\uc774\ub2e4. \ub274\ud134\uc774 \uc870\ud3d0\uad6d\uc5d0 \ub4e4\uc5b4\uac14\uc744 \ubb34\ub835\uc5d0\ub294 \uc624\ub798\ub41c \uc740\ud654\ub97c \uc0c8\ub85c \ub9cc\ub4dc\ub294 \ud070 \uc791\uc5c5\uc774 \uc9c4\ud589\ub418\uace0 \uc788\uc5c8\ub2e4. \uc5ec\ub7ec \uc9c0\uc5ed\uc5d0 \ubcf4\uc870 \uc870\ud3d0 \uc2dc\uc124\uae4c\uc9c0 \ub9c8\ub828\ud560 \ub9cc\ud07c \uaddc\ubaa8\uac00 \ucef8\ub2e4. \uc0c8\ub85c\uc6b4 \uc9c1\uc7a5\uc5d0 \uc801\uc751\ud560 \uc2dc\uac04\ubd80\ud130 \ub109\ub109\ud558\uac8c \uc8fc\uc5b4\uc9c4 \uc0c1\ud669\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \uc774 \uc791\uc5c5\uc774 \uc57d 3\ub144 \uc548\uc5d0 \ub9c8\ubb34\ub9ac\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub274\ud134 \ud63c\uc790\uc11c \ubaa8\ub4e0 \uc77c\uc744 \ud574\ub0c8\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc218\ub9ce\uc740 \uc0ac\ub78c\uacfc \uc2dc\uc124\uc774 \uc6c0\uc9c1\uc774\ub294 \uc870\uc9c1 \uc548\uc5d0\uc11c \uadf8\ub3c4 \uc77c\uc744 \ub9e1\uc558\ub2e4. \uc774\ud6c4\uc5d0\ub294 \ub3d9\uc804\uc744 \uc704\uc870\ud558\uac70\ub098 \ud6fc\uc190\ud55c \uc0ac\ub78c\ub4e4\uc744 \uc870\uc0ac\ud558\ub294 \uc77c\uc5d0\ub3c4 \uad00\uc5ec\ud588\ub2e4. \ubc94\uc8c4\uc790\uc640 \uc81c\ubcf4\uc790\ub97c \uc9c1\uc811 \ub9cc\ub098 \uc870\uc0ac\ud55c \uae30\ub85d\ub3c4 \uc18c\uac1c\ub41c\ub2e4. \uc6b0\ub9ac\uac00 \uc775\uc219\ud558\uac8c \ub5a0\uc62c\ub9ac\ub294 \uacfc\ud559\uc790\uc758 \ubaa8\uc2b5\uc5d0 \uc11c\ub958\uc640 \uba74\ub2f4 \uc77c\uc815\uc774 \ub354\ud574\uc9c4\ub2e4. \uadf8\ub807\ub2e4\uace0 \uac70\ub9ac\uc5d0\uc11c \ubc94\uc778\uc744 \ucad3\ub294 \uc7a5\uba74\uae4c\uc9c0 \uc0c1\uc0c1\ud574 \ub123\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc2e4\uc81c\ub85c \ud655\uc778\ub418\ub294 \uc5c5\ubb34\ub9cc\uc73c\ub85c\ub3c4 \uadf8\uc758 \uc870\ud3d0\uad6d \uc0dd\ud65c\uc740 \ucda9\ubd84\ud788 \ubd84\uc8fc\ud574 \ubcf4\uc778\ub2e4. \uc870\ud3d0\uad6d\uc5d0\uc11c \uc911\uc694\ud55c \uac83\uc740 \ub3d9\uc804\uc5d0 \uc608\uc05c \uadf8\ub9bc\uc744 \ucc0d\ub294 \uc77c\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uc815\ud574\uc9c4 \ubb34\uac8c\uc640 \uae08\uc18d\uc758 \uc21c\ub3c4\ub97c \ub9de\ucd94\uace0, \ub3d9\uc804\ub07c\ub9ac\uc758 \ucc28\uc774\ub97c \uc904\uc774\ub294 \uac83\ub3c4 \ud544\uc694\ud588\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \ub274\ud134\uc758 \uae30\uc5ec \uac00\uc6b4\ub370 \ud558\ub098\ub85c \uc774\ub7f0 \uc815\ud655\uc131\uc5d0 \ub300\ud55c \uad00\uc2ec\uc744 \ub4e0\ub2e4. \uc190\uc5d0 \uc950\ub294 \uc791\uc740 \ub3d9\uc804\uc774\ub77c\ub3c4, \uc5ec\ub7ec \uac1c\uac00 \uc11c\ub85c \ub2e4\ub974\uac8c \ub9cc\ub4e4\uc5b4\uc9c0\uba74 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc5d0\uac8c \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\uc5c8\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uc11c\ub958 \uc18d \uc791\uc740 \uc218\uce58\uc600\uaca0\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \uc7ac\ub8cc\uc640 \uc81c\uc791 \uacfc\uc815, \uac80\uc0ac\ub97c \uc5f0\uacb0\ud558\ub294 \ubb38\uc81c\uc600\ub2e4. \ucc45\uc0c1 \uc704\uc5d0\uc11c \uacc4\uc0b0\ud55c \uae30\uc900\uc774 \uc791\uc5c5\uc7a5\uc758 \uae08\uc18d\uc73c\ub85c \uc774\uc5b4\uc838\uc57c \ud588\ub2e4. \uadf8\uc758 \uc774\ub984\uc774 \ubd99\uc5c8\ub2e4\uace0 \ud574\uc11c \uc870\ud3d0\uad6d\uc758 \ubaa8\ub4e0 \uc81c\ub3c4\uac00 \ub2e8\ubc88\uc5d0 \ubc14\ub010 \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \uc124\uba85\ub3c4 \ud070 \uc870\uc9c1 \uac1c\ud601\uacfc \uadf8\uac00 \uae30\uc6b8\uc778 \uad00\ub9ac\uc758 \ub178\ub825\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc720\uba85\ud55c \uc778\ubb3c\uc758 \uc774\ub825\uc774\ub77c\uace0 \ubaa8\ub4e0 \uc77c\uc744 \uadf9\uc801\uc778 \ud601\uba85\uc73c\ub85c \ub9cc\ub4e4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub274\ud134\uc740 1699\ub144\ubd80\ud130 \uc870\ud3d0\uad6d\uc758 \ub2e4\ub978 \uad00\ub9ac\uc9c1\uc744 \ub9e1\uc558\uace0, 1727\ub144 \uc138\uc0c1\uc744 \ub5a0\ub0a0 \ub54c\uae4c\uc9c0 \uadf8\uacf3\uacfc \uad00\uacc4\ub97c \uc774\uc5b4 \uac14\ub2e4. \uc7a0\uae50\uc758 \uc678\ub3c4\uac00 \uc544\ub2c8\ub77c \uc0dd\uc560\uc758 \uae34 \ubd80\ubd84\uc774\uc5c8\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uace0 \ub098\uba74 \uc704\uc778\uc758 \uc774\ub825\ub3c4 \ud55c \uac00\uc9c0 \uc9c1\ud568\uc73c\ub85c\ub9cc \uc77d\ud788\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc5f0\uad6c \uacb0\uacfc\ub97c \ub0a8\uae34 \uc0ac\ub78c\uc5d0\uac8c\ub3c4 \uc870\uc9c1 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud574\uc57c \ud560 \uc77c\uacfc \ud655\uc778\ud574\uc57c \ud560 \ubb38\uc11c\uac00 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \ub3d9\uc804\uc744 \uc190\uc5d0 \uc954\ub2e4\uace0 \ub274\ud134\uc744 \uaf2d \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uacfc\ud559\ucc45\uc758 \ucd08\uc0c1\ud654 \uc606\uc5d0 \ub3d9\uc804\uc758 \ubb34\uac8c\uc640 \uc21c\ub3c4\ub97c \uc0b4\ud53c\ub358 \ub610 \ub2e4\ub978 \uc9c1\uc7a5\uc778\uc758 \ubaa8\uc2b5\ub3c4 \ub193\uc544 \ubcfc \uc218\ub294 \uc788\uaca0\ub2e4. \uc791\uc740 \ub3c8 \ud55c \uac1c\ub97c \uc815\ud655\ud558\uac8c \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \uadf8\uc758 \uc624\ub79c \uc77c\uc0c1\uc774\uc5c8\ub2e4."}, {"id": "passport-three-languages", "title": "\uc61b \uc5ec\uad8c \ud55c \uc7a5\uc5d0 \uc138 \uc5b8\uc5b4\uac00 \ubaa8\uc600\ub2e4", "summary": "\ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \ub098\ub780\ud788 \ub193\uc778 \uc5ec\uad8c \uc591\uc2dd\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "history", "category_title": "History", "subcategory": "Korea", "url": "stories/passport-three-languages/index.html", "image": "media/passport-three-languages.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ub300\uc870\uc120\uad6d \uc5ec\uad8c \uc591\uc2dd \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \uc5ec\uad8c \ud55c \uc7a5\uc5d0 \uc138 \uc5b8\uc5b4\uac00 \ubaa8\uc600\ub2e4 \ucc45\uc790 \ub300\uc2e0 \ucee4\ub2e4\ub780 \uc885\uc774\ub85c \ub9cc\ub098\ub294 \uc5ec\ud589 \ubb38\uc11c \ud55c\ubb38\uacfc \uc601\uc5b4, \ud504\ub791\uc2a4\uc5b4\uac00 \ub098\ub780\ud788 \ub193\uc778 \uc5ec\uad8c \uc591\uc2dd\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. Korea \uc5ed\uc0ac \uc5ec\uad8c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc190\ubc14\ub2e5\ub9cc \ud55c \ucc45\uc790\ub97c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ub300\uc870\uc120\uad6d \uc5ec\uad8c \uc591\uc2dd\uc740 \ud55c \uc7a5\uc758 \ub113\uc740 \uc885\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uac00\uc6b4\ub370\ub97c \uacbd\uacc4\ub85c \uae00\uc904\uc758 \ubaa8\uc2b5\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \uc77d\uc744 \uc218 \uc788\ub294 \uae00\uc790\ub97c \uba3c\uc800 \ucc3e\uc544\ub3c4 \uc88b\uace0, \ubb38\uc7a5\uc774 \ub193\uc778 \ubc29\ud5a5\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ud55c \uc7a5\uc758 \uc885\uc774\uac00 \uc11c\ub85c \ub2e4\ub978 \ub3c5\uc790\ub97c \ub9cc\ub0a0 \uc900\ube44\ub97c \ud558\uace0 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc870\uae08\uc529 \ubcf4\uc778\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc624\ub978\ucabd\uc5d0\ub294 \ud55c\ubb38, \uc67c\ucabd\uc5d0\ub294 \uc601\uc5b4\uc640 \ud504\ub791\uc2a4\uc5b4\ub85c \ub0b4\uc6a9\uc744 \uc778\uc1c4\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc138 \uc5b8\uc5b4\uac00 \uc11c\ub85c \ub2e4\ub978 \ubb38\uc11c\uc5d0 \ud769\uc5b4\uc9c4 \uac83\uc774 \uc544\ub2c8\ub77c \uac19\uc740 \uc885\uc774 \uc704\uc5d0 \ubaa8\uc600\ub2e4. \ud574\uc678\uc5d0\uc11c \uc4f0\ub294 \ubb38\uc11c\ub77c\ub294 \uac83\uc744 \ubaa8\uc591\ub9cc\uc73c\ub85c\ub3c4 \uc2e4\uac10\ud558\uac8c \ub41c\ub2e4. \uc9c0\uae08\uc758 \uc5ec\ud589\uc790\uac00 \ud734\ub300\uc804\ud654 \ubc88\uc5ed \ud654\uba74\uc744 \uaebc\ub0b4\ub4ef, \uc774 \uc885\uc774\ub3c4 \uc5b8\uc5b4\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ub0b4\uc6a9\uc744 \uc804\ub2ec\ud560 \uc790\ub9ac\ub97c \uac16\ucd94\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc774\ub294 \uc624\ub298\uc758 \uacbd\ud5d8\uc5d0 \ube57\ub300\uc5b4 \ubcf4\ub294 \ubc29\ubc95\uc774\ub2e4. \uae00\uc790\ub9cc \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubc14\uae65\uc5d0\ub294 \ubc30\uaf43\uacfc \ub369\uad74\uc744 \uc5ee\uc740 \ubb34\ub2ac\uac00 \ub458\ub7ec\uc838 \uc788\uace0, \uac00\uc6b4\ub370 \uc704\ucabd\uc5d0\ub294 \ubc30\uaf43\ubb34\ub2ac, \ub124 \uadc0\ud241\uc774\uc5d0\ub294 \ud0dc\uadf9\ubb34\ub2ac\uac00 \ubc30\uce58\ub418\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \ucc0d\ud78c \ub3c4\uc7a5\uc758 \uc774\ub984\uacfc \uc704\uce58\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uc7a5\uc2dd\ucc98\ub7fc \ubcf4\uc774\ub294 \ubd80\ubd84\ub4e4\uc774 \ubb38\uc11c\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \uc5bc\uad74\uc744 \ub9cc\ub4e0\ub2e4. \uae00\uc744 \ubaa8\ub450 \uc77d\uae30 \uc5b4\ub824\uc6cc\ub3c4 \ud14c\ub450\ub9ac\uc640 \ub3c4\uc7a5\uc744 \ub530\ub77c\uac00\uba74 \ub2e8\uc21c\ud55c \uba54\ubaa8\uc9c0\uc640\ub294 \ub2e4\ub978 \uc131\uaca9\uc758 \uc885\uc774\ub77c\ub294 \uac83\uc744 \ub290\ub07c\uac8c \ub41c\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc591\uc2dd\uc5d0 \uc4f0\uc778 \uc5f0\ud638\uc640 \uc678\uad50 \ub2f4\ub2f9 \uad00\uccad\uc758 \uba85\uce6d\uc744 \uadfc\uac70\ub85c \uc791\uc131 \uc2dc\uae30\ub97c 1895\ub144\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4. \ub0a0\uc9dc \ud558\ub098\ub97c \ub9d0\ud558\ub294 \ub370\ub3c4 \ubb38\uc11c \uc548\uc758 \ub2e8\uc11c\ub4e4\uc744 \ud568\uaed8 \uc77d\ub294 \uacfc\uc815\uc774 \ud544\uc694\ud55c \uac83\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \ud2b9\uc815 \uc5ec\ud589\uc790\uc758 \uc5ec\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774 \uc544\ub2c8\ub77c \uc5ec\uad8c \uc591\uc2dd\uc744 \ubcf4\ub294 \uc790\ub8cc\ub2e4. \ub204\uad6c\uc758 \uc9d0\uac00\ubc29\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\uc744\uc9c0 \uc0c1\uc0c1\ud558\uae30\uc5d0 \uc55e\uc11c, \ud55c \uc885\uc774\uc5d0 \uc138 \uc5b8\uc5b4\ub97c \ub098\ub780\ud788 \ub193\uc558\ub2e4\ub294 \uc120\ud0dd\ubd80\ud130 \uae30\uc5b5\ud574 \ub450\uc790. \uad6d\uacbd\uc744 \ub118\uc744 \uc900\ube44\uac00 \ubb38\uc7a5 \ubc30\uce58\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "chicago-lion-sports-helmet", "title": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4", "summary": "\uadfc\uc5c4\ud55c \uccad\ub3d9 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc4f0\uac8c \ub41c \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Americas", "url": "stories/chicago-lion-sports-helmet/index.html", "image": "media/chicago-lion-sports-helmet.jpg", "alt": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub294 \uac00\ub054 \ud5ec\uba67\uc744 \uc4f4\ub2e4 \ubbf8\uc220\uad00 \uc55e \uc870\uac01\uc0c1\uc774 \ub3c4\uc2dc\uc758 \uc751\uc6d0\ub2e8\uc774 \ub418\ub294 \ub0a0 \uadfc\uc5c4\ud55c \uccad\ub3d9 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc4f0\uac8c \ub41c \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Americas \ub3c4\uc2dc \ubbf8\uc220\uad00 \uc785\uad6c\uc758 \uc0ac\uc790\ub77c\uba74 \uadfc\uc5c4\ud55c \ud45c\uc815\uc744 \uae30\ub300\ud558\uac8c \ub41c\ub2e4. \uadf8\ub7f0\ub370 \ubbf8\uad6d \uc2dc\uce74\uace0\uc5d0\uc11c\ub294 \uadf8 \uc0ac\uc790\uc5d0\uac8c \ucee4\ub2e4\ub780 \uc2a4\ud3ec\uce20 \ud5ec\uba67\uc744 \uc50c\uc6b0\uae30\ub3c4 \ud55c\ub2e4. \uc870\uac01\uc0c1\uc774 \uac11\uc790\uae30 \ub3d9\ub124 \uc751\uc6d0\ub2e8\uc774 \ub41c \uac83 \uac19\uc740 \ubaa8\uc2b5\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uc9c0\uc5ed \ud300\uc744 \uc751\uc6d0\ud558\ub294 \uc0ac\uc790\ub4e4\uc758 \uc774\uc57c\uae30\ub97c \uacf5\uc2dd \uae00\uc5d0 \ub0a8\uacbc\ub2e4. \uc791\ud488\uc758 \uc81c\uc791 \uc5f0\ub3c4\ub9cc \uc54c\uba74 \ub05d\ub098\ub294 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub3c4\uc2dc \uc0ac\ub78c\ub4e4\uc774 \uc870\uac01\uc0c1\uacfc \uc5b4\ub5bb\uac8c \uc9c0\ub0b4\ub294\uc9c0\ub3c4 \uc774 \uc0ac\uc790\ub4e4\uc758 \uc774\ub825\uc774 \ub41c\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc0ac\uc790\ub4e4\uc740 \uc5d0\ub4dc\uc6cc\ub4dc \ucf00\ubbf8\uc2a4\uac00 \ub9cc\ub4e4\uc5c8\uace0 1894\ub144 \ubbf8\uc220\uad00 \uc815\ubb38 \uc55e\uc5d0 \uc124\uce58\ub418\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \ub458\uc740 \ub611\uac19\uc740 \uc870\uac01\uc774 \uc544\ub2c8\ub2e4. \uc790\uc138\ub3c4 \ub2e4\ub974\uace0 \ubab8\uc758 \ud06c\uae30\uc640 \uac08\uae30\uc758 \ubaa8\uc591\ub3c4 \ub2e4\ub974\ub2e4. \ubd81\ucabd \uc0ac\uc790\ub294 \uba39\uc787\uac10\uc744 \ucc3e\uc544 \uc6c0\uc9c1\uc774\ub294 \ub4ef\ud55c \uc790\uc138\uc774\uace0 \ub0a8\ucabd \uc0ac\uc790\ub294 \ub2f9\ub2f9\ud788 \ubc84\ud2f0\ub294 \uc790\uc138\ub85c \uc18c\uac1c\ub41c\ub2e4. \uac19\uc740 \uc0ac\uc790\ucc98\ub7fc \ubcf4\uace0 \uc9c0\ub098\ucce4\ub2e4\uba74 \ub2e4\uc74c\uc5d0\ub294 \ub2e4\ub9ac\uc640 \uace0\uac1c\ub97c \ube44\uad50\ud574 \ubcfc \ub9cc\ud558\ub2e4. \ubbf8\uc220\uad00\uc740 \uc0ac\uc790\ub4e4\uc774 \uc2a4\ud3ec\uce20 \uc751\uc6d0\uc5d0 \ucc38\uc5ec\ud55c \uc77c\uc744 1985\ub144 \uc2dc\uce74\uace0 \ubca0\uc5b4\uc2a4\uc758 \uc288\ud37c\ubcfc \uc9c4\ucd9c \ubb34\ub835\ubd80\ud130 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc\uc758 \ud5ec\uba67\uc740 \ub4a4\uc9d1\uc740 \ubc14\ube44\ud050 \uadf8\ub9b4\uc5d0 \uac04\ub2e8\ud55c \uc548\uba74 \ubcf4\ud638\ub300\ub97c \ubd99\uc5ec \ub9cc\ub4e0 \uac83\uc774\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uac00\uac8c\uc5d0\uc11c \uc0ac \uc628 \uae30\uc131\ud488\uc774 \uc544\ub2c8\uc5c8\ub358 \uc148\uc774\ub2e4. \uc0ac\ub78c\ubcf4\ub2e4 \ud6e8\uc52c \ud070 \uba38\ub9ac\uc5d0 \ub9de\ucdb0\uc57c \ud558\ub2c8 \uc751\uc6d0 \ub3c4\uad6c\ub3c4 \ud2b9\ubcc4\ud55c \uc81c\uc791\uc774 \ud544\uc694\ud588\ub2e4. \ubbf8\uc220\uad00 \uc55e\uc5d0\uc11c\ub294 \uc791\ud488\uc744 \uac10\uc0c1\ud558\ub294 \uc77c\uacfc \uc2a4\ud3ec\uce20\ub97c \uc751\uc6d0\ud558\ub294 \uc77c\uc774 \uc774\ub807\uac8c \ub9cc\ub0ac\ub2e4. \uc774\ud6c4 \uc0ac\uc790\ub4e4\uc740 \uc544\uc774\uc2a4\ud558\ud0a4 \ud300 \ube14\ub799\ud638\ud06c\uc2a4\ub97c \uc751\uc6d0\ud558\ub294 \ud5ec\uba67\ub3c4 \uc37c\ub2e4. \ub2e4\ub9cc \ubc29\ubb38\ud560 \ub54c\ub9c8\ub2e4 \ud5ec\uba67\uc744 \ubcfc \uc218 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud2b9\uc815 \uc751\uc6d0 \ud589\uc0ac\uc5d0 \ub9de\ucdb0 \uc637\ucc28\ub9bc\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc870\uac01\uc0c1\ub4e4\uc774\ub2e4. \uc624\ub798\ub41c \uacf5\uacf5 \uc870\uac01\uc740 \uac00\ub9cc\ud788 \uc11c \uc788\uae30\ub9cc \ud558\ub294 \ubb3c\uac74\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \ud558\uc9c0\ub9cc \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5b8\uac00\ub97c \uc50c\uc6b0\uace0, \uc0ac\uc9c4\uc744 \ucc0d\uace0, \ucd94\uc5b5\uc744 \ubcf4\ud0dc\uba74 \uc0c8\ub85c\uc6b4 \uc774\uc57c\uae30\uac00 \ubd99\ub294\ub2e4. \uc2dc\uce74\uace0\uc758 \uc0ac\uc790\ub4e4\uc740 \ubbf8\uc220\uad00\uc744 \uc9c0\ud0a4\ub294 \ub3d9\uc2dc\uc5d0 \ub3c4\uc2dc\uc758 \uae30\ubd84\uc744 \ud568\uaed8 \ub098\ub204\uace0 \uc788\ub2e4."}, {"id": "gyeonghoeru-pond-dragon", "title": "\uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0\uc11c\ub294 \uc65c \uccad\ub3d9 \uc6a9\uc774 \ub098\uc654\uc744\uae4c", "summary": "\uc5f0\ubabb\uc5d0\uc11c \ubc1c\uacac\ub41c \uc6a9\uc740 \uc7a5\uc2dd\uc5d0\uc11c \ub5a8\uc5b4\uc9c4 \ubb3c\uac74\uc774 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\ub85d\uc5d0\ub294 \ubb3c\uc5d0 \ub123\uc740 \uc774\uc720\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/gyeonghoeru-pond-dragon/index.html", "image": "media/gyeonghoeru-pond-dragon.jpg", "alt": "\uad81\uad90 \uc5f0\ubabb\uc758 \uc815\uc790 \ubc18\uc601\uacfc \ubb3c \uc544\ub798 \uc791\uc740 \uc6a9\uc758 \ud615\uc0c1\uc744 \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0\uc11c\ub294 \uc65c \uccad\ub3d9 \uc6a9\uc774 \ub098\uc654\uc744\uae4c \ubb3c\uc18d\uc5d0 \ub123\uc5b4 \ub454 \uad81\uad90\uc758 \ud654\uc7ac \uc608\ubc29 \uae30\uc6d0 \uc5f0\ubabb\uc5d0\uc11c \ubc1c\uacac\ub41c \uc6a9\uc740 \uc7a5\uc2dd\uc5d0\uc11c \ub5a8\uc5b4\uc9c4 \ubb3c\uac74\uc774 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4. \uae30\ub85d\uc5d0\ub294 \ubb3c\uc5d0 \ub123\uc740 \uc774\uc720\uac00 \ub0a8\uc544 \uc788\uc2b5\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uacbd\ubcf5\uad81\uc758 \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc5f0\ubabb\uc5d0 \ube44\uce5c \uac74\ubb3c\ubd80\ud130 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubb3c \uc544\ub798\uc5d0 \ubb34\uc5c7\uc774 \uc788\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc0dd\uac01\ud558\uac8c \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f0\ub370 1997\ub144, \uadf8 \uc5f0\ubabb\uc5d0\uc11c \uccad\ub3d9\uc73c\ub85c \ub9cc\ub4e0 \uc6a9\uc774 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uc720\ubb3c\uc740 \uae38\uc774\uac00 1\ubbf8\ud130\ub97c \ud6cc\uca4d \ub118\uace0 \ubb34\uac8c\ub3c4 60\ud0ac\ub85c\uadf8\ub7a8\uc774 \ub118\ub294\ub2e4. \uc190\ubc14\ub2e5\uc5d0 \ub4e4\uc5b4\uc624\ub294 \uc791\uc740 \uc7a5\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc65c \uc774\ub7f0 \ubb3c\uac74\uc774 \ubb3c\uc18d\uc5d0 \uc788\uc5c8\uc744\uae4c. \ub204\uac00 \ub5a8\uc5b4\ub728\ub9b0 \uac83\uc774 \uc544\ub2c8\ub77c, \uad81\uad90\uc744 \ubd88\uc5d0\uc11c \uc9c0\ucf1c \ub2ec\ub77c\ub294 \ub73b\uc73c\ub85c \ub123\uc5b4 \ub454 \uc6a9\uc774\uc5c8\ub2e4. \ub098\ubb34\ub85c \uc9c0\uc740 \uac74\ubb3c\uc774 \ub9ce\uc558\ub358 \uad81\uad90\uc5d0\uc11c \ubd88\uc740 \ud070 \uac71\uc815\uac70\ub9ac\uc600\ub2e4. \uacbd\ubcf5\uad81\uc744 \ub2e4\uc2dc \uc9d3\ub294 \uacfc\uc815\uc5d0\uc11c\ub3c4 \ud654\uc7ac\ub97c \ud53c\ud558\ub824\ub294 \uc5ec\ub7ec \uc870\uce58\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \ub2f9\uc2dc \uc0ac\ub78c\ub4e4\uc740 \uc6a9\uc774 \ubb3c\uacfc \uad6c\ub984\uc744 \ub2e4\uc2a4\ub9b0\ub2e4\uace0 \uc5ec\uacbc\ub2e4. \ubb3c\uc744 \ub2e4\ub8e8\ub294 \uc874\uc7ac\uc5d0\uac8c \ubd88\uc744 \ub9c9\uc544 \ub2ec\ub77c\ub294 \ub73b\uc744 \ub2f4\uc544 \uc5f0\ubabb\uc5d0 \uccad\ub3d9 \uc6a9\uc744 \ub123\uc740 \uac83\uc774\ub2e4. \uc774\ub54c\uc758 \uc6a9\uc740 \uc18c\ud654 \uc7a5\uce58\ub77c\uae30\ubcf4\ub2e4 \ubc14\ub78c\uc744 \ub2f4\uc740 \uc0c1\uc9d5\uc774\uc5c8\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \u300e\uacbd\ubcf5\uad81\uc601\uac74\uc77c\uae30\u300f\ub97c \uadfc\uac70\ub85c \uc81c\uc791\uacfc \ubc30\uce58 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc6a9\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ubfd0 \uc544\ub2c8\ub77c \ubb3c\uc5d0 \uac00\ub77c\uc549\ud78c \uae30\ub85d\uae4c\uc9c0 \ub0a8\uc544 \uc788\ub2e4. \ub2e8\uc21c\ud788 \uc0dd\uae40\uc0c8\ub97c \ubcf4\uace0 \uc624\ub298\uc758 \uad00\ub78c\uac1d\uc774 \ubd99\uc778 \ud574\uc11d\uc740 \uc544\ub2cc \uc148\uc774\ub2e4. \uccad\ub3d9 \uc6a9\uc740 1865\ub144\uc5d0 \ud55c \uc30d\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\uace0, 1867\ub144\uc5d0 \uacbd\ud68c\ub8e8 \uc5f0\ubabb\uc5d0 \ub123\uc5c8\ub2e4\uace0 \uae30\ub85d\ub418\uc5b4 \uc788\ub2e4. \uadf8\ub7f0\ub370 1997\ub144 \ubc1c\uacac \ub2f9\uc2dc \ud655\uc778\ub41c \uac83\uc740 \ud55c \ub9c8\ub9ac\uc600\ub2e4. \ub458\uacfc \ud558\ub098\uc758 \ucc28\uc774\uac00 \uc791\uc740 \uad81\uae08\uc99d\uc744 \ub0a8\uae34\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub2e4\ub978 \ud55c \ub9c8\ub9ac\uc758 \ud589\ubc29\uc744 \uc0c1\uc0c1\uc73c\ub85c \ucc44\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a8\uc544 \uc788\ub294 \uae30\ub85d\uc774 \uc54c\ub824\uc8fc\ub294 \uc218\uc640 \uc2e4\uc81c \ubc1c\uacac\uc5d0\uc11c \ud655\uc778\ud55c \uc218\ub97c \ub098\ub204\uc5b4 \uae30\uc5b5\ud558\uba74 \ub41c\ub2e4. \ubc1c\uacac\ub41c \uc6a9\uc740 \ubc18\ucabd\uc529 \uc8fc\uc870\ud55c \ub4a4 \ubd99\uc5ec \ub9cc\ub4dc\ub294 \ubc29\uc2dd\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ubb3c\uc18d\uc5d0 \ub123\uc744 \ubb3c\uac74\uc5d0\ub3c4 \uae08\uc18d\uc744 \ub2e4\ub8e8\ub294 \uc218\uace0\uac00 \ub4e4\uc5b4\uac14\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0 \ub454\ub2e4\uace0 \ub300\ucda9 \ub9c8\ub828\ud55c \ubb3c\uac74\uc740 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uace0\uc0ac\ubb38\uc5d0\ub294 \uad81\uad90\uc744 \uc624\ub798 \ubcf4\ud638\ud574 \ub2ec\ub77c\ub294 \uae30\uc6d0\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uadf8 \uae00\uc744 \ud1b5\ud574 \uc6b0\ub9ac\ub294 \uc6a9\uc774 \uc2e4\uc81c\ub85c \ubd88\uc744 \ub9c9\uc558\ub294\uc9c0\uac00 \uc544\ub2c8\ub77c, \uc0ac\ub78c\ub4e4\uc774 \ubb34\uc5c7\uc744 \ub450\ub824\uc6cc\ud558\uace0 \ubb34\uc5c7\uc744 \ubc14\ub790\ub294\uc9c0 \uc77d\uac8c \ub41c\ub2e4. \uad81\uad90\uc758 \uc0c1\uc9d5\uc740 \uc9c0\ubd95\uc774\ub098 \ubb38 \uc704\uc5d0\uc11c\ub9cc \ubc1c\uacac\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uacbd\ud68c\ub8e8\uc758 \uc6a9\uc740 \uc624\ub7ab\ub3d9\uc548 \ubb3c \uc544\ub798\uc5d0 \uc788\uc5c8\ub2e4. \ubc14\ub77c\ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c \uc790\uc2e0\uc744 \ub4dc\ub7ec\ub0b4\ub294 \uc7a5\uc2dd\uacfc\ub294 \uc870\uae08 \ub2e4\ub978 \uc790\ub9ac\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc548 \ub4a4 \uacbd\ud68c\ub8e8\ub97c \ubcf4\uba74 \uc5f0\ubabb\uc774 \ub2e8\uc21c\ud55c \ubc30\uacbd\ub9cc\uc73c\ub85c \ubcf4\uc774\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uac74\ubb3c\uc758 \uc544\ub984\ub2e4\uc6c0\uc744 \ube44\ucd94\ub358 \ubb3c\uc774, \ud55c\ub54c\ub294 \ubd88\uc744 \ub9c9\uc544 \uc8fc\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc744 \ub9e1\uae34 \uacf3\uc774\uae30\ub3c4 \ud588\ub2e4. \ub2e4\uc74c\uc5d0 \uacbd\ud68c\ub8e8 \uc0ac\uc9c4\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \uc9c0\ubd95\uc5d0\uc11c \ubb3c\uac00\ub85c \uc2dc\uc120\uc744 \ub0b4\ub824 \ubcf4\uc790. \uc870\uc6a9\ud55c \uc218\uba74 \uc544\ub798\uc5d0\ub3c4 \uac74\ubb3c\uc744 \uc9c0\ud0a4\uace0 \uc2f6\uc5c8\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc774\uc57c\uae30\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "mozambique-village-cultural-center", "title": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4", "summary": "\ub9d0\ub791\uac00\ud0c0\ub098\uac00 \uace0\ud5a5\uc5d0\uc11c \uc2dc\uc791\ud55c \ubb38\ud654\uc13c\ud130\ub97c \ud1b5\ud574 \uc608\uc220\uacfc \ub9c8\uc744\uc758 \uad00\uacc4\ub97c \ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Africa", "url": "stories/mozambique-village-cultural-center/index.html", "image": "media/mozambique-village-cultural-center.jpg", "alt": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uace0\ud5a5 \ub9c8\uc744\uc5d0 \ub465\uadfc \ucc3d\uc758 \ubb38\ud654 \uacf5\uac04\uc744 \ub9cc\ub4e4\ub2e4 \ubaa8\uc7a0\ube44\ud06c \ud654\uac00\uc758 \uc77c\uc774 \uadf8\ub9bc \ubc16\uc73c\ub85c \uc774\uc5b4\uc9c4 \uc21c\uac04 \ub9d0\ub791\uac00\ud0c0\ub098\uac00 \uace0\ud5a5\uc5d0\uc11c \uc2dc\uc791\ud55c \ubb38\ud654\uc13c\ud130\ub97c \ud1b5\ud574 \uc608\uc220\uacfc \ub9c8\uc744\uc758 \uad00\uacc4\ub97c \ubd05\ub2c8\ub2e4. Africa \ub3c4\uc2dc \ud654\uac00\uc758 \uc791\uc5c5\uc774\ub77c\uace0 \ud558\uba74 \uce94\ubc84\uc2a4 \uc55e\uc5d0 \uc120 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \ubaa8\uc7a0\ube44\ud06c\uc758 \ud654\uac00 \ub9d0\ub791\uac00\ud0c0\ub098 \uc751\uc6e8\ub0d0\ub294 \uace0\ud5a5 \ub9c8\uc744\uc5d0 \ubb38\ud654\uc13c\ud130\ub97c \ub9cc\ub4dc\ub294 \uc77c\ub3c4 \uc2dc\uc791\ud588\ub2e4. \uadf8\ub9bc\uc744 \ub193\uc744 \ubcbd\ub9cc\uc774 \uc544\ub2c8\ub77c \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc77c \uacf5\uac04\uc744 \uc0dd\uac01\ud55c \uac83\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \uc5f0\uad6c \uc790\ub8cc\ub294 \uadf8\uac00 1995\ub144\uc5d0 \ub9c8\ud0c8\ub77c\ub098\uc5d0\uc11c \uc774 \uacf5\uac04\uc744 \ub9cc\ub4e4\uae30 \uc2dc\uc791\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc608\uc220 \uad50\uc721\uacfc \ub9c8\uc744 \ud589\uc0ac\ub97c \uc704\ud55c \uacf3\uc774\uc5c8\ub2e4. \uadf8\ub294 \uc5b4\ub9b0 \uc2dc\uc808 \uace0\ud5a5\uc5d0\uc11c \ub3c4\uc790\uae30\uc640 \ubc14\uad6c\ub2c8 \ub9cc\ub4e4\uae30, \uadf8\ub9bc \uac19\uc740 \uc9c0\uc5ed\uc758 \uc608\uc220\uacfc \uacf5\uc608\ub97c \uc811\ud588\ub2e4. \uc774\ud6c4 \ub3c4\uc2dc\ub85c \ub098\uac00 \uc77c\ud558\uace0 \uadf8\ub9bc\uc744 \ubc30\uc6b0\uba70 \uc790\uc2e0\uc758 \uae38\uc744 \ub113\ud614\ub2e4\uace0 \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \uc774 \ub300\ubaa9\uc740 \uadf8\ub97c \uc544\ubb34\ub7f0 \ubc30\uc6c0\ub3c4 \uc5c6\uc774 \ub4f1\uc7a5\ud55c \ud2b9\ubcc4\ud55c \ucc9c\uc7ac\ub85c \ubcf4\ub294 \uc0dd\uac01\uacfc \ub2e4\ub974\ub2e4. \ub9c8\uc744\uc5d0\uc11c \ub9cc\ub09c \uc190\uc77c\uacfc \ub3c4\uc2dc\uc5d0\uc11c\uc758 \ubc30\uc6c0, \ub2e4\ub978 \uc608\uc220\uac00\ub4e4\uacfc\uc758 \uad00\uacc4\uac00 \ud568\uaed8 \uc313\uc778 \uc0b6\uc774\uc5c8\ub2e4. \uace0\ud5a5\uc758 \ubb38\ud654 \uacf5\uac04\ub3c4 \uadf8\ub7f0 \uc2dc\uac04\uc744 \ub5a0\uc62c\ub9ac\uba70 \ubcfc \uc218 \uc788\ub2e4. \ubbf8\uc220\uad00\uc740 \ubb38\ud654\uc13c\ud130\uc758 \uac74\ucd95\uc5d0 \uae30\ud558\ud559\uc801 \uad6c\uc131\uacfc \uc0b0\uc5c5 \uc7ac\ub8cc\uac00 \uc4f0\uc600\uace0, \ub465\uadfc \ucc3d\uacfc \uaca9\uc790, \uc778\ubb3c \ud615\ud0dc\uc758 \ubcbd\uba74 \ubd80\uc870 \uac19\uc740 \uc694\uc18c\uac00 \ub354\ud574\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uce5c\uad6c\uc774\uc790 \ud6c4\uc6d0\uc790\uc600\ub358 \uac74\ucd95\uac00 \ud310\ucd08 \uac8c\ub4dc\uc2a4\uc640\uc758 \uad00\uacc4\ub3c4 \ud568\uaed8 \uc18c\uac1c\ud55c\ub2e4. \uc774\ub984\ub09c \uac74\ucd95 \uc591\uc2dd\uc744 \uba3c\uc800 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub465\uadfc \ucc3d\uc73c\ub85c \ube5b\uc774 \ub4e4\uc5b4\uc624\uace0 \ubcbd\uc5d0\ub3c4 \ubb34\uc5b8\uac00\ub97c \ud45c\ud604\ud560 \uc790\ub9ac\uac00 \uc788\ub294 \uacf5\uac04\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc5ec\uae30\uc758 \uc0bd\ud654\ub294 \uadf8 \uc0dd\uac01\uc744 \ub3d5\ub294 \uac1c\ub150 \uadf8\ub9bc\uc774\uba70 \uc2e4\uc81c \uac74\ubb3c\uc744 \uadf8\ub300\ub85c \uadf8\ub9b0 \uc0ac\uc9c4\uc740 \uc544\ub2c8\ub2e4. \ubb38\ud654\uc13c\ud130\uac00 \uad50\uc721\uacfc \ub9c8\uc744 \ud589\uc0ac\ub97c \uc704\ud574 \uc2dc\uc791\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc778\uc0c1\uc801\uc774\ub2e4. \uc608\uc220\uc744 \uba40\ub9ac \uc788\ub294 \uc804\uc2dc\uc7a5\uc5d0\uc11c\ub9cc \ub9cc\ub098\ub294 \ub300\uc2e0 \uc790\uc2e0\uc774 \uc790\ub780 \uacf3\uc5d0\uc11c \ubc30\uc6b0\uace0 \ubaa8\uc77c \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uc120\ud0dd\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc774 \ud654\uac00\ub294 \uadf8\ub9bc\ubfd0 \uc544\ub2c8\ub77c \uae00\uacfc \uc2dc, \uad50\uc721\uacfc \uc870\uac01\uc5d0\uc11c\ub3c4 \ud65c\ub3d9\ud588\ub2e4. \uace0\ud5a5\uc758 \uacf5\uac04\uc740 \uadf8 \uc5ec\ub7ec \uc77c\uc744 \ub2f4\uc744 \ub610 \ud558\ub098\uc758 \ud615\ud0dc\ub85c \uc77d\ud78c\ub2e4. \uadf8\ub9bc \ud55c \uc810\uc744 \ub0a8\uae30\ub294 \uac83\uacfc \ud568\uaed8, \ub2e4\uc74c \uc0ac\ub78c\uc774 \ubb34\uc5b8\uac00\ub97c \uc2dc\uc791\ud560 \uc790\ub9ac\ub3c4 \ub9cc\ub4e4\uace0 \uc2f6\uc5c8\ub358 \uac83\uc774\ub2e4."}, {"id": "palace-roof-pangolin", "title": "\uad81\uad90 \uc9c0\ubd95 \uc704\uc5d0\ub294 \ub0af\uc120 \ub3d9\ubb3c\uc774 \uc549\uc544 \uc788\uc5c8\ub2e4", "summary": "\ub192\uc740 \uc9c0\ubd95\uc5d0\uc11c \uba40\ub9ac \ubcf4\uc774\ub358 \uc791\uc740 \uc870\uac01\uc0c1\uc744 \uac00\uae4c\uc774 \ubd05\ub2c8\ub2e4.", "category": "cities", "category_title": "Cities", "subcategory": "Asia", "url": "stories/palace-roof-pangolin/index.html", "image": "media/palace-roof-pangolin.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc7a1\uc0c1 '\ucc9c\uc0b0\uac11' \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uad81\uad90 \uc9c0\ubd95 \uc704\uc5d0\ub294 \ub0af\uc120 \ub3d9\ubb3c\uc774 \uc549\uc544 \uc788\uc5c8\ub2e4 \uadfc\uc815\ubb38\uc5d0\uc11c \ub0b4\ub824\uc628 \ucc9c\uc0b0\uac11 \uc7a1\uc0c1 \ub192\uc740 \uc9c0\ubd95\uc5d0\uc11c \uba40\ub9ac \ubcf4\uc774\ub358 \uc791\uc740 \uc870\uac01\uc0c1\uc744 \uac00\uae4c\uc774 \ubd05\ub2c8\ub2e4. Asia \ub3c4\uc2dc \uad81\uad90 \uc9c0\ubd95\uc744 \uc62c\ub824\ub2e4\ubcf4\uba74 \ub05d\ubd80\ubd84\uc744 \ub530\ub77c \uc791\uc740 \ud615\uc0c1\ub4e4\uc774 \ub298\uc5b4\uc11c \uc788\ub2e4. \uba40\ub9ac\uc11c\ub294 \uc724\uacfd\ub9cc \ubcf4\uc5ec\uc11c \ubaa8\ub450 \ube44\uc2b7\ud55c \uc870\uac01\ucc98\ub7fc \ub290\uaef4\uc9c0\uae30 \uc27d\ub2e4. \uac00\uae4c\uc774 \ubcf4\uba74 \uadf8\uc911 \ud558\ub098\ub294 \uad75\uc740 \ubaa9\uacfc \uc791\uc740 \uc5bc\uad74\uc744 \uac00\uc9c4 \ub0af\uc120 \ubaa8\uc2b5\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \ucc9c\uc0b0\uac11\uc774\ub77c\uace0 \uc18c\uac1c\ud558\ub294 \uc7a1\uc0c1\uc774\ub2e4. \uacbd\ubcf5\uad81 \uadfc\uc815\ubb38 \uc9c0\ubd95\uc758 \ucd94\ub140\ub9c8\ub8e8\uc5d0 \uc62c\ub838\ub358 \uac83 \uac00\uc6b4\ub370 \ud558\ub098\ub2e4. \uc6d0\ub798\ub294 \uace0\uac1c\ub97c \ud55c\ucc38 \ub4e4\uc5b4\uc57c \ubcf4\uc558\uc744 \ubb3c\uac74\uc744 \uc774\uc81c \uc0ac\uc9c4\uc5d0\uc11c \ub208\ub192\uc774\ub85c \ub9cc\ub09c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc774 \uc7a1\uc0c1\uc5d0 \ubfd4\uacfc \ube44\ub298\uc774 \uc788\uace0 \ub4f1\uc5d0 \uaddc\uce59\uc801\uc778 \ub3cc\uae30\uac00 \ub3cb\uc558\ub2e4\uace0 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \uc5bc\uad74\ubcf4\ub2e4 \ubab8\uc744 \ub530\ub77c \uc774\uc5b4\uc9c0\ub294 \uad74\uace1\uc774 \uba3c\uc800 \uc778\uc0c1\uc5d0 \ub0a8\uc744 \uc218\ub3c4 \uc788\ub2e4. \ud55c \ubc29\ud5a5\uc5d0\uc11c\ub9cc \ubcf4\uace0 \ub3d9\ubb3c \uc774\ub984 \ub9de\ud788\uae30\ub97c \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ucc9c\uc0b0\uac11\uc744 \ud615\uc0c1\ud654\ud55c \uc9c0\ubd95 \uc7a5\uc2dd\uc774\ub77c\ub294 \ubc15\ubb3c\uad00\uc758 \uba85\uce6d\uacfc \uc2e4\uc81c \uc870\uac01\uc758 \ud2b9\uc9d5\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc0b4\uc544 \uc788\ub294 \ub3d9\ubb3c\uc758 \ubab8\uc744 \uc815\ud655\ud788 \uc7ac\ud604\ud55c \ubaa8\ud615\uc73c\ub85c \uc0dd\uac01\ud560 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc740 1867\ub144 \uadfc\uc815\ubb38\uc744 \ub2e4\uc2dc \uc138\uc6b8 \ub54c \ub610\ub294 \uadf8 \uc774\ud6c4\uc5d0 \uc9c0\ubd95\uc5d0 \uc62c\ub9b0 \uc7a1\uc0c1\uc774\ub77c\uace0 \ud55c\ub2e4. \ub531 \ud55c \ud574\uc5d0 \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ubabb \ubc15\ub294 \ub300\uc2e0 \uac00\ub2a5\ud55c \uc2dc\uae30\ub97c \uc5f4\uc5b4 \ub193\uc740 \uc124\uba85\uc774\ub2e4. \uc774 \ucc28\uc774\ub294 \uc791\uc544 \ubcf4\uc5ec\ub3c4 \ubb3c\uac74\uc758 \uc774\ub825\uc744 \uc774\ud574\ud560 \ub54c \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac74\ubb3c\uc774 \ub2e4\uc2dc \uc138\uc6cc\uc9c4 \ud574\ub97c \uc548\ub2e4\uace0 \uadf8 \uc704\uc758 \ubaa8\ub4e0 \uc7a5\uc2dd\uc774 \uadf8\ub0a0 \ud568\uaed8 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4\uace0 \uc815\ud560 \uc218\ub294 \uc5c6\ub294 \uac83\uc774\ub2e4. \uc775\uc219\ud55c \uad81\uad90\uc5d0\ub3c4 \uc774\ub807\uac8c \uc870\uae08\uc529 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud560 \uc2dc\uac04\uc774 \ub0a8\uc544 \uc788\ub2e4. \uad81\uad90\uc5d0 \uac00\uba74 \ud070 \ubb38\uc774\ub098 \ud604\ud310\uc744 \uba3c\uc800 \ucc3e\uae30 \uc27d\ub2e4. \uc774 \uc7a1\uc0c1\uc744 \ud55c \ubc88 \ubcf4\uace0 \ub098\uba74 \uc2dc\uc120\uc774 \uc9c0\ubd95\uc758 \uac00\uc7a5\uc790\ub9ac\ub85c\ub3c4 \ud5a5\ud560 \uac83 \uac19\ub2e4. \uc791\uac8c \ubcf4\uc774\ub358 \uc724\uacfd \ud558\ub098\ud558\ub098\uc5d0 \uc11c\ub85c \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \uc0c1\uc9d5\uc758 \ub73b\uc744 \uc804\ubd80 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uad1c\ucc2e\ub2e4. \uc624\ub298\uc740 \uad75\uc740 \ubaa9\uacfc \ub4f1 \uc704\uc758 \ub3cc\uae30 \uc815\ub3c4\ub9cc \uae30\uc5b5\ud574 \ubcf4\uc790. \uc774\ub984\uc870\ucc28 \ub0af\uc124\ub358 \uc870\uac01 \ud558\ub098\uac00 \ub2e4\uc74c \uad81\uad90 \uc0b0\ucc45\uc5d0\uc11c \ub208\uae38\uc744 \ubd99\uc7a1\ub294 \ud45c\uc9c0\uac00 \ub420 \uc218 \uc788\ub2e4."}, {"id": "book-owner-seal", "title": "\ucc45\uc5d0\ub3c4 \uc8fc\uc778\uc758 \uc774\ub984\ud45c\ub97c \ucc0d\uc5b4 \ub450\uc5c8\ub2e4", "summary": "\uc774\ub984\uc744 \uc4f0\uac70\ub098 \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc774\ub4ef, \ucc45\uc5d0 \ub3c4\uc7a5\uc744 \ucc0d\uc5b4 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/book-owner-seal/index.html", "image": "media/book-owner-seal.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00 \uc18c\uc7a5 \uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778 \uc778\uc7a5\uc758 \ub3cc \ubab8\uccb4 \ubaa8\uc2b5", "text": "\ucc45\uc5d0\ub3c4 \uc8fc\uc778\uc758 \uc774\ub984\ud45c\ub97c \ucc0d\uc5b4 \ub450\uc5c8\ub2e4 \uc791\uc740 \uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778\uc774 \uc54c\ub824\uc8fc\ub294 \ucc45\uacfc \ub3c4\uc7a5\uc758 \uad00\uacc4 \uc774\ub984\uc744 \uc4f0\uac70\ub098 \uc2a4\ud2f0\ucee4\ub97c \ubd99\uc774\ub4ef, \ucc45\uc5d0 \ub3c4\uc7a5\uc744 \ucc0d\uc5b4 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\uae30\ub3c4 \ud588\uc2b5\ub2c8\ub2e4. Literature \ubb38\ud654 \ucc45\uc744 \ube4c\ub824\uc8fc\uae30 \uc804\uc5d0 \uccab \uc7a5\uc5d0 \uc774\ub984\uc744 \uc368 \ub454 \uacbd\ud5d8\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \ub098\uc911\uc5d0 \ub3cc\uc544\uc654\uc744 \ub54c \ub204\uad6c\uc758 \ucc45\uc778\uc9c0 \uc54c\uc544\ubcfc \uc218 \uc788\uac8c \ud558\ub824\ub294 \uc791\uc740 \ud45c\uc2dc\ub2e4. \uc61b \ucc45\uacfc \uc11c\ud654\uc5d0\uc11c\ub294 \uadf8\ub7f0 \uc5ed\ud560\uc744 \ud558\ub294 \ub3c4\uc7a5\ub3c4 \ub9cc\ub09c\ub2e4. \uc7a5\uc11c\uc778\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc5d0\ub294 \u2018\uc5f0\uacbd\uc7ac\uc7a5\uc11c\uc778\u2019\uc774\ub77c\ub294 \uae00\uc790\ub97c \uc0c8\uae34 \ub3cc\ub3c4\uc7a5\uc774 \uc788\ub2e4. \uc0ac\uc9c4 \uc18d\uc758 \ubab8\uccb4\ub294 \uc190\uc5d0 \ub4e4\uc5b4\uc62c \ub9cc\ud55c \ud06c\uae30\uc758 \uc791\uc740 \ub3cc\uc774\ub2e4. \uadf8\ub7f0\ub370 \uadf8 \ub3c4\uc7a5\uc774 \ub0a8\uae30\ub294 \uae00\uc790\uc5d0\ub294 \ucc45\uc774 \uba38\ubb3c\ub358 \uacf3\uc758 \uc774\ub984\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc778\uc7a5\uc774 \uc5f0\uacbd\uc7ac\uc5d0 \uc18c\uc7a5\ud55c \uc11c\uc801\uacfc \uc11c\ud654 \ub4f1\uc5d0 \ucc0d\ub358 \uac83\uc774\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc81c\ubaa9\uc758 \u2018\uc7a5\uc11c\u2019\ub294 \ucc45\uc744 \ubaa8\uc544 \uc18c\uc7a5\ud55c\ub2e4\ub294 \ub9d0\uc774\ub2e4. \ub3c4\uc7a5\uc740 \uc791\uc740 \uc774\ub984\ud45c\uac00 \ub418\uc5b4 \uc18c\uc7a5 \uad00\uacc4\ub97c \ub4dc\ub7ec\ub0c8\ub2e4. \uc11c\uba85\uacfc \ub2ee\uc740 \uc810\ub3c4 \uc788\uc9c0\ub9cc \ud55c \ubc88 \uc0c8\uae34 \uae00\uc790\ub97c \uc5ec\ub7ec \uacf3\uc5d0 \ubc18\ubcf5\ud574 \ucc0d\uc744 \uc218 \uc788\ub2e4\ub294 \ucc28\uc774\uac00 \uc788\ub2e4. \ucc45\uc774 \uc5ec\ub7ec \uad8c\uc774\uc5b4\ub3c4 \uac19\uc740 \ub3c4\uc7a5\uc73c\ub85c \ud45c\uc2dc\ud560 \uc218 \uc788\ub2e4. \uc190\uc73c\ub85c \ub9e4\ubc88 \uac19\uc740 \uae00\uc790\ub97c \uc4f0\ub294 \uac83\uacfc\ub294 \ub2e4\ub978 \uc7ac\ubbf8\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc61b \ucc45\uc758 \ub3c4\uc7a5\uc774 \ubaa8\ub450 \uac19\uc740 \ubaa9\uc801\uc774\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc740 \uc18c\uc7a5\uc744 \ud45c\uc2dc\ud558\ub294 \uc7a5\uc11c\uc778 \ud55c \uc810\uc774\ub2e4. \uc778\uc7a5\uc758 \uc138\uacc4\uc5d0\ub294 \uad6d\uac00 \uc5c5\ubb34\uc6a9 \ub3c4\uc7a5\ubd80\ud130 \uac1c\uc778\uc774 \uc4f0\ub294 \ub3c4\uc7a5\uae4c\uc9c0 \uc5ec\ub7ec \uc885\ub958\uac00 \uc788\uc5c8\ub2e4. \uc774 \uc778\uc7a5\uc758 \uc0ac\uc6a9\uc790\uc5d0 \ub300\ud574 \ubc15\ubb3c\uad00\uc740 \u2018\ud5cc\uc885 \ucd94\uc815\u2019\uc774\ub77c\uace0 \uc801\uc5b4 \ub454\ub2e4. \ud5cc\uc885\uc774 \uc0ac\uc6a9\ud588\ub2e4\uace0 \ud655\uc815\ud558\ub294 \ub300\uc2e0, \ud604\uc7ac\uc758 \ud310\ub2e8\uc5d0 \uc5ec\uc9c0\ub97c \ub0a8\uae34 \uc124\uba85\uc774\ub2e4. \uc720\ubb3c \uc774\ub984\uc774 \ub610\ub837\ud558\uac8c \uc801\ud600 \uc788\uc5b4\ub3c4 \uadf8 \uc774\ub825\uc758 \ubaa8\ub4e0 \ubd80\ubd84\uc744 \uac19\uc740 \uc815\ub3c4\ub85c \uc544\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubb34\uc5c7\uc774 \uc0c8\uaca8\uc838 \uc788\ub294\uc9c0\uc640 \ub204\uac00 \uc2e4\uc81c\ub85c \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \ub2e4\ub978 \uc9c8\ubb38\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc5d0\ub294 \ud5cc\uc885\uc774 \uc5ec\ub7ec \uc61b \uc778\uc7a5\uc744 \uc218\uc9d1\ud558\uace0 \uac10\uc0c1\ud588\uc73c\uba70 \uac1c\uc778\uc6a9 \uc778\uc7a5\ub3c4 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uc774\uc57c\uae30\uac00 \ud568\uaed8 \ub098\uc628\ub2e4. \ub2e4\ub9cc \uadf8 \uc77c\ubc18\uc801\uc778 \ubc30\uacbd\uc774 \uc774 \ud55c \uc810\uc758 \uc0ac\uc6a9\uc790 \ucd94\uc815\uc744 \ud655\uc815\uc73c\ub85c \ubc14\uafb8\uc5b4 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \ucc59\uae38 \uac83\uc740 \uc5b4\ub824\uc6b4 \uc655\uc2e4 \uacc4\ubcf4\ubcf4\ub2e4 \uc774 \uc791\uc740 \ub9d0\uc758 \ucc28\uc774\ub2e4. \u2018\ucd94\uc815\u2019\uc774\ub77c\ub294 \ub450 \uae00\uc790\ub97c \uadf8\ub300\ub85c \ub450\uc5b4\ub3c4 \ub3c4\uc7a5\uc744 \uad6c\uacbd\ud558\ub294 \uc7ac\ubbf8\ub294 \ucda9\ubd84\ud558\ub2e4. \ucc45\uc5d0\uc11c \uc77d\uc744\uac70\ub9ac\ub294 \ubcf8\ubb38\uc5d0\ub9cc \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uc801\uc740 \uc790\ub9ac, \uc18c\uc7a5 \ud45c\uc2dc, \ub204\uad70\uac00 \ub0a8\uae34 \uba54\ubaa8\ub3c4 \uadf8 \ucc45\uc774 \uc9c0\ub098\uc628 \uc2dc\uac04\uc744 \uc0dd\uac01\ud558\uac8c \ud55c\ub2e4. \uc7a5\uc11c\uc778\uc744 \ubcf4\uba74 \uae00\uc790\ub97c \uc77d\ub294 \ubc29\uc2dd\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb38\uc7a5\uc758 \ub73b\ub9cc \uc774\ud574\ud558\ub824\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uc65c \uadf8 \uc790\ub9ac\uc5d0 \uadf8 \uc774\ub984\uc744 \ub0a8\uacbc\ub294\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uac19\uc740 \ucc45\uc774\ub77c\ub3c4 \ub204\uad6c\uc758 \ucc45\uc7a5\uc5d0 \uc788\uc5c8\ub294\uc9c0\uac00 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30\uac00 \ub420 \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \uc624\ub798\ub41c \ucc45\uc758 \uccab \uc7a5\uc5d0\uc11c \uc791\uc740 \uc778\uc7a5\uc744 \ubc1c\uacac\ud55c\ub2e4\uba74 \ubcf8\ubb38\uc73c\ub85c \ubc14\ub85c \ub118\uc5b4\uac00\uae30 \uc804\uc5d0 \uc7a0\uae50 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ucc45\uc5d0 \ub2f4\uae34 \uc774\uc57c\uae30 \uc606\uc5d0, \ucc45\uc744 \uac00\uc9c0\uace0 \uc788\ub358 \uc0ac\ub78c\uc758 \ud754\uc801\uc774 \ucc0d\ud600 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "building-repair-letter", "title": "\uac74\ubb3c\uc744 \uace0\uce58\ub294 \uc77c\uc740 \uae00\ub85c\ub3c4 \ub0a8\uc558\ub2e4", "summary": "\ub0a1\uc740 \uac74\ubb3c\uc744 \uc190\ubcf4\ub294 \uc77c\uc5d0\ub3c4 \uae30\ub150\ubb38\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\uc11c \uc61b \uacf5\uc0ac\uc758 \uc0ac\uc815\uc744 \uc77d\uc5b4 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Architecture", "url": "stories/building-repair-letter/index.html", "image": "media/building-repair-letter.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00 \uc18c\uc7a5 \uc120\ub989 \uc815\uc790\uac01 \uc911\uc218 \uc0c1\ub7c9\ubb38\uc758 \uae00\uc528\uac00 \ubcf4\uc774\ub294 \uacf5\uac1c \uc0ac\uc9c4", "text": "\uac74\ubb3c\uc744 \uace0\uce58\ub294 \uc77c\uc740 \uae00\ub85c\ub3c4 \ub0a8\uc558\ub2e4 \uc120\ub989 \uc815\uc790\uac01 \uc0c1\ub7c9\ubb38\uc5d0 \ub2f4\uae34 \uc218\ub9ac\uc758 \uae30\ub85d \ub0a1\uc740 \uac74\ubb3c\uc744 \uc190\ubcf4\ub294 \uc77c\uc5d0\ub3c4 \uae30\ub150\ubb38\uc774 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc885\uc774 \ud55c \uc7a5\uc5d0\uc11c \uc61b \uacf5\uc0ac\uc758 \uc0ac\uc815\uc744 \uc77d\uc5b4 \ubd05\ub2c8\ub2e4. Architecture \ubb38\ud654 \uc624\ub798\ub41c \uac74\ubb3c \uc55e\uc5d0\uc11c\ub294 \uc5b8\uc81c \ucc98\uc74c \uc138\uc6e0\ub294\uc9c0\ubd80\ud130 \ubb3b\uac8c \ub41c\ub2e4. \ud558\uc9c0\ub9cc \ucc98\uc74c \uc9c0\uc740 \ub0a0\ub9cc\uc73c\ub85c \uac74\ubb3c\uc758 \uae34 \uc2dc\uac04\uc744 \ub2e4 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uae30\uc6b8\uc5b4\uc9c4 \uacf3\uc744 \ubc14\ub85c\uc7a1\uace0 \uc624\ub798\ub41c \ubd80\ubd84\uc744 \uace0\uce5c \uc2dc\uac04\ub3c4 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\uc120\ub989 \uc815\uc790\uac01 \uc911\uc218 \uc0c1\ub7c9\ubb38\u300d\uc740 \uadf8\ub7f0 \uc77c\uc744 \uae00\ub85c \ub0a8\uae34 \uc790\ub8cc\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \ubcf4\uba74 \uc885\uc774 \uc704\uc5d0 \uae00\uc790\uac00 \uae38\uac8c \uc774\uc5b4\uc838 \uc788\ub2e4. \uac74\ubb3c\uc758 \uadf8\ub9bc\uc774\ub098 \uc124\uacc4\ub3c4\ub97c \uae30\ub300\ud588\ub2e4\uba74 \uc870\uae08 \ub2e4\ub978 \ubaa8\uc2b5\uc774\ub2e4. \uc774 \uae00\uc5d0\ub294 \ubb34\uc5c7\uc744 \uace0\ucce4\uace0 \uc65c \uc190\uc744 \ubcf4\uc544\uc57c \ud588\ub294\uc9c0\uac00 \ub2f4\uaca8 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc0c1\ub7c9\ubb38\uc774 1706\ub144 \uc120\ub989\uc758 \uc815\uc790\uac01\uc744 \uc911\uac74\ud560 \ub54c \uc791\uc131\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub79c \uc138\uc6d4 \ub3d9\uc548 \uc11d\ubb3c\uacfc \uc815\uc790\uac01\uc744 \ubcf4\uc218\ud574\uc57c \ud55c\ub2e4\ub294 \ud544\uc694\uac00 \uc81c\uae30\ub418\uc5c8\uace0, \uc2e4\uc81c\ub85c \uae30\uc6b8\uc5b4\uc9c4 \uac74\ubb3c\uc744 \ub2e4\uc2dc \uc190\ubcf4\uac8c \ub41c \uac83\uc774\ub2e4. \uae00\uc744 \uc9c0\uc740 \uc0ac\ub78c\uc740 \uc870\uc120 \ud6c4\uae30\uc758 \ubb38\uc2e0 \ucd5c\uc11d\ud56d\uc774\ub2e4. \uac19\uc740 \ub0b4\uc6a9\uc774 \uadf8\uc758 \ubb38\uc9d1\uc5d0\ub3c4 \uc2e4\ub824 \uc788\ub2e4\uace0 \ud55c\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \ub0a8\uc740 \uc885\uc774\uc640 \ucc45 \uc18d\uc758 \uae00\uc774 \uc11c\ub85c \uc5f0\uacb0\ub41c\ub2e4. \uc0c1\ub7c9\ubb38\uc740 \uac74\ubb3c\uc744 \uc138\uc6b0\uac70\ub098 \uace0\uce58\ub294 \uc77c\uc744 \uae30\ub150\ud558\uace0 \uc798 \ub9c8\ubb34\ub9ac\ub418\uae30\ub97c \ubc14\ub77c\ub294 \uae00\uc774\ub2e4. \uc774 \uc790\ub8cc\uc758 \ubc88\uc5ed\uc5d0\uc11c\ub3c4 \uae30\ub465\uacfc \ucc98\ub9c8\uac00 \ube44\ubc14\ub78c\uc744 \uacaa\uc740 \uc0ac\uc815, \uc218\uc120\uc744 \ub2a6\ucd9c \uc218 \uc5c6\ub2e4\ub294 \ub73b\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uacf5\uc0ac\ub97c \uc544\ub984\ub2e4\uc6b4 \uc77c\ub85c\ub9cc \uafb8\ubbf8\ub294 \uae00\uc778 \uc904 \uc54c\uc558\ub294\ub370, \uc624\ub798\ub41c \uac74\ubb3c\uc774 \uacac\ub38c \uc628 \ubb38\uc81c\ub3c4 \ud568\uaed8 \ubcf4\uc778\ub2e4. \uc624\ub298\uc758 \uc218\ub9ac \uae30\ub85d\uc5d0\uc11c \ubc1c\uacac\ud560 \ubc95\ud55c \uc0ac\uc815\uc774 \uc61b \ubb38\uc7a5 \uc548\uc5d0\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc124\uacc4\ub3c4\ub77c\uba74 \uce58\uc218\uc640 \uad6c\uc870\ub97c \uba3c\uc800 \ubcf4\uac8c \ub420 \uac83\uc774\ub2e4. \uc0c1\ub7c9\ubb38\uc5d0\uc11c\ub294 \uac74\ubb3c\uc744 \ub300\ud558\ub294 \ud0dc\ub3c4\uc640 \uacf5\uc0ac\uc758 \uc758\ubbf8\uac00 \uc55e\uc5d0 \ub098\uc628\ub2e4. \uac19\uc740 \uac74\ubb3c\uc744 \ub0a8\uae30\ub294 \uc790\ub8cc\uc5ec\ub3c4 \ub9e1\uc740 \uc5ed\ud560\uc774 \ub2e4\ub974\ub2e4. \uc774 \uae00\uc740 \uae30\uc874 \uc81c\ub3c4\ub97c \ub530\ub974\uba70 \ud130\ub97c \ub354 \ub113\ud788\uc9c0 \uc54a\uc558\ub2e4\ub294 \uc810, \uac10\ub3c5\uc744 \ub9e1\uaca8 \uc77c\uc744 \uc9c4\ud589\ud588\ub2e4\ub294 \uc810\ub3c4 \uc774\uc57c\uae30\ud55c\ub2e4. \uc774\ub7f0 \ub300\ubaa9\uc740 \ud654\ub824\ud55c \uc218\uc0ac \uc0ac\uc774\uc5d0 \ub193\uc5ec \uc788\uc5b4 \uadf8\ub0e5 \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \ubb3c\ub860 \uc0c1\ub7c9\ubb38 \ud55c \ud3b8\ub9cc\uc73c\ub85c \uacf5\uc0ac\uc758 \ubaa8\ub4e0 \uacfc\uc815\uc744 \ubcf5\uc6d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub204\uac00 \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \uc5f0\uc7a5\uc744 \ub4e4\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc54c\ub824\uc8fc\ub294 \uc791\uc5c5 \uc77c\uc9c0\ub294 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc65c \uacf5\uc0ac\uac00 \ud544\uc694\ud588\uace0 \uc5b4\ub5bb\uac8c \uc758\ubbf8\ub97c \ubd80\uc5ec\ud588\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 \ucc3d\uc740 \ub41c\ub2e4. \uc6d0\ubb38\uc758 \ud55c\uc790\ub97c \ubaa8\ub450 \uc77d\uc9c0 \ubabb\ud574\ub3c4 \uad1c\ucc2e\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc790\ub8cc\uc758 \uc124\uba85\uacfc \ubc88\uc5ed\uc744 \ud568\uaed8 \uacf5\uac1c\ud55c\ub2e4. \uae00\uc758 \uc81c\ubaa9\uacfc \uc791\uc131 \ubc30\uacbd\uc744 \uc54c\uace0 \ubcf4\uba74 \uc885\uc774 \uc704\uc758 \ube7d\ube7d\ud55c \uae00\uc528\ub3c4 \ub2e4\ub978 \uc778\uc0c1\uc744 \uc900\ub2e4. \uc624\ub798\ub41c \uac74\ubb3c\uc740 \ucc98\uc74c \ubaa8\uc2b5 \uadf8\ub300\ub85c \uc2dc\uac04\uc774 \uba48\ucd98 \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc77c \ub54c\uac00 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uadf8 \ubaa8\uc2b5\uc744 \uc774\uc5b4 \uac00\uae30 \uc704\ud574 \ub204\uad70\uac00\ub294 \uc190\uc744 \ubcf4\uc558\uace0, \ub54c\ub85c\ub294 \uadf8 \uc77c\uc744 \uae00\ub85c \ub0a8\uacbc\ub2e4. \ub2e4\uc74c\uc5d0 \uc720\uc11c \uae4a\uc740 \uac74\ubb3c\uc744 \uad6c\uacbd\ud55c\ub2e4\uba74 \ucc3d\uac74 \uc5f0\ub3c4 \uc606\uc758 \uc911\uc218\ub098 \uc911\uac74 \uae30\ub85d\ub3c4 \ud55c\ubc88 \uc0b4\ud3b4\ubcf4\uc790. \uc624\ub798\ub418\uc5c8\ub2e4\ub294 \ud55c\ub9c8\ub514 \uc548\uc5d0, \uc624\ub798 \ubc84\ud2f0\uac8c \ud558\ub824\ub358 \uc5ec\ub7ec \ubc88\uc758 \uc77c\uc774 \uc811\ud600 \uc788\ub2e4."}, {"id": "chicago-floating-stair-detail", "title": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4", "summary": "\ubcbd\uacfc \uacc4\ub2e8, \uc758\uc790 \uc544\ub798\uc758 \uac00\ub290\ub2e4\ub780 \ud2c8\uc5d0 \uc8fc\ubaa9\ud569\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Architecture", "url": "stories/chicago-floating-stair-detail/index.html", "image": "media/chicago-floating-stair-detail.jpg", "alt": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uacc4\ub2e8 \uc544\ub798\uc758 \uc791\uc740 \ud2c8\uc774 \uac74\ubb3c\uc744 \uac00\ubccd\uac8c \ub9cc\ub4e0\ub2e4 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc5d0\uc11c \ubc14\ub2e5\uc744 \ud55c \ubc88 \ub354 \ubcf4\ub294 \ubc29\ubc95 \ubcbd\uacfc \uacc4\ub2e8, \uc758\uc790 \uc544\ub798\uc758 \uac00\ub290\ub2e4\ub780 \ud2c8\uc5d0 \uc8fc\ubaa9\ud569\ub2c8\ub2e4. Architecture \ubb38\ud654 \ud070 \uac74\ubb3c\uc744 \ubcf4\uace0 \uac00\ubccd\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc744 \ub54c\uac00 \uc788\ub2e4. \uc2e4\uc81c \ubb34\uac8c\uac00 \uac00\ubcbc\uc6b8 \ub9ac\ub294 \uc5c6\ub294\ub370 \ubcbd\uc774\ub098 \uacc4\ub2e8\uc774 \uc0b4\uc9dd \ub5a0 \uc788\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \uc21c\uac04\uc774\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \ubaa8\ub358 \uc719 \uc124\uba85\uc5d0\ub294 \uadf8 \ub290\ub08c\uc744 \ub9cc\ub4dc\ub294 \uc791\uc740 \ud2c8\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc124\uacc4\uc790\ub294 \uc774\ud0c8\ub9ac\uc544 \uac74\ucd95\uac00 \ub80c\ucd08 \ud53c\uc544\ub178\ub2e4. \ubbf8\uc220\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uadf8\uc758 \uc0dd\uac01 \uac00\uc6b4\ub370 \ud558\ub098\ub294 \uac74\ubb3c\uc774 \ub5a0\uc624\ub974\ub4ef \ubcf4\uc774\uac8c \ud558\ub294 \uc81c\ub85c \uadf8\ub798\ube44\ud2f0\ub77c\ub294 \ud45c\ud604\uc774\ub2e4. \ub9d0\uc740 \uac70\ucc3d\ud558\uc9c0\ub9cc \ub208\uc5ec\uaca8\ubcfc \uacf3\uc740 \uc758\uc678\ub85c \ubc1c\ubc11\uc774\ub2e4. \uae30\uad00\uc758 \uae00\uc740 \ubcbd \uc544\ub7ab\ubd80\ubd84\uc5d0 \uc57d 1\uc778\uce58\uc758 \ub4dc\ub7ec\ub09c \ud2c8\uc774 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc57d 2.5\uc13c\ud2f0\ubbf8\ud130\ub2e4. \ubcbd \uc804\uccb4\uc5d0 \ube44\ud558\uba74 \uc791\uc740 \ub192\uc774\uc9c0\ub9cc \ubc14\ub2e5\uacfc \ubcbd \uc0ac\uc774\uc5d0 \uac00\ub290\ub2e4\ub780 \uc120\uc744 \ub9cc\ub4e0\ub2e4. \ubcbd\uc740 \ub2f9\uc5f0\ud788 \ubc14\ub2e5\uc5d0 \ub2ff\uc544 \uc788\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uadf8 \ub9cc\ub098\ub294 \uc790\ub9ac\ub97c \uc870\uae08 \ub2e4\ub974\uac8c \ucc98\ub9ac\ud558\uba74 \ub369\uc5b4\ub9ac\uc758 \ub290\ub08c\ub3c4 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \ucc9c\uc7a5\ub9cc \uc62c\ub824\ub2e4\ubcf4\ub358 \uc2dc\uc120\uc744 \uc544\ub798\ub85c \ub0b4\ub9ac\ub294 \uc774\uc720\uac00 \uc0dd\uae34\ub2e4. \uae00\uc5d0 \ub530\ub974\uba74 \ud53c\uc544\ub178\uac00 \ub514\uc790\uc778\ud55c \ubca4\uce58\ub3c4 \uc791\uc740 \ubc1b\uce68 \uc704\uc5d0 \ub193\uc5ec \ubc14\ub2e5\uc5d0\uc11c \uc870\uae08 \uc62c\ub77c\uac00 \uc788\ub2e4. \uc870\uac01\uc758 \ubc1b\uce68\ub300\uc640 \ub2e8 \uc5ed\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ub5a8\uc5b4\uc838 \ubcf4\uc774\ub3c4\ub85d \ud588\uc73c\uba70, \ud070 \uacc4\ub2e8 \uc544\ub798\uc5d0\ub3c4 \ud2c8\uc774 \uc788\ub2e4. \ubcbd \ud558\ub098\uc5d0\ub9cc \ub123\uc740 \uc6b0\uc5f0\ud55c \uc7a5\uc2dd\uc774 \uc544\ub2c8\ub77c \uc5ec\ub7ec \ubd80\ubd84\uc5d0\uc11c \uc774\uc5b4\uc9c0\ub294 \uc120\ud0dd\uc774\uc5c8\ub2e4. \ub2e4\ub978 \ubaa8\uc591\uc758 \uac00\uad6c\uc640 \uad6c\uc870\ubb3c\uc774 \ube44\uc2b7\ud55c \ubc29\uc2dd\uc73c\ub85c \ubc14\ub2e5\uc744 \ub9cc\ub098\uba74 \uacf5\uac04 \uc804\uccb4\uc5d0\ub3c4 \uacf5\ud1b5\ub41c \uc778\uc0c1\uc774 \ub9cc\ub4e4\uc5b4\uc9c4\ub2e4. \ubb3c\ub860 \uac74\ubb3c\uc774 \uc2e4\uc81c\ub85c \uacf5\uc911\uc5d0 \ub9e4\ub2ec\ub838\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uae30\uad00 \uae00\uc740 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc811\uc810\uacfc \ud2c8\uc774 \uac00\ubcbc\uc6b4 \uc778\uc0c1\uc744 \uc8fc\ub294 \ubc29\uc2dd\uc744 \uc124\uba85\ud55c\ub2e4. \uad6c\uc870\ub97c \uc9c0\ud0f1\ud558\ub294 \uc6d0\ub9ac\ub97c \uc804\ubd80 \uc54c\uc544\uc57c\ub9cc \uc990\uae38 \uc218 \uc788\ub294 \ub300\ubaa9\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc0c8\ub85c\uc6b4 \uac74\ubb3c\uc5d0 \ub4e4\uc5b4\uac00\uba74 \ucc3d\ubb38\uc774\ub098 \uba4b\uc9c4 \ucc9c\uc7a5\uc744 \ubcf8 \ub4a4 \uc758\uc790 \ubc11\ub3c4 \ud55c \ubc88 \ubcf4\uc790. \ubc14\ub2e5\uacfc \ub9cc\ub098\ub294 \uc120\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub918\ub294\uc9c0 \uc0b4\ud53c\ub294 \uac83\uc774\ub2e4. \uac74\ucd95\uac00\uc758 \uc0dd\uac01\uc774 \uac00\uc7a5 \uc791\uc740 \uadf8\ub9bc\uc790\ucc98\ub7fc \ub0a8\uc544 \uc788\ub294 \uc790\ub9ac\uc77c \uc218 \uc788\ub2e4."}, {"id": "dokseodang-gathering", "title": "\uadf8\ub9bc \uc18d \ubc43\ub180\uc774\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \uc788\ub2e4", "summary": "\ud55c\uac15\uc5d0\uc11c \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4, \uadf8\ub9ac\uace0 \uadf8\ub9bc \uc544\ub798 \ube7d\ube7d\ud55c \uae00\uc528. \uc624\ub798\ub41c \ubaa8\uc784 \uadf8\ub9bc\uc5d0\ub294 \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0\ub3c4 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/dokseodang-gathering/index.html", "image": "media/dokseodang-gathering.jpg", "alt": "\uc704\ucabd \uc81c\ubaa9\uacfc \uac00\uc6b4\ub370 \ud55c\uac15 \ud48d\uacbd, \uc544\ub798\ucabd \ucc38\uc11d\uc790 \uba85\ub2e8\uc73c\ub85c \uad6c\uc131\ub41c \ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4 \uc871\uc790 \uc804\uccb4", "text": "\uadf8\ub9bc \uc18d \ubc43\ub180\uc774\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \uc788\ub2e4 \ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4\uc5d0 \ub0a8\uc740 \uc5f4\ub450 \uc0ac\ub78c\uc758 \ubaa8\uc784 \ud55c\uac15\uc5d0\uc11c \ubc30\ub97c \ud0c4 \uc0ac\ub78c\ub4e4, \uadf8\ub9ac\uace0 \uadf8\ub9bc \uc544\ub798 \ube7d\ube7d\ud55c \uae00\uc528. \uc624\ub798\ub41c \ubaa8\uc784 \uadf8\ub9bc\uc5d0\ub294 \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0\ub3c4 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \uc61b \uadf8\ub9bc\uc744 \ubcfc \ub54c \uae00\uc528\ub294 \uc77c\ub2e8 \uac74\ub108\ub6f0\uac8c \ub41c\ub2e4. \uc0b0\uc774 \uc5b4\ub514 \uc788\ub294\uc9c0, \uc0ac\ub78c\uc740 \ubb34\uc5c7\uc744 \ud558\ub294\uc9c0\ubd80\ud130 \ucc3e\uc544\ubcf4\ub294 \ud3b8\uc774 \uc27d\ub2e4. \ud55c\uc790\uac00 \ube7d\ube7d\ud558\uac8c \uc801\ud600 \uc788\uc73c\uba74 \uadf8\ub9bc \uc124\uba85\uc774\uaca0\uac70\ub2c8 \ud558\uace0 \uc9c0\ub098\uce58\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\ub3c5\uc11c\ub2f9\uacc4\ud68c\ub3c4\u300d\uc5d0\uc11c\ub294 \uc544\ub798\ucabd \uae00\uc528\uc5d0\ub3c4 \uc7a0\uae50 \ub208\uc744 \uc8fc\uba74 \uc88b\uaca0\ub2e4. \uac70\uae30\uc5d0\ub294 \uc774 \ubaa8\uc784\uc5d0 \ucc38\uc11d\ud55c \uc0ac\ub78c\ub4e4\uc758 \uc774\ub984\uc774 \uc801\ud600 \uc788\ub2e4. \uadf8\ub9bc \uc18d\uc5d0\uc11c\ub294 \uad00\ubcf5 \ucc28\ub9bc\uc758 \uc0ac\ub78c\ub4e4\uc774 \ud55c\uac15\uc5d0\uc11c \ubc43\ub180\uc774\ub97c \ud55c\ub2e4. \ub290\uae0b\ud55c \ud48d\uacbd\ud654\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc791\ud488\uc740 \ubaa8\uc784\uc758 \uae30\uc5b5\uacfc \ucc38\uc11d\uc790 \uc815\ubcf4\ub97c \ud568\uaed8 \ub0a8\uaca8 \ub450\uc5c8\ub2e4. \uc624\ub298\uc758 \ub2e8\uccb4 \uae30\ub150\uc0ac\uc9c4 \ub4a4\uc5d0 \uc774\ub984\uc744 \uc801\uc5b4 \ub193\ub294 \ubaa8\uc2b5\uc774 \uc870\uae08 \ub5a0\uc624\ub978\ub2e4. \uc81c\ubaa9\uc758 \u2018\uacc4\ud68c\ub3c4\u2019\ub294 \ubaa8\uc784\uc744 \uae30\ub150\ud558\ub294 \uadf8\ub9bc\uc774\ub77c\ub294 \ub73b\uc73c\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc774 \uc791\ud488\uc740 \uc0ac\uac00\ub3c5\uc11c\ud55c \uc774\ub825\uc774 \uc788\ub294 \uad00\ub8cc\ub4e4\uc758 \ubaa8\uc784\uc744 \uae30\ub150\ud574 \ub9cc\ub4e4\uc5c8\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \uc0ac\uac00\ub3c5\uc11c\ub294 \ud734\uac00\ub97c \ubc1b\uc544 \ub3c5\uc11c\uc5d0 \uc804\ub150\ud558\ub294 \uc77c\uc744 \uac00\ub9ac\ud0a8\ub2e4. \ucc45 \uc77d\ub358 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc600\ub2e4\uace0 \ud558\ub2c8 \uadf8\ub9bc \uc18d\uc5d0\uc11c\ub3c4 \ubaa8\ub450 \ucc45\uc0c1 \uc55e\uc5d0 \uc549\uc544 \uc788\uc744 \uac83 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uae30\ub85d\ub41c \ubaa8\uc784\uc758 \ubaa8\uc2b5\uc740 \ub2e4\ub974\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ubc30\ub97c \ud0d4\uace0, \uadf8 \uc8fc\ubcc0\uc73c\ub85c \uac15\uacfc \uc0b0\uc774 \ud3bc\uccd0\uc838 \uc788\ub2e4. \uadf8\ub807\ub2e4\uace0 \uad00\ub9ac\ub4e4\uc774 \ubab0\ub798 \uc77c\uc744 \ube7c\uba39\uc5c8\ub2e4\uace0 \uc0c1\uc0c1\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8\ub9bc\uc740 \ubaa8\uc784\uc758 \ud55c \uc7a5\uba74\uc744 \ubcf4\uc5ec\uc904 \ubfd0, \uc0ac\ub78c\ub4e4\uc774 \uc8fc\uace0\ubc1b\uc740 \ub9d0\uc774\ub098 \uadf8\ub0a0\uc758 \uc18d\uc0ac\uc815\uae4c\uc9c0 \uc54c\ub824\uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uad00\ubcf5\uacfc \ubc43\ub180\uc774\uac00 \ud55c \ud654\uba74\uc5d0 \uc788\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ub208\uae38\uc744 \ub048\ub2e4. \ud48d\uacbd\uc740 \ub9c9\uc5f0\ud788 \uba4b\uc9c4 \uc0b0\uc218\ub97c \uadf8\ub824 \ub123\uc740 \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub3c5\uc11c\ub2f9\uc774 \uc788\ub358 \ud55c\uac15\ubcc0 \ub450\ubaa8\ud3ec, \uc9c0\uae08\uc758 \uc11c\uc6b8 \uc131\ub3d9\uad6c \uc625\uc218\ub3d9 \uc77c\ub300\uac00 \ubb18\uc0ac\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud654\uba74 \uac00\uc6b4\ub370 \uc19f\uc740 \uc751\ubd09\uc740 \ud604\uc7ac\uc758 \ub9e4\ubd09\uc0b0\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc9c0\uae08 \uc544\ub294 \uc11c\uc6b8\uc758 \uc9c0\uba85\uacfc \uc5f0\uacb0\ud574 \ubcf4\uba74 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \ud48d\uacbd\uc744 \ud1b5\uc9f8\ub85c \ud604\uc7ac\uc758 \uc9c0\ub3c4\uc640 \ub9de\ucd9c \ud544\uc694\ub294 \uc5c6\ub2e4. \ud55c\uac15\ubcc0\uc758 \uc5b4\ub290 \uc7a5\uc18c\ub97c \uae30\uc5b5\ud558\uba70 \uadf8\ub838\ub2e4\ub294 \ub2e8\uc11c \uc815\ub3c4\ub9cc \ucc59\uaca8\ub3c4 \uc88b\ub2e4. \uc774 \uc791\ud488\uc740 \uc704\uc5d0\uc11c \uc544\ub798\ub85c \uc77d\ub294 \uc21c\uc11c\uac00 \uc788\ub2e4. \ub9e8 \uc704\uc5d0\ub294 \uc81c\ubaa9, \uac00\uc6b4\ub370\uc5d0\ub294 \ubaa8\uc784 \uc7a5\uba74, \uc544\ub798\uc5d0\ub294 \ucc38\uc11d\uc790 \uba85\ub2e8\uc774 \ub193\uc778\ub2e4. \uba40\ub9ac\uc11c \ubcf4\uba74 \uae34 \uc871\uc790 \ud558\ub098\uc9c0\ub9cc, \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc11c\ub85c \ub2e4\ub978 \uc77c\uc744 \ud558\ub294 \uc138 \ubd80\ubd84\uc774 \ubaa8\uc5ec \uc788\ub2e4. \uc544\ub798\ucabd \uba85\ub2e8\uc740 \u2018\uc88c\ubaa9\u2019\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc774 \uadf8\ub9bc\uc758 \uc88c\ubaa9\uc5d0\ub294 \uc5f4\ub450 \uc0ac\ub78c\uc758 \ud638\uc640 \uc774\ub984\ubfd0 \uc544\ub2c8\ub77c \ubcf8\uad00\uacfc \uc0dd\ub144, \uacfc\uac70\uc5d0 \uae09\uc81c\ud55c \uc5f0\ub3c4, \uc0ac\uac00\ub3c5\uc11c\ub97c \ud55c \uc2dc\uae30, \ub2f9\uc2dc \ud488\uacc4\uc640 \uad00\uc9c1\uae4c\uc9c0 \uc801\ud600 \uc788\ub2e4. \uc774\ub984\ub9cc \uc801\uc5b4\ub3c4 \uae30\ub150\uc740 \ub420 \ud150\ub370 \uaf64 \uaf3c\uaf3c\ud558\ub2e4. \ubaa8\uc784\uc5d0 \ub204\uac00 \uc788\uc5c8\ub294\uc9c0\uc640 \uadf8 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \uc774\ub825\uc744 \uc9c0\ub154\ub294\uc9c0\ub97c \ud568\uaed8 \ub0a8\uacbc\ub2e4. \ud6c4\ub300\uc758 \uad00\ub78c\uac1d\uc5d0\uac8c\ub294 \uadf8\ub9bc \uc606\uc5d0 \uc791\uc740 \uc778\ubb3c \uc18c\uac1c\uac00 \ubd99\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uba85\ub2e8\uc758 \ud55c\uc790\ub97c \ubaa8\ub450 \uc77d\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub9bc\uc5d0\uc11c \uc0ac\ub78c\uc744 \ucc3e\uc740 \ub4a4 \uc544\ub798\uc758 \uae00\uc528\ub85c \ub208\uc744 \uc62e\uaca8 \ubcf4\uba74 \ub41c\ub2e4. \ub208\uc55e\uc758 \uc7a5\uba74\uacfc \uadf8 \uc7a5\uba74\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\ub78c\ub4e4\uc758 \uae30\ub85d\uc774 \ud55c \uc791\ud488 \uc548\uc5d0 \ub098\ub780\ud788 \uc788\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc791\ud488\uc744 1531\ub144\uacbd\uc758 \uadf8\ub9bc\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ud654\uba74\uc758 \uc5b4\ub290 \uad6c\uc11d\uc5d0 \ud070 \uc22b\uc790\ub85c \uc5f0\ub3c4\uac00 \uc801\ud600 \uc788\uc5b4\uc11c\uc77c\uae4c? \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc81c\uc791 \uc2dc\uae30\ub97c \ucd94\uc815\ud558\ub294 \uadfc\uac70\ub294 \uc88c\ubaa9\uc5d0 \uc801\ud78c \uad00\uc9c1\uc774\ub2e4. \ub4f1\uc7a5\uc778\ubb3c\ub4e4\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uc790\ub9ac\uc5d0 \uc788\uc5c8\ub294\uc9c0\ub97c \uc0b4\ud53c\uba74, \uadf8\ub9bc\uc774 \ub9cc\ub4e4\uc5b4\uc9c4 \ub54c\ub97c \uc881\ud600 \ubcfc \uc218 \uc788\ub2e4. \ud48d\uacbd\ubcf4\ub2e4 \uc544\ub798\ucabd\uc758 \uae00\uc528\uac00 \ub0a0\uc9dc\uc758 \ub2e8\uc11c\ub97c \uc8fc\ub294 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \u2018\uacbd\u2019\uc774\ub77c\ub294 \ub9d0\ub3c4 \ub193\uce58\uc9c0 \uc54a\ub294 \ud3b8\uc774 \uc88b\ub2e4. 1531\ub144\uc758 \uc5b4\ub290 \ud558\ub8e8\ub97c \uc815\ud655\ud558\uac8c \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ub0a8\uc544 \uc788\ub294 \uc815\ubcf4\ub97c \ubc14\ud0d5\uc73c\ub85c \uadf8 \ubb34\ub835\uc774\ub77c\uace0 \ucd94\uc815\ud55c\ub2e4\ub294 \ub73b\uc774\ub2e4. \ubaa8\ub974\ub294 \ubd80\ubd84\uae4c\uc9c0 \ucc44\uc6cc \ub123\uc9c0 \uc54a\uc544\ub3c4 \uadf8\ub9bc\uc758 \uc7ac\ubbf8\uac00 \uc904\uc5b4\ub4e4\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub2e8\uccb4\uc0ac\uc9c4\uc744 \uc624\ub798 \ubcf4\uad00\ud558\ub2e4\uac00 \ub204\uad70\uac00\uc758 \uc774\ub984\uc774\ub098 \ub2f9\uc2dc\uc758 \uc77c\uc744 \ub5a0\uc62c\ub9b0 \uacbd\ud5d8\uc774 \uc788\uc744 \uac83\uc774\ub2e4. \uc774 \uadf8\ub9bc\uc5d0\uc11c\ub294 \uadf8 \ub2e8\uc11c\uac00 \uc791\ud488 \uc544\ub798\uc5d0 \ucc98\uc74c\ubd80\ud130 \ud568\uaed8 \uc801\ud600 \uc788\uc5c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \uadf8\ub9bc \uc18d\uc758 \uc0ac\ub78c\ub4e4\uc774 \ubaa8\uc5ec \uc788\ub294 \uc7a5\uba74\uc744 \ub9cc\ub098\uba74 \ud48d\uacbd\ub9cc \ubcf4\uace0 \uc9c0\ub098\uce58\uc9c0 \ub9d0\uace0 \uc8fc\ubcc0\uc758 \uae00\uc528\ub3c4 \ud55c\ubc88 \uc0b4\ud3b4\ubcf4\uc790. \uc77d\uae30 \uc5b4\ub824\uc6b4 \uae00\uc790 \uc0ac\uc774\uc5d0, \ub204\uac00 \ud568\uaed8\ud588\ub294\uc9c0 \uc78a\uc9c0 \uc54a\uc73c\ub824 \ub0a8\uae34 \uba85\ub2e8\uc774 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "el-greco-painting-journey", "title": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4", "summary": "\uba54\ub9ac \ucee4\uc0db\uc774 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc744 \ubbf8\uc220\uad00\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/el-greco-painting-journey/index.html", "image": "media/el-greco-painting-journey.jpg", "alt": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc720\uba85\ud55c \uadf8\ub9bc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \uac70\uc808\ub2f9\ud588\ub2e4 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc791\ud488\uc744 \uc704\ud574 \ubc1c \ubc97\uace0 \ub098\uc120 \ud654\uac00 \uba54\ub9ac \ucee4\uc0db\uc774 \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc744 \ubbf8\uc220\uad00\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \uc9c0\uae08 \ubbf8\uc220\uad00\uc758 \ub300\ud45c \uc791\ud488\uc774\ub77c\uace0 \ud574\uc11c \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450\uac00 \uac16\uace0 \uc2f6\uc5b4 \ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5d8 \uadf8\ub808\ucf54\uc758 \uc131\ubaa8\uc2b9\ucc9c\uc5d0\ub3c4 \uc120\ub73b \uc0c8 \uc9d1\uc744 \ucc3e\uc9c0 \ubabb\ud558\ub358 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc758 \uacf5\uc2dd \uae00\uc740 \uc774 \uc791\ud488\uc774 \uc5ec\ub7ec \uae30\uad00\uc758 \uac70\uc808\uc744 \uc9c0\ub098 \uc18c\uc7a5\ud488\uc774 \ub41c \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc774\uc57c\uae30\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \ub2e4\ub978 \ud654\uac00 \uba54\ub9ac \ucee4\uc0db\uc774 \uc788\ub2e4. \uc790\uae30 \uadf8\ub9bc\uc774 \uc544\ub2cc \uc791\ud488\uc744 \uc704\ud574 \uafb8\uc900\ud788 \uc0ac\ub78c\ub4e4\uc744 \uc124\ub4dd\ud55c \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc5d0 \ub530\ub974\uba74 \uc791\ud488\uc740 1904\ub144\uc5d0 \uc2dc\uc7a5\uc5d0 \ub098\uc654\ub2e4. \ub2f9\uc2dc \uc5d8 \uadf8\ub808\ucf54\uc758 \ud3c9\ud310\uc740 \uc9c0\uae08 \uc6b0\ub9ac\uac00 \uc0dd\uac01\ud558\ub294 \uac83\uacfc \uac19\uc9c0 \uc54a\uc558\ub2e4. \ub9c8\ub4dc\ub9ac\ub4dc\uc5d0\uc11c \ud314\ub9ac\uc9c0 \ubabb\ud55c \uc791\ud488\uc740 1904\ub144\ubd80\ud130 1905\ub144\uae4c\uc9c0 \ud30c\ub9ac\uc758 \ub4a4\ub791\ub93c\uc5d8 \ud654\ub791\uc5d0\uc11c \uc804\uc2dc\ub418\uc5c8\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ucee4\uc0db\uc744 \ube44\ub86f\ud55c \ud654\uac00\ub4e4\uc774 \uc774 \uc791\ud488\uc5d0 \uad00\uc2ec\uc744 \uac00\uc84c\ub2e4. \ub204\uad70\uac00\uc5d0\uac8c\ub294 \ud314\uae30 \uc5b4\ub824\uc6b4 \uc624\ub798\ub41c \uadf8\ub9bc\uc774 \ub2e4\ub978 \ub204\uad70\uac00\uc5d0\uac8c\ub294 \uaf2d \ubbf8\uc220\uad00\uc5d0 \uc788\uc5b4\uc57c \ud560 \uadf8\ub9bc\uc774\uc5c8\ub358 \uc148\uc774\ub2e4. \ucee4\uc0db\uc740 \uba3c\uc800 \uce5c\uad6c\uc778 \ud558\ube0c\ub9c8\uc774\uc5b4 \ubd80\ubd80\uac00 \ud654\ub791\uc758 \uc791\ud488 \uad6c\uc785\uc744 \uc9c0\uc6d0\ud558\ub3c4\ub85d \uc124\ub4dd\ud588\ub2e4. \uc774\ud6c4 \ubbf8\uad6d \ubbf8\uc220\uad00\ub4e4\uc774 \uad00\uc2ec\uc744 \uac16\ub3c4\ub85d \uc6c0\uc9c1\uc600\ub2e4. \uc791\ud488\uc758 \ub2e4\uc74c \uc8fc\uc18c\ub97c \ucc3e\ub294 \uc77c\uc774 \ud55c \uc0ac\ub78c\uc758 \ubd80\ud0c1\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc558\ub358 \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc758 \uae00\uc740 \ub274\uc695\uacfc \ud544\ub77c\ub378\ud53c\uc544, \ubcf4\uc2a4\ud134\uc5d0\uc11c \uac70\uc808\uc774 \uc774\uc5b4\uc84c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc624\ub298\uc758 \uba85\uc131\ub9cc \uc0dd\uac01\ud558\uba74 \ub180\ub78d\uc9c0\ub9cc, \uadf8\ub54c\uc758 \uae30\uad00\ub4e4\uc740 \uac01\uc790\uc758 \ud310\ub2e8\uc744 \ud588\ub2e4. \uc720\uba85\ud574\uc9c4 \ub4a4\uc758 \ud3c9\uac00\ub97c \uacfc\uac70\uc5d0 \uadf8\ub300\ub85c \uac00\uc838\uac00\uba74 \ubcf4\uc774\uc9c0 \uc54a\ub294 \ub300\ubaa9\uc774\ub2e4. \ub9c8\uce68\ub0b4 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc774 \uad00\uc2ec\uc744 \ubcf4\uc600\uc9c0\ub9cc \uc790\uae08\uc744 \ubaa8\uc73c\ub294 \ub370\uc5d0\ub3c4 19\uac1c\uc6d4\uc774 \uac78\ub838\ub2e4\uace0 \ud55c\ub2e4. \uc791\ud488\uc740 \ub3c4\ucc29\ud55c \ub4a4 \ubbf8\uc220\uad00\uc744 \ub300\ud45c\ud558\ub294 \uadf8\ub9bc \uac00\uc6b4\ub370 \ud558\ub098\uac00 \ub418\uc5c8\ub2e4. \ud55c \uadf8\ub9bc\uc758 \uc790\ub9ac\ub97c \ub9cc\ub4e0 \uac83\uc740 \ud654\uac00\uc758 \uc190\uae38\ub9cc\uc774 \uc544\ub2c8\uc5c8\ub2e4. \ub2e4\ub978 \ud654\uac00\uc758 \uad00\uc2ec, \uce5c\uad6c\ub4e4\uc758 \uc9c0\uc6d0, \uae30\uad00\uc758 \uacb0\uc815\uacfc \uae30\ub2e4\ub9bc\uc774 \ud568\uaed8 \uc788\uc5c8\ub2e4. \uc804\uc2dc\uc7a5 \ubcbd\uc5d0 \uac78\ub9b0 \ud55c \uc810\uc744 \ubcfc \ub54c \uadf8 \ubcbd\uae4c\uc9c0 \uc624\ub294 \uae38\ub3c4 \uc788\uc5c8\ub2e4\ub294 \uac83\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \uc774\uc57c\uae30\ub2e4."}, {"id": "glass-photo-pillow-ruler", "title": "\uc61b \ubca0\uac1c \uc0ac\uc9c4 \uc606\uc5d0\ub294 \uc65c \uc790\uac00 \uc11c \uc788\uc744\uae4c", "summary": "\uc720\ub9ac\uac74\ud310\uc5d0 \ub0a8\uc740 \ubca0\uac1c \uc0ac\uc9c4\uc5d0\uc11c \ub208\uae08\uc790\uc640 \ubc88\ud638\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/glass-photo-pillow-ruler/index.html", "image": "media/glass-photo-pillow-ruler.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc31\uc790\ubca0\uac1c \uc720\ub9ac\uac74\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \ubca0\uac1c \uc0ac\uc9c4 \uc606\uc5d0\ub294 \uc65c \uc790\uac00 \uc11c \uc788\uc744\uae4c \uc8fc\uc778\uacf5\ub9cc\ud07c \uc911\uc694\ud55c \uc0ac\uc9c4 \uc18d \uc870\uc5f0 \uc720\ub9ac\uac74\ud310\uc5d0 \ub0a8\uc740 \ubca0\uac1c \uc0ac\uc9c4\uc5d0\uc11c \ub208\uae08\uc790\uc640 \ubc88\ud638\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4. Art \ubb38\ud654 \uc624\ub798\ub41c \ud751\ubc31 \uc0ac\uc9c4 \ud55c \uc7a5\uc744 \ubcf4\uc790. \uac00\uc6b4\ub370\uc5d0\ub294 \ubca0\uac1c\uac00 \ub193\uc5ec \uc788\uace0 \uc624\ub978\ucabd\uc5d0\ub294 \uae34 \ub9c9\ub300\uac00 \uc11c \uc788\ub2e4. \uae30\ub150\uc0ac\uc9c4\uc774\ub77c\uba74 \uce58\uc6cc \ub450\uc5c8\uc744 \uac83 \uac19\uc740 \ubb3c\uac74\uc778\ub370, \uc774 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ud568\uaed8 \ub0a8\uc544 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \ubc31\uc790\ubca0\uac1c \uc720\ub9ac\uac74\ud310\uc774\ub2e4. \uc774 \uc790\ub8cc\uc5d0\uc11c \ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uac83\uc740 \uc0ac\uc9c4\uc744 \ub2f4\uc740 \uc720\ub9ac\uac74\ud310\uc774\uba70, \uc0ac\uc9c4 \uc18d \ubca0\uac1c \uc790\uccb4\uc640\ub294 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \ud55c \uc7a5\uc758 \uc0ac\uc9c4\uc5d0\ub3c4 \uc11c\ub85c \ub2e4\ub978 \ubb3c\uac74\uc758 \uc774\ub825\uc774 \uacb9\uce5c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uc624\ub978\ucabd \ub9c9\ub300\ub97c \ud06c\uae30 \uce21\uc815\uc6a9 \uc790\ub77c\uace0 \uc54c\ub824 \uc900\ub2e4. \uc0ac\uc9c4\ub9cc \ubcf4\uba74 \ubca0\uac1c\uac00 \uc190\ubc14\ub2e5\ub9cc \ud55c\uc9c0, \ud6e8\uc52c \ud070\uc9c0 \uac00\ub2a0\ud558\uae30 \uc5b4\ub835\ub2e4. \uacc1\uc5d0 \uc120 \uc790\ub294 \uadf8 \ud310\ub2e8\uc744 \ub3d5\ub294 \uc5ed\ud560\uc744 \ud55c\ub2e4. \uc624\ub298 \uc911\uace0 \ubb3c\ud488 \uc0ac\uc9c4\uc5d0 \ub3d9\uc804\uc774\ub098 \uc790\ub97c \ud568\uaed8 \ub193\ub294 \uc77c\uc744 \ub5a0\uc62c\ub824\ub3c4 \uc88b\ub2e4. \uc0ac\uc9c4\uc740 \ubaa8\uc591\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ub370 \ub2a5\ud558\uc9c0\ub9cc \ud06c\uae30\ub97c \uc800\uc808\ub85c \uc124\uba85\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub798\ub41c \ucd2c\uc601\uc5d0\ub3c4 \uadf8 \ube48\ud2c8\uc744 \ucc44\uc6b8 \ub3c4\uad6c\uac00 \ud544\uc694\ud588\ub358 \uac83\uc774\ub2e4. \uc0ac\uc9c4 \uc18d \uc624\ub978\ucabd\uc5d0\ub294 \ucd2c\uc601 \ub2f9\uc2dc \ubc88\ud638 6014\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc0ac\uc9c4 \uc18d \ubca0\uac1c\uac00 \uc911\uad6d \ub3c4\uc790\uc774\uba70 \ud604\uc7ac \uad6d\ub9bd\uc911\uc559\ubc15\ubb3c\uad00\uc758 \ub355\uc2182165\ub85c \uc18c\uc7a5\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ucd2c\uc601 \ubc88\ud638\uc640 \uc9c0\uae08\uc758 \uc18c\uc7a5\ud488 \ubc88\ud638\ub294 \uac19\uc740 \uac83\uc774 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc22b\uc790\uac00 \ub2e4\ub974\ub2e4\uace0 \uc0ac\uc9c4\uc774 \uc798\ubabb\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \uc22b\uc790\uac00 \uc0ac\uc9c4\uc744 \uc704\ud55c \uae30\ub85d\uc774\uace0 \uc5b4\ub290 \uc22b\uc790\uac00 \ubb3c\uac74\uc744 \ucc3e\ub294 \ud45c\uc9c0\uc778\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \ud55c\uacb0 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \uc124\uba85\uc5d0\ub294 \ubca0\uac1c\uc758 \ud30c\uc190\ub41c \uc717\ubd80\ubd84\uc774 \uc218\ub9ac\ub418\uc5c8\ub2e4\ub294 \ub0b4\uc6a9\ub3c4 \uc788\ub2e4. \uc644\ubcbd\ud55c \uc678\ud615\ub9cc \uae30\ub85d\ud55c \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\ub54c \ub0a8\uc544 \uc788\ub358 \uc0c1\ud0dc \uc5ed\uc2dc \uc0ac\uc9c4\uacfc \uc124\uba85 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uc148\uc774\ub2e4. \uc774 \uc0ac\uc9c4\uc744 \ubcfc \ub54c \ubca0\uac1c \ubb34\ub2ac\ub97c \ubaa8\ub450 \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc606\uc758 \uc790\uc640 \ubc88\ud638\ubd80\ud130 \ucc3e\uc544\ubcf4\uc790. \ubb3c\uac74\uc744 \uc544\ub984\ub2f5\uac8c \ubcf4\uc5ec \uc8fc\ub294 \uc0ac\uc9c4\uacfc \ubb3c\uac74\uc744 \uc815\ud655\ud558\uac8c \ub0a8\uae30\ub294 \uc0ac\uc9c4\uc774 \uc5b4\ub5a4 \uc810\uc5d0\uc11c \ub2e4\ub978\uc9c0, \uc791\uc740 \uc870\uc5f0\ub4e4\uc774 \uc870\uc6a9\ud788 \uc54c\ub824 \uc900\ub2e4."}, {"id": "harp-colored-strings", "title": "\ud558\ud504 \uc904\uc5d0\ub294 \uc65c \ube68\uac04\uc0c9\uc774 \uc11e\uc5ec \uc788\uc744\uae4c", "summary": "\uba40\ub9ac\uc11c\ub294 \ubaa8\ub450 \ube44\uc2b7\ud574 \ubcf4\uc774\ub294 \ud558\ud504\uc758 \uc904. \uac00\uae4c\uc774 \ubcf4\uba74 \uc5f0\uc8fc\uc790\ub97c \uc704\ud55c \uc791\uc740 \uc0c9\uae54 \ud45c\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/harp-colored-strings/index.html", "image": "media/harp-colored-strings.jpg", "alt": "\ubc1d\uc740 \uc904 \uc0ac\uc774\uc5d0 \ubd89\uace0 \uc5b4\ub450\uc6b4 \uc904\uc774 \uc11e\uc778 \ud558\ud504 \uc77c\ubd80\ub97c \uadf8\ub9b0 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud558\ud504 \uc904\uc5d0\ub294 \uc65c \ube68\uac04\uc0c9\uc774 \uc11e\uc5ec \uc788\uc744\uae4c \uc218\ub9ce\uc740 \ud604 \uc0ac\uc774\uc5d0\uc11c \uae38\uc744 \ucc3e\ub294 \uc0c9\uae54 \uba40\ub9ac\uc11c\ub294 \ubaa8\ub450 \ube44\uc2b7\ud574 \ubcf4\uc774\ub294 \ud558\ud504\uc758 \uc904. \uac00\uae4c\uc774 \ubcf4\uba74 \uc5f0\uc8fc\uc790\ub97c \uc704\ud55c \uc791\uc740 \uc0c9\uae54 \ud45c\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ud558\ud504\ub97c \ubcf4\uba74 \uba3c\uc800 \uc904\uc758 \uc218\uc5d0 \uc555\ub3c4\ub41c\ub2e4. \uae38\uace0 \uc9e7\uc740 \uc904\uc774 \ub098\ub780\ud788 \uc11c \uc788\uc5b4\uc11c, \uc5b4\ub514\ub97c \uc9da\uc5b4\uc57c \uc6d0\ud558\ub294 \uc18c\ub9ac\uac00 \ub098\ub294\uc9c0 \uc7a0\uae50 \ub9c9\ub9c9\ud574\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uac00\uae4c\uc774 \ubcf4\uba74 \ubaa8\ub4e0 \uc904\uc774 \uac19\uc740 \uc0c9\uc740 \uc544\ub2c8\ub2e4. \ube68\uac04 \uc904\uc774 \uc11e\uc5ec \uc788\uace0 \uc5b4\ub450\uc6b4 \uc904\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uc73c\ub85c \uc0c9\uc744 \ub123\uc740 \uac83 \uac19\uc9c0\ub9cc, \uc5f0\uc8fc\uc790\uac00 \uc904\uc744 \ucc3e\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc8fc\ub294 \ud45c\uc2dc\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc758 \ud558\ud504 \uc548\ub0b4\ub294 \ub3c4\uc5d0 \ud574\ub2f9\ud558\ub294 C \uc904\uc744 \ube68\uac04\uc0c9, \ud30c\uc5d0 \ud574\ub2f9\ud558\ub294 F \uc904\uc744 \uac80\uc740\uc0c9\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \ube7d\ube7d\ud55c \uc904 \uc0ac\uc774\uc5d0 \uc54c\uc544\ubcf4\uae30 \uc26c\uc6b4 \uae30\uc900\uc810\uc744 \ub454 \uac83\uc774\ub2e4. \uc774\uc57c\uae30\uc758 \ub300\uc0c1\uc740 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ud604\ub300\uc801\uc778 \ud398\ub2ec \ud558\ud504\ub2e4. \uc548\ub0b4\uc5d0 \ub530\ub974\uba74 \uc774 \ud558\ud504\uc5d0\ub294 47\uac1c\uc758 \uc904\uc774 \uc788\ub2e4. \uc904\ub9c8\ub2e4 \uc190\uae00\uc528 \uc774\ub984\ud45c\ub97c \ub2ec\uae30\ubcf4\ub2e4 \uc0c9\uc73c\ub85c \uc790\ub9ac\ub97c \uad6c\ubd84\ud558\uba74 \uc5f0\uc8fc \uc911\uc5d0\ub3c4 \ub208\uc5d0 \ube68\ub9ac \ub4e4\uc5b4\uc628\ub2e4. \uc6b0\ub9ac\ub3c4 \ube44\uc2b7\ud55c \ud45c\uc2dc\ub97c \uc4f4\ub2e4. \uc790\uc8fc \ucc3e\ub294 \ucc45\uc5d0 \uc0c9\uae54 \ucabd\uc9c0\ub97c \ubd99\uc774\uac70\ub098, \ube44\uc2b7\ud55c \uc5f4\uc1e0\ub97c \uad6c\ubd84\ud558\ub824 \uace0\ub9ac\ub97c \ub2ec \ub54c\uac00 \uc788\ub2e4. \ud558\ud504\uc758 \uc904\uc5d0\uc11c\ub294 \uc0c9\uc774 \uadf8 \uc791\uc740 \uae38\uc7a1\uc774 \uc5ed\ud560\uc744 \ud55c\ub2e4. \ud558\ud504\ub97c \ubcf4\ub294 \uc2dc\uc120\uc740 \ubcf4\ud1b5 \uc190\uc5d0 \uba38\ubb38\ub2e4. \ud558\uc9c0\ub9cc \uc544\ub798\uc5d0\ub294 \uc77c\uacf1 \uac1c\uc758 \ud398\ub2ec\ub3c4 \uc788\ub2e4. \uc774 \ud398\ub2ec\uc740 \uac19\uc740 \uc774\ub984\uc758 \uc74c\uc5d0 \ud574\ub2f9\ud558\ub294 \uc904\ub4e4\uc758 \uc74c\ub192\uc774\ub97c \ubc14\uafb8\ub294 \ub370 \uc4f0\uc778\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 C \ud398\ub2ec\uc744 \ubc14\uafb8\uba74 \uc5ec\ub7ec \ub192\uc774\uc5d0 \uc788\ub294 C \uc904\ub4e4\uc774 \ud568\uaed8 \uc601\ud5a5\uc744 \ubc1b\ub294\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc904 \ud558\ub098\ub9c8\ub2e4 \ubc1c\ud310 \ud558\ub098\uac00 \uc788\ub294 \uad6c\uc870\ub294 \uc544\ub2cc \uac83\uc774\ub2e4. \uadf8\ub798\uc11c \uc5f0\uc8fc\uc790\ub294 \uc190\uc73c\ub85c \uc904\uc744 \ub72f\ub294 \ub3d9\uc548\uc5d0\ub3c4 \ubc1c\ubc11\uc758 \uc0c1\ud0dc\ub97c \uc0b4\ud540\ub2e4. \uc26c\ub294 \uad6c\uac04\uc774 \ubcf4\uc778\ub2e4\uace0 \uc644\uc804\ud788 \ud560 \uc77c\uc774 \uc5c6\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \ud544\uc694\ud55c \uc18c\ub9ac\ub97c \uc704\ud574 \ud398\ub2ec\uc744 \ubc14\uafb8\ub294 \uc2dc\uac04\uc77c \uc218\ub3c4 \uc788\ub2e4. \ud558\ud504\uc758 \uace1\uc120\uacfc \uc904\uc740 \uba40\ub9ac\uc11c\ub3c4 \uc544\ub984\ub2f5\ub2e4. \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uadf8 \uc544\ub984\ub2e4\uc6b4 \ubaa8\uc2b5 \uc548\uc5d0 \uc5f0\uc8fc\ub97c \ub3d5\ub294 \uc7a5\uce58\uac00 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uac83\uc774 \ubcf4\uc778\ub2e4. \uc0c9\uae54\uc740 \uc704\uce58\ub97c, \ud398\ub2ec\uc740 \uc74c\uc758 \ubcc0\ud654\ub97c \ub2e4\ub8ec\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ud558\ud504 \uc5f0\uc8fc\uc790\ub4e4\uc774 \uacf5\uc5f0 \uc804\uc5d0 \uc5ec\ub7ec \uc904\uc744 \uc870\uc728\ud558\ub294 \ubaa8\uc2b5\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \ubc18\uc9dd\uc774\ub294 \uc904\uc774 \ub9ce\uc774 \uc788\ub2e4\ub294 \uac83\uc740, \uadf8\ub9cc\ud07c \ubbf8\ub9ac \ud655\uc778\ud574\uc57c \ud560 \uc18c\ub9ac\ub3c4 \ub9ce\ub2e4\ub294 \ub73b\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ud558\ud504\ub97c \ub9cc\ub098\uba74 \uc904\uc744 \ud558\ub098\uc529 \uc138\ub824\uace0 \uc560\uc4f0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uba3c\uc800 \ube68\uac04 \uc904\uc744 \ucc3e\uc544\ubcf4\uc790. \uc544\ub984\ub2e4\uc6b4 \uc545\uae30 \uc548\uc5d0\uc11c \uc5f0\uc8fc\uc790\uac00 \uae38\uc744 \uc783\uc9c0 \uc54a\ub3c4\ub85d \ub9c8\ub828\ud55c \uc791\uc740 \ud45c\uc9c0\uac00 \ubcf4\uc77c \uac83\uc774\ub2e4."}, {"id": "inkstone-water-dropper", "title": "\ubcbc\ub8e8\ud568 \uc18d \ud574\ud0dc\uc758 \uc785\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \uc788\ub2e4", "summary": "\uac80\uc740 \uce60\ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\uac00, \uc548\ucabd\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uc2dd\uacfc \uc4f0\uc784\uc774 \ud55c \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/inkstone-water-dropper/index.html", "image": "media/inkstone-water-dropper.jpg", "alt": "\ub69c\uaed1\uc744 \uc5f4\uc5b4 \ubcbc\ub8e8\uc640 \uc791\uc740 \ud574\ud0dc \ubaa8\uc591 \uc5f0\uc801\uc744 \ud568\uaed8 \ubcf4\uc5ec \uc8fc\ub294 \ub098\uc804\uce60\uae30\ubd80\ucc44\ubb34\ub2ac\uc5f0\uac11 \uc0ac\uc9c4", "text": "\ubcbc\ub8e8\ud568 \uc18d \ud574\ud0dc\uc758 \uc785\uc5d0\ub294 \uc791\uc740 \uad6c\uba4d\uc774 \uc788\ub2e4 \uae00\uc4f0\uae30 \ub3c4\uad6c\ub97c \ub2f4\uc740 \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub098\ub294 \ub73b\ubc16\uc758 \ub3d9\ubb3c \uac80\uc740 \uce60\ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\uac00, \uc548\ucabd\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uc7a5\uc2dd\uacfc \uc4f0\uc784\uc774 \ud55c \uc0c1\uc790\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4. Art \ubb38\ud654 \uac80\uc740 \uce60\uc744 \ud55c \uc0c1\uc790\uc5d0 \ubc18\uc9dd\uc774\ub294 \ubd80\ucc44 \ubb34\ub2ac\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uac89\ubaa8\uc2b5\ub9cc \ubcf4\uba74 \uc7a5\uc2dd\ud488\uc744 \ub2f4\uc740 \ud568\uc77c \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud558\ub294 \uc774 \ubb3c\uac74\uc758 \uc774\ub984\uc740 \u300c\ub098\uc804\uce60\uae30\ubd80\ucc44\ubb34\ub2ac\uc5f0\uac11\u300d\uc774\ub2e4. \ubcbc\ub8e8\uc640 \uc5f0\uc801\uc744 \ud568\uaed8 \ubcf4\uad00\ud558\ub294 \uc0c1\uc790\ub2e4. \u2018\uc5f0\uc801\u2019\uc774\ub77c\ub294 \ub0af\uc120 \ub9d0\uc740 \uc7a0\uae50 \ub4a4\ub85c \ub450\uc5b4\ub3c4 \uc88b\ub2e4. \uc774 \uc0c1\uc790 \uc548\uc5d0\ub294 \uc791\uc740 \ud574\ud0dc \ubaa8\uc591\uc758 \uae08\uc18d \ubb3c\uac74\uc774 \ub4e4\uc5b4 \uc788\uace0, \uadf8 \ub4f1\uc5d0 \ud558\ub098, \uc785\uc5d0 \ud558\ub098 \uad6c\uba4d\uc774 \uc788\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ud568\uc758 \uc548\ucabd \uac00\uc6b4\ub370\ub294 \ubcbc\ub8e8 \ubaa8\uc591\uc5d0 \ub9de\uac8c \ud30c\uc5ec \uc788\ub2e4. \ubcbc\ub8e8\ub97c \uadf8 \uc790\ub9ac\uc5d0 \ub07c\uc6cc \ub123\uc5b4 \ubcf4\uad00\ud558\ub3c4\ub85d \ud55c \uac83\uc774\ub2e4. \uc5f0\uc801\uc744 \uc704\ud55c \ud648\ub3c4 \uc788\uc5b4 \uc27d\uac8c \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub3c4\ub85d \ud588\ub2e4. \uadf8\ub0e5 \ub113\uc740 \uc0c1\uc790\uc5d0 \ub3c4\uad6c\ub97c \ub123\uc5b4 \ub454 \uac83\uacfc\ub294 \ub2e4\ub974\ub2e4. \uc548\uc5d0 \ub4e4\uc5b4\uac08 \ubb3c\uac74\uc758 \ubaa8\uc591\uc744 \uc0dd\uac01\ud574 \uc790\ub9ac\ub97c \ub9c8\ub828\ud588\ub2e4. \uc624\ub298\uc758 \uc548\uacbd\uc9d1\uc774\ub098 \ub3c4\uad6c \ubcf4\uad00\ud568\uc5d0\uc11c\ub3c4 \ub9cc\ub098\ub294 \uc775\uc219\ud55c \uc0dd\uac01\uc774\ub2e4. \ub69c\uaed1\uc774 \uae4a\ub2e4\ub294 \uc810\ub3c4 \ub208\uc5d0 \ub748\ub2e4. \ub69c\uaed1\uacfc \ubab8\uccb4\ub97c \ub36e\uc73c\uba74 \ubab8\uccb4\uc758 \ubc14\ub2e5 \ubd80\ubd84\ub9cc \ubcf4\uc774\ub294 \ud615\ud0dc\ub77c\uace0 \ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c\uc758 \ub2e8\uc815\ud55c \ubaa8\uc2b5\uacfc \uc5f4\uc5c8\uc744 \ub54c\uc758 \uc54c\ub9de\uc740 \uc790\ub9ac\uac00 \ud55c \ubb3c\uac74 \uc548\uc5d0 \uc788\ub2e4. \uc5f0\uc801\uc740 \ubcbc\ub8e8\uc5d0 \uc4f8 \ubb3c\uc744 \ub2f4\ub294 \ub3c4\uad6c\ub2e4. \uc774 \ud568\uc758 \uc5f0\uc801\uc740 \ud574\ud0dc \ubaa8\uc591\uc774\uba70, \ub4f1 \ubd80\ubd84\uc5d0 \ubb3c\uc744 \ub123\ub294 \uad6c\uba4d\uc774 \uc788\uace0 \uc785 \ubd80\ubd84\uc5d0\ub294 \ubb3c\uc774 \ub098\uc624\ub294 \uc791\uc740 \ub465\uadfc \uad6c\uba4d\uc774 \ub6ab\ub824 \uc788\ub2e4. \ub3d9\ubb3c\uc758 \uc5bc\uad74\uc744 \uc54c\uc544\ubcf8 \ub2e4\uc74c\uc5d0 \uad6c\uba4d\uc758 \uc704\uce58\ub97c \ubcf4\uba74 \uc4f0\uc784\ub3c4 \ud568\uaed8 \ub4dc\ub7ec\ub09c\ub2e4. \uc7a5\uc2dd\uc744 \uc704\ud574 \ub354\ud55c \uc785\uc774 \ubb3c\uc744 \ub0b4\ubcf4\ub0b4\ub294 \uc790\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ubb3c\uac74\uc758 \uae30\ub2a5\uc774 \uc0dd\uae40\uc0c8 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc73c\ub85c \uad6c\uba4d\uc774 \ubaa8\ub450 \ub610\ub837\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ubc15\ubb3c\uad00 \uc124\uba85\uc744 \ub530\ub77c \uc704\uce58\ub97c \uc9d0\uc791\ud574 \ubcfc \uc218 \uc788\ub2e4. \ud574\ud0dc\uac00 \uc65c \uadf8 \uc0c1\uc790 \uc548\uc5d0 \uc788\ub294\uc9c0 \uc54c\uace0 \ub098\uba74 \uc791\uc740 \ub3d9\ubb3c\uc744 \ubcf4\ub294 \ub208\uc774 \uc870\uae08 \ub2ec\ub77c\uc9c4\ub2e4. \ud568\uc758 \ub69c\uaed1\uc5d0\ub294 \ubd80\ucc44\ub97c \ubcf8\ub72c \ubb34\ub2ac\uac00 \uc788\ub2e4. \ubd80\ucc44\uc5d0 \ub4e4\uc5b4\uac04 \ubb34\ub2ac\uc640 \ubd80\ucc57\uc0b4, \uad6c\uc2ac\uacfc \uace0\ub9ac\ub294 \ub098\uc804\uc73c\ub85c \ud45c\ud604\ud588\uace0 \ub048\uc740 \uae08\uc0c9 \uc548\ub8cc\ub85c \ub098\ud0c0\ub0c8\ub2e4\uace0 \ud55c\ub2e4. \ub098\uc804\uc740 \ube5b\uc744 \ubc1b\uc73c\uba74 \ubc18\uc9dd\uc774\ub294 \uc7ac\ub8cc\ub2e4. \uc0c1\uc790\uc758 \uae30\ub2a5\ub9cc \uc0dd\uac01\ud558\uba74 \uc5c6\uc5b4\ub3c4 \ub420 \uac83 \uac19\uc740 \ubd80\ubd84\uc774\uc9c0\ub9cc, \uadf8 \ub355\ubd84\uc5d0 \ub2eb\ud78c \ud568\uc5d0\ub3c4 \uc624\ub798 \ubc14\ub77c\ubcfc \uc790\ub9ac\uac00 \uc0dd\uae34\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \ubb38\ubc29\uad6c\ub97c \ub9cc\ub098\uba74 \uae00\uc528\ub97c \uc4f0\ub294 \ub3c4\uad6c\ub77c\ub294 \uc124\uba85\ub9cc \uc77d\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ub69c\uaed1\uc758 \ubd80\ucc44\uc5d0\uc11c \uc548\ucabd\uc758 \uc791\uc740 \ud574\ud0dc\uae4c\uc9c0, \uc4f0\ub294 \uc0ac\ub78c\uc758 \uc190\uae38\uc744 \uae30\ub2e4\ub9ac\ub358 \ubb3c\uac74\uc5d0\ub294 \uae30\ub2a5\uacfc \uad6c\uacbd\uac70\ub9ac\uac00 \ub098\ub780\ud788 \ub4e4\uc5b4 \uc788\ub2e4."}, {"id": "italy-print-painting-proposal", "title": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4", "summary": "\uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uac00 \ud310\ud654\ub85c \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5c8\ub358 \ub354 \ud070 \uadf8\ub9bc\uc744 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/italy-print-painting-proposal/index.html", "image": "media/italy-print-painting-proposal.jpg", "alt": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\ud310\ud654 \ud55c \uc7a5\uc774 \ud070 \uadf8\ub9bc\uc758 \uc81c\uc548\uc11c\uac00 \ub418\uc5c8\ub2e4 \uc774\ud0c8\ub9ac\uc544 \ud654\uac00\uac00 \ud6c4\uc6d0\uc790\ub97c \ucc3e\ub358 \ubc29\ubc95 \uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uac00 \ud310\ud654\ub85c \ubcf4\uc5ec \uc8fc\uace0 \uc2f6\uc5c8\ub358 \ub354 \ud070 \uadf8\ub9bc\uc744 \uc0dd\uac01\ud574 \ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uadf8\ub9bc\uc744 \ud06c\uac8c \uadf8\ub9ac\uace0 \uc2f6\uc740\ub370 \uadf8 \uc77c\uc744 \ub9e1\uaca8 \uc904 \uc0ac\ub78c\uc774 \uc5c6\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ud560\uae4c. \uc694\uc998\uc774\ub77c\uba74 \uad6c\uc0c1\uc548\uc774\ub098 \uc791\uc740 \uacac\ubcf8\uc744 \ub9cc\ub4e4\uc5b4 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc744 \uac83\uc774\ub2e4. \uc774\ud0c8\ub9ac\uc544\uc758 \uc608\uc220\uac00 \uc0b4\ubc14\ud1a0\ub974 \ub85c\uc0ac\uc5d0\uac8c\ub294 \ud310\ud654\ub77c\ub294 \ubc29\ubc95\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uadf8\uc758 \uac70\uc778\ub4e4\uc758 \ucd94\ub77d\uc774\ub77c\ub294 \ud310\ud654\ub97c \uc18c\uac1c\ud558\uba70 \ud070 \uadf8\ub9bc\uc744 \uc2e4\ud604\ud558\uae30 \uc704\ud574 \ud6c4\uc6d0\uc790\uc758 \uad00\uc2ec\uc744 \uc5bb\uc73c\ub824\ub358 \ubaa9\uc801\ub3c4 \uc124\uba85\ud55c\ub2e4. \ud310\ud654\uac00 \uc644\uc131\ub41c \uc791\ud488\uc774\uba74\uc11c \ub2e4\uc74c \uc77c\uc744 \uc81c\uc548\ud558\ub294 \ubb3c\uac74\uc774 \ub41c \uc148\uc774\ub2e4. \ubbf8\uc220\uad00 \ud574\uc124\uc5d0 \ub530\ub974\uba74 \uc791\ud488\uc740 \uac70\uc778\ub4e4\uc774 \uc2e0\ub4e4\uc758 \uc790\ub9ac\ub97c \uacf5\uaca9\ud558\ub824 \ud558\uc790 \uc720\ud53c\ud14c\ub974\uac00 \ubc88\uac1c\ub85c \uadf8\ub4e4\uc744 \ub5a8\uc5b4\ub728\ub9ac\ub294 \uc7a5\uba74\uc744 \ub2f4\ub294\ub2e4. \uc704\ucabd \uad6c\ub984\uc5d0\ub294 \uc2e0\uc774, \uc544\ub798\uc5d0\ub294 \ucd94\ub77d\ud558\ub294 \uac70\uc778\ub4e4\uc774 \ub193\uc774\ub294 \uad6c\uc0c1\uc774\ub2e4. \uc6b0\ub9ac\uac00 \uc5ec\uae30\uc11c \ubcf4\ub294 \uc0bd\ud654\ub294 \uadf8 \ud310\ud654\ub97c \ubcf5\uc81c\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \uc791\uc5c5\uc2e4\uc744 \ub5a0\uc62c\ub9ac\ub3c4\ub85d \ub9cc\ub4e0 \uc124\uba85\uc6a9 \uadf8\ub9bc\uc774\ub2e4. \uc2e4\uc81c \ud654\uba74\uc758 \uad6c\uc131\uc5d0 \uad00\ud55c \uc774\uc57c\uae30\ub294 \ubbf8\uc220\uad00\uc758 \uc791\ud488 \ud574\uc124\uc744 \uadfc\uac70\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \ub85c\uc0ac\ub294 \ud310\ud654\uac00\uc774\uba74\uc11c \ud654\uac00\uc600\uace0 \uc2dc\uc640 \uc5f0\uae30, \uc74c\uc545\uc5d0\uc11c\ub3c4 \ud65c\ub3d9\ud588\ub2e4\uace0 \ubbf8\uc220\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \ud55c \uac00\uc9c0 \uc774\ub984\ud45c\ub9cc\uc73c\ub85c \uadf8\uc758 \uc77c\uc744 \ubaa8\ub450 \uc124\uba85\ud558\uae30\ub294 \uc5b4\ub824\uc6b4 \uc778\ubb3c\uc774\uc5c8\ub2e4. \uc774 \ud310\ud654\ub294 \uac19\uc740 \uc8fc\uc81c\uc758 \ud68c\ud654\ub97c \uc81c\uc791\ud560 \uc0dd\uac01\uc744 \uc54c\ub9ac\uace0 \uadf8 \uc77c\uc744 \ud6c4\uc6d0\ud560 \uc0ac\ub78c\uc744 \ucc3e\uae30 \uc704\ud55c \uac83\uc774\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc774\ubbf8 \ud55c \ubc88 \ub9cc\ub4e0 \uc774\ubbf8\uc9c0\ub97c \ub2e4\uc74c \uc7ac\ub8cc\uc640 \ub2e4\uc74c \ud06c\uae30\uc758 \uc791\uc5c5\uc73c\ub85c \uc774\uc5b4 \ubcf4\ub824\ub294 \uc2dc\ub3c4\uc600\ub2e4. \uc624\ub298\uc758 \ub208\uc73c\ub85c \ubcf4\uba74 \uc791\uc740 \ubaa8\ud615\uc774\ub098 \uc81c\uc548\uc11c\ub97c \ub9cc\ub4dc\ub294 \uc77c\uacfc \ub2ee\uc544 \ubcf4\uc778\ub2e4. \ub2e4\ub9cc \ud310\ud654\uac00 \ub2e8\uc21c\ud55c \ubbf8\uc644\uc131 \ucd08\uc548\uc774\uc5c8\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud310\ud654 \uc790\uccb4\ub85c \uc644\uc131\ub41c \uc791\ud488\uc774\uba74\uc11c \ub354 \ud070 \uacc4\ud68d\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc5ed\ud560\ub3c4 \ud55c \uac83\uc774\ub2e4. \ubbf8\uc220\uad00\uc758 \uc791\ud488 \ud558\ub098\ub97c \ubcfc \ub54c \uadf8 \ub4a4\uc5d0 \ubb34\uc5c7\uc744 \ud558\ub824 \ud588\ub294\uc9c0\ub3c4 \uc9c8\ubb38\ud574 \ubcfc \uc218 \uc788\ub2e4. \ub9cc\ub4e0 \uc0ac\ub78c\uc774 \uc774 \uc774\ubbf8\uc9c0\ub85c \ub204\uad6c\ub97c \uc124\ub4dd\ud558\uace0 \uc2f6\uc5c8\ub294\uc9c0 \uc0dd\uac01\ud558\ub294 \uac83\uc774\ub2e4. \uac70\uc778\ub4e4\uc758 \ucd94\ub77d\uc740 \uc2e0\ud654\uc758 \uc7a5\uba74\uc778 \ub3d9\uc2dc\uc5d0 \ud55c \uc608\uc220\uac00\uc758 \ub2e4\uc74c \uc791\uc5c5\uc744 \ud5a5\ud55c \uc81c\uc548\uc774\uae30\ub3c4 \ud588\ub2e4."}, {"id": "japan-fierce-temple-guardian", "title": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c", "summary": "\ud5d8\uc0c1\uad82\uc740 \ud45c\uc815\uc774 \ubc29\ubb38\uac1d\uc744 \ud5a5\ud55c \uc801\ub300\uac10\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/japan-fierce-temple-guardian/index.html", "image": "media/japan-fierce-temple-guardian.jpg", "alt": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc808\uc744 \uc9c0\ud0a4\ub294 \uc5bc\uad74\uc740 \uc65c \uadf8\ub807\uac8c \ubb34\uc11c\uc6b8\uae4c \uc77c\ubcf8 \uc218\ud638\uc0c1\uc744 \ubcf4\ub294 \uc2dc\uc120\uc744 \ubc14\uafb8\ub294 \ubc29\ubc95 \ud5d8\uc0c1\uad82\uc740 \ud45c\uc815\uc774 \ubc29\ubb38\uac1d\uc744 \ud5a5\ud55c \uc801\ub300\uac10\ub9cc\uc740 \uc544\ub2d0 \uc218 \uc788\ub2e4\ub294 \uc774\uc57c\uae30\ub97c \uc77d\uc2b5\ub2c8\ub2e4. Art \ubb38\ud654 \ub208\uc744 \ud06c\uac8c \ub728\uace0 \uc785\uc744 \ubc8c\ub9b0 \uc870\uac01\uc0c1\uc774 \uc55e\uc744 \ub0b4\ub824\ub2e4\ubcf8\ub2e4. \ucc98\uc74c \ub9cc\ub0ac\ub2e4\uba74 \ubc18\uac11\uac8c \ub9de\uc544 \uc8fc\ub294 \uc5bc\uad74\uc774\ub77c\uace0 \ud558\uae30\ub294 \uc5b4\ub824\uc6b8 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc77c\ubcf8\uc758 \ubd88\uad50 \uc218\ud638\uc0c1\uc744 \ubcfc \ub54c\ub294 \uc9c8\ubb38\uc744 \ud55c \ubc88 \ubc14\uafd4 \ubcfc \uc218 \uc788\ub2e4. \ub204\uad6c\ub97c \uac81\uc8fc\uae30 \uc704\ud55c \ud45c\uc815\uc77c\uae4c. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \uc288\ucf58\uace0\uc9c4\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \uc218\ud638\uc0c1\uc5d0 \uad00\ud55c \uad50\uc721 \uc790\ub8cc\uc5d0\uc11c \ubc14\ub85c \uadf8 \ub450 \uac00\uc9c0 \ub290\ub08c\uc744 \ud568\uaed8 \uc9da\ub294\ub2e4. \ubb34\uc11c\uc6c0\uacfc \ubcf4\ud638\ubc1b\ub294 \ub9c8\uc74c\uc774\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc740 \ud06c\uac8c \ubd80\ub985\ub72c \ub208\uacfc \uc678\uce58\ub294 \ub4ef \uc5f4\ub9b0 \uc785, \uac15\ud55c \ubab8\uc758 \ud45c\ud604\uc744 \uc774\uc57c\uae30\ud55c\ub2e4. \uc0ac\ucc30\ub85c \ub2e4\uac00\uc624\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub450\ub824\uc6c0\uc744 \uc904 \uc218 \uc788\ub294 \ubaa8\uc2b5\uc774\ub2e4. \uadf8\ub7ec\ub098 \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00 \ub9c8\uc74c\uc744 \uac00\ub77c\uc549\ud788\ub824\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ub2e4\ub978 \ub73b\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \ubb34\uc5b8\uac00\uac00 \uc790\uc2e0\uc744 \uc9c0\ucf1c \uc8fc\uace0 \uc788\ub2e4\ub294 \uc548\ub3c4\uac10\uc774\ub2e4. \uac19\uc740 \ud45c\uc815\uc774\ub77c\ub3c4 \uadf8 \uc874\uc7ac\ub97c \ub0b4 \ud3b8\uc73c\ub85c \uc0dd\uac01\ud558\ub294\uc9c0\uc5d0 \ub530\ub77c \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \uc774 \uc870\uac01\uc744 \uacf5\uaca9\uc801\uc778 \uc5bc\uad74 \ud558\ub098\ub85c\ub9cc \ubcf4\uba74 \uae30\uad34\ud55c \uc7a5\uc2dd\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc0ac\ucc30\uc744 \uc9c0\ud0a4\ub294 \uc5ed\ud560\uacfc \ud568\uaed8 \ubcf4\uba74 \ubab8\uc9d3\uc744 \uc77d\ub294 \ubc29\ubc95\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uc6c3\uace0 \uc788\uc5b4\uc57c\ub9cc \uce5c\uc808\ud55c \uc874\uc7ac\uc778 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\ub0a0 \ubb38 \uc55e\uc5d0 \ubd99\uc774\ub294 \uacbd\uace0\ubb38\ub3c4 \ub5a0\uc62c\ub824 \ubcfc \uc218 \uc788\ub2e4. \ub4e4\uc5b4\uc624\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \ubbf8\uc6cc\ud574\uc11c\ub77c\uae30\ubcf4\ub2e4 \uc548\ucabd\uc758 \uc0ac\ub78c\uacfc \uacf5\uac04\uc744 \ubcf4\ud638\ud558\ub824\ub294 \ubaa9\uc801\uc77c \ub54c\uac00 \uc788\ub2e4. \uc774\uac83\uc740 \uc5ed\ud560\uc744 \uc774\ud574\ud558\uae30 \uc704\ud55c \ud604\ub300\uc758 \ube44\uc720\ub2e4. \uae30\uad00 \uc790\ub8cc\ub294 \uc6d0\ub798 \ubc29\ubb38\uac1d\uc774 \ub290\uaf08\uc744 \ubc18\uc751\uc744 \uac00\ub2a5\uc131\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc2e4\uc81c \ubaa8\ub4e0 \uc0ac\ub78c\uc774 \uac19\uc740 \ub450\ub824\uc6c0\uc774\ub098 \uc548\ub3c4\uac10\uc744 \ub290\uaf08\ub2e4\uace0 \uc815\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub798\ub41c \uc870\uac01 \uc55e\uc5d0\uc11c\ub3c4 \ubcf4\ub294 \uc0ac\ub78c\uc758 \uacbd\ud5d8\uc740 \ub2e4\ub97c \uc218 \uc788\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \ub204\uad6c\ub97c \uc9c0\ud0a4\uace0 \ub204\uad6c\ub97c \ud5a5\ud574 \ud798\uc744 \ubcf4\uc774\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uc740 \uc4f8\ubaa8\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubb34\uc11c\uc6b4 \ud45c\uc815\uc758 \uc218\ud638\uc0c1\uc744 \ub9cc\ub098\uba74 \uc5bc\uad74\uc744 \ud53c\ud558\uae30 \uc804\uc5d0 \uc5ed\ud560\uc744 \uc0dd\uac01\ud574 \ubcf4\uc790. \ub0af\uc124\ub358 \ud45c\uc815\uc774 \ub2e4\ub978 \ub73b\uc73c\ub85c \ub2e4\uac00\uc624\ub294 \uc21c\uac04\uc774 \uc788\uc744 \uc218 \uc788\ub2e4."}, {"id": "japan-phoenix-wood-panels", "title": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4", "summary": "\uac74\ubb3c\uc774 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \ub0a8\uc558\ub358 \uc77c\ubcf8\uc2dd \uac74\ucd95 \uc7a5\uc2dd\uc758 \uc774\ub3d9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Architecture", "url": "stories/japan-phoenix-wood-panels/index.html", "image": "media/japan-phoenix-wood-panels.jpg", "alt": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc77c\ubcf8\uc758 \ub098\ubb34 \uc7a5\uc2dd\uc740 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \ubc1c\uacac\ub410\ub2e4 \ubc15\ub78c\ud68c \uac74\ubb3c\uc5d0\uc11c \ubbf8\uc220\uad00\uc73c\ub85c \uc774\uc5b4\uc9c4 \ub124 \uc870\uac01 \uac74\ubb3c\uc774 \uc0ac\ub77c\uc9c4 \ub4a4\uc5d0\ub3c4 \ub0a8\uc558\ub358 \uc77c\ubcf8\uc2dd \uac74\ucd95 \uc7a5\uc2dd\uc758 \uc774\ub3d9\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. Architecture \ubb38\ud654 \uc6b4\ub3d9\uc7a5 \uad00\ub78c\uc11d \uc544\ub798\uc5d0\uc11c \uc77c\ubcf8 \uac74\ucd95 \uc7a5\uc2dd\uc774 \ub098\uc628\ub2e4\uba74 \uc870\uae08 \uc5c9\ub6b1\ud558\uac8c \ub4e4\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc774 \uc18c\uac1c\ud558\ub294 \ub124 \uc810\uc758 \ubaa9\uc870 \uc7a5\uc2dd\uc5d0\ub294 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc788\uc5c8\ub2e4. \ud55c\ub54c \ubc15\ub78c\ud68c \uac74\ubb3c\uc5d0 \ub2ec\ub838\ub358 \ubb3c\uac74\ub4e4\uc774\ub2e4. \uc774 \uc7a5\uc2dd\uc740 \ub780\ub9c8\ub77c\uace0 \ubd80\ub974\ub294 \ubaa9\uc870 \uac74\ucd95 \ubd80\uc7ac\ub2e4. \ubb38 \uc704\ucabd \uacf5\uac04\uc5d0 \ub193\uc774\ub294 \uc7a5\uc2dd\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc720\ub9ac\uc7a5 \uc548\uc5d0 \uc804\uc2dc\ud558\ub824\uace0 \ub9cc\ub4e0 \uc870\uac01\uc740 \uc544\ub2c8\uc5c8\ub2e4. 1893\ub144 \uc2dc\uce74\uace0 \ub9cc\uad6d\ubc15\ub78c\ud68c\uc5d0\uc11c \uc77c\ubcf8\uc740 \ud53c\ub2c9\uc2a4 \ud640\uc774\ub77c\ub294 \uad6d\uac00 \uc804\uc2dc\uad00\uc744 \uc138\uc6e0\ub2e4. \ubbf8\uc220\uad00 \uc124\uba85\uc740 \uc774 \uac74\ubb3c\uc774 \uad50\ud1a0 \uadfc\uad50\uc758 11\uc138\uae30 \uc0ac\ucc30\uc744 \ubcf8\ub5b4\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub978 \uc804\uc2dc\uad00\ub4e4\uacfc\ub294 \uad6c\ubcc4\ub418\ub294 \uc77c\ubcf8\uc2dd \uac74\ubb3c\uc774\uc5c8\ub2e4. \ub124 \uc810\uc758 \ubaa9\uc870 \uc7a5\uc2dd\ub3c4 \uadf8 \uc804\uc2dc\uad00\uc744 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc84c\ub2e4. \uac74\ubb3c\uc758 \uc77c\ubd80\uc600\uc73c\ub2c8 \uc0ac\ub78c\ub4e4\uc740 \uc870\uac01 \ud558\ub098\ub97c \ub530\ub85c \ubcf4\uae30\ubcf4\ub2e4 \uadf8 \uc544\ub798\ub97c \uc9c0\ub098\uac00\uba70 \uacf5\uac04 \uc804\uccb4\ub97c \ub9cc\ub0ac\uc744 \uac83\uc774\ub2e4. \uc774\uac83\uc740 \uac74\ucd95 \ubd80\uc7ac\uc758 \uc790\ub9ac\ub97c \ub5a0\uc62c\ub824 \ubcf4\ub294 \ubc29\uc2dd\uc774\ub2e4. \ubc15\ub78c\ud68c\uac00 \ub05d\ub09c \ub4a4 \uc77c\ubcf8 \uc815\ubd80\ub294 \uc804\uc2dc\uad00\uc744 \uc2dc\uce74\uace0\uc2dc\uc5d0 \uae30\uc99d\ud588\ub2e4. \uadf8\ub7ec\ub098 \uac74\ubb3c\uc740 1945\ub144\uacfc 1946\ub144\uc758 \ud654\uc7ac\ub85c \ud6fc\uc190\ub418\uc5b4 \ucca0\uac70\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ubbf8\uc220\uad00\uc740 \ub124 \uc7a5\uc2dd\uc774 \ub0a8\uc740 \ubd80\uc7ac\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8 \ub4a4 \uc774 \ubb3c\uac74\ub4e4\uc740 \uc194\uc800 \ud544\ub4dc\uc758 \uad00\ub78c\uc11d \uc544\ub798\uc5d0 \ubcf4\uad00\ub418\uc5c8\uace0, \uc78a\ud78c \ucc44 \uc9c0\ub0b4\ub2e4\uac00 1973\ub144\uc5d0 \ubc1c\uacac\ub418\uc5c8\ub2e4. \uac74\ucd95 \uc7a5\uc2dd\uc758 \ub2e4\uc74c \uc8fc\uc18c\uac00 \uc0ac\ucc30\ub3c4 \ubc15\ubb3c\uad00\ub3c4 \uc544\ub2cc \uacbd\uae30\uc7a5\uc774\uc5c8\ub2e4\ub294 \uc810\uc774 \ub73b\ubc16\uc774\ub2e4. \ubc1c\uacac \ub4a4\uc5d0\ub294 \ub450 \uc810\uc529 \ub2e4\ub978 \uae30\uad00\uc73c\ub85c \ub098\ub258\uc5c8\ub2e4\uac00 \ub124 \uc810 \ubaa8\ub450 \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc73c\ub85c \ubaa8\uc600\ub2e4. \uae30\uad00\uc774 \ub0a8\uae34 \uae00\uc740 \uc774 \uc7a5\uc2dd\ub4e4\uc744 \ud568\uaed8 \ubcf4\uc874\ud558\uace0 \ubcf4\uc5ec \uc8fc\ub824\ub358 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub798\uc804\uc758 \uc804\uc2dc \uc900\ube44\ub97c \uae30\ub85d\ud55c \uae00\uc774\ubbc0\ub85c \uc9c0\uae08\uc758 \uc804\uc2dc\uc2e4 \uc548\ub0b4\uc640\ub294 \uad6c\ubd84\ud574\uc11c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uac74\ubb3c\uc740 \uc0ac\ub77c\uc838\ub3c4 \uadf8 \uc77c\ubd80\uac00 \ub2e4\ub978 \uc2dc\uac04\uc744 \uc0b4\uc544\uac08 \uc218 \uc788\ub2e4. \uc77c\ubcf8\uc2dd \uc804\uc2dc\uad00\uacfc \ubbf8\uad6d\uc758 \uc6b4\ub3d9\uc7a5, \ubbf8\uc220\uad00\uc744 \uc774\uc5b4 \uc8fc\ub294 \uac83\uc740 \ub124 \uc870\uac01\uc758 \ub098\ubb34\uc600\ub2e4. \ubb3c\uac74\uc758 \uc774\ub825\uc740 \ub73b\ubc16\uc758 \uc7a5\uc18c\uc5d0\uc11c \ud55c \uc7a5 \ub354 \ub298\uc5b4\ub098\uae30\ub3c4 \ud55c\ub2e4."}, {"id": "man-ray-chess-photo-layout", "title": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4", "summary": "\ub9e8 \ub808\uc774\uc758 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud558\uba70 \ub9d0\uc758 \uc704\uce58\ub97c \uace0\ub974\ub358 \uacfc\uc815\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/man-ray-chess-photo-layout/index.html", "image": "media/man-ray-chess-photo-layout.jpg", "alt": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uccb4\uc2a4 \ub9d0\uc744 \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc624\ub798\ub41c \uc0ac\uc9c4\uc5d0 \ubb3c\uc5c8\ub2e4 \uc791\ud488 \uc804\uc2dc\uac00 \uc791\uc740 \ucd94\ub9ac \ubb38\uc81c\uac00 \ub41c \uc21c\uac04 \ub9e8 \ub808\uc774\uc758 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud558\uba70 \ub9d0\uc758 \uc704\uce58\ub97c \uace0\ub974\ub358 \uacfc\uc815\uc744 \ub530\ub77c\uac11\ub2c8\ub2e4. Art \ubb38\ud654 \uccb4\uc2a4 \uc138\ud2b8\ub97c \uc804\uc2dc\ud55c\ub2e4\uace0 \ud558\uba74 \ub9d0\ub4e4\uc744 \uc608\uc058\uac8c \uc138\uc6cc \ub450\uba74 \ub420 \uac83 \uac19\ub2e4. \uadf8\ub7f0\ub370 \uac8c\uc784 \ub3c4\uad6c\ub294 \uc704\uce58\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \uc7a5\uba74\uc774 \ub41c\ub2e4. \ub9c9 \uc2dc\uc791\ud55c \ud310\uc77c \uc218\ub3c4 \uc788\uace0, \ub204\uad70\uac00 \ub2e4\uc74c \uc218\ub97c \uace0\ubbfc\ud558\ub294 \ud310\uc77c \uc218\ub3c4 \uc788\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ub9e8 \ub808\uc774\uac00 \ub514\uc790\uc778\ud55c \uccb4\uc2a4 \uc138\ud2b8\ub97c \ub193\uc73c\uba70 \uc774\ub7f0 \uace0\ubbfc\uc744 \ud588\ub2e4. \uc5b4\ub5bb\uac8c \ubc30\uce58\ud574\uc57c \uc774 \ubb3c\uac74\uc744 \ub354 \uc798 \ubcf4\uc5ec \uc904 \uc218 \uc788\uc744\uae4c. \uadf8 \uc9c8\ubb38\uc740 \uc624\ub798\ub41c \uc0ac\uc9c4 \ud55c \uc7a5\uc73c\ub85c \uc774\uc5b4\uc84c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ub9e8 \ub808\uc774\ub294 1920\ub144\uc5d0 \uccab \uccb4\uc2a4 \uc138\ud2b8\ub97c \ub514\uc790\uc778\ud588\ub2e4. \ubbf8\uc220\uad00\uc758 \uc138\ud2b8\ub294 \uc778\ub3c4 \uc778\ub3c4\ub974\uc758 \ub9c8\ud558\ub77c\uc790\ub97c \uc704\ud574 1927\ub144\uc5d0 \ub9cc\ub4e0 \uac83\uc73c\ub85c \uc18c\uac1c\ub41c\ub2e4. \uc608\uc220\uac00\uac00 \ub9cc\ub4e0 \uccb4\uc2a4 \ub9d0\uc774\ub2c8 \uc870\uac01\uc73c\ub85c \ubcfc \uc218 \uc788\uc9c0\ub9cc, \ub3d9\uc2dc\uc5d0 \uc2e4\uc81c \uac8c\uc784\uc758 \uc790\ub9ac\ub97c \uac00\uc9c4 \ubb3c\uac74\uc774\ub2e4. \ub9d0\uc744 \ud55c \uac1c\ub9cc \uc55e\uc73c\ub85c \uc62e\uaca8 \ub193\ub294 \uac83\uacfc \uac8c\uc784 \uc911\uac04\uc758 \ud310\uc744 \ub9cc\ub4dc\ub294 \uac83\uc740 \ubcf4\ub294 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\ub978 \ub290\ub08c\uc744 \uc900\ub2e4. \ubbf8\uc220\uad00\uc740 \ub2e4\ub978 \uc138\ud2b8\uc758 \uc0ac\uc9c4\uc744 \ucc38\uace0\ud574 \ubc30\uce58\ud558\uae30\ub3c4 \ud588\uc9c0\ub9cc \ub354 \uc624\ub798\ub41c \uc790\ub8cc\ub97c \uc0b4\ud3c8\ub2e4. \uc911\uc694\ud55c \ub2e8\uc11c\ub294 1921\ub144 \ub9e8 \ub808\uc774\uc758 \uc790\ud654\uc0c1 \uc0ac\uc9c4\uc774\uc5c8\ub2e4. \ubb38\uc81c\ub294 \uc0ac\uc9c4\uc5d0 \uccb4\uc2a4\ud310 \uc77c\ubd80\ub9cc \ub098\uc640 \uc788\ub2e4\ub294 \uc810\uc774\uc5c8\ub2e4. \uae30\uad00 \uae00\uc758 \ud544\uc790\ub294 \uc0ac\uc9c4\uc744 \ud655\ub300\ud558\uace0 \ubcf4\uc774\ub294 \uce78\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c \ud3c9\ud589\uc120\uc744 \uadf8\uc5c8\ub2e4. \ubcf4\uc774\ub294 \ub9d0\uc758 \uc704\uce58\ub97c \ucc3e\uace0, \uccb4\uc2a4\uc758 \uaddc\uce59\uc744 \uc0dd\uac01\ud574 \uac00\ub824\uc9c4 \ubd80\ubd84\uc758 \ubc30\uce58\ub97c \ucd94\uc815\ud588\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc77c\uc774 \uc791\uc740 \ud37c\uc990 \ud480\uc774\uac00 \ub41c \uac83\uc774\ub2e4. \uadf8\uac00 \uc81c\uc548\ud55c \ubc30\uce58\ub294 \uc2e4\uc81c \uc804\uc2dc\ub97c \ub2e4\uc2dc \ub193\ub294 \ub370 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uae00\uc740 \uc804\ud55c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc0ac\uc9c4 \ubc16\uc758 \ub9d0\uae4c\uc9c0 \uc644\ubcbd\ud558\uac8c \ud655\uc778\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ud544\uc790 \uc5ed\uc2dc \uc790\uc2e0\uc758 \uac00\uc124\uc774 \ub9de\ub294\uc9c0 \uc9c8\ubb38\uc744 \ub0a8\uacbc\ub2e4. \uc774 \uc774\uc57c\uae30\uc758 \uc7ac\ubbf8\ub294 \uc791\ud488\uc758 \uc81c\ubaa9\uc774\ub098 \uac00\uaca9\uc5d0 \uc788\uc9c0 \uc54a\ub2e4. \uccb4\uc2a4 \ub9d0 \uba87 \uac1c\ub97c \uc5b4\ub514\uc5d0 \ub458\uc9c0 \uc815\ud558\ub824\uace0 \uc0ac\uc9c4\uacfc \uac8c\uc784 \uaddc\uce59\uc744 \ud568\uaed8 \uc0b4\ud3c8\ub2e4\ub294 \ub370 \uc788\ub2e4. \uc804\uc2dc\uc7a5 \uc18d \uac00\uc9c0\ub7f0\ud55c \ubc30\uce58\uc5d0\ub3c4 \ub204\uad70\uac00\uc758 \uae34 \uad00\ucc30\uacfc \uc870\uc2ec\uc2a4\ub7ec\uc6b4 \ucd94\ub9ac\uac00 \ub4e4\uc5b4 \uc788\uc744 \uc218 \uc788\ub2e4."}, {"id": "metal-flute-inlaid-flowers", "title": "\ub300\uae08\uc5d0\ub3c4 \ubc18\uc9dd\uc774\ub294 \uaf43\ubb34\ub2ac\uac00 \uc788\uc5c8\ub2e4", "summary": "\uae08\uc740\uc785\uc0ac \uc7a5\uc2dd\uc774 \uc788\ub294 \ub300\uae08\uc5d0\uc11c \uc545\uae30\uc758 \ub610 \ub2e4\ub978 \ud45c\uc815\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/metal-flute-inlaid-flowers/index.html", "image": "media/metal-flute-inlaid-flowers.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ucca0\uc81c\uae08\uc740\uc785\uc0ac\ub300\uae08 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ub300\uae08\uc5d0\ub3c4 \ubc18\uc9dd\uc774\ub294 \uaf43\ubb34\ub2ac\uac00 \uc788\uc5c8\ub2e4 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uae34 \uad00\uc5d0 \ub354\ud55c \uc7a5\uc2dd \uae08\uc740\uc785\uc0ac \uc7a5\uc2dd\uc774 \uc788\ub294 \ub300\uae08\uc5d0\uc11c \uc545\uae30\uc758 \ub610 \ub2e4\ub978 \ud45c\uc815\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. Music \ubb38\ud654 \ub300\uae08\uc774\ub77c\ub294 \uc774\ub984\uc744 \ub4e4\uc73c\uba74 \uae38\ucb49\ud55c \ub300\ub098\ubb34 \uc545\uae30\uac00 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ucca0\uc81c\uae08\uc740\uc785\uc0ac\ub300\uae08\uc740 \uc774\ub984\ubd80\ud130 \uc870\uae08 \ub2e4\ub974\ub2e4. \uae08\uc18d\uc73c\ub85c \ub9cc\ub4e0 \uc545\uae30\uc5d0 \uaf43\uacfc \ud559 \ubb34\ub2ac\uae4c\uc9c0 \ub354\ud588\ub2e4. \uc804\uccb4 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uac00\ub290\ub2e4\ub780 \uc120\ucc98\ub7fc \ubcf4\uc5ec\uc11c \uc7a5\uc2dd\uc774 \uc27d\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc624\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \uc545\uae30\ub77c\ub294 \uc0ac\uc2e4\uc744 \ud655\uc778\ud55c \ub4a4, \uc774\ubc88\uc5d0\ub294 \uc5b4\ub514\uc5d0 \uc5b4\ub5a4 \ubb34\ub2ac\ub97c \ub193\uc558\ub294\uc9c0 \uc124\uba85\uc744 \uae38\uc7a1\uc774 \uc0bc\uc544 \ucc9c\ucc9c\ud788 \uc0b4\ud3b4\ubcf4\uc790. \ubc15\ubb3c\uad00\uc740 \uc774 \uc545\uae30\ub97c \uac00\ub85c\ub85c \uc5f0\uc8fc\ud558\ub294 \uad00\uc545\uae30\ub85c \uc18c\uac1c\ud558\uace0, \ubab8\uccb4\uc5d0 \uad6c\uba4d\uc774 \uc5f4\ub450 \uac1c \ub6ab\ub824 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uae38\uac8c \ubed7\uc740 \uad00\uacfc \uad6c\uba4d\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud2b9\uc9d5\uc744 \ubcf4\uc5ec \uc8fc\ub294 \ubd80\ubd84\uc774\ub2e4. \uac70\uae30\uc5d0 \uae08\uc740\uc785\uc0ac \uae30\ubc95\uc73c\ub85c \uaf43\ubb34\ub2ac\uc640 \uaf43\ub369\uad74\ubb34\ub2ac\ub97c \ub354\ud588\ub2e4\uace0 \ud55c\ub2e4. \uc5f0\uc8fc \ub3c4\uad6c\uc758 \ud45c\uba74\uc5d0 \uc7a5\uc2dd\uc758 \uc790\ub9ac\uac00 \ud568\uaed8 \ub9c8\ub828\ub41c \uac83\uc774\ub2e4. \uad6c\uba4d\uc744 \ubaa8\ub450 \uac19\uc740 \uc6a9\ub3c4\uc758 \uc190\uac00\ub77d \uad6c\uba4d\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubc15\ubb3c\uad00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc804\uccb4 \uac1c\uc218\ub85c \uc77d\uc73c\uba74 \ub41c\ub2e4. \uc591\ub05d\uc5d0\ub294 \uac19\uc740 \uae30\ubc95\uc73c\ub85c \ud559 \ubb34\ub2ac\ub97c \ud45c\ud604\ud588\ub2e4. \ubab8\ud1b5\uc758 \uaf43\uacfc \ub05d\ubd80\ubd84\uc758 \uc0c8\ub97c \ub098\ub204\uc5b4 \ub193\uc740 \uad6c\uc131\uc774 \ubcf4\uc778\ub2e4. \uac00\uc6b4\ub370\uc640 \ub05d\uc744 \ub530\ub85c \uc0b4\ud53c\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uae34 \ubb3c\uac74\uc744 \ubcf4\ub294 \uc21c\uc11c\uac00 \uc0dd\uae34\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc791\uc740 \ubb34\ub2ac\uac00 \uc120\uba85\ud558\uc9c0 \uc54a\uc744 \ub54c\ub294 \ud655\ub300\ud574 \ubcf4\ub418 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc120\uc744 \uc5b5\uc9c0\ub85c \uc77d\uc5b4\ub0bc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc545\uae30\uc758 \uc7a5\uc2dd\uc5d0 \uad00\ud55c \uc815\ubcf4\ub294 \uc0ac\uc9c4\uacfc \ud568\uaed8 \uc81c\uacf5\ub418\ub294 \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc870\uc120\uc2dc\ub300 \ub300\uae08\uc774 \uc81c\ub840\uc545\uacfc \uc5f0\ub840\uc545\uc758 \uc5ec\ub7ec \ud3b8\uc131\uc5d0\uc11c \uc5f0\uc8fc\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4\uc758 \uc774 \uc720\ubb3c\uc774 \uc5b4\ub5a4 \ub0a0 \uc5b4\ub5a4 \uace1\uc744 \uc5f0\uc8fc\ud588\ub294\uc9c0\uae4c\uc9c0 \uc54c\ub824 \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298 \uc0ac\uc9c4\uc73c\ub85c \uc54c \uc218 \uc5c6\ub294 \uac83\uc740 \uc2e4\uc81c \uc74c\uc0c9\uc774\ub2e4. \ub300\uc2e0 \ub0a8\uc544 \uc788\ub294 \uac83\uc740 \uae34 \uad00\uacfc \uad6c\uba4d, \uae08\uc18d \ud45c\uba74\uacfc \uc7a5\uc2dd\uc774\ub2e4. \uc74c\uc545\uc744 \ub4e3\uc9c0 \ubabb\ud558\ub294 \uc790\ub9ac\uc5d0\uc11c\ub3c4 \uc545\uae30\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub294 \uc788\ub2e4. \uc18c\ub9ac\ub97c \ub9cc\ub4e4\ub358 \ubb3c\uac74\uc5d0 \uaf43\uacfc \ud559\uc744 \ub354\ud558\uace0 \uc2f6\uc5c8\ub358 \uc120\ud0dd\uc774 \uadf8 \ud55c \uac00\uc9c0\ub2e4."}, {"id": "poem-plaque-raised-letters", "title": "\uc774 \ud604\ud310\uc758 \uae00\uc790\ub294 \ub530\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc600\ub2e4", "summary": "\uc2dc \ud55c \ud3b8\uacfc \uc785\uccb4\uc801\uc778 \uae00\uc790\uac00 \ud568\uaed8 \ub0a8\uc740 \ud604\ud310\uc744 \ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Literature", "url": "stories/poem-plaque-raised-letters/index.html", "image": "media/poem-plaque-raised-letters.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc30\ub9bc\ucd98\ubc29\uacbd\ucc28\uc5b4\uc81c \ud604\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ud604\ud310\uc758 \uae00\uc790\ub294 \ub530\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc600\ub2e4 \uc138\uc790\uac00 \ub2f5\ud55c \uc2dc\uac00 \ub098\ubb34\ud310\uc5d0 \ub0a8\ub294 \uacfc\uc815 \uc2dc \ud55c \ud3b8\uacfc \uc785\uccb4\uc801\uc778 \uae00\uc790\uac00 \ud568\uaed8 \ub0a8\uc740 \ud604\ud310\uc744 \ubd05\ub2c8\ub2e4. Literature \ubb38\ud654 \ud604\ud310\uc774\ub77c\uace0 \ud558\uba74 \uac74\ubb3c \uc774\ub984\uc774 \ud06c\uac8c \uc801\ud78c \ud310\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc774 \ud604\ud310\uc5d0\ub294 \uc5ec\ub7ec \uc904\uc758 \uae00\uc774 \ub2f4\uaca8 \uc788\ub2e4. \uc774\ub984\ud45c\ub77c\uae30\ubcf4\ub2e4 \ubcbd\uc5d0 \uac78\uc5b4 \ub450\ub294 \ud55c \ud3b8\uc758 \uc2dc\uc5d0 \uac00\uae5d\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \ubc30\ub9bc\ucd98\ubc29\uacbd\ucc28\uc5b4\uc81c \ud604\ud310\uc774\ub2e4. \uc81c\ubaa9\uc740 \uae38\uace0 \ub0af\uc124\uc9c0\ub9cc \uadf8 \uc548\uc758 \uc0c1\ud669\uc740 \uc870\uae08 \uce5c\uc219\ud558\ub2e4. \ub204\uad70\uac00 \uba3c\uc800 \uc2dc\ub97c \uc9c0\uc5c8\uace0 \ub2e4\ub978 \uc0ac\ub78c\uc774 \uadf8 \uc2dc\uc5d0 \ub2f5\ud588\ub2e4. \ubc15\ubb3c\uad00\uc5d0 \ub530\ub974\uba74 1886\ub144 3\uc6d4 15\uc77c \uace0\uc885\uc740 \uc138\uc790\uac00 \uacf5\ubd80\ud558\ub294 \uc790\ub9ac\uc5d0 \ub098\uc544\uac14\ub2e4. \uae30\uc05c \ub9c8\uc74c\uc5d0 \uad00\uc6d0\ub4e4\uc5d0\uac8c \uc220\uc744 \ub0b4\ub9ac\uace0 \uc2dc\ub97c \uc9c0\uc5c8\uc73c\uba70, \uc655\uc138\uc790\ub294 \uadf8 \uc2dc\uc5d0 \ud654\ub2f5\ud588\ub2e4. \ud6d7\ub0a0 \uc21c\uc885\uc774 \ub418\ub294 \uc138\uc790\ub2e4. \uc774 \ud604\ud310\uc5d0\ub294 \uadf8 \ub2f5\uc2dc\uac00 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uae34 \uad00\uc9c1\uba85\uc774\ub098 \uc5b4\ub824\uc6b4 \uc758\ub840 \uc808\ucc28\ub97c \uba3c\uc800 \uc54c\uc544\uc57c\ub9cc \ubcf4\ub294 \ubb3c\uac74\uc740 \uc544\ub2c8\ub2e4. \ub204\uad70\uac00\uc758 \uae00\uc5d0 \ub2e4\ub978 \uae00\ub85c \uc751\ub2f5\ud55c \uc7a5\uba74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc2dc\uc791\uc774 \ud55c\uacb0 \uac00\ubcbc\uc6cc\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \uac19\uc740 \ub0b4\uc6a9\uc774 \uc21c\uc885\uc758 \ubb38\uc9d1\uc778 \uc815\ud5cc\uc9d1\uc5d0\ub3c4 \uae30\ub85d\ub418\uc5b4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uae00\uc740 \ucc45 \uc548\uc5d0\ub3c4 \ub0a8\uc558\uace0, \ud604\ud310\uc774\ub77c\ub294 \ubb3c\uac74\uc5d0\ub3c4 \ub0a8\uc558\ub2e4. \uac19\uc740 \ubb38\uc7a5\uc774 \uba38\ubb34\ub294 \uc790\ub9ac\uac00 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc774\ub2e4. \ucc45\uc5d0\uc11c\ub294 \ud398\uc774\uc9c0\ub97c \ub118\uaca8 \uc77d\uc9c0\ub9cc \ud604\ud310\uc740 \uacf5\uac04\uc5d0 \uac78\uc5b4 \ub454\ub2e4. \uadf8\ub798\uc11c \uc2dc\ub97c \uae30\uc5b5\ud558\ub294 \ubc29\uc2dd\ub3c4 \ub2e4\ub974\uac8c \uc0c1\uc0c1\ud560 \uc218 \uc788\ub2e4. \ubb3c\ub860 \uc2e4\uc81c\ub85c \ub204\uac00 \uc774 \uc55e\uc5d0\uc11c \uc2dc\ub97c \uc77d\uc5c8\ub294\uc9c0\ub294 \uc774 \ubb3c\uac74\ub9cc \ubcf4\uace0 \uc815\ud560 \uc218 \uc5c6\ub2e4. \ub9cc\ub4dc\ub294 \ubc29\ubc95\ub3c4 \ub208\uc5ec\uaca8\ubcfc \ub9cc\ud558\ub2e4. \ubc15\ubb3c\uad00\uc740 \uae00\uc790\ub97c \ub530\ub85c \ub098\ubb34\ub85c \uc870\uac01\ud55c \ub4a4 \ubd99\uc600\ub2e4\uace0 \ud55c\ub2e4. \ud3c9\ud3c9\ud55c \ud310\uc5d0 \ubd93\uc73c\ub85c \uc4f0\ub294 \ubc29\ubc95\uacfc \ub2ec\ub9ac \uae00\uc790 \uc790\uccb4\uac00 \uc791\uc740 \ubd80\ud488\uc774 \ub418\ub294 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uae00\uc790 \ud558\ub098\uc758 \uac00\uc7a5\uc790\ub9ac\ub97c \ub530\ub77c\ubcf4\uc790. \uc2dc\uc758 \ub73b\uc744 \ubaa8\ub450 \ubc88\uc5ed\ud558\uc9c0 \uc54a\uc544\ub3c4, \ubb38\uc7a5\uc744 \uc785\uccb4\uc801\uc778 \ubb3c\uac74\uc73c\ub85c \ubc14\uafb8\ub294 \uc190\uae38\uc744 \uc0dd\uac01\ud560 \uc218 \uc788\ub2e4. \ub204\uad70\uac00\uc758 \ub2f5\uc2dc\uac00 \ucc45\uc758 \ud55c \ud398\uc774\uc9c0\uc640 \ub098\ubb34\ud310\uc758 \ud55c \uc904\ub85c \uac01\uac01 \ub0a8\uc558\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc774 \ud604\ud310\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uac8c \ud55c\ub2e4."}, {"id": "silver-kettle-hidden-letters", "title": "\uc8fc\uc804\uc790\uc758 \uc774\uc57c\uae30\ub294 \ubc14\ub2e5\uc5d0\ub3c4 \uc801\ud600 \uc788\ub2e4", "summary": "\uc740\uc81c \uc8fc\uc804\uc790\uc758 \uaf43\ubd09\uc624\ub9ac \uc190\uc7a1\uc774\uc640 \ubc14\ub2e5\uc758 \uba85\ubb38\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Art", "url": "stories/silver-kettle-hidden-letters/index.html", "image": "media/silver-kettle-hidden-letters.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc740\uc81c\uc8fc\uc804\uc790 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc8fc\uc804\uc790\uc758 \uc774\uc57c\uae30\ub294 \ubc14\ub2e5\uc5d0\ub3c4 \uc801\ud600 \uc788\ub2e4 \ubc18\uc9dd\uc774\ub294 \ubab8\uccb4 \uc544\ub798\uc758 \uc791\uc740 \uae00\uc790\ub4e4 \uc740\uc81c \uc8fc\uc804\uc790\uc758 \uaf43\ubd09\uc624\ub9ac \uc190\uc7a1\uc774\uc640 \ubc14\ub2e5\uc758 \uba85\ubb38\uc744 \ucc3e\uc544\ubd05\ub2c8\ub2e4. Art \ubb38\ud654 \uc740\ube5b \uc8fc\uc804\uc790\ub97c \ubcf4\uba74 \uba3c\uc800 \uae38\uac8c \ubed7\uc740 \uc8fc\ub465\uc774\uc640 \ud718\uc5b4\uc9c4 \uc190\uc7a1\uc774\uac00 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uac00\uc6b4\ub370 \ub465\uadfc \ubab8\ud1b5\uae4c\uc9c0, \ubb3c\uc744 \ub530\ub974\ub294 \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc740 \uc5b4\ub835\uc9c0 \uc54a\uac8c \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uc8fc\uc804\uc790\ub294 \uc606\ubaa8\uc2b5\ub9cc \ubcf4\uace0 \ub05d\ub0b4\uae30 \uc544\uae5d\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc744 \ub530\ub77c\uac00\uba74 \ub69c\uaed1\uc5d0\ub294 \uaf43\ubd09\uc624\ub9ac\uac00 \uc788\uace0, \ubab8\uccb4 \uc591\ucabd\uc5d0\ub294 \uae00\uc790\uac00 \uc788\uc73c\uba70, \ubc14\ub2e5\uc5d0\ub3c4 \uae30\ub85d\uc774 \uc788\ub2e4. \ud55c \ubb3c\uac74\uc744 \ubcf4\ub294 \ubc29\ud5a5\uc774 \uc138 \ubc88 \ubc14\ub010\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub69c\uaed1 \uc190\uc7a1\uc774\ub97c \uc5f0\ubd09\uc624\ub9ac \ud615\ud0dc\ub85c \uc124\uba85\ud55c\ub2e4. \uc9d1\uc5b4 \ub4dc\ub294 \ubd80\ubd84\uc5d0 \uaf43\uc758 \ubaa8\uc591\uc744 \ube4c\ub824 \ub193\uc740 \uac83\uc774\ub2e4. \uc2e4\uc81c \uc5f0\uaf43\uc774 \ud540 \ud48d\uacbd\uc744 \uadf8\ub9b0 \ub300\uc2e0 \uc190\uc5d0 \ub2ff\ub294 \uc791\uc740 \uaf2d\uc9c0\ub97c \uaf43\ucc98\ub7fc \ub9cc\ub4e4\uc5c8\ub2e4. \ub69c\uaed1\uc5d0\ub294 \uc120\uc73c\ub85c \uc0c8\uae34 \ubc15\uc950\ubb34\ub2ac\ub3c4 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc9c4 \ud55c \uc7a5\uc5d0 \ubaa8\ub4e0 \ubc29\ud5a5\uc774 \ubcf4\uc774\uc9c0\ub294 \uc54a\uc73c\ub2c8, \ubcf4\uc774\uc9c0 \uc54a\ub294 \ubb34\ub2ac\ub97c \uc5b5\uc9c0\ub85c \ucc3e\uc544\ub0b4\uae30\ubcf4\ub2e4 \uc124\uba85\uc744 \uae38\uc7a1\uc774\ub85c \uc0bc\uc73c\uba74 \ub41c\ub2e4. \ubc15\uc950\uc758 \ub73b\uae4c\uc9c0 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \uae38\uac8c \ud480\uc9c0\ub294 \uc54a\uae30\ub85c \ud558\uc790. \ubab8\uccb4 \uc591\ucabd\uc5d0\ub294 \ub465\uadfc \ud2c0\uc758 \uc218\uba85 \uc218, \uace7 \u58fd\ub97c \ub098\ud0c0\ub0b8 \ubb34\ub2ac\uac00 \uc788\ub2e4. \uc8fc\uc804\uc790\uc758 \ub465\uadfc \ud615\ud0dc \uc548\uc5d0 \uae00\uc790 \uc7a5\uc2dd\uc774 \ub354\ud574\uc9c4 \uac83\uc774\ub2e4. \ub2e8\uc21c\ud788 \ubc18\uc9dd\uc774\ub294 \uc740\uadf8\ub987\uc774\ub77c\uace0\ub9cc \ubcf4\uae30\uc5d0\ub294 \ubcfc\uac70\ub9ac\uac00 \ub9ce\ub2e4. \uad7d\uc5d0\ub294 \uc120\ud76c\uad81\uc744 \ub73b\ud558\ub294 \u5ba3\u79a7\u5bae\uc73c\ub85c \uc2dc\uc791\ud558\ub294 \uae00\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \uba85\ubb38 \uc804\uccb4\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf8\uc911\uc5d0\ub294 \uc0c8\ub85c \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \u65b0\u9020\uc640 \ubb34\uac8c\ub97c \ub73b\ud558\ub294 \u91cd \uac19\uc740 \uae00\uc790\ub3c4 \ubcf4\uc778\ub2e4. \uc7a5\uc2dd\uacfc \ubcc4\uac1c\ub85c \uc81c\uc791\uc5d0 \uad00\ud55c \uc815\ubcf4\ub97c \ub0a8\uae30\ub294 \uc790\ub9ac\uc600\uc74c\uc744 \uc77d\uc744 \uc218 \uc788\ub2e4. \uc5ec\uae30\uc11c\ub294 \ubb34\uc778\ub144\uc744 \ud2b9\uc815\ud55c \uc11c\uae30 \uc5f0\ub3c4\ub85c \ubc14\uafb8\uac70\ub098 \uc61b \ubb34\uac8c\ub97c \uc9c0\uae08\uc758 \uadf8\ub7a8\uc73c\ub85c \ud658\uc0b0\ud558\uc9c0 \uc54a\ub294\ub2e4. \ucd94\uac00 \ub300\uc870 \uc5c6\uc774 \uc22b\uc790\ub9cc \ud655\uc815\ud558\uba74 \uc791\uc740 \uae00\uc528\uac00 \uc54c\ub824 \uc8fc\ub294 \ubc94\uc704\ub97c \ub118\uc5b4\uc124 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ub300\uc2e0 \ubcf4\ub294 \uc21c\uc11c \ud558\ub098\ub97c \uae30\uc5b5\ud574 \ub450\uba74 \uc88b\uaca0\ub2e4. \ub69c\uaed1\uc758 \uaf43, \ubab8\uccb4\uc758 \uae00\uc790, \ubc14\ub2e5\uc758 \uae30\ub85d. \uc775\uc219\ud55c \uc8fc\uc804\uc790\ub3c4 \uc5b4\ub514\ub97c \ubcf4\ub290\ub0d0\uc5d0 \ub530\ub77c \uc7a5\uc2dd\ud488\uc774 \ub418\uc5c8\ub2e4\uac00 \uae30\ub85d\ubb3c\uc774 \ub41c\ub2e4. \ub2e4\uc74c\uc5d0 \uc61b \uadf8\ub987\uc744 \ub9cc\ub0a0 \ub54c \ubc14\ub2e5 \uc0ac\uc9c4\uc744 \ud55c \ubc88 \ub354 \ub20c\ub7ec \ubcf4\uace0 \uc2f6\uc5b4\uc9c0\ub294 \uc774\uc720\ub2e4."}, {"id": "stone-chime-thickness", "title": "\uc774 \ub3cc\uc740 \ub450\ub4dc\ub9ac\uba74 \uc74c\uc774 \ub41c\ub2e4", "summary": "\uaebe\uc778 \ub3cc \ud55c \uc7a5\uc774 \uc545\uae30\uac00 \ub418\ub294 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/stone-chime-thickness/index.html", "image": "media/stone-chime-thickness.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ud3b8\uacbd \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ub3cc\uc740 \ub450\ub4dc\ub9ac\uba74 \uc74c\uc774 \ub41c\ub2e4 \ud3b8\uacbd \ud55c \uc870\uac01\uc5d0\uc11c \uc2dc\uc791\ud558\ub294 \uc74c\uc545 \uc774\uc57c\uae30 \uaebe\uc778 \ub3cc \ud55c \uc7a5\uc774 \uc545\uae30\uac00 \ub418\ub294 \ubc29\ubc95\uc744 \uc0b4\ud3b4\ubd05\ub2c8\ub2e4. Music \ubb38\ud654 \uc0ac\uc9c4 \uc18d \ub3cc\uc740 \ud55c\ucabd\uc774 \uaebe\uc5ec \uc788\ub2e4. \ub05d\ubd80\ubd84\uc5d0 \uad6c\uba4d\ub3c4 \ud558\ub098 \ubcf4\uc778\ub2e4. \ub530\ub85c \ub193\uc73c\uba74 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\ub2e4 \ub0a8\uae34 \uc870\uac01\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\uc9c0\ub9cc, \uc774\uac83\uc740 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud55c \ubd80\ubd84\uc774\ub2e4. \uc774\ub984\uc740 \ud3b8\uacbd\uc774\ub2e4. \ud53c\uc544\ub178\uc758 \uac74\ubc18\uc774\ub098 \ubc14\uc774\uc62c\ub9b0\uc758 \uc904\ucc98\ub7fc \uc774 \uc545\uae30\uc5d0\uc11c\ub294 \ub3cc\uc774 \uc74c\uc744 \ub9e1\ub294\ub2e4. \ubb34\ub300 \uc704 \uc545\uae30\ub97c \ub5a0\uc62c\ub9ac\ub2e4\uac00 \uac11\uc790\uae30 \ub3cc\uc744 \ub9cc\ub098\ub2c8 \uc74c\uc545\uc758 \uc7ac\ub8cc\uac00 \uc0dd\uac01\ubcf4\ub2e4 \ub113\uac8c \ub290\uaef4\uc9c4\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc625\uc11d\uc744 \uae4e\uc544 \ub9cc\ub4e0 \uacbd \uc5f4\uc5ec\uc12f \uac1c\ub97c \ub450 \ub2e8\uc758 \ud2c0\uc5d0 \uc5ec\ub35f \uac1c\uc529 \ub9e4\ub2ec\uc544 \uc5f0\uc8fc\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0ac\uc9c4\uc758 \ud55c \uc870\uac01\uc744 \ubcf4\ub294 \uac83\uacfc \uc804\uccb4 \uc545\uae30\ub97c \uc0c1\uc0c1\ud558\ub294 \uc77c \uc0ac\uc774\uc5d0 \uc791\uc740 \uac04\uaca9\uc774 \uc788\ub2e4. \uad6c\uba4d\uc740 \uadf8 \uc870\uac01\uc774 \ud63c\uc790 \ub193\uc774\ub294 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \ub9e4\ub2ec\ub9ac\ub294 \ubb3c\uac74\uc774\ub77c\ub294 \uc0ac\uc2e4\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \uc774\ub984 \ubaa8\ub97c \ub3cc\uc774 \uc904\uc9c0\uc5b4 \uc18c\ub9ac\ub97c \ub0b4\ub294 \uc545\uae30\uc758 \ud55c \uc790\ub9ac\ub85c \uc62e\uaca8 \uac00\ub294 \uc21c\uac04\uc774\ub2e4. \uc774 \uc545\uae30\uc5d0\uc11c \uc7ac\ubbf8\uc788\ub294 \ubd80\ubd84\uc740 \uc74c\ub192\uc774\ub97c \ub3cc\uc758 \ub450\uaed8\ub85c \uc870\uc808\ud588\ub2e4\ub294 \uc810\uc774\ub2e4. \uc904\uc744 \ud33d\ud33d\ud558\uac8c \ub2f9\uae30\uac70\ub098 \uad00\uc758 \uad6c\uba4d\uc744 \ub9c9\ub294 \ubc29\uc2dd\uacfc\ub294 \ub2e4\ub974\ub2e4. \uae4e\uc544 \ub9cc\ub4e0 \ub3cc\uc758 \ub450\uaed8\uac00 \uc74c\uc545\uc744 \uc900\ube44\ud558\ub294 \uc77c\uc774 \ub418\ub294 \uac83\uc774\ub2e4. \uc5f0\uc8fc\ud560 \ub54c\ub294 \uc18c\ubfd4\ub85c \ub9cc\ub4e0 \ub3c4\uad6c\uc778 \uac01\ud1f4\ub85c \uacbd\uc758 \uc544\ub7ab\ubd80\ubd84\uc744 \ucce4\ub2e4\uace0 \ud55c\ub2e4. \ub3cc\uc774\ub77c\uace0 \uc544\ubb34 \ub9c9\ub300\ub098 \uac00\uc838\uc640 \ub450\ub4dc\ub9ac\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \uc18c\ub9ac\ub97c \ub0bc \ubb3c\uac74\uacfc \uadf8\uac83\uc744 \uce58\ub294 \ub3c4\uad6c\uac00 \ud568\uaed8 \uac16\ucd94\uc5b4\uc9c4\ub2e4. \ubc15\ubb3c\uad00\uc740 \ud3b8\uacbd\uc774 \uc870\uc120\uc2dc\ub300\uc758 \uc5ec\ub7ec \uc81c\ub840\uc640 \uc5f0\ub840\uc5d0 \uc0ac\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc624\ub298 \uc0ac\uc9c4\uc5d0\uc11c \ubcf4\uc774\ub294 \uac83\uc740 \uc870\uc6a9\ud55c \ub3cc \ud55c \uc7a5\uc774\uc9c0\ub9cc, \uc6d0\ub798\ub294 \ub2e4\ub978 \uc545\uae30\uc640 \ud568\uaed8 \uc18c\ub9ac\ub97c \ub0b4\ub358 \uc790\ub9ac\uc758 \uc77c\ubd80\uc600\ub358 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcfc \ub54c \ubaa8\ub4e0 \uc74c\uc758 \uc774\ub984\uc744 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uad6c\uba4d \ud558\ub098\uc640 \uaebe\uc778 \ubaa8\uc591, \ub450\uaed8\ub97c \ub5a0\uc62c\ub9ac\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \uc545\uae30\ub294 \uaf2d \uc904\uc774 \uc788\uac70\ub098 \uc18d\uc774 \ube48 \uad00\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc0dd\uac01\ub3c4 \uc7a0\uc2dc \ub0b4\ub824\ub193\uc744 \uc218 \uc788\ub2e4. \ub3cc\uc5d0\ub3c4 \uc74c\uc545\uc744 \ub9e1\uae34 \uc0ac\ub78c\ub4e4\uc774 \uc788\uc5c8\ub2e4."}, {"id": "trombone-sliding-notes", "title": "\ud2b8\ub86c\ubcf8 \uc5f0\uc8fc\uc790\ub294 \uc65c \ud314\uc744 \uae38\uac8c \ubed7\uc744\uae4c", "summary": "\uc55e\uc73c\ub85c \ub098\uac14\ub2e4 \ub3cc\uc544\uc624\ub294 \uae34 \uad00. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ub3d9\uc791\uc740 \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4.", "category": "culture", "category_title": "Culture", "subcategory": "Music", "url": "stories/trombone-sliding-notes/index.html", "image": "media/trombone-sliding-notes.jpg", "alt": "\uae08\ube5b \ud2b8\ub86c\ubcf8\uacfc \uae38\uac8c \ubed7\uc740 \uc2ac\ub77c\uc774\ub4dc\ub97c \ubcf4\uc5ec \uc8fc\ub294 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud2b8\ub86c\ubcf8 \uc5f0\uc8fc\uc790\ub294 \uc65c \ud314\uc744 \uae38\uac8c \ubed7\uc744\uae4c \uc18c\ub9ac \uc0ac\uc774\ub97c \ubbf8\ub044\ub7ec\uc9c0\ub294 \uae08\uad00\uc545\uae30 \uc55e\uc73c\ub85c \ub098\uac14\ub2e4 \ub3cc\uc544\uc624\ub294 \uae34 \uad00. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ub3d9\uc791\uc740 \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4. Music \ubb38\ud654 \uc624\ucf00\uc2a4\ud2b8\ub77c\uc5d0\uc11c \ud2b8\ub86c\ubcf8\uc744 \ucc3e\ub294 \uc26c\uc6b4 \ubc29\ubc95\uc774 \uc788\ub2e4. \uc5f0\uc8fc\uc790\uc758 \ud314\uc774 \uc55e\ub4a4\ub85c \uae38\uac8c \uc6c0\uc9c1\uc774\ub294 \uc790\ub9ac\ub97c \ubcf4\ub294 \uac83\uc774\ub2e4. \ubc88\uca4d\uc774\ub294 \uad00 \ud55c\ucabd\uc774 \ub098\uac14\ub2e4\uac00 \ub4e4\uc5b4\uc628\ub2e4. \ucc98\uc74c \ubcf4\uba74 \uc545\uae30\ub97c \ub298\uc600\ub2e4 \uc904\uc600\ub2e4 \ud558\ub294 \ubb18\uae30 \uac19\ub2e4. \ud558\uc9c0\ub9cc \uc5f0\uc8fc\uc790\ub294 \uadf8 \uc6c0\uc9c1\uc784\uc73c\ub85c \uc74c\uc744 \uace0\ub974\uace0 \uc788\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544 \uc624\ucf00\uc2a4\ud2b8\ub77c\ub294 \ud2b8\ub86c\ubcf8\uc758 \uc2ac\ub77c\uc774\ub4dc\ub97c \uc74c\ub192\uc774\ub97c \uc120\ud0dd\ud558\ub294 \uc7a5\uce58\ub85c \uc124\uba85\ud55c\ub2e4. \ud2b8\ub86c\ubcf8\uc758 \ub208\uc5d0 \ub744\ub294 \ubd80\ubd84\uc740 \uae38\uac8c \uc811\ud600 \ub3cc\uc544\uc624\ub294 \uad00\uc774\ub2e4. \uadf8 \uad00\uc758 \uc77c\ubd80\ub97c \ubbf8\ub044\ub7ec\ub728\ub9ac\ub294 \uc2ac\ub77c\uc774\ub4dc\uac00 \uc545\uae30 \ubc14\uae65\uc73c\ub85c \uae38\uac8c \ubed7\uc5b4 \uc788\ub2e4. \uc545\uae30\ub97c \ucc98\uc74c \ubcf4\ub294 \uc0ac\ub78c\ub3c4 \uc6c0\uc9c1\uc774\ub294 \uacf3\uc744 \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\ub2e4. \ubc84\ud2bc\uc744 \uc9e7\uac8c \ub204\ub974\ub294 \ub3d9\uc791\uacfc \ub2ec\ub9ac, \uc2ac\ub77c\uc774\ub4dc\uc758 \uc774\ub3d9\uc740 \uac1d\uc11d\uc5d0\uc11c\ub3c4 \ubcf4\uc778\ub2e4. \ud314\uc774 \ud070 \ub3d9\uc791\uc744 \ud558\uc9c0\ub9cc \ubaa9\uc801\uc740 \uc12c\uc138\ud558\ub2e4. \uc5f0\uc8fc\uc790\ub294 \uc545\uae30\uc758 \uae38\uc774\ub97c \ubc14\uafb8\uba70 \ud544\uc694\ud55c \uc18c\ub9ac\ub97c \ucc3e\uc544\uac04\ub2e4. \uadf8\ub798\uc11c \ud2b8\ub86c\ubcf8\uc740 \uc18c\ub9ac\ub97c \ub4e3\ub294 \uc7ac\ubbf8\uc640 \ub3d9\uc791\uc744 \ubcf4\ub294 \uc7ac\ubbf8\uac00 \ud568\uaed8 \uc788\ub294 \uc545\uae30\ub2e4. \uc6c0\uc9c1\uc784\uc744 \ud55c \ubc88 \uc54c\uc544\ub450\uba74 \ub9ce\uc740 \uc545\uae30\uac00 \ubaa8\uc778 \uc7a5\uba74\uc5d0\uc11c\ub3c4 \ub2e4\uc2dc \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud2b8\ub86c\ubcf8\uc740 \uc74c \uc0ac\uc774\ub97c \ubbf8\ub044\ub7ec\uc9c0\ub4ef \uc787\ub294 \uc18c\ub9ac\ub85c\ub3c4 \uc720\uba85\ud558\ub2e4. \u2018\uae00\ub9ac\uc0b0\ub3c4\u2019\ub77c\uace0 \ubd80\ub974\ub294 \ud6a8\uacfc\ub2e4. \ub2e8\uc5b4\ub97c \uc678\uc6b0\uae30\ubcf4\ub2e4 \uc18c\ub9ac\uac00 \uc544\ub798\uc704\ub85c \ucb49 \ubbf8\ub044\ub7ec\uc9c0\ub294 \ub290\ub08c\uc744 \ub5a0\uc62c\ub9ac\uba74 \uc27d\ub2e4. \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \uc774 \ud2b9\uc9d5\uc774 \ub9cc\ud654\uc758 \uc74c\uc545\uc5d0\uc11c\ub3c4 \uc624\ub7ab\ub3d9\uc548 \ud65c\uc6a9\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc6b0\uc2a4\uaf5d\uc2a4\ub7ec\uc6b4 \ub3d9\uc791\uc5d0 \ub9de\ucdb0 \uc18c\ub9ac\uac00 \ud718\uc5b4\uc9c0\ub294 \ub4ef\ud55c \uc7a5\uba74\uc744 \ub5a0\uc62c\ub9ac\uba74, \ub0af\uc120 \uc545\uae30\uac00 \uc870\uae08 \uc775\uc219\ud574\uc9c4\ub2e4. \uadf8\ub7ec\ub098 \ud2b8\ub86c\ubcf8\uc744 \uc6c3\uae34 \uc18c\ub9ac\ub9cc \ub0b4\ub294 \uc545\uae30\ub85c \uae30\uc5b5\ud558\uba74 \uc544\uc27d\ub2e4. \uac19\uc740 \uc548\ub0b4\ub294 \ud2b8\ub86c\ubcf8\uc774 \uc544\uc8fc \ubd80\ub4dc\ub7ec\uc6b4 \uc120\uc728\ub3c4 \uc5f0\uc8fc\ud560 \uc218 \uc788\ub2e4\uace0 \uac15\uc870\ud55c\ub2e4. \ud55c \uac00\uc9c0 \ud6a8\uacfc\uac00 \uc778\uc0c1\uc801\uc774\ub77c\uace0 \uadf8 \uc545\uae30\uc758 \ubaa8\ub4e0 \ud45c\uc815\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ud2b8\ub86c\ubcf8\uc740 \uc624\ucf00\uc2a4\ud2b8\ub77c\uac00 \uc6c5\uc7a5\ud574\uc9c0\ub294 \uc21c\uac04\uc5d0 \ud798\uc744 \ubcf4\ud0dc\uae30\ub3c4 \ud55c\ub2e4. \uadf8\ub798\uc11c \ud06c\uace0 \uac15\ud55c \uc18c\ub9ac\ubd80\ud130 \uc5f0\uc0c1\ud558\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \ud544\ud558\ubaa8\ub2c8\uc544\ub294 \ub974\ub124\uc0c1\uc2a4 \uc2dc\ub300\uc5d0 \uad50\ud68c\uc5d0\uc11c \ud2b8\ub86c\ubcf8 \ud569\uc8fc\ub85c \uc5f0\uc8fc\ud558\ub358 \uc12c\uc138\ud55c \uc74c\uc545\ub3c4 \uc18c\uac1c\ud55c\ub2e4. \ubb34\ub300\uc5d0\uc11c \ubcf4\uc774\ub294 \uae34 \uad00\uacfc \ud798\ucc2c \uc790\uc138\ub9cc\uc73c\ub85c \uc18c\ub9ac\uc758 \uc131\uaca9\uc744 \ud558\ub098\ub85c \uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ubd80\ub4dc\ub7fd\uac8c \uc774\uc5b4\uc9c0\ub294 \uc120\uc728\uc744 \ub4e4\uc744 \ub54c\uc5d0\ub3c4 \uac19\uc740 \uc2ac\ub77c\uc774\ub4dc\uac00 \uc6c0\uc9c1\uc778\ub2e4. \ub2e4\uc74c\uc5d0 \uacf5\uc5f0 \uc601\uc0c1\uc744 \ubcfc \ub54c\ub294 \ud314\uc774 \uc55e\uc73c\ub85c \ub098\uc624\ub294 \uc21c\uac04\uacfc \uadf8\ub54c\uc758 \uc18c\ub9ac\ub97c \ud568\uaed8 \ub530\ub77c\uac00 \ubcf4\uc790. \ud07c\uc9c1\ud55c \ub3d9\uc791 \uc18d\uc5d0\uc11c \uc74c\uc744 \uace0\ub974\ub294 \uc77c\uc774 \uc0dd\uac01\ubcf4\ub2e4 \uc870\uc6a9\ud558\uace0 \uc138\ubc00\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\ub2e4."}, {"id": "blue-dish-hidden-fortune", "title": "\uc811\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\ub2e4", "summary": "\ubc31\uc790 \uc811\uc2dc\uc758 \uac00\uc6b4\ub370\uc640 \ubc14\uae65\uba74\uc744 \ub530\ub77c\uac00\uba70 \uae00\uc790\uc640 \uaf43\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/blue-dish-hidden-fortune/index.html", "image": "media/blue-dish-hidden-fortune.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubc31\uc790\uccad\ud654\ubcf5\uc790\u00b7\ud480\uaf43\ubb34\ub2ac\uc811\uc2dc \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc811\uc2dc \ubc14\ub2e5\uc5d0\uc11c \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\ub2e4 \uc74c\uc2dd \uc544\ub798\uc5d0 \uc228\uc5b4 \uc788\uc744 \ud478\ub978 \uc778\uc0ac \ubc31\uc790 \uc811\uc2dc\uc758 \uac00\uc6b4\ub370\uc640 \ubc14\uae65\uba74\uc744 \ub530\ub77c\uac00\uba70 \uae00\uc790\uc640 \uaf43\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. Food \uc0dd\ud65c \uc74c\uc2dd\uc744 \ub2f4\uc740 \uc811\uc2dc\uc5d0\uc11c\ub294 \uc694\ub9ac\uac00 \uba3c\uc800 \ubcf4\uc778\ub2e4. \uadf8\ub987 \ud55c\uac00\uc6b4\ub370 \uc5b4\ub5a4 \uadf8\ub9bc\uc774 \uc788\ub294\uc9c0\ub294 \ub2e4 \uba39\uace0 \ub098\uc11c\uc57c \uc54c\uac8c \ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4. \uc774 \uc811\uc2dc\ub77c\uba74 \ub9c8\uc9c0\ub9c9\uc5d0 \ubcf5 \ud55c \uae00\uc790\ub97c \ub9cc\ub098\uac8c \ub420\uc9c0\ub3c4 \ubaa8\ub974\uaca0\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \ubc31\uc790\uccad\ud654\ubcf5\uc790\u00b7\ud480\uaf43\ubb34\ub2ac\uc811\uc2dc\ub2e4. \uc774\ub984\uc740 \uae38\uc9c0\ub9cc \ub208\uc5ec\uaca8\ubcfc \uac83\uc740 \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \ud770 \ubc14\ud0d5\uc5d0 \ud478\ub978 \uc120, \uc548\ucabd\uc758 \uae00\uc790, \ubc14\uae65\ucabd\uc758 \uaf43\uc774\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc811\uc2dc \uc548\ubc14\ub2e5\uc5d0\ub294 \ucee4\ub2e4\ub780 \uc6d0 \ub450 \uc904\uc774 \uc788\uace0 \uadf8 \uc548\uc5d0 \ub3c4\uc548\ud654\ub41c \ubcf5, \uace7 \u798f \uae00\uc790\uac00 \uc788\ub2e4. \ubd93\uae00\uc528 \ud55c \uae00\uc790\ub97c \uadf8\ub300\ub85c \uc801\uc740 \uac83\uc774 \uc544\ub2c8\ub77c \ubb34\ub2ac\ucc98\ub7fc \uad6c\uc131\ud55c \uae00\uc790\ub2e4. \uadf8\ub798\uc11c \ucc98\uc74c\uc5d0\ub294 \uaf43\uc774\ub098 \uae30\ud558\ud559\ubb34\ub2ac\ub85c \ubcf4\uc77c \uc218 \uc788\ub2e4. \uae00\uc790\ub77c\ub294 \uc124\uba85\uc744 \ub4e3\uace0 \ub098\uba74 \uac00\uc6b4\ub370\ub97c \ub2e4\uc2dc \ub4e4\uc5ec\ub2e4\ubcf4\uac8c \ub41c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud55c \ubc88\uc5d0 \uc77d\ud788\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc774\uc0c1\ud55c \uc77c\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc744 \uc54c\uace0 \ucc3e\uc544\ubcf4\ub294 \uacfc\uc815 \uc790\uccb4\uac00 \uc774 \uc811\uc2dc\ub97c \ubcf4\ub294 \uc7ac\ubbf8\ub2e4. \uc7a5\uc2dd\uc740 \uc74c\uc2dd\uc774 \ub193\uc77c \uc548\ucabd\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4. \ubc14\uae65\uba74\uc740 S\uc790 \ubaa8\uc591\uc758 \uc120\uc73c\ub85c \ub2e4\uc12f \uad6c\uc5ed\uc744 \ub098\ub204\uace0 \uac01 \uce78\uc5d0 \ud480\uaf43\ubb34\ub2ac\ub97c \uadf8\ub838\ub2e4\uace0 \ud55c\ub2e4. \ud14c\ub450\ub9ac\uc640 \uad7d\uc5d0\ub3c4 \ud478\ub978 \uc120\uc774 \ub458\ub7ec\uc838 \uc788\ub2e4. \ud55c \uc811\uc2dc\ub97c \uc704\uc5d0\uc11c \ubcf4\uba74 \uae00\uc790\uac00 \uc911\uc2ec\uc774\uace0, \uc606\uc5d0\uc11c \ubcf4\uba74 \uaf43\uc774 \uc911\uc2ec\uc774 \ub41c\ub2e4. \uc815\uba74 \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc\uc73c\ub85c \ubb3c\uac74\uc744 \ub2e4 \ubcf4\uc558\ub2e4\uace0 \ub290\ub07c\uae30 \uc26c\uc6b4\ub370, \uadf8\ub987\uc740 \ubc14\ub77c\ubcf4\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc804\ud600 \ub2e4\ub978 \ubd80\ubd84\uc744 \ub0b4\uc900\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc5d0\ub294 \uc785\uc9c0\ub984\uc774 18\uc13c\ud2f0\ubbf8\ud130\ub77c\uace0 \uc801\ud600 \uc788\ub2e4. \uac70\ub300\ud55c \uc804\uc2dc\uc6a9 \uc811\uc2dc\ub97c \uc0c1\uc0c1\ud558\uae30\ubcf4\ub2e4 \ud06c\uae30\ub97c \uac00\ub2a0\ud558\uba70 \ubcf4\uba74 \ubb34\ub2ac\uc640\uc758 \uac70\ub9ac\ub3c4 \uc870\uae08 \uac00\uae4c\uc6cc\uc9c4\ub2e4. \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc74c\uc2dd\uc744 \ub2f4\uc558\uace0 \ub204\uac00 \uc0ac\uc6a9\ud588\ub294\uc9c0\ub294 \uc774 \uc790\ub8cc\uc5d0\uc11c \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \ubcf5\uc744 \ub9cc\ub09c\ub2e4\ub294 \uccab \uc7a5\uba74\ub3c4 \uadf8\ub987\uc758 \ubc30\uce58\ub97c \ub5a0\uc62c\ub824 \ubcf8 \uc6b0\ub9ac\uc758 \uc0c1\uc0c1\uc774\ub2e4. \ud655\uc2e4\ud55c \uac83\uc740 \ube48 \uc811\uc2dc\ub9cc\uc73c\ub85c\ub3c4 \ubcfc\uac70\ub9ac\uac00 \uc788\ub2e4\ub294 \uc0ac\uc2e4\uc774\ub2e4. \uac00\uc6b4\ub370\uc758 \uae00\uc790\ub97c \ubcf4\uace0, \uc606\uc758 \uaf43\uc744 \ubcf4\ub294 \uac83. \uc2dd\ud0c1\uc758 \ubb3c\uac74\uc744 \ucc9c\ucc9c\ud788 \uc77d\ub294 \uac04\ub2e8\ud55c \ubc29\ubc95\uc774\ub2e4."}, {"id": "brazier-animal-feet", "title": "\ud654\ub85c \uc544\ub798\uc5d0 \uc791\uc740 \uc9d0\uc2b9\uc758 \ubc1c\uc774 \uc788\ub2e4", "summary": "\ud3c9\ubc94\ud55c \uc138 \ubc1c\ucc98\ub7fc \ubcf4\uc774\ub358 \ud654\ub85c \ub2e4\ub9ac\uc5d0 \uc5bc\uad74\uacfc \ubc1c\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/brazier-animal-feet/index.html", "image": "media/brazier-animal-feet.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc0bc\uc871\ud654\ub85c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ud654\ub85c \uc544\ub798\uc5d0 \uc791\uc740 \uc9d0\uc2b9\uc758 \ubc1c\uc774 \uc788\ub2e4 \ub530\ub73b\ud568\uc744 \ub2f4\ub294 \uadf8\ub987\uc758 \ub73b\ubc16\uc758 \ud45c\uc815 \ud3c9\ubc94\ud55c \uc138 \ubc1c\ucc98\ub7fc \ubcf4\uc774\ub358 \ud654\ub85c \ub2e4\ub9ac\uc5d0 \uc5bc\uad74\uacfc \ubc1c\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. Housing \uc0dd\ud65c \ub465\uadfc \ud654\ub85c \ud55c \uc810\uc774 \ub193\uc5ec \uc788\ub2e4. \uac00\uc6b4\ub370\ub294 \uae4a\uac8c \ud30c\uc600\uace0 \uac00\uc7a5\uc790\ub9ac\ub294 \ub113\uac8c \ubc8c\uc5b4\uc84c\ub2e4. \uc704\uc5d0\uc11c \ubcf4\uba74 \uaf64 \uc58c\uc804\ud55c \ubb3c\uac74\uc778\ub370, \uc2dc\uc120\uc744 \uc544\ub798\ub85c \ub0b4\ub9ac\uba74 \ubd84\uc704\uae30\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc138 \ub2e4\ub9ac\uac00 \uc791\uc740 \uc9d0\uc2b9\ucc98\ub7fc \uc0dd\uacbc\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uc0bc\uc871\ud654\ub85c\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc601\uce5c\uc655\ube44 \uc774\ubc29\uc790\uac00 \uc18c\uc720\ud588\ub358 \ubb3c\uac74\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac70\ucc3d\ud55c \uc758\ub840 \uc7a5\uba74\uc744 \uc0c1\uc0c1\ud558\uae30 \uc804\uc5d0, \uba3c\uc800 \uadf8 \ubc1c\ubd80\ud130 \uc0b4\ud3b4\ubcf4\uba74 \uc88b\uaca0\ub2e4. \ub2e4\ub9ac\uc758 \uc704\ucabd\uc5d0\ub294 \ubfd4\uc774 \ub450 \uac1c \ub2ec\ub9b0 \uc5bc\uad74\uc774 \ud45c\ud604\ub418\uc5b4 \uc788\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc758 \uc774\ub984\uc740 \uadc0\uba74\uc774\ub2e4. \ub0af\uc120 \ub2e8\uc5b4\uc9c0\ub9cc \uc0ac\uc9c4\uacfc \ud568\uaed8 \ubcf4\uba74 \uc870\uae08 \uc27d\ub2e4. \ub2e4\ub9ac\uc640 \ubab8\ud1b5\uc774 \ub9cc\ub098\ub294 \uacf3\uc5d0 \uc785\uccb4\uc801\uc778 \uc5bc\uad74\uc774 \ub193\uc5ec \uc788\ub2e4\ub294 \ub73b\uc774\ub2e4. \uadf8 \uc544\ub798\ub294 \ub3d9\ubb3c\uc758 \ubc1c \ud615\ud0dc\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uc5bc\uad74\uc774 \uc788\uace0 \ubc1c\uc774 \uc788\uc73c\ub2c8 \ub2e8\uc21c\ud788 \ubc1b\uce68 \uc138 \uac1c\ub97c \ubd99\uc778 \uac83\uacfc\ub294 \uc778\uc0c1\uc774 \ub2e4\ub974\ub2e4. \ub465\uadfc \ubab8\uccb4\ub97c \uc791\uc740 \uc0dd\ubb3c\ub4e4\uc774 \ubc1b\ub4e4\uace0 \uc788\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc774\uac83\uc740 \ubaa8\uc591\uc5d0\uc11c \uc5bb\ub294 \uac10\uc0c1\uc774\uc9c0, \ud2b9\uc815 \ub3d9\ubb3c\uc744 \ud655\uc778\ud588\ub2e4\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \ud654\ub85c\ub294 \uad6c\ub9ac\ub85c \ub9cc\ub4e0 \ubab8\uccb4\uc5d0 \uc138 \uac1c\uc758 \ub2e4\ub9ac\uac00 \ub2ec\ub9b0 \uad6c\uc870\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub2e4\ub9ac\ub97c \ub530\ub85c \uc8fc\uc870\ud55c \ub2e4\uc74c \ub9ac\ubcb3\uc73c\ub85c \ubab8\uccb4\uc5d0 \ubd99\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud55c \ub369\uc5b4\ub9ac \uac19\uc544\ub3c4 \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\uc11c\ub294 \ubd80\ud488\uc774 \ub098\ub258\uc5c8\ub358 \uac83\uc774\ub2e4. \ub113\uc740 \ud14c\ub450\ub9ac \ub05d\uc5d0\ub294 \ub465\uae00\uac8c \ud131\ub3c4 \uc84c\ub2e4. \ubab8\uccb4\uc640 \ub2e4\ub9ac, \uac00\uc7a5\uc790\ub9ac\ub97c \ucc28\ub840\ub85c \ubcf4\uba74 \ud070 \ubaa8\uc591 \uc548\uc5d0 \uc11c\ub85c \ub2e4\ub978 \uc791\uc5c5\uc774 \ub4e4\uc5b4 \uc788\uc74c\uc744 \uc54c\uac8c \ub41c\ub2e4. \uc7a5\uc778\uc758 \uc190\uae38\uc744 \ucc3e\ub294 \ub370 \ubc18\ub4dc\uc2dc \ubcf5\uc7a1\ud55c \ubb38\uc591\ubd80\ud130 \uc77d\uc5b4\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c \uc5b4\ub5a4 \uc5bc\uad74\uc774 \uc5b4\ub5a4 \ud798\uc744 \uc9c0\ucf1c \uc8fc\uc5c8\ub2e4\uace0 \ub2e8\uc815\ud560 \uc790\ub8cc\ub294 \uc5ec\uae30\uc11c \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \uadf8\ub798\uc11c \uc0c1\uc9d5 \ud480\uc774\ub97c \uae38\uac8c \ubd99\uc774\uae30\ubcf4\ub2e4 \uc2e4\uc81c \ub0a8\uc544 \uc788\ub294 \ud615\ud0dc\ub97c \ubcf4\ub294 \ud3b8\uc774 \ub354 \uc990\uac81\ub2e4. \ub2e4\uc74c\uc5d0 \ud654\ub85c\ub098 \ud5a5\ub85c\ub97c \ub9cc\ub098\uba74 \uadf8\ub987 \uc548\ucabd\ub9cc \ub4e4\uc5ec\ub2e4\ubcf4\uc9c0 \ub9d0\uace0 \uc544\ub798\ub3c4 \ubcf4\uc790. \ubc14\ub2e5\uc744 \ub51b\uace0 \uc788\ub294 \ubc1c\uc5d0 \uc758\uc678\ub85c \uac00\uc7a5 \uc7ac\ubbf8\uc788\ub294 \ud45c\uc815\uc774 \uc228\uc5b4 \uc788\uc744\uc9c0 \ubaa8\ub978\ub2e4. \uc774 \uc0bc\uc871\ud654\ub85c\uc5d0\uc11c\ub294 \ub530\ub73b\ud55c \uadf8\ub987\ubcf4\ub2e4 \uba3c\uc800 \uc138 \ubc1c\uc758 \uac1c\uc131\uc774 \uae30\uc5b5\uc5d0 \ub0a8\ub294\ub2e4."}, {"id": "christmas-pudding-sixpence", "title": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc5d0\ub294 \uc65c \ub3d9\uc804 \uc774\uc57c\uae30\uac00 \ub530\ub77c\uc62c\uae4c", "summary": "\uc5f0\ub9d0 \ub514\uc800\ud2b8 \uc606\uc5d0 \uc740\ube5b \ub3d9\uc804\uc774 \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \ub3c8\uc758 \uc561\uba74\ubcf4\ub2e4 \ud589\uc6b4\uc744 \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uc55e\uc5d0 \ub193\uc774\ub294 \ud48d\uc2b5\uc785\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Folks", "url": "stories/christmas-pudding-sixpence/index.html", "image": "media/christmas-pudding-sixpence.jpg", "alt": "\ud478\ub529 \uc811\uc2dc \ubc14\uae65\uc5d0 \uc740\ube5b \ub3d9\uc804\uc744 \ub098\ub780\ud788 \ub193\uc740 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc5d0\ub294 \uc65c \ub3d9\uc804 \uc774\uc57c\uae30\uac00 \ub530\ub77c\uc62c\uae4c \uc791\uc740 \uc2dd\uc2a4\ud39c\uc2a4\uc5d0 \ub2f4\uc544 \ub450\uc5c8\ub358 \uc0c8\ud574\uc758 \ubc14\ub78c \uc5f0\ub9d0 \ub514\uc800\ud2b8 \uc606\uc5d0 \uc740\ube5b \ub3d9\uc804\uc774 \ub4f1\uc7a5\ud569\ub2c8\ub2e4. \ub3c8\uc758 \uc561\uba74\ubcf4\ub2e4 \ud589\uc6b4\uc744 \ubc14\ub77c\ub294 \ub9c8\uc74c\uc774 \uc55e\uc5d0 \ub193\uc774\ub294 \ud48d\uc2b5\uc785\ub2c8\ub2e4. Folks \uc0dd\ud65c \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529 \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub465\uadfc \ub514\uc800\ud2b8 \uc606\uc5d0 \uc791\uc740 \uc740\ube5b \ub3d9\uc804\uc774 \ub193\uc5ec \uc788\uae30\ub3c4 \ud558\ub2e4. \ud6c4\uc2dd \uac12\uc744 \ubbf8\ub9ac \uacc4\uc0b0\ud574 \ub454 \uac83\uc77c\uae4c. \uadf8 \ub3d9\uc804\uc740 \uc601\uad6d\uc758 \uc2dd\uc2a4\ud39c\uc2a4\uc640 \uad00\ub828\ub41c \ud48d\uc2b5\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud55c\ub2e4. \ud478\ub529 \uc18d\uc5d0 \ub3d9\uc804\uc744 \uc228\uae30\uace0, \uadf8\uac83\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub2e4\uc74c \ud574\uc758 \uc88b\uc740 \uc6b4\uc774 \uc624\uae30\ub97c \ubc14\ub790\ub2e4\ub294 \uc774\uc57c\uae30\ub2e4. \ub3d9\uc804\uc774 \ub3c8\uc744 \ub0b4\ub294 \uc790\ub9ac\uc5d0\uc11c \uc7a0\uae50 \ubc97\uc5b4\ub098 \uc18c\uc6d0\uc744 \ub2f4\ub294 \ubb3c\uac74\uc774 \ub41c\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 2024\ub144 \ubcf4\ub3c4\uc790\ub8cc\uc5d0\uc11c \u2018\uc2a4\ud138\uc5c5 \uc120\ub370\uc774\u2019\ub77c\ub294 \ud48d\uc2b5\uc744 \uc18c\uac1c\ud588\ub2e4. \ub300\ub9bc\uc808\uc774 \uc2dc\uc791\ub418\uae30 \uc804 \ub9c8\uc9c0\ub9c9 \uc77c\uc694\uc77c, \uac00\uc871\uacfc \uce5c\uad6c\uac00 \ubaa8\uc5ec \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ud478\ub529\uc744 \uc900\ube44\ud558\ub294 \ub0a0\uc774\ub2e4. \uc790\ub8cc\uc5d0 \uc18c\uac1c\ub41c \uc74c\uc2dd\uc0ac \uc5f0\uad6c\uc790 \uc560\ub2c8 \uadf8\ub808\uc774\ub294 \uc0ac\ub78c\ub4e4\uc774 \ubc18\uc8fd\uc744 \ubc88\uac08\uc544 \uc800\uc73c\uba70 \uc18c\uc6d0\uc744 \ube4c\ub358 \uc804\ud1b5\uc744 \uc124\uba85\ud55c\ub2e4. \ud06c\ub9ac\uc2a4\ub9c8\uc2a4 \ub2f9\uc77c\ub9cc \uae30\ub2e4\ub9ac\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \ubbf8\ub9ac \ubaa8\uc5ec \uc900\ube44\ud558\ub294 \uc2dc\uac04\uc5d0\ub3c4 \uc758\ubbf8\ub97c \ub450\uc5c8\ub358 \uc148\uc774\ub2e4. \uc774 \uc774\ub984\uc5d0\ub294 \u2018\uc800\uc5b4 \uc11e\ub2e4\u2019\ub77c\ub294 \ub73b\uacfc \uc5f0\uacb0\ub418\ub294 \ub9d0\uc7a5\ub09c\ub3c4 \uc788\ub2e4. \uadf8\ub808\uc774\ub294 \uad50\ud68c\uc758 \uae30\ub3c4\ubb38\uc5d0 \ub098\uc624\ub294 \ud45c\ud604\uc774 \ud478\ub529 \uc900\ube44\ub97c \ub5a0\uc62c\ub9ac\ub294 \uacc4\uae30\ub85c \uc4f0\uc600\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uae38\uace0 \uc5b4\ub824\uc6b4 \uc124\uba85\ubcf4\ub2e4, \uc775\uc219\ud55c \ub9d0\uc744 \uc5f0\ub9d0\uc758 \ud560 \uc77c\uacfc \uc5ee\uc5b4 \uae30\uc5b5\ud55c \ubaa8\uc2b5\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uac19\uc740 \uc790\ub8cc\ub294 \ub354 \uc624\ub798\ub41c \ud2b8\uc6f0\ud504\uc2a4 \ucf00\uc774\ud06c\uc5d0 \ud45c\uc2dd\uc744 \uc228\uae30\ub358 \ud48d\uc2b5\ub3c4 \uc774\uc57c\uae30\ud55c\ub2e4. \uc774\ud6c4\uc758 \ud478\ub529 \uc804\ud1b5\uc5d0\uc11c\ub294 \uc791\uc740 \ub3d9\uc804\uc744 \ucc3e\uc740 \uc0ac\ub78c\uc5d0\uac8c \ubd80\uc640 \uac74\uac15, \ud589\ubcf5\uc744 \uae30\uc6d0\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub3d9\uc804\uc744 \ucc3e\uc558\ub2e4\uace0 \uc2e4\uc81c\ub85c \ubbf8\ub798\uac00 \ub2ec\ub77c\uc9c4\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ud55c \ud574\ub97c \ub9c8\ubb34\ub9ac\ud558\ub294 \uc790\ub9ac\uc5d0 \ub2e4\uc74c \ud574\uc758 \ubc14\ub78c\uc744 \uc5b9\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \ud3c9\ubc94\ud55c \ud6c4\uc2dd\uc5d0 \uc791\uc740 \ub73b\ubc16\uc758 \uc77c\uc774 \ub354\ud574\uc9c4\ub2e4. \uadf8\ub798\uc11c \uc774 \uc774\uc57c\uae30\uc5d0\uc11c \ub3d9\uc804\uc758 \uc561\uba74\uc740 \uc8fc\uc778\uacf5\uc774 \uc544\ub2c8\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ud568\uaed8 \uc900\ube44\ud558\uace0, \ub204\uad70\uac00 \uc88b\uc740 \uac83\uc744 \ubc1c\uacac\ud558\uae30\ub97c \uae30\ub300\ud588\ub2e4\ub294 \uae30\uc5b5\uc774 \ub3d9\uc804 \uc8fc\ubcc0\uc5d0 \ub0a8\ub294\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc774 \uc774 \uc790\ub8cc\ub97c \ub0b8 \uac83\uc740 \uc804\ud1b5\uc744 \ub418\uc0b4\ub9ac\ub824\ub294 \uc0c1\ud488 \ud64d\ubcf4\uc640\ub3c4 \uad00\ub828\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub2c8 \uc624\ub298\uc758 \uc601\uad6d \uac00\uc815\uc774 \ubaa8\ub450 \uac19\uc740 \ud478\ub529\uc744 \ub9cc\ub4e4\uace0 \uac19\uc740 \ud48d\uc2b5\uc744 \uc9c0\ud0a8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uadf8 \uc810\uc744 \uc54c\uace0 \uc77d\uc5b4\ub3c4 \uc791\uc740 \uc774\uc57c\uae30\ub294 \ub0a8\ub294\ub2e4. \ud2b9\ubcc4\ud55c \ub0a0\uc758 \uc74c\uc2dd\uc5d0\ub294 \ub9db\uacfc \uc7ac\ub8cc\ub9cc \ub4e4\uc5b4\uac00\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \uc900\ube44\ud558\ub294 \uc21c\uc11c, \ud568\uaed8\ud558\ub294 \uc0ac\ub78c, \uc88b\uc740 \uc6b4\uc744 \ubc14\ub77c\ub358 \ub9c8\uc74c\ub3c4 \ubd99\uc5b4 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ud478\ub529 \uc606\uc758 \uc740\ube5b \ub3d9\uc804\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \ud6c4\uc2dd \uac12 \ub300\uc2e0 \ub204\uad70\uac00\uc758 \uc18c\uc6d0\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774\ubc88 \uc0bd\ud654\ucc98\ub7fc \ub3d9\uc804\uc744 \uc811\uc2dc \ubc16\uc5d0 \ub098\ub780\ud788 \ub193\uc544\ub450\uc5b4\ub3c4, \uadf8 \uc791\uc740 \ubb3c\uac74\uc774 \ub4e4\ub824\uc8fc\ub294 \uc5f0\ub9d0 \uc774\uc57c\uae30\ub294 \ucda9\ubd84\ud788 \uc804\ud574\uc9c4\ub2e4."}, {"id": "crane-embroidered-badge", "title": "\uad00\ubcf5\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub294 \ubb34\uc5c7\uc744 \uc54c\ub824\uc904\uae4c", "summary": "\uc637 \uc704\uc758 \uc791\uc740 \uadf8\ub9bc\uc5d0\ub294 \uc785\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc704\uc640 \uc790\uc218\uc758 \uc19c\uc528\uac00 \ud568\uaed8 \ub2f4\uacbc\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Clothing", "url": "stories/crane-embroidered-badge/index.html", "image": "media/crane-embroidered-badge.jpg", "alt": "\ub450 \ud559\uacfc \uc2dd\ubb3c \ubb34\ub2ac\ub97c \uc5ec\ub7ec \uc0c9 \uc2e4\ub85c \uc218\ub193\uc740 \uc30d\ud559\ubb34\ub2ac \ud749\ubc30\uc758 \uc138\ubd80 \uc0ac\uc9c4", "text": "\uad00\ubcf5\uc758 \ud559 \ub450 \ub9c8\ub9ac\ub294 \ubb34\uc5c7\uc744 \uc54c\ub824\uc904\uae4c \uc30d\ud559\ubb34\ub2ac \ud749\ubc30\ub97c \uac00\uae4c\uc774\uc5d0\uc11c \ubcf4\ub294 \uc7ac\ubbf8 \uc637 \uc704\uc758 \uc791\uc740 \uadf8\ub9bc\uc5d0\ub294 \uc785\ub294 \uc0ac\ub78c\uc758 \uc9c0\uc704\uc640 \uc790\uc218\uc758 \uc19c\uc528\uac00 \ud568\uaed8 \ub2f4\uacbc\uc2b5\ub2c8\ub2e4. Clothing \uc0dd\ud65c \uc61b \uad00\ubcf5\uc744 \ubcf4\uba74 \uac00\uc2b4\uaed8\uc758 \uc0ac\uac01\ud615 \uadf8\ub9bc\uc774 \uba3c\uc800 \ub208\uc5d0 \ub74c \ub54c\uac00 \uc788\ub2e4. \ub113\uc740 \uc637 \ud55c\uac00\uc6b4\ub370\uc5d0\uc11c \ub3d9\ubb3c\uc774 \ub0a0\uac70\ub098 \uad6c\ub984 \uc0ac\uc774\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\uc30d\ud559\ubb34\ub2ac \ud749\ubc30\u300d\uc5d0\ub294 \ub450 \ub9c8\ub9ac \ud559\uc774 \uc704\uc544\ub798\ub85c \ub9c8\uc8fc \ubcf4\uace0 \uc788\ub2e4. \uac00\uae4c\uc774 \ubcf4\uba74 \ud770 \ubab8\uacfc \ub0a0\uac1c\ub3c4 \ubb3c\uac10\uc774 \uc544\ub2c8\ub77c \uc2e4\ub85c \ub9cc\ub4e4\uc5b4\uc838 \uc788\ub2e4. \uc608\uc05c \uadf8\ub9bc\uc744 \uc637\uc5d0 \ubd99\uc778 \uac83\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc774 \ubb3c\uac74\uc5d0\ub294 \ucc29\uc6a9\uc790\uc758 \uc9c0\uc704\ub97c \ub098\ud0c0\ub0b4\ub294 \uc5ed\ud560\ub3c4 \uc788\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \ud749\ubc30\ub97c \ubb38\uad00 \ub2f9\uc0c1\uad00\uc774 \ucc29\uc6a9\ud55c \uac83\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ub2f9\uc0c1\uad00\uc740 \uad00\ub8cc\uc758 \ub192\uc740 \uc9c0\uc704\uc5d0 \uc18d\ud558\ub294 \uad6c\ubd84\uc774\ub2e4. \uc5ec\uae30\uc11c\ub294 \uc138\uc138\ud55c \ud488\uacc4\ud45c\ubcf4\ub2e4, \uc637\uc758 \ubb38\uc591\uc774 \uc544\ubb34\ub807\uac8c\ub098 \uc815\ud574\uc9c0\uc9c0\ub294 \uc54a\uc558\ub2e4\ub294 \uc810\uc744 \uc54c\uc544\ub450\uba74 \ub41c\ub2e4. \ubc15\ubb3c\uad00\uc758 \uad81\uc911 \uc790\uc218 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c\ub3c4 \uc2e0\ud558\ub4e4\uc5d0\uac8c \uad00\uc9c1\uacfc \ub4f1\uae09\uc5d0 \ub530\ub77c \uc218\uc2e4\uacfc \ubb38\uc591\uc744 \ub2ec\ub9ac\ud55c \ud749\ubc30\ub97c \ub0b4\ub838\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc7a5\uc2dd\uacfc \uc0ac\ud68c\uc801\uc778 \uad6c\ubd84\uc774 \uac19\uc740 \ubb3c\uac74 \uc548\uc5d0 \uc788\uc5c8\ub2e4. \uadf8\ub807\ub2e4\uace0 \ub3d9\ubb3c\uc758 \uc218\ub9cc \uc678\uc6cc \ubaa8\ub4e0 \uc2dc\ub300\uc758 \uad00\ubcf5\uc744 \ub9de\ud788\ub294 \uc2dc\ud5d8\uc744 \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ubcf4\ub294 \ud55c \uc810\uc758 \uc124\uba85\ubd80\ud130 \uc77d\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4. \uc774 \ud749\ubc30\uc5d0\ub294 \ud559 \ub450 \ub9c8\ub9ac\uc640 \ubd88\ub85c\ucd08\ub97c \ubb38 \ubaa8\uc2b5\uc774 \uc218\ub193\uc5ec \uc788\ub2e4. \uc0ac\uc9c4\uc744 \ud655\ub300\ud558\uba74 \ud770 \ub0a0\uac1c\ub97c \ucc44\uc6b4 \uc2e4\uc758 \uacb0\uc744 \ubcfc \uc218 \uc788\ub2e4. \uad6c\ub984 \uac00\uc7a5\uc790\ub9ac\uc5d0\ub294 \ub610 \ub2e4\ub978 \ube5b\uae54\uacfc \uc9c8\uac10\uc774 \uc774\uc5b4\uc9c4\ub2e4. \uba40\ub9ac\uc11c\ub294 \ud558\ub098\uc758 \uadf8\ub9bc\uc774\uc9c0\ub9cc \uac00\uae4c\uc774\uc5d0\uc11c\ub294 \uc791\uc740 \uc2e4\uc758 \uc6c0\uc9c1\uc784\uc73c\ub85c \ub098\ub25c\ub2e4. \uad81\uc911 \uc790\uc218\ub294 \uc804\ubb38 \ud654\uc6d0\uc774 \ubc11\uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \uc218\ubc29\uc758 \uc0ac\ub78c\ub4e4\uc774 \uc774\ub97c \uc62e\uaca8 \uc218\ub193\ub294 \ubc29\uc2dd\uc73c\ub85c \uc81c\uc791\ub418\uc5c8\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc124\uba85\ud55c\ub2e4. \uadf8\ub9ac\ub294 \uc77c\uacfc \ubc14\ub290\uc9c8\ud558\ub294 \uc77c\uc774 \ud55c \ubb3c\uac74\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \ud3c9\uba74\uc758 \uadf8\ub9bc\uc740 \uc637\uac10 \uc704\uc758 \uc9c8\uac10\uc744 \uc5bb\ub294\ub2e4. \ube5b\uc744 \ubc1b\ub294 \ubc29\ud5a5\uc5d0 \ub530\ub77c \uc2e4\uc758 \ud45c\uba74\uc774 \ub2ec\ub77c \ubcf4\uc774\ub294 \uac83\ub3c4 \uc790\uc218 \uc0ac\uc9c4\uc744 \ubcf4\ub294 \uc990\uac70\uc6c0\uc774\ub2e4. \ub3d9\ubb3c\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf8 \ub4a4\uc5d0\ub294 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0\ub3c4 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubcf5\uc2dd \uc804\uc2dc\uc5d0\ub294 \ub0af\uc120 \uc637 \uc774\ub984\uacfc \uae34 \uc124\uba85\uc774 \ubd99\uc5b4 \uc788\uae30 \uc27d\ub2e4. \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \uc678\uc6b0\ub824 \ud558\uba74 \uad00\ub78c\uc774 \uacf5\ubd80\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f4 \ub54c\ub294 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \ubb38\uc591 \ud558\ub098\ubd80\ud130 \ucc3e\uc544\ubcf4\uc544\ub3c4 \uc88b\ub2e4. \ud559\uc758 \ub0a0\uac1c\uac00 \uc5b4\ub514\uae4c\uc9c0 \ud3bc\uccd0\uc838 \uc788\ub294\uc9c0, \uad6c\ub984\uc740 \uc5b4\ub5a4 \uc0c9\uc778\uc9c0, \uac19\uc740 \ud770 \ubd80\ubd84\ub3c4 \uc2e4\uc758 \ubc29\ud5a5\uc774 \ub2e4\ub978\uc9c0 \uc0b4\ud3b4\ubcf4\uc790. \uc54c\uace0 \uc788\ub294 \ub3d9\ubb3c\uc774 \ub0af\uc120 \uc637\uc744 \ubcf4\ub294 \uc785\uad6c\uac00 \ub41c\ub2e4. \uadf8\ub2e4\uc74c \uc124\uba85\uc5d0\uc11c \ub204\uac00 \uc785\ub358 \uac83\uc778\uc9c0 \ud655\uc778\ud558\uba74 \uc791\uc740 \uadf8\ub9bc\uc758 \ub450 \uc5ed\ud560\uc774 \ud568\uaed8 \ubcf4\uc778\ub2e4. \ud55c \uc0ac\ub78c\uc758 \uc790\ub9ac\ub97c \uc54c\ub824\uc8fc\ub294 \ud45c\uc2dc\uc774\uba74\uc11c, \uc5ec\ub7ec \uc0ac\ub78c\uc758 \uc190\uc774 \uc9c0\ub098\uac04 \uc12c\uc138\ud55c \uacf5\uc608\ud488\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uad00\ubcf5 \uc18d \ub3d9\ubb3c\uc744 \ub9cc\ub098\uba74 \uc774\ub984\ub9cc \ub9de\ud788\uace0 \uc9c0\ub098\uce58\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc2e4 \ud55c \uac00\ub2e5\uc529 \uac00\uae4c\uc774 \ubcf4\ub294 \ub370\uc5d0\ub3c4 \uc0dd\uac01\ubcf4\ub2e4 \uae34 \uad6c\uacbd\uac70\ub9ac\uac00 \uc228\uc5b4 \uc788\ub2e4."}, {"id": "dasik-sweets-frame", "title": "\uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \ub370\uc5d0\ub3c4 \ud2c0\uc774 \ud544\uc694\ud588\ub2e4", "summary": "\uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uae08\uc18d \ud2c0\uc5d0\uc11c \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \uc7a1\ub358 \ubc29\ubc95\uc744 \ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/dasik-sweets-frame/index.html", "image": "media/dasik-sweets-frame.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc720\uc81c \ub2e4\uc2dd\uc6b0\ub9ac \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \ub370\uc5d0\ub3c4 \ud2c0\uc774 \ud544\uc694\ud588\ub2e4 \uc774\ub984\uc740 \ub0af\uc124\uc9c0\ub9cc \uc4f0\uc784\uc740 \uc120\uba85\ud55c \ub2e4\uc2dd\uc6b0\ub9ac \uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uae08\uc18d \ud2c0\uc5d0\uc11c \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \uc7a1\ub358 \ubc29\ubc95\uc744 \ubd05\ub2c8\ub2e4. Food \uc0dd\ud65c \uc791\uc740 \uc6d0\ud1b5 \ud558\ub098\uac00 \ub193\uc5ec \uc788\ub2e4. \uc606\uc740 \uae30\ub465 \uc0ac\uc774\ub85c \ud6e4\ud788 \ubcf4\uc774\uace0 \uc704\uc640 \uc544\ub798\ub3c4 \ub6ab\ub824 \uc788\ub2e4. \ubb3c\uc744 \ub2f4\ub294 \uadf8\ub987 \uac19\uc9c0\ub294 \uc54a\ub2e4. \ubb34\uc5c7\uc5d0 \uc37c\uc744\uae4c \uad81\uae08\ud574\uc9c0\ub294 \uc21c\uac04, \uc774\ub984\uc744 \uc77d\ub294\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub2e4. \uc6b0\ub9ac\ub77c\ub294 \ub9d0 \ub54c\ubb38\uc5d0 \ubb34\uc5c7\uc744 \uac00\ub450\ub294 \uc791\uc740 \uc6b8\ud0c0\ub9ac\ub97c \ub5a0\uc62c\ub838\ub2e4\uba74 \uc4f0\uc784\uc5d0 \uc870\uae08 \uac00\uae4c\uc774 \uac04 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc774 \uc548\uc5d0\uc11c \uc790\ub9ac\ub97c \uc7a1\ub294 \uac83\uc740 \ub3d9\ubb3c\uc774 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc6b0\ub9ac\ub97c \uc81c\uc0ac\uc5d0 \uc4f0\ub294 \uadf8\ub987\uc758 \ud55c \uc885\ub958\ub85c \uc124\uba85\ud55c\ub2e4. \uc0b0\uc790\uc640 \ub2e4\uc2dd, \uc57d\uacfc \uac19\uc740 \uc74c\uc2dd\uc744 \ub192\uc774 \uc313\uc744 \ub54c \uace0\uc815\ud558\ub294 \ub370 \uc0ac\uc6a9\ud588\ub2e4\ub294 \uac83\uc774\ub2e4. \ub2e4\uc2dd\uc6b0\ub9ac\ub294 \uadf8\uc911 \ub2e4\uc2dd\uc744 \uace0\uc815\ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \uc2dd\ud0c1 \uc704\uc5d0 \uacfc\uc790\ub97c \ub192\uc774 \ud3ec\uac1c\uc5b4 \ubcf8\ub2e4\uba74 \ub9e8 \uc544\ub798 \uac83\ub9cc \uc798 \ub193\ub294\ub2e4\uace0 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e0\ub2e4. \uc774 \ubb3c\uac74\uc740 \uc313\uc740 \ud615\ud0dc\ub97c \ubd99\ub4e4\uc5b4 \uc8fc\ub294 \ud2c0\uc774\ub77c\ub294 \uc4f0\uc784\uc744 \uac16\ub294\ub2e4. \uc74c\uc2dd \uc790\uccb4\ubfd0 \uc544\ub2c8\ub77c \uc74c\uc2dd\uc744 \uc5b4\ub5a4 \ubaa8\uc2b5\uc73c\ub85c \uc62c\ub9b4\uc9c0\ub3c4 \uc900\ube44\ud55c \uc148\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc740 \uc704\uc544\ub798\uac00 \ub6ab\ub9b0 \uc6d0\ud1b5\ud615\uc774\uba70 \uc606\uba74\uc740 \uc5ec\ub35f \uae30\ub465\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\ub2e4. \uae30\ub465\uc5d0\ub294 \ubd80\ucc44 \uac19\uc740 \ud615\ud0dc\uc758 \uc7a5\uc2dd\ub3c4 \uc788\ub2e4. \ubcf4\uae30\uc5d0\ub294 \uac00\ubcbc\uc6b4 \uc6b8\ud0c0\ub9ac \uac19\uc9c0\ub9cc \ub458\ub808\ub97c \uc7a1\uc544 \uc8fc\ub294 \ubaa8\uc591\uc774\ub2e4. \ubcc4\ub3c4\uc758 \ub2e4\uc2dd\uc6b0\ub9ac\ub300\uc640 \ud55c \uc9dd\uc744 \uc774\ub8e8\uc5b4 \ubc1b\uce68 \uc704\uc5d0 \uace0\uc815\ud588\ub2e4\uace0 \ud55c\ub2e4. \uad6c\uba4d \ub09c \uc6d0\ud1b5 \ud558\ub098\uac00 \ud63c\uc790 \ubc14\ub2e5\uc5d0 \ub193\uc774\ub294 \uac83\ub9cc \uc0dd\uac01\ud558\uba74 \uc4f0\uc784\uc744 \ub193\uce58\uae30 \uc27d\ub2e4. \ud568\uaed8 \uc0ac\uc6a9\ud558\ub294 \ubc1b\uce68\uae4c\uc9c0 \ub5a0\uc62c\ub824\uc57c \uad6c\uc870\uac00 \uc774\uc5b4\uc9c4\ub2e4. \uc6d0\ud1b5 \uc704\ucabd \ubc14\uae65\uc5d0\ub294 \ub2e4\uc2dd\uc744 \ub73b\ud558\ub294 \u8336\u98df \ub450 \uae00\uc790\ub97c \uc0c8\uacbc\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc6a9\ub3c4\ub97c \uad6c\ubcc4\ud558\uae30 \uc704\ud55c \ud45c\uc2dc\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uc2b7\ud55c \ubb3c\uac74\uc774 \uc788\uc5b4\ub3c4 \ubb34\uc5c7\uc744 \ub9e1\ub294\uc9c0 \uae00\uc790\ub85c \uc54c\ub824 \uc8fc\ub294 \uac83\uc774\ub2e4. \ub0af\uc120 \uc81c\uae30 \uc774\ub984\uc744 \uc5ec\ub7ec \uac1c \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc624\ub298\uc740 \uacfc\uc790\ub97c \ub192\uc774 \uc313\ub294 \uc77c\uc5d0\ub3c4 \ud2c0\uacfc \ubc1b\uce68, \uc6a9\ub3c4\ub97c \uc801\uc740 \uae00\uc528\uac00 \uc788\uc5c8\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud574 \ubcf4\uc790. \uadf8\ub987\ucc98\ub7fc \ubcf4\uc774\uc9c0 \uc54a\ub358 \uc6d0\ud1b5\uc774 \uc81c\uc0ac\uc0c1 \uc74c\uc2dd\uc758 \ubaa8\uc591\uc744 \ub9cc\ub4dc\ub294 \ub3c4\uad6c\ub85c \ubc14\ub00c\uc5b4 \ubcf4\uc778\ub2e4."}, {"id": "embroidered-spoon-pouch", "title": "\uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uc5d0 \ubc14\ub78c\uc744 \uc218\ub193\uc558\ub2e4", "summary": "\ubd89\uc740 \uc218\uc800\uc9d1\uc758 \uadf8\ub9bc\uacfc \uae00\uc528\ub97c \ub530\ub77c\uac00\uba70 \uc0dd\ud65c \uc18d \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/embroidered-spoon-pouch/index.html", "image": "media/embroidered-spoon-pouch.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\uc218\uc218\uc800\uc9d1 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc218\uc800\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uc5d0 \ubc14\ub78c\uc744 \uc218\ub193\uc558\ub2e4 \ubc25\uc0c1 \uacc1\uc758 \uc791\uc740 \ubb3c\uac74\uc5d0 \ub2f4\uae34 \uae34 \ucd95\uc6d0 \ubd89\uc740 \uc218\uc800\uc9d1\uc758 \uadf8\ub9bc\uacfc \uae00\uc528\ub97c \ub530\ub77c\uac00\uba70 \uc0dd\ud65c \uc18d \uc18c\ub9dd\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Food \uc0dd\ud65c \uc0ac\uc9c4\uc744 \uc5bc\ud54f \ubcf4\uba74 \uae38\ucb49\ud55c \uc7a5\uc2dd\ud488 \uac19\ub2e4. \ubd89\uc740 \ubc14\ud0d5\uc5d0 \uaf43\uc774 \ud53c\uace0, \uc0c8\uac00 \uc11c \uc788\uace0, \uc5ec\ub7ec \uc0c9\uc758 \uc220\uc774 \uc544\ub798\ub85c \ub298\uc5b4\uc9c4\ub2e4. \uc774\ub984\uc744 \ubcf4\uace0 \ub098\uc11c\uc57c \uace0\uac1c\ub97c \ub044\ub355\uc778\ub2e4. \uc790\uc218\uc218\uc800\uc9d1\uc774\ub2e4. \uc21f\uac00\ub77d\uacfc \uc813\uac00\ub77d\uc744 \ub2f4\ub294 \ubb3c\uac74\uc778\ub370 \uc7a5\uc2dd\uc740 \uaf64 \ud48d\uc131\ud558\ub2e4. \ubb34\uc5c7\uc744 \ub2f4\ub294 \uc8fc\uba38\ub2c8\uc778\uc9c0\ub9cc \uc54c\uba74 \uc9c0\ub098\uce58\uae30 \uc27d\uc9c0\ub9cc, \ubb34\uc5c7\uc744 \uc218\ub193\uc558\ub294\uc9c0\uae4c\uc9c0 \ubcf4\uba74 \ub610 \ud558\ub098\uc758 \uc774\uc57c\uae30\uac00 \uc5f4\ub9b0\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc55e\uba74 \uc544\ub798\ucabd\uc5d0 \ubc14\uc704\uc640 \uc601\uc9c0, \ud30c\ub3c4\uac00 \uc788\uace0 \uac00\uc6b4\ub370\uc5d0 \uc18c\ub098\ubb34\uc640 \ubaa8\ub780, \ud559 \ub450 \ub9c8\ub9ac \ub4f1\uc774 \uc218\ub193\uc600\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\ub7ec \uc0c9\uc758 \uc2e4\ub85c \uadf8\ub9b0 \ud48d\uacbd\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \ubb38\uc591\ub4e4\uc774 \uc624\ub798 \uc0b4\uace0 \ubcf5\uc744 \ub204\ub9ac\uba70 \ud3c9\uc548\ud558\uae30\ub97c \ubc14\ub77c\ub294 \ub9c8\uc74c\uc744 \ud45c\ud604\ud55c\ub2e4\uace0 \ud480\uc774\ud55c\ub2e4. \ubaa8\ub974\ub294 \ubb38\uc591\uc758 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc88b\ub2e4. \uc2dd\uc0ac \ub3c4\uad6c\ub97c \ub123\ub294 \uc8fc\uba38\ub2c8\uac00 \uc88b\uc740 \uc0b6\uc5d0 \ub300\ud55c \ubc14\ub78c\uae4c\uc9c0 \ud488\uace0 \uc788\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc774 \uc218\uc800\uc9d1\uc740 \uc55e\uba74\ub9cc \ubcf4\uace0 \ub05d\ub0bc \ubb3c\uac74\uc774 \uc544\ub2c8\ub2e4. \ub4b7\uba74\uc5d0\ub294 \uc911\uc559\uc120\uc744 \uc0ac\uc774\uc5d0 \ub450\uace0 \uae38\ud55c \ub73b\uc758 \uae00\uadc0\uac00 \uc218\ub193\uc5ec \uc788\ub2e4. \uc624\ub798 \uc0b4\uace0 \ud3c9\uc548\ud558\uae30\ub97c \ubc14\ub77c\ub294 \ud45c\ud604\uacfc \uc5ec\uc720\uc640 \ubd80\uadc0\ub97c \ubc14\ub77c\ub294 \ud45c\ud604\uc774\ub2e4. \ub208\uc73c\ub85c \ubcf4\ub294 \uadf8\ub9bc\uacfc \uc77d\ub294 \uae00\uc774 \ud55c \uc8fc\uba38\ub2c8\uc5d0 \ud568\uaed8 \ub193\uc600\ub2e4. \uc55e\uc758 \ud48d\uacbd\uc744 \ub4a4\uc758 \ubb38\uc7a5\uc774 \ub2e4\uc2dc \ud480\uc5b4 \uc8fc\ub294 \uac83\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uc624\ub298\ub0a0 \uc120\ubb3c\uc5d0 \uc9e7\uc740 \ucd95\ud558 \uce74\ub4dc\ub97c \ub367\ubd99\uc774\ub294 \uc77c\uc744 \ube44\uad50\ud574 \ubcfc \uc218\ub3c4 \uc788\uaca0\ub2e4. \ubb3c\ub860 \uc774 \ubb3c\uac74\uc774 \uc2e4\uc81c \uc5b4\ub5a4 \uc120\ubb3c \uc790\ub9ac\uc5d0\uc11c \uc4f0\uc600\ub294\uc9c0\ub294 \ud655\uc778\ub41c \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub2e4. \ub69c\uaed1\uc758 \uc55e\ub4b7\uba74\uc5d0\ub3c4 \ub9e4\ud654\uac00 \ub450 \uc1a1\uc774\uc529 \uc218\ub193\uc600\ub2e4. \uaf43\uc758 \uc528\ubc29\uc5d0\ub294 \uad6c\uba4d\uc744 \ub0b4\uace0 \ub048\uc744 \uaff0\uc5c8\uc73c\uba70 \uadf8 \uc544\ub798\ub85c \uc5ec\ub7ec \uc0c9\uc758 \uc220\uc744 \ub2ec\uc558\ub2e4. \uc8fc\uba38\ub2c8\ub97c \uafb8\ubbf8\ub294 \uc77c\uc774 \ubab8\uccb4\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc740 \uc148\uc774\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \ud55c\uaebc\ubc88\uc5d0 \ubaa8\ub4e0 \ubb34\ub2ac\ub97c \ucc3e\uc73c\ub824 \ud558\uba74 \ub208\uc774 \ubc14\ube60\uc9c4\ub2e4. \uba3c\uc800 \ud559\uc744 \ubcf4\uace0 \ub2e4\uc74c\uc5d0 \uaf43\uc744 \ubcf4\ub294 \uc815\ub3c4\uba74 \ucda9\ubd84\ud558\ub2e4. \ub9e4\uc77c\uc758 \uc2dd\uc0ac\uc640 \uba40\uc9c0 \uc54a\uc740 \ubb3c\uac74\uc5d0 \uc774\ub807\uac8c \ub9ce\uc740 \uc88b\uc740 \ub73b\uc744 \ubaa8\uc544 \ub450\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c\ub3c4, \ubd89\uc740 \uc218\uc800\uc9d1\uc740 \uc791\uc740 \uadf8\ub9bc\ucc45\ucc98\ub7fc \uc77d\ud78c\ub2e4."}, {"id": "lock-green-knot", "title": "\uc61b \uc5f4\uc1e0\uc5d0\ub3c4 \ucd08\ub85d\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\uc5c8\ub2e4", "summary": "\uaf43\ubb34\ub2ac \uc790\ubb3c\uc1e0\uc640 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub9b0 \uc5f4\uc1e0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/lock-green-knot/index.html", "image": "media/lock-green-knot.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\ubb3c\uc1e0, \uc5f4\uc1e0 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc61b \uc5f4\uc1e0\uc5d0\ub3c4 \ucd08\ub85d\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\uc5c8\ub2e4 \uc7a0\uadf8\ub294 \ubb3c\uac74\uc5d0\ub3c4 \uafb8\ubc08\uc740 \ub0a8\uc558\ub2e4 \uaf43\ubb34\ub2ac \uc790\ubb3c\uc1e0\uc640 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub9b0 \uc5f4\uc1e0\ub97c \ud568\uaed8 \ubd05\ub2c8\ub2e4. Housing \uc0dd\ud65c \uc5f4\uc1e0\ub97c \ucc3e\ub290\ub77c \uac00\ubc29 \uc548\uc744 \ub4a4\uc801\uc778 \uacbd\ud5d8\uc774 \uc788\ub2e4\uba74, \uc5f4\uc1e0\uace0\ub9ac \ud558\ub098\uc5d0\ub3c4 \ucde8\ud5a5\uc774 \ub4e4\uc5b4\uac04\ub2e4\ub294 \ub9d0\uc744 \uc774\ud574\ud560 \uac83\uc774\ub2e4. \uc798 \ubcf4\uc774\ub294 \uc0c9\uc744 \uace0\ub974\uae30\ub3c4 \ud558\uace0, \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc791\uc740 \uc7a5\uc2dd\uc744 \ub2ec\uae30\ub3c4 \ud55c\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc61b \uc790\ubb3c\uc1e0\uc640 \uc5f4\uc1e0\ub97c \ubcf4\uba74 \uadf8\ub7f0 \uc624\ub298\uc758 \uc2b5\uad00\uc774 \ubb38\ub4dd \ub5a0\uc624\ub978\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc5f4\uc1e0 \ub05d\uc5d0\ub294 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ub2ec\ub824 \uc788\ub2e4. \uc791\uc740 \uc7a0\uae08 \ub3c4\uad6c\uc5d0\ub3c4 \uc0c9\uc744 \ubcf4\ud0e0 \uac83\uc774\ub2e4. \uc774 \ud55c \uc30d\uc740 \uc601\uce5c\uc655\ube44\uc758 \uc720\ud488\uc73c\ub85c \uc804\ud574\uc9c0\ub294 \ubb3c\uac74\uc774\ub2e4. \uc5ec\uae30\uc11c \ub208\uc5ec\uaca8\ubcfc \ub9d0\uc740 \u2018\uc804\ud574\uc9c0\ub294\u2019\uc774\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5b4\ub290 \uc0c1\uc790\ub97c \uc7a0\uac14\ub294\uc9c0\uae4c\uc9c0 \ud655\uc815\ub41c \uc7a5\uba74\uc73c\ub85c \ubc14\uafb8\uc5b4 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4. \ud655\uc778\ub418\ub294 \uac83\uc740 \ud45c\uba74\uc758 \uc7a5\uc2dd\uc774\ub2e4. \uc790\ubb3c\uc1e0 \uc55e\uba74\uc5d0\ub294 \ub465\uadfc \ubb34\ub2ac\uc640 \uaf43\ubb34\ub2ac\uac00 \uc74c\uac01\ub418\uc5b4 \uc788\ub2e4. \uc74c\uac01\uc740 \ubc14\ud0d5\uc744 \ud30c\uc11c \uc120\uc774\ub098 \ubb34\ub2ac\ub97c \ub098\ud0c0\ub0b4\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc791\uc544\uc11c \uadf8\ub0e5 \uc9c0\ub098\uce60 \ubb3c\uac74\uc5d0\ub3c4 \ube48 \ud45c\uba74\uc744 \uadf8\ub300\ub85c \ub450\uc9c0 \uc54a\uc558\ub2e4. \uc5f4\uc1e0 \ub05d\uc758 \ub9e4\ub4ed\uc740 \uc790\ubb3c\uc1e0\uc758 \uc0c8\uae34 \ubb34\ub2ac\uc640 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \ubb3c\uac74\uc744 \uafb8\ubbfc\ub2e4. \ub2e8\ub2e8\ud55c \uae08\uc18d\uc5d0\ub294 \ud30c\uc778 \uc120\uc774, \ub05d\ubd80\ubd84\uc5d0\ub294 \ub179\uc0c9 \ub9e4\ub4ed\uc774 \ubd99\ub294\ub2e4. \ud55c \uc870\ub97c \uc774\ub8e8\uba74\uc11c\ub3c4 \uc7ac\ub8cc\uc758 \ub290\ub08c\uc740 \ub2e4\ub974\ub2e4. \ub9e4\ub4ed\uc774 \uc190\uc5d0 \uc7a1\uae30 \ud3b8\ud588\uc744\uc9c0, \uba40\ub9ac\uc11c \ucc3e\uae30 \uc26c\uc6e0\uc744\uc9c0 \uc0c1\uc0c1\ud574 \ubcfc \uc218\ub294 \uc788\ub2e4. \uadf8\ub7ec\ub098 \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \uadf8 \ubaa9\uc801\uae4c\uc9c0 \uc815\ud574 \uc8fc\uc9c0\ub294 \uc54a\ub294\ub2e4. \uc624\ub298\uc758 \uc5f4\uc1e0\uace0\ub9ac\uc640 \ub2ee\uc558\ub2e4\ub294 \uc0dd\uac01\uc740 \uc6b0\ub9ac\uc758 \ube44\uad50\ub85c \ub0a8\uaca8 \ub450\ub294 \ud3b8\uc774 \uc88b\ub2e4. \uc0c1\uc790\ub97c \uc5f4\uc5b4 \uc548\uc758 \ubcf4\ubb3c\uc744 \ubcf4\uc5ec \uc8fc\ub294 \uc774\uc57c\uae30\ub294 \uc544\ub2c8\ub2e4. \uc774 \uc790\ubb3c\uc1e0\uac00 \uc9c0\ud0a4\ub358 \ubb3c\uac74\uc740 \ud655\uc778\ud558\uc9c0 \ubabb\ud588\ub2e4. \ub300\uc2e0 \uc7a0\uadf8\ub294 \ub3c4\uad6c \uc790\uccb4\uc5d0\ub3c4 \ubcf4\ub294 \uc990\uac70\uc6c0\uc774 \uc788\uc5c8\ub2e4\ub294 \uac83\uc744 \ud45c\uba74\uacfc \ub9e4\ub4ed\uc5d0\uc11c \ubc1c\uacac\ud55c\ub2e4. \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \ucee4\ub2e4\ub780 \uc7a5\uc2dd\ubcf4\ub2e4 \uc791\uc740 \uc120\uc774 \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc62c \uc218 \uc788\ub2e4. \uadf8 \uc606\uc5d0 \ub193\uc600\uc744 \uc5f4\uc1e0\uc758 \ucd08\ub85d\uc0c9\uae4c\uc9c0 \ub5a0\uc62c\ub9ac\uba74, \uc7a0\uae08\uc7a5\uce58\ub294 \uae30\ub2a5\ub9cc \ub0a8\uc740 \uae08\uc18d \ubd80\ud488\uc5d0\uc11c \uc870\uae08 \ub2e4\ub978 \uc5bc\uad74\uc744 \uc5bb\ub294\ub2e4. \uc61b \uc0dd\ud65c\uc758 \ucde8\ud5a5\uc740 \uc774\ub807\uac8c \uc791\uc740 \uacf3\uc5d0\ub3c4 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "maehwa-portable-toilet", "title": "\uad81\uad90\uc758 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc0dd\ud65c\uc758 \ud544\uc694\uac00 \ub2f4\uacbc\ub2e4", "summary": "\uc758\uc790\ucc98\ub7fc\ub3c4 \uc0c1\uc790\ucc98\ub7fc\ub3c4 \ubcf4\uc774\ub294 \ubb3c\uac74. \uc774\ub984\uacfc \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uba74 \uc61b \uc0dd\ud65c\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc785\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/maehwa-portable-toilet/index.html", "image": "media/maehwa-portable-toilet.jpg", "alt": "\uc9c1\ubb3c\ub85c \uc2fc \ub098\ubb34\ud2c0\uacfc \uc704\ucabd \uad6c\uba4d\uc774 \ubcf4\uc774\ub294 \uc655\uc2e4 \uc774\ub3d9\uc2dd \ubcc0\uae30 \ub9e4\ud654\ud2c0", "text": "\uad81\uad90\uc758 \uc791\uc740 \uc0c1\uc790\uc5d0\ub294 \uc0dd\ud65c\uc758 \ud544\uc694\uac00 \ub2f4\uacbc\ub2e4 \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30 \ub9e4\ud654\ud2c0\uc758 \uad6c\uc870\ub97c \ub4e4\uc5ec\ub2e4\ubcf4\ub2e4 \uc758\uc790\ucc98\ub7fc\ub3c4 \uc0c1\uc790\ucc98\ub7fc\ub3c4 \ubcf4\uc774\ub294 \ubb3c\uac74. \uc774\ub984\uacfc \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uba74 \uc61b \uc0dd\ud65c\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc785\ub2c8\ub2e4. Housing \uc0dd\ud65c \uad81\uad90\uc758 \uc0dd\ud65c\uc744 \uc0c1\uc0c1\ud558\uba74 \ud070 \uce68\uc804\uacfc \ud654\ub824\ud55c \uac00\uad6c\ubd80\ud130 \ub5a0\uc624\ub974\uae30 \uc27d\ub2e4. \ud558\uc9c0\ub9cc \uc0dd\ud65c\uc744 \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uac83\uc740 \uba4b\uc9c4 \ubb3c\uac74\ub9cc\uc774 \uc544\ub2c8\ub2e4. \ub9e4\uc77c \ud574\uacb0\ud574\uc57c \ud558\ub294 \uc791\uc740 \ud544\uc694\ub3c4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \u300c\ub9e4\ud654\ud2c0\u300d\uc740 \uadf8\ub7f0 \uba74\uc744 \ubcf4\uc5ec\uc900\ub2e4. \uc9c1\uc721\uba74\uccb4\uc758 \ub098\ubb34 \ubab8\uccb4\uc5d0 \ucc9c\uc744 \uc50c\uc6e0\uace0, \uc717\uba74\uc5d0\ub294 \uae34 \uad6c\uba4d\uc774 \ub098 \uc788\ub2e4. \ud06c\uc9c0 \uc54a\uc740 \uac00\uad6c\ucc98\ub7fc \ubcf4\uc774\ub294 \uc774 \ubb3c\uac74\uc740 \uc655\uc2e4 \uc804\uc6a9\uc758 \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\uc600\ub2e4. \uc774\ub984\ub9cc \ub4e3\uace0 \uaf43\uc744 \uc7a5\uc2dd\ud558\ub294 \ud2c0\uc744 \ub5a0\uc62c\ub838\ub2e4\uba74 \uc4f0\uc784\uc774 \uaf64 \ub2e4\ub974\uac8c \ub290\uaef4\uc9c8 \uac83\uc774\ub2e4. \uc774 \ub9e4\ud654\ud2c0\uc740 \ubc30\uc124\ubb3c\uc744 \ubc1b\ub294 \uc6a9\uae30\ub97c \ub123\uace0 \ube84 \uc218 \uc788\ub3c4\ub85d \uace0\uc548\ub418\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc549\ub294 \ubd80\ubd84\uacfc \uc548\ucabd\uc758 \uc6a9\uae30\ub97c \ub098\ub204\uc5b4 \uc0dd\uac01\ud55c \uad6c\uc870\ub2e4. \uc717\uba74\uc758 \uad6c\uba4d\ub9cc \uc788\ub294 \ub2e8\uc21c\ud55c \uc0c1\uc790\ub3c4 \uc544\ub2c8\ub2e4. \uc544\ub798 \uc591\uc606\uc5d0\ub294 \ubc1c\ud310\uc774 \ub9c8\ub828\ub418\uc5b4 \uc788\uace0, \uc88c\ub300 \uc717\ubd80\ubd84\uc5d0\ub294 \ub4f1\ubc1b\uce68\uc744 \uace0\uc815\ud558\uae30 \uc704\ud55c \ud648\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc124\uba85\uc744 \uc77d\uc73c\uba70 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \uae30\ub2a5\uc5d0 \ud544\uc694\ud55c \ubd80\ubd84\ub4e4\uc774 \ud558\ub098\uc529 \ubcf4\uc778\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \uc774 \ubb3c\uac74\uc758 \uc131\uaca9\uc744 \uc54c\ub824\uc900\ub2e4. \ubc29 \uc548\uc5d0\uc11c \uc4f0\ub294 \uac00\uad6c\ucc98\ub7fc \uc0ac\uc6a9\ud558\uba74\uc11c, \uc548\ucabd \uc6a9\uae30\ub97c \ub2e4\ub8e8\uace0 \ud544\uc694\uc5d0 \ub530\ub77c \uc704\uce58\ub97c \uc62e\uae38 \uc218 \uc788\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \uc624\ub298\uc758 \ubc30\uad00 \uc2dc\uc124\uacfc\ub294 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c \uc0dd\ud65c\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud55c \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc5d0\ub294 \uac19\uc740 \ub9e4\ud654\ud2c0\uc774\ub77c\ub294 \uc774\ub984\uc758 \uccad\ub3d9\uc81c \uc774\ub3d9\uc2dd \uc6a9\ubcc0\uae30\ub3c4 \uc788\ub2e4. \uc124\uba85\uc5d0\ub294 \ub0b4\ubd80\uc5d0 \uc7ac\ub97c \ub2f4\uc544 \uc18c\ub9ac\uc640 \ub0c4\uc0c8\ub97c \uc904\uc774\ub824 \ud588\ub2e4\uace0 \ub098\uc628\ub2e4. \ub450 \ubb3c\uac74\uc744 \ubcf4\uba74 \uc6a9\ubcc0\uc744 \ubc1b\ub294 \uae30\ub2a5\ubfd0 \uc544\ub2c8\ub77c \uc0ac\uc6a9 \ub4a4\uc758 \ucc98\ub9ac, \uc8fc\ubcc0\uc5d0 \uc8fc\ub294 \uc601\ud5a5\uc744 \uc0dd\uac01\ud588\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud55c \uc720\ubb3c\uc758 \uc124\uba85\uc744 \ubaa8\ub4e0 \uc655\uc2e4 \uc6a9\ubcc0\uae30\uc5d0 \ub611\uac19\uc774 \uc801\uc6a9\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc7ac\ub8cc\uc640 \uad6c\uc870\uac00 \ub2e4\ub978 \ubb3c\uac74\uc740 \uac01\uac01\uc758 \uae30\ub85d\uc744 \ub530\ub77c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ub204\uac00 \uc5b8\uc81c \uc5b4\ub290 \ubc29\uc5d0\uc11c \uc37c\ub294\uc9c0, \uc8fc\ubcc0 \uc0ac\ub78c\ub4e4\uc774 \uc5b4\ub5a4 \ub9d0\uc744 \ud588\ub294\uc9c0\ub294 \uc5ec\uae30\uc758 \uc18c\uc7a5\ud488 \uc124\uba85\ub9cc\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \uadf8\ub7f0 \uc7a5\uba74\uc744 \ub367\ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4 \ub0a8\uc544 \uc788\ub294 \uad6c\uc870\ub9cc\uc73c\ub85c \uc0dd\ud65c\uc758 \uace0\ubbfc\uc744 \uc9d0\uc791\ud560 \uc218 \uc788\ub2e4. \uad81\uad90\uc744 \uad6c\uacbd\ud560 \ub54c\ub294 \uacf5\uac04\uc774 \uc6cc\ub099 \ucee4\uc11c \uadf8 \uc548\uc5d0\uc11c \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \uc9c0\ub0c8\ub294\uc9c0 \ub193\uce58\uae30 \uc27d\ub2e4. \uc791\uc740 \uc0dd\ud65c \ub3c4\uad6c\ub294 \uadf8 \uac70\ub9ac\ub97c \uc904\uc5ec \uc900\ub2e4. \uc5b4\ub518\uac00\uc5d0 \ub193\uace0 \uc0ac\ub78c\uc774 \uc0ac\uc6a9\ud574\uc57c \ud588\ub358 \ubb3c\uac74\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub9e4\ud654\ud2c0\uc744 \ubcf4\uba74\uc11c \uc61b\uc0ac\ub78c\ub4e4\uc758 \uc0dd\ud65c\uc744 \ubd88\ud3b8\ud568 \ud558\ub098\ub85c\ub9cc \ud3c9\uac00\ud560 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \ub2f9\uc2dc\uc758 \uc7ac\ub8cc\uc640 \ubc29\uc2dd\uc73c\ub85c \ubb34\uc5c7\uc744 \ud574\uacb0\ud558\ub824 \ud588\ub294\uc9c0\ub97c \ubcf4\uba74 \ub41c\ub2e4. \ub123\uace0 \ube7c\ub294 \uc6a9\uae30, \ubc1c\ud310, \ub4f1\ubc1b\uce68\uc758 \ud754\uc801\uc740 \uadf8 \ub2f5\uc758 \uc77c\ubd80\ub2e4. \ub2e4\uc74c\uc5d0 \uc0dd\ud65c \uc720\ubb3c \uc804\uc2dc\ub97c \ub9cc\ub098\uba74 \ud654\ub824\ud55c \uc7a5\uc2dd \uc0ac\uc774\uc758 \uc18c\ubc15\ud55c \ubb3c\uac74\ub3c4 \uc0b4\ud3b4\ubcf4\uc790. \ud070 \uc5ed\uc0ac\uc758 \ubb34\ub300\uc600\ub358 \uad81\uad90\uc5d0\ub3c4, \ub9e4\uc77c\uc758 \uc0dd\ud65c\uc744 \ubc1b\uccd0 \uc8fc\ub294 \uc791\uc740 \uac00\uad6c\uac00 \ud544\uc694\ud588\ub2e4."}, {"id": "popcorn-little-explosion", "title": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c", "summary": "\ubd84\uba85 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\uc600\ub294\ub370 \uc5b4\ub290\uc0c8 \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uac04\uc2dd\uc73c\ub85c. \ud31d\ucf58\uc758 \ubcc0\uc2e0\uc5d0\ub294 \uc528\uc557 \uc18d \uc218\ubd84\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Food", "url": "stories/popcorn-little-explosion/index.html", "image": "media/popcorn-little-explosion.jpg", "alt": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud31d\ucf58 \ud55c \uc54c\uc740 \uc5b4\ub5bb\uac8c \uc800\ub807\uac8c \ucee4\uc9c8\uae4c \uc54c\uac31\uc774 \uc548\uc5d0 \ub0a8\uc544 \uc788\ub358 \uc218\ubd84\uc774 \ud558\ub294 \uc77c \ubd84\uba85 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\uc600\ub294\ub370 \uc5b4\ub290\uc0c8 \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uac04\uc2dd\uc73c\ub85c. \ud31d\ucf58\uc758 \ubcc0\uc2e0\uc5d0\ub294 \uc528\uc557 \uc18d \uc218\ubd84\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. Food \uc0dd\ud65c \uc601\ud654\uac00 \uc2dc\uc791\ub418\uae30 \uc804, \ud31d\ucf58 \ud1b5\uc5d0\ub294 \ubc8c\uc368 \uc190\uc774 \uba87 \ubc88 \uc624\uac04\ub2e4. \ud558\uc597\uace0 \uac00\ubcbc\uc6b4 \uc870\uac01\uc744 \uc9d1\ub2e4 \ubcf4\uba74 \uac00\ub054 \ubc14\ub2e5\uc5d0 \ub0a8\uc740 \ub2e8\ub2e8\ud55c \uc54c\uac31\uc774\ub97c \ub9cc\ub098\uae30\ub3c4 \ud55c\ub2e4. \ub458\uc740 \uac19\uc740 \uc625\uc218\uc218\uc5d0\uc11c \ucd9c\ubc1c\ud588\ub2e4. \uadf8\ub7f0\ub370 \ud558\ub098\ub294 \ubd80\ud480\uc5b4 \uc62c\ub790\uace0 \ub2e4\ub978 \ud558\ub098\ub294 \uc791\uc740 \ub3cc\ucc98\ub7fc \ub0a8\uc558\ub2e4. \ub300\uccb4 \uc54c\uac31\uc774 \uc548\uc5d0\uc11c \ubb34\uc2a8 \uc77c\uc774 \ubc8c\uc5b4\uc9c4 \uac83\uc77c\uae4c. \ud31d\ucf58\uc744 \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub294 \ub2e8\uc9c0 \ub192\uc740 \uc628\ub3c4\ub9cc \ud544\uc694\ud55c \uac83\uc774 \uc544\ub2c8\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\uc9c0\ub9cc \uc911\uc694\ud55c \uc900\ube44\ubb3c\uc774 \uc788\ub2e4. \uc54c\uac31\uc774 \uc548\uc758 \uc218\ubd84\uc774\ub2e4. \ud31d\ucf58\uc6a9 \uc625\uc218\uc218\ub3c4 \ubcf4\uad00\uacfc \uac00\uacf5\uc744 \uac70\uccd0 \uc6b0\ub9ac \uc190\uc5d0 \uc628\ub2e4. \ubbf8\uad6d \uad6d\ub9bd\ub18d\uc5c5\ub3c4\uc11c\uad00\uc758 \ud31d\ucf58 \uc804\uc2dc\ub294 \uc218\ud655\ud55c \uc625\uc218\uc218\ub97c \uc801\uc808\ud55c \uc218\ubd84 \uc0c1\ud0dc\ub85c \ub9d0\ub9ac\ub294 \uacfc\uc815\ubd80\ud130 \uc18c\uac1c\ud55c\ub2e4. \ubb34\uc870\uac74 \ubc14\uc2f9 \ub9d0\ub9ac\ub294 \uac83\uc774 \ubaa9\uc801\uc740 \uc544\ub2c8\ub2e4. \ud130\uc9c0\ub294 \ub370 \ud544\uc694\ud55c \uc218\ubd84\uc740 \ub0a8\uaca8\uc57c \ud55c\ub2e4. \uac00\uacf5 \uacfc\uc815\uc5d0\uc11c\ub294 \uc190\uc0c1\ub41c \uc54c\uac31\uc774\ub098 \uc774\ubb3c\uc9c8\uc744 \uace8\ub77c\ub0b4\uace0, \ud3ec\uc7a5\ud558\uae30 \uc88b\uac8c \uc815\ub9ac\ud55c\ub2e4. \uc791\uc740 \ubd09\uc9c0 \uc18d\uc5d0 \ub2f4\uaca8 \uc788\uc73c\ub2c8 \ub2e8\uc21c\ud55c \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uc548\uc5d0\uc11c\ub3c4 \uc0c1\ud0dc\ub97c \ub9de\ucd94\ub294 \uc77c\uc774 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc9d1\uc5d0\uc11c \ub370\uc6b4 \uc54c\uac31\uc774 \uc911 \uc77c\ubd80\uac00 \ub0a8\uc558\ub2e4\uace0 \ud574\uc11c \ubaa8\ub450 \uac19\uc740 \uc774\uc720\ub85c \uc2e4\ud328\ud588\ub2e4\uace0 \ub2e8\uc815\ud560 \uc218\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \ud31d\ucf58\uc774 \ud130\uc9c0\ub824\uba74 \ub0b4\ubd80\uc758 \uc218\ubd84\uacfc \uc555\ub825\uc774 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4\ub294 \uc810\uc744 \uc54c\uba74, \uc54c\uac31\uc774\uc758 \uc0c1\ud0dc\uac00 \uc65c \ud544\uc694\ud55c\uc9c0 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ubb3c\ub860 \uc774 \uc774\uc57c\uae30\ub294 \ub0a8\uc740 \uc54c\uac31\uc774\ub97c \uc5b5\uc9c0\ub85c \uc539\uc5b4 \ubcf4\ub77c\ub294 \uad8c\uc720\uac00 \uc544\ub2c8\ub2e4. \ud31d\ucf58 \uc0ac\uc774\uc5d0\uc11c \ub2e8\ub2e8\ud55c \uac83\uc774 \ub290\uaef4\uc9c0\uba74 \ub530\ub85c \uace8\ub77c\ub0b4\uba74 \ub41c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uac83\uacfc \uc774\uac00 \ud574\uc57c \ud560 \uc77c\uc744 \ub298\ub9ac\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ud31d\ucf58 \ud55c \ud1b5\uc744 \uc870\uae08 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc774 \uc544\ub2c8\ub2e4. \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ubc8c\uc5b4\uc9c4 \uac83\ub3c4 \uc788\uace0, \ube44\uad50\uc801 \ub465\uae00\uac8c \ubcf4\uc774\ub294 \uac83\ub3c4 \uc788\ub2e4. \uc5b4\ub290 \ucabd\uc774 \ub354 \uc7ac\ubbf8\uc788\uac8c \uc0dd\uacbc\ub294\uc9c0 \uace8\ub77c \ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uc791\uc740 \uad6c\uacbd\uc774 \ub41c\ub2e4. \ud31d\ucf58\uc6a9 \uc54c\uac31\uc774\ub3c4 \ubaa8\ub450 \uc131\uacf5\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc218\ubd84 \uc0c1\ud0dc\ub098 \uaecd\uc9c8\uc758 \uc190\uc0c1, \uac00\uc5f4 \uc870\uac74\uc774 \uc601\ud5a5\uc744 \uc900\ub2e4. \uadf8\ub798\uc11c \ubc14\ub2e5\uc5d0 \ub0a8\uc740 \uc54c\uac31\uc774\ub97c \ubcf4\uace0 \ubb34\uc870\uac74 \ub35c \uc775\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ud130\uc9c0\uae30 \uc704\ud55c \uc870\uac74\uc744 \uac16\ucd94\uc9c0 \ubabb\ud588\uc744 \uc218\ub3c4 \uc788\ub2e4. \uae30\ub984 \uc5ed\uc2dc \ud31d\ucf58\uc758 \ud770 \ubd80\ubd84\uc744 \ub9cc\ub4dc\ub294 \uc7ac\ub8cc\ub294 \uc544\ub2c8\ub2e4. \uae30\ub984\uc740 \uc870\ub9ac \uacfc\uc815\uc5d0\uc11c \uc5f4\uc744 \uc804\ub2ec\ud558\uace0 \ub9db\uc744 \ub354\ud560 \uc218 \uc788\uc9c0\ub9cc, \ub728\uac70\uc6b4 \uacf5\uae30\ub97c \uc774\uc6a9\ud574 \ub9cc\ub4dc\ub294 \ud31d\ucf58\ub3c4 \uc788\ub2e4. \ubcc0\uc2e0\uc758 \uc8fc\uc778\uacf5\uc740 \uc5ec\uc804\ud788 \uc625\uc218\uc218 \uc54c\uac31\uc774 \uc548\uc5d0 \uc788\ub2e4. \ubb3c\ub860 \uc774 \uc774\uc57c\uae30\ub294 \ud130\uc9c0\uc9c0 \uc54a\uc740 \uc54c\uac31\uc774\ub97c \uc5b5\uc9c0\ub85c \uc539\uc5b4 \ubcf4\ub77c\ub294 \uad8c\uc720\uac00 \uc544\ub2c8\ub2e4. \ud31d\ucf58 \uc0ac\uc774\uc5d0\uc11c \ub2e8\ub2e8\ud55c \uac83\uc774 \ub290\uaef4\uc9c0\uba74 \ub530\ub85c \uace8\ub77c\ub0b4\uba74 \ub41c\ub2e4. \uc6d0\ub9ac\ub97c \uc544\ub294 \uac83\uacfc \uc774\uac00 \ud574\uc57c \ud560 \uc77c\uc744 \ub298\ub9ac\ub294 \uac83\uc740 \ub2e4\ub978 \ubb38\uc81c\ub2e4. \ud31d\ucf58 \ud55c \ud1b5\uc744 \uc870\uae08 \ucc9c\ucc9c\ud788 \ubcf4\uba74 \ubaa8\ub450 \uac19\uc740 \ubaa8\uc591\uc774 \uc544\ub2c8\ub2e4. \ub0a0\uac1c\ucc98\ub7fc \uc5ec\ub7ec \ubc29\ud5a5\uc73c\ub85c \ubc8c\uc5b4\uc9c4 \uac83\ub3c4 \uc788\uace0, \ube44\uad50\uc801 \ub465\uae00\uac8c \ubd80\ud47c \uac83\ub3c4 \uc788\ub2e4. \ud488\uc885\uacfc \uac00\uc5f4 \uc870\uac74\uc5d0 \ub530\ub77c \ubaa8\uc2b5\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ud31d\ucf58\uc740 \uac04\uc2dd\uc774\uba74\uc11c \uc791\uc740 \uad6c\uacbd\uac70\ub9ac\uc774\uae30\ub3c4 \ud558\ub2e4. \ub611\uac19\uc740 \uae08\ud615\uc73c\ub85c \ucc0d\uc740 \uacfc\uc790\uc640 \ub2ec\ub9ac, \uc54c\uac31\uc774\ub9c8\ub2e4 \ud130\uc9c0\uace0 \uad73\uc740 \ud754\uc801\uc774 \ub0a8\ub294\ub2e4. \uac19\uc740 \ud1b5 \uc548\uc5d0\uc11c\ub3c4 \uc720\ub09c\ud788 \ud070 \uc870\uac01\uacfc \uc791\uc740 \uc870\uac01\uc774 \uc11e\uc5ec \uc788\ub2e4. \uc601\ud654\ub97c \ubcfc \ub54c \uc774 \ubaa8\ub4e0 \uacfc\uc815\uc744 \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774\uc57c\uae30\uc758 \uc911\uc694\ud55c \uc7a5\uba74\uc5d0 \uc625\uc218\uc218\uc758 \uaecd\uc9c8\uc744 \uc5f0\uad6c\ud558\uace0 \uc788\uc744 \uc774\uc720\ub3c4 \uc5c6\ub2e4. \ub2e4\ub9cc \ub2e4\uc74c\uc5d0 \ud31d\ucf58\uc744 \uc9d1\uc5c8\uc744 \ub54c, \uadf8 \uac00\ubcbc\uc6b4 \uc870\uac01\uc774 \ud55c\ub54c\ub294 \ub2e8\ub2e8\ud55c \uc528\uc557\uc774\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc7a0\uae50 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub2e4. \uc694\ub780\ud55c \uc18c\ub9ac\uc640 \ud568\uaed8 \ubc8c\uc5b4\uc9c0\ub294 \uc791\uc740 \ubcc0\uc2e0. \ud31d\ucf58\uc740 \uc601\ud654\uac00 \uc2dc\uc791\ub418\uae30\ub3c4 \uc804\uc5d0 \uc790\uae30 \ubaab\uc758 \uc9e7\uc740 \uc7a5\uba74\uc744 \ub05d\ub0b8 \uc148\uc774\ub2e4."}, {"id": "princess-crescent-comb", "title": "\uc791\uc740 \ubc18\ub2ec\uc740 \uba38\ub9ac\ub97c \ube57\ub294 \ub3c4\uad6c\uc600\ub2e4", "summary": "\ub098\ubb34\ub85c \ub9cc\ub4e0 \uc791\uc740 \uc5bc\ub808\ube57\uc774 \ub0af\uc120 \uc655\uc2e4 \uc778\ubb3c\uc744 \uac00\uae4c\uc774 \ub370\ub824\uc635\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Clothing", "url": "stories/princess-crescent-comb/index.html", "image": "media/princess-crescent-comb.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc5bc\ub808\ube57 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc791\uc740 \ubc18\ub2ec\uc740 \uba38\ub9ac\ub97c \ube57\ub294 \ub3c4\uad6c\uc600\ub2e4 \ud654\ud611\uc639\uc8fc\uc758 \ube57\uc5d0\uc11c \ubc1c\uacac\ud558\ub294 \uc77c\uc0c1\uc758 \ubaa8\uc591 \ub098\ubb34\ub85c \ub9cc\ub4e0 \uc791\uc740 \uc5bc\ub808\ube57\uc774 \ub0af\uc120 \uc655\uc2e4 \uc778\ubb3c\uc744 \uac00\uae4c\uc774 \ub370\ub824\uc635\ub2c8\ub2e4. Clothing \uc0dd\ud65c \uc791\uc740 \uac08\uc0c9 \uc870\uac01\uc774 \ubc18\ub2ec\ucc98\ub7fc \uad7d\uc5b4 \uc788\ub2e4. \uc544\ub798\ucabd\uc758 \ube57\uc0b4\uc744 \ubcf4\uae30 \uc804\uc5d0\ub294 \ubb34\uc2a8 \ubb3c\uac74\uc778\uc9c0 \uc7a0\uae50 \uace0\uac1c\ub97c \uae30\uc6b8\uc774\uac8c \ub41c\ub2e4. \uc774\ub984\uc740 \uc5bc\ub808\ube57\uc774\ub2e4. \uad81\uc911 \uc720\ubb3c\uc774\ub77c\uace0 \ud558\uba74 \uba3c\uc800 \ucee4\ub2e4\ub780 \uc655\uad00\uc774\ub098 \ud654\ub824\ud55c \uc758\ubcf5\uc744 \ub5a0\uc62c\ub9ac\uc9c0\ub9cc, \uba38\ub9ac\ub97c \uc815\ub3c8\ud558\ub294 \uc791\uc740 \ub3c4\uad6c\ub3c4 \ub0a8\uc544 \uc788\ub2e4. \uc774 \ube57\uc740 \ud654\ud611\uc639\uc8fc\uc758 \ubb18\uc5d0\uc11c \ucd9c\ud1a0\ub41c \uac83\uc73c\ub85c \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uac1c\ud55c\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \ud615\ud0dc\ub97c \ud3c9\ud3c9\ud55c \ubc18\ub2ec \ubaa8\uc591\uc774\ub77c\uace0 \ud558\uace0, \ube57\uc0b4\uc740 \ud55c\ucabd\uc73c\ub85c\ub9cc \ub098 \uc788\ub2e4\uace0 \uc801\ub294\ub2e4. \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ub465\uadfc \ub4f1\uacfc \ube57\uc0b4\uc774 \uc788\ub294 \uac00\uc7a5\uc790\ub9ac\uac00 \uc11c\ub85c \ub2e4\ub978 \uc120\uc744 \ub9cc\ub4e0\ub2e4. \uc774 \ube57\uc758 \uc7ac\ub8cc\ub294 \ub098\ubb34\ub2e4. \ubd89\uc740 \uce60\uc744 \ub73b\ud558\ub294 \uc8fc\uce60\uc740 \ub4f1\ub9c8\ub8e8\uc5d0 \ud588\ub2e4\uace0 \ud55c\ub2e4. \uc0ac\uc9c4 \uc804\uccb4\uac00 \ubd89\uc740\uc0c9\uc73c\ub85c \uc120\uba85\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4, \ud604\uc7ac \ubaa8\uc2b5\uacfc \uc124\uba85\uc5d0 \ub0a8\uc740 \uc81c\uc791 \ud2b9\uc9d5\uc744 \ud568\uaed8 \uc77d\uc73c\uba74 \ub193\uce58\uae30 \uc26c\uc6b4 \ubd80\ubd84\uc744 \ubc1c\uacac\ud560 \uc218 \uc788\ub2e4. \ud654\ud611\uc639\uc8fc\ub294 1733\ub144\uc5d0 \ud0dc\uc5b4\ub098 1752\ub144\uc5d0 \uc138\uc0c1\uc744 \ub5a0\ub09c \uc778\ubb3c\uc774\ub2e4. \ubc15\ubb3c\uad00\uc774 \uc54c\ub824 \uc8fc\ub294 \uc0dd\ubab0\ub144\uacfc \ucd9c\ud1a0 \uc7a5\uc18c\uac00 \uc774 \uc791\uc740 \ube57\uc744 \ud2b9\uc815\ud55c \uc778\ubb3c\uc758 \ud754\uc801\uacfc \uc774\uc5b4 \uc900\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc2e4\uc81c\ub85c \uc5b4\ub290 \ub0a0 \uc5b4\ub5a4 \uba38\ub9ac\ub97c \ube57\uc5c8\ub294\uc9c0\uae4c\uc9c0 \uc7ac\ud604\ud560 \uc218\ub294 \uc5c6\ub2e4. \ubb18\uc5d0\uc11c \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\uacfc \uc0dd\uc804\uc758 \uc0ac\uc6a9 \uc7a5\uba74\uc740 \uad6c\ubd84\ud574\uc57c \ud55c\ub2e4. \uc0c1\uc0c1\uc758 \ub300\ud654\ub97c \ubd99\uc774\uc9c0 \uc54a\uc544\ub3c4, \uc6b0\ub9ac\uac00 \uc544\ub294 \ube57\uc774\ub77c\ub294 \ubb3c\uac74\ub9cc\uc73c\ub85c \ub0af\uc120 \uc0ac\ub78c\uacfc\uc758 \uac70\ub9ac\uac00 \uc870\uae08 \uc904\uc5b4\ub4e0\ub2e4. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc758 \uac00\ub85c \uae38\uc774\ub294 4.9\uc13c\ud2f0\ubbf8\ud130\ub2e4. \uc22b\uc790\ub97c \uc77d\uace0 \uc0ac\uc9c4\uc744 \ub2e4\uc2dc \ubcf4\uba74 \ucc98\uc74c\uc5d0 \uc9d0\uc791\ud588\ub358 \uac83\ubcf4\ub2e4 \ub354 \uc791\uc740 \ubb3c\uac74\uc73c\ub85c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \ud06c\uac8c \ubcf8\ub2e4\uace0 \uc2e4\uc81c \ubb3c\uac74\ub3c4 \ucee4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774 \ube57\uc5d0\uc11c \ud2b9\ubcc4\ud55c \ube44\ubc00\uc744 \ucc3e\uc73c\ub824\uace0 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub098\ubb34\ub97c \ub2e4\ub4ec\uace0 \ud55c\ucabd\uc5d0 \ube57\uc0b4\uc744 \ub0b4\uace0 \ub4f1\uc5d0 \ubd89\uc740 \uce60\uc744 \ud588\ub2e4\ub294 \uac83. \uadf8\ub7f0 \uad6c\uccb4\uc801\uc778 \ubaa8\uc2b5\uc774 \uc624\ub798\uc804\uc758 \uc0dd\ud65c\uc744 \ub5a0\uc62c\ub9b4 \ucd9c\ubc1c\uc810\uc774 \ub41c\ub2e4. \ubc18\ub2ec \ubaa8\uc591 \ud558\ub098\uac00 \uc778\ubb3c\uc758 \uae34 \uc124\uba85\ubcf4\ub2e4 \uc624\ub798 \uae30\uc5b5\ub420 \ub54c\ub3c4 \uc788\ub2e4."}, {"id": "red-comb-chest-turtle", "title": "\ube57\uc744 \ub2f4\ub294 \uc0c1\uc790\uc758 \ubb38\uc9c0\uae30\ub294 \uac70\ubd81\uc774\uc5c8\ub2e4", "summary": "\uc11c\ub78d\uacfc \uce78\ub9c9\uc774\ub97c \uac16\ucd98 \ube57\uc811\uc5d0\uc11c \uac70\ubd81\uc774 \ubaa8\uc591 \uc790\ubb3c\uc1e0\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Housing", "url": "stories/red-comb-chest-turtle/index.html", "image": "media/red-comb-chest-turtle.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc8fc\uce60\ube57\uc811 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ube57\uc744 \ub2f4\ub294 \uc0c1\uc790\uc758 \ubb38\uc9c0\uae30\ub294 \uac70\ubd81\uc774\uc5c8\ub2e4 \ubd89\uc740 \ube57\uc811\uc5d0 \ub2ec\ub9b0 \uc791\uc740 \uc790\ubb3c\uc1e0 \uc11c\ub78d\uacfc \uce78\ub9c9\uc774\ub97c \uac16\ucd98 \ube57\uc811\uc5d0\uc11c \uac70\ubd81\uc774 \ubaa8\uc591 \uc790\ubb3c\uc1e0\ub97c \ubc1c\uacac\ud569\ub2c8\ub2e4. Housing \uc0dd\ud65c \uc791\uc740 \ubd89\uc740 \uc0c1\uc790\uac00 \uc788\ub2e4. \ubb38\uc9dd\uacfc \uae08\uc18d \uc7a5\uc2dd\uc774 \ub2ec\ub824 \uc788\uc5b4\uc11c \uac00\uad6c\ub97c \uc904\uc5ec \ub193\uc740 \uac83\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uac00\uae4c\uc774 \uc0b4\ud3b4\ubcfc \ub54c \uc7ac\ubbf8\uc788\ub294 \uac83\uc740 \uac00\uc6b4\ub370 \ubd99\uc740 \uc790\ubb3c\uc1e0\ub2e4. \ubaa8\uc591\uc774 \uac70\ubd81\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc8fc\uce60\ube57\uc811\uc774\ub2e4. \ube57\uc811\uc774\ub77c\ub294 \ub0af\uc120 \uc774\ub984\uc744 \ub9cc\ub0ac\ub2e4\uba74, \ube57\uc744 \ub450\ub294 \uc791\uc740 \uc218\ub0a9 \uac00\uad6c\ub97c \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \uc548\uc744 \uc815\ub9ac\ud558\ub294 \uad6c\uc870\uc640 \ubc16\uc744 \uafb8\ubbf8\ub294 \uc7a5\uc2dd\uc774 \ud568\uaed8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc717\ub2e8\uc744 \uc816\ud600 \uc5ec\ub294 \ubd80\ubd84\uacfc \uc548\ucabd\uc758 \uc11c\ub78d \ub450 \uac1c\uac00 \uc788\ub294 \uad6c\uc870\ub77c\uace0 \uc124\uba85\ud55c\ub2e4. \uc717\ubd80\ubd84 \uc548\uc5d0\ub294 \uce78\ub9c9\uc774\ub3c4 \uc788\uc73c\uba70, \ud604\uc7ac \uadf8 \uc77c\ubd80\ub294 \uc5c6\uc5b4\uc838 \uc788\ub2e4. \uc791\uc740 \uc0c1\uc790\ub77c\uace0 \uc548\uc774 \ud145 \ube44\uc5b4 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub298\ub0a0 \ud654\uc7a5\ub300 \uc11c\ub78d\uc5d0 \uc815\ub9ac\ud568\uc744 \ub123\ub294 \ubaa8\uc2b5\uc744 \uc0dd\uac01\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\ub2e4. \ub2e4\ub9cc \uac01 \uce78\uc5d0 \uc815\ud655\ud788 \ubb34\uc5c7\uc744 \ub123\uc5c8\ub294\uc9c0\ub294 \uc774 \uc124\uba85\ub9cc\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \ubb3c\uac74\ub9c8\ub2e4 \uc790\ub9ac\ub97c \ub098\ub204\uc5b4 \ub454 \uad6c\uc870\uc5d0 \uba3c\uc800 \uc8fc\ubaa9\ud558\uba74 \ub41c\ub2e4. \uac89\uba74\uc5d0\ub294 \ubd89\uc740 \uce60\uc744 \ud588\uace0 \ub0b4\ubd80\ub294 \uac80\uc740 \uce60\ub85c \ub9c8\uac10\ud588\ub2e4. \uc11c\ub78d \uc5ed\uc2dc \uc55e\uba74\uc740 \ubd89\uace0 \ub098\uba38\uc9c0 \uba74\uc740 \uac80\ub2e4\uace0 \ud55c\ub2e4. \ub2eb\uc558\uc744 \ub54c \ubcf4\uc774\ub294 \ubd80\ubd84\uacfc \uc5f4\uc5c8\uc744 \ub54c \ub4dc\ub7ec\ub098\ub294 \ubd80\ubd84\uc758 \uc0c9\uc774 \ub2e4\ub974\ub2e4. \uae08\uc18d \uc7a5\uc2dd\uc5d0\ub294 \uaf43\ubb34\ub2ac\ub97c \ube44\ub86f\ud55c \uc5ec\ub7ec \ubb34\ub2ac\uac00 \uc788\ub2e4. \ud638\ub9ac\ubcd1\uacfc \ubcf5\uc22d\uc544, \ubd80\ucc44, \uaf43\uacfc \uc0c8 \uc7a5\uc2dd\ub3c4 \uc124\uba85\uc5d0 \ub4f1\uc7a5\ud55c\ub2e4. \uc791\uc740 \uc218\ub0a9 \uac00\uad6c\uc5d0 \uaf64 \ub9ce\uc740 \ubcfc\uac70\ub9ac\ub97c \ubaa8\uc544 \ub454 \uc148\uc774\uc9c0\ub9cc, \ucc98\uc74c\ubd80\ud130 \ubaa8\ub450 \ucc3e\uc73c\ub824 \uc560\uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc774 \ube57\uc811\uc5d0\ub294 \uac70\ubd81\uc774 \ud615\ud0dc\uc758 \uc790\ubb3c\uc1e0\uac00 \ubd99\uc5b4 \uc788\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc54c\ub824 \uc900\ub2e4. \uc11c\ub78d \uc18d\uc744 \ub2e4 \ud655\uc778\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774 \uc791\uc740 \ub3d9\ubb3c \ud558\ub098 \ub355\ubd84\uc5d0 \uc0c1\uc790\uc758 \uc778\uc0c1\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \uac70\ubd81\uc774 \uc7a5\uc2dd\uc758 \ub73b\uc744 \uc774 \uc790\ub8cc\ub9cc\uc73c\ub85c \ud655\uc815\ud558\uac70\ub098 \uc7a0\uae08\uc7a5\uce58\uc758 \uc131\ub2a5\uc744 \uc9d0\uc791\ud558\uc9c0\ub294 \ub9d0\uc790. \uc5ec\uae30\uc11c \uc990\uae38 \uac83\uc740 \uc218\ub0a9 \uac00\uad6c\uc758 \ud55c\uac00\uc6b4\ub370 \ub3d9\ubb3c\uc758 \ubaa8\uc591\uc744 \ub193\uc558\ub2e4\ub294 \uc120\ud0dd\uc774\ub2e4. \ubd89\uc740 \uc0c1\uc790\ub97c \ub2e4\uc2dc \ubcfc \ub54c \ubb38\uc591\uc774 \ub9ce\uc558\ub2e4\ub294 \uae30\uc5b5\ubcf4\ub2e4, \ube57\uc744 \uc9c0\ud0a4\ub294 \uac70\ubd81\uc774 \uac19\uc558\ub2e4\ub294 \uc778\uc0c1\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "scent-bead-norigae", "title": "\uc774 \ubaa9\uac78\uc774 \uac19\uc740 \uc7a5\uc2dd\uc740 \uce58\ub9c8 \uc18d\uc5d0 \uc228\uc5c8\ub2e4", "summary": "\uad6c\uc2ac\ucc98\ub7fc \uc774\uc5b4\uc9c4 \uc7a5\uc2e0\uad6c\uac00 \ud5a5\uae30\ub97c \uac04\uc9c1\ud558\ub358 \ubc29\ubc95\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Clothing", "url": "stories/scent-bead-norigae/index.html", "image": "media/scent-bead-norigae.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc904\ud5a5\ub178\ub9ac\uac1c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \ubaa9\uac78\uc774 \uac19\uc740 \uc7a5\uc2dd\uc740 \uce58\ub9c8 \uc18d\uc5d0 \uc228\uc5c8\ub2e4 \ub208\ubcf4\ub2e4 \ucf54\uac00 \uba3c\uc800 \ub9cc\ub098\ub294 \ub178\ub9ac\uac1c \uad6c\uc2ac\ucc98\ub7fc \uc774\uc5b4\uc9c4 \uc7a5\uc2e0\uad6c\uac00 \ud5a5\uae30\ub97c \uac04\uc9c1\ud558\ub358 \ubc29\ubc95\uc744 \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. Clothing \uc0dd\ud65c \uc0ac\uc9c4 \uc18d \ubb3c\uac74\uc740 \uae34 \ubaa9\uac78\uc774\ucc98\ub7fc \ubcf4\uc778\ub2e4. \uc0c9\uc774 \ub2e4\ub978 \uc791\uc740 \uc54c\ub4e4\uc774 \uc904\uc744 \ub530\ub77c \uc774\uc5b4\uc9c0\uace0, \uc544\ub798\uc5d0\ub294 \uc220\uc774 \ub2ec\ub838\ub2e4. \uadf8\ub7f0\ub370 \uc774\ub984\uc740 \ubaa9\uac78\uc774\uac00 \uc544\ub2c8\ub77c \uc904\ud5a5\ub178\ub9ac\uac1c\ub2e4. \uc7a5\uc2e0\uad6c\ub77c\uba74 \ub0a8\uc5d0\uac8c \ubcf4\uc5ec \uc8fc\ub294 \ubb3c\uac74\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uae30 \uc27d\ub2e4. \uc774 \ub178\ub9ac\uac1c\ub294 \uc870\uae08 \ub2e4\ub974\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0\ub294 \uc740\uc740\ud55c \ud5a5\uae30\ub97c \ud48d\uae30\ub3c4\ub85d \uce58\ub9c8 \uc18d\uc5d0 \ucc3c\ub2e4\uace0 \uc801\ud600 \uc788\ub2e4. \ub208\uc5d0 \uc798 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc790\ub9ac\uc5d0\ub3c4 \uafb8\ubc08\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc904\ud5a5\uc744 \ud5a5\uc73c\ub85c \ub9cc\ub4e0 \ub465\uadfc \uc54c\uc744 \uc774\uc5b4 \ub193\uc740 \uac83\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \ud5a5\uc744 \uad6c\uc2ac \ubaa8\uc591\uc73c\ub85c \ube5a\uc5b4 \uc0c9\uc744 \uce60\ud558\uac70\ub098 \ucc9c\uc73c\ub85c \uc2f8\uc11c, \uc5fc\uc8fc\ucc98\ub7fc \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc774 \uc18c\uc7a5\ud488\uc758 \uc124\uba85\uc5d0\ub294 \ubd89\uc740\uc0c9\uacfc \ud669\uc0c9, \ub179\uc0c9, \ud770\uc0c9\uc774 \ub4f1\uc7a5\ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uc0c9\uc744 \ucc3e\ub2e4 \ubcf4\uba74 \ucc98\uc74c\uc5d0\ub294 \uadf8\uc800 \uc608\uc05c \uad6c\uc2ac\uc774\ub77c\uace0 \uc5ec\uacbc\ub358 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \ubaa8\uc591\ubfd0 \uc544\ub2c8\ub77c \ud5a5\uae30\ub97c \ud568\uaed8 \uc0dd\uac01\ud574\uc57c \ud558\ub294 \ubb3c\uac74\uc774\ub2e4. \ub178\ub9ac\uac1c\ub294 \uc800\uace0\ub9ac \uace0\ub984\uc774\ub098 \uce58\ub9c8\ud5c8\ub9ac \ub048\uc5d0 \ucc28\ub294 \uc7a5\uc2e0\uad6c\ub2e4. \uc904\ud5a5\ub178\ub9ac\uac1c \uc5ed\uc2dc \uc637\uacfc \ud568\uaed8 \uc4f0\uc600\uc9c0\ub9cc, \ubc15\ubb3c\uad00\uc740 \uce58\ub9c8 \uc18d\uc5d0 \ucc28\ub294 \uc4f0\uc784\uc744 \ub530\ub85c \uc18c\uac1c\ud55c\ub2e4. \uac89\uc73c\ub85c \ub4dc\ub7ec\ub098\ub294 \uc7a5\uc2dd\uacfc \ud5a5\uae30\ub97c \uac00\uae4c\uc774 \ub450\ub294 \uc77c\uc740 \uaf2d \uac19\uc744 \ud544\uc694\uac00 \uc5c6\uc5c8\ub2e4. \uc624\ub298\ub0a0 \ud5a5\uc218\ub97c \ubfcc\ub9ac\ub294 \uc77c\uacfc \ub098\ub780\ud788 \ub5a0\uc62c\ub9b4 \uc218\ub294 \uc788\ub2e4. \ub2e4\ub9cc \uc774 \ubb3c\uac74\uc5d0 \uc5b4\ub5a4 \ud5a5 \uc7ac\ub8cc\uac00 \ub4e4\uc5b4\uac14\ub294\uc9c0, \ud5a5\uc774 \uc5bc\ub9c8\ub098 \uc624\ub798\uac14\ub294\uc9c0\uae4c\uc9c0 \ud655\uc778\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4. \uc0ac\uc9c4\ub9cc \ubcf4\uace0 \uaf43\ud5a5\uae30\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc815\ud574 \ubc84\ub9ac\uba74 \uc774\uc57c\uae30\uac00 \ubb3c\uac74\ubcf4\ub2e4 \uc55e\uc11c \ub098\uac04\ub2e4. \uc774 \ub178\ub9ac\uac1c\uc758 \uc7ac\ubbf8\ub294 \uc4f0\uc784\uc744 \uc54c\uace0 \ub098\uc11c \ubaa8\uc2b5\uc774 \ub2ec\ub77c \ubcf4\uc778\ub2e4\ub294 \ub370 \uc788\ub2e4. \uae38\uac8c \uc774\uc5b4\uc9c4 \uc54c\ub4e4\uc740 \uc0c9\uc744 \ub098\ub204\ub294 \uc7a5\uc2dd\uc778 \ub3d9\uc2dc\uc5d0 \ud5a5\uc744 \uac04\uc9c1\ud558\ub294 \ubd80\ubd84\uc774\uc5c8\ub2e4. \uc9c0\uae08 \uc0ac\uc9c4\uc5d0\uc11c\ub294 \ud5a5\uae30\ub97c \ub9e1\uc744 \uc218 \uc5c6\ub2e4. \uadf8\ub798\ub3c4 \uce58\ub9c8 \uc18d\uc5d0 \ub2ec\uc558\ub2e4\ub294 \uc9e7\uc740 \uc124\uba85 \ub355\ubd84\uc5d0, \uc624\ub798\ub41c \uc7a5\uc2e0\uad6c\uac00 \uc720\ub9ac\uc7a5 \uc548\uc758 \ubc18\uc9dd\uc774\ub294 \ubb3c\uac74\uc5d0\uc11c \uc77c\uc0c1 \uac00\uae4c\uc774\ub85c \ub0b4\ub824\uc628\ub2e4. \uc61b\uc0ac\ub78c\ub3c4 \uc790\uc2e0\uc758 \ubab8 \uac00\uae4c\uc774\uc5d0 \uae30\ubd84 \uc88b\uc740 \ubb34\uc5c7\uc744 \ub450\uace0 \uc2f6\uc5c8\ub358 \ubaa8\uc591\uc774\ub2e4."}, {"id": "victorian-paper-lace-valentine", "title": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4", "summary": "\uaf43\uacfc \ucc9c, \uc885\uc774 \ub808\uc774\uc2a4\ub97c \uacb9\uccd0 \ub9cc\ub4e0 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\uc758 \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "life", "category_title": "Life", "subcategory": "Folks", "url": "stories/victorian-paper-lace-valentine/index.html", "image": "media/victorian-paper-lace-valentine.jpg", "alt": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4\uc758 \uc8fc\uc81c\ub97c \ud45c\ud604\ud55c AI \uc124\uba85\uc6a9 \uc0bd\ud654. \uc2e4\uc81c \uc791\ud488\uc774\ub098 \uac74\ucd95\ubb3c\uc744 \uadf8\ub300\ub85c \uc7ac\ud604\ud55c \uc774\ubbf8\uc9c0\uac00 \uc544\ub2d9\ub2c8\ub2e4.", "text": "\uc61b \uc5f0\uc560\ud3b8\uc9c0\uc5d0\ub294 \uc885\uc774\ub85c \ub9cc\ub4e0 \ub808\uc774\uc2a4\uac00 \uc788\uc5c8\ub2e4 \ubbf8\uad6d\uc758 \uce74\ub4dc \uc81c\uc791\uc790\uac00 \uafb8\ubbfc \uc791\uc740 \uaf43\ubc14\uad6c\ub2c8 \uaf43\uacfc \ucc9c, \uc885\uc774 \ub808\uc774\uc2a4\ub97c \uacb9\uccd0 \ub9cc\ub4e0 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\uc758 \ubaa8\uc2b5\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Folks \uc0dd\ud65c \ucd95\ud558 \uce74\ub4dc \ud55c \uc7a5\uc744 \uc5f4\uc5c8\ub294\ub370 \uc885\uc774\uaf43\uacfc \ucc9c \uc870\uac01\uc774 \uce35\uce35\uc774 \ubd99\uc5b4 \uc788\ub2e4\uba74 \uc5b4\ub5a8\uae4c. \ud3b8\uc9c0\ub97c \uc77d\uae30 \uc804\uc5d0 \uba3c\uc800 \uc791\uc740 \uacf5\uc608\ud488\uc744 \ud3bc\uccd0 \ubcf4\ub294 \ub290\ub08c\uc77c \uac83\uc774\ub2e4. 19\uc138\uae30 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc \uc911\uc5d0\ub294 \uc2e4\uc81c\ub85c \uadf8\ub7f0 \ubb3c\uac74\ub4e4\uc774 \uc788\uc5c8\ub2e4. \uc2dc\uce74\uace0 \ubbf8\uc220\uad00\uc740 \ube45\ud1a0\ub9ac\uc544 \uc2dc\ub300\uc758 \ubc38\ub7f0\ud0c0\uc778 \uce74\ub4dc\ub97c 2\ucc9c \uc810 \ub118\uac8c \uc18c\uc7a5\ud55c \uceec\ub809\uc158\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc778\uc1c4\ub41c \ud55c \uc904\ub9cc \uc788\ub294 \uce74\ub4dc\uac00 \uc544\ub2c8\ub77c \uc885\uc774 \ub808\uc774\uc2a4\uc640 \ucc9c, \uc778\uc870 \uaf43\uc744 \ub354\ud55c \uce74\ub4dc\ub4e4\uc774 \ud568\uaed8 \uc788\ub2e4. \ub2f9\uc2dc\uc758 \uce74\ub4dc\ub294 \ud615\ud0dc\uac00 \ub2e4\uc591\ud588\ub2e4. \uc775\uc0b4\uc2a4\ub7ec\uc6b4 \uc8fc\uc81c\ub97c \uc778\uc1c4\ud55c \uac12\uc2fc \uce74\ub4dc\ub3c4 \uc788\uc5c8\uace0, \uc5ec\ub7ec \uc7ac\ub8cc\ub97c \ubd99\uc5ec \uc785\uccb4\uc801\uc73c\ub85c \ub9cc\ub4e0 \uce74\ub4dc\ub3c4 \uc788\uc5c8\ub2e4\uace0 \ud55c\ub2e4. \ub204\uad6c\ub098 \uac19\uc740 \ubaa8\uc591\uc73c\ub85c \ub9c8\uc74c\uc744 \uc804\ud588\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc885\uc774\ub97c \uc624\ub824 \ub9cc\ub4e0 \ub808\uc774\uc2a4\ub294 \ube48 \uacf5\uac04\uae4c\uc9c0 \uc7a5\uc2dd\uc774 \ub41c\ub2e4. \uaf43\uc744 \ud3c9\uba74\uc5d0 \uadf8\ub9ac\ub294 \ub300\uc2e0 \uc885\uc774\uc640 \ucc9c\uc73c\ub85c \ub9cc\ub4e4\uc5b4 \ubd99\uc774\uba74 \uce74\ub4dc\uc758 \ud45c\uba74\uc5d0\ub3c4 \ub192\ub0ae\uc774\uac00 \uc0dd\uae34\ub2e4. \ubc1b\ub294 \uc0ac\ub78c\uc740 \ubb38\uc7a5\ub9cc \uc77d\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacb9\uce5c \uc7ac\ub8cc\ub97c \ud568\uaed8 \ubcf4\uac8c \ub41c\ub2e4. \ubbf8\uc220\uad00\uc758 \uc124\uba85\uc740 \ubbf8\uad6d \ub9e4\uc0ac\ucd94\uc138\uce20\uc8fc \uc6b0\uc2a4\ud130\uc5d0\uc11c \uc77c\ud55c \uce74\ub4dc \uc81c\uc791\uc790 \uc5d0\uc2a4\ud130 \ud558\uc6b8\ub79c\ub4dc\ub97c \uc18c\uac1c\ud55c\ub2e4. \uadf8\ub294 1849\ub144\uc5d0 \uc790\uc2e0\uc758 \ud68c\uc0ac\ub97c \uc5f4\uc5c8\uace0 \uc5ec\uc131\ub4e4\uc744 \uace0\uc6a9\ud588\ub2e4\uace0 \ud55c\ub2e4. \ud2b9\ud788 \uc778\uae30\ub97c \ub048 \uac83\uc740 \uba54\uc774 \ubc14\uc2a4\ucf13\uc774\ub77c\ub294 \uaf43\ubc14\uad6c\ub2c8 \ud615\ud0dc\uc758 \uce74\ub4dc\uc600\ub2e4. \uc885\uc774 \ub808\uc774\uc2a4 \uac00\uc6b4\ub370 \ucee4\ub2e4\ub780 \uc624\ub824 \ub0b8 \ubc14\uad6c\ub2c8\ub97c \ub450\uace0, \uc548\uc5d0\ub294 \uc885\uc774\uc640 \ucc9c\uc73c\ub85c \ub9cc\ub4e0 \uaf43\ub4e4\uc744 \ube7d\ube7d\ud558\uac8c \ubaa8\uc558\ub2e4. \ubbf8\uc220\uad00\uc740 \uc774\ub7f0 \uce74\ub4dc \ub450 \uc810\uc744 \uc18c\uc7a5\ud558\uace0 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc9c0\uae08\uc740 \uadf8\ub9bc\uacfc \ubb38\uad6c\ub97c \uace8\ub77c \uc804\uc1a1\ud558\uba74 \uba87 \ucd08 \uc548\uc5d0 \ub9c8\uc74c\uc744 \uc804\ud560 \uc218 \uc788\ub2e4. \uc774\ub7f0 \uce74\ub4dc\ub294 \uadf8 \uc8fc\ubcc0\uc744 \ub9cc\ub4dc\ub294 \ub370\uc5d0\ub3c4 \uc190\uc774 \ub9ce\uc774 \uac14\uc744 \uac83\uc774\ub2e4. \ub9d0 \ub300\uc2e0 \uc5b4\ub5a4 \uc7ac\ub8cc\ub97c \uace0\ub974\uace0 \uc5b4\ub5bb\uac8c \uacb9\ucce4\ub294\uc9c0\uac00 \uc778\uc0ac\uc5d0 \ub354\ud574\uc9c4\ub2e4. \uc61b \uce74\ub4dc\ub97c \ubaa8\ub450 \uac70\ucc3d\ud55c \uc0ac\ub791\uc758 \uc99d\uac70\ub85c \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298\uc740 \uc885\uc774 \ub808\uc774\uc2a4\uc640 \uaf43\ubc14\uad6c\ub2c8\ub9cc \ub5a0\uc62c\ub824 \ubcf4\uc790. \ud55c \uc7a5\uc758 \uc885\uc774\ub97c \ub354 \uc608\uc058\uac8c \uafb8\uba70 \ub204\uad70\uac00\uc5d0\uac8c \uac74\ub124\uace0 \uc2f6\uc5c8\ub358 \ub9c8\uc74c\uc740 \uc9c0\uae08\uc758 \uce74\ub4dc \uace0\ub974\uae30\uc640\ub3c4 \ud06c\uac8c \uba40\uc9c0 \uc54a\ub2e4."}, {"id": "lego-first-wheels", "title": "\ub808\uace0 \ube14\ub85d\uc774 \uad74\ub7ec\uac00\uae30 \uc2dc\uc791\ud55c \ub0a0", "summary": "\ubcbd\uacfc \uc9d1\uc744 \uc313\ub358 \ube14\ub85d\uc5d0 \ubc14\ud034\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub180\uc774\uc5d0 \uc5b4\ub5a4 \ubcc0\ud654\ub97c \uc8fc\uc5c8\uc744\uae4c\uc694?", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/lego-first-wheels/index.html", "image": "media/lego-first-wheels.jpg", "alt": "\ube14\ub85d \uc7a5\ub09c\uac10 \uc790\ub3d9\ucc28\uc640 \uc791\uc740 \ubc14\ud034\ub97c \uadf8\ub9b0 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uace0 \ube14\ub85d\uc774 \uad74\ub7ec\uac00\uae30 \uc2dc\uc791\ud55c \ub0a0 \uc791\uc740 \ubc14\ud034 \ud558\ub098\uac00 \ubc14\uafbc \ub180\uc774\uc758 \uc6c0\uc9c1\uc784 \ubcbd\uacfc \uc9d1\uc744 \uc313\ub358 \ube14\ub85d\uc5d0 \ubc14\ud034\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4. \uc6c0\uc9c1\uc77c \uc218 \uc788\ub2e4\ub294 \uac83\uc740 \ub180\uc774\uc5d0 \uc5b4\ub5a4 \ubcc0\ud654\ub97c \uc8fc\uc5c8\uc744\uae4c\uc694? Technology \uae30\uc5c5 \ube14\ub85d\uc73c\ub85c \uc790\ub3d9\ucc28\ub97c \ub9cc\ub4e4\uc5c8\ub294\ub370 \ubc14\ud034\uac00 \uc5c6\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c. \ubaa8\uc591\uc740 \uc790\ub3d9\ucc28\uc9c0\ub9cc \uc6c0\uc9c1\uc774\ub824\uba74 \ubc14\ub2e5 \uc704\ub85c \ubc00\uac70\ub098 \uc190\uc73c\ub85c \ub4e4\uc5b4 \uc62e\uaca8\uc57c \ud55c\ub2e4. \uc9c0\uae08\uc740 \ub2f9\uc5f0\ud558\uac8c \ub290\uaef4\uc9c0\ub294 \ub808\uace0\uc758 \ubc14\ud034\ub3c4 \ucc98\uc74c\ubd80\ud130 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub808\uace0 \uacf5\uc2dd \uc5f0\ud601\uc740 1950\ub144\ub300 \ub9d0, \ube14\ub85d\uc5d0 \ub9de\ub294 \ubc14\ud034\ub97c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc5ec\ub7ec \uc0ac\ub78c\uc774 \uc124\uacc4\ub97c \uace0\ubbfc\ud558\ub358 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uc791\uc740 \uc6d0 \ud558\ub098\ub97c \ubd99\uc774\uba74 \ub420 \uac83 \uac19\uc9c0\ub9cc, \ube14\ub85d\uc758 \uc138\uacc4\uc5d0\uc11c\ub294 \uadf8 \uc6d0\uc744 \uc5b4\ub514\uc5d0 \uc5b4\ub5bb\uac8c \uc5f0\uacb0\ud560\uc9c0\uac00 \ubb38\uc81c\uc600\ub2e4. \uacf5\uc2dd \uc5f0\ud601\uc5d0 \ub530\ub974\uba74 \uac1c\ubc1c \ubd80\uc11c\uc758 \ud06c\ub204\ub4dc \ubb04\ub808\ub974 \ud06c\ub9ac\uc2a4\ud150\uc13c\uc740 1958\ub144\uc5d0 \ubc14\ud034\uc758 \ubaa8\uc2b5\uc744 \uc2a4\ucf00\uce58\ud588\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ubc14\ud034\ub97c \ube14\ub85d \ub450 \uac1c \uc0ac\uc774\uc5d0 \ub450\ub824 \ud588\uc9c0\ub9cc, \uadf8 \ubc29\uc2dd\uc740 \uc81c\ub300\ub85c \uc791\ub3d9\ud558\uc9c0 \uc54a\uc558\ub2e4. \uadf8 \ub4a4\uc758 \ud574\uacb0\ucc45\uc5d0\ub294 \ube14\ub85d\uacfc \uae08\uc18d \ucd95, \ubc14\ud034 \uc911\uc2ec\ubd80\uc640 \uace0\ubb34 \ud0c0\uc774\uc5b4\uac00 \ud568\uaed8 \ub4e4\uc5b4\uac14\ub2e4. \ucd95\uc744 \ubc1b\uc544 \uc8fc\ub294 \uad6c\uba4d\uc774 \uc788\ub294 \ube14\ub85d\uacfc \uc5f0\uacb0\ud558\ub294 \ubc29\uc2dd\uc774\uc5c8\ub2e4. \ubc14\ud034\ub9cc \ub530\ub85c \uc798 \uad74\ub7ec\uac04\ub2e4\uace0 \ub05d\ub098\ub294 \uc77c\uc740 \uc544\ub2c8\uc5c8\ub2e4. \uc774\ubbf8 \uc788\ub358 \ube14\ub85d\uacfc \ud568\uaed8 \uc4f8 \uc218 \uc788\uc5b4\uc57c \ud588\ub2e4. \uc0c8 \ubd80\ud488 \ud558\ub098\uac00 \uae30\uc874 \ub180\uc774\uc758 \uc57d\uc18d \uc548\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uacfc\uc815\uc774\uc5c8\ub358 \uac83\uc774\ub2e4. \uc774 \ubc14\ud034\ub294 \uc218\uc815\uc744 \uac70\uccd0 1962\ub144\uc5d0 \ucd9c\uc2dc\ub418\uc5c8\ub2e4. \ub808\uace0\ub294 \uac19\uc740 \ud574 \ub258\ub978\ubca0\ub974\ud06c \ubc15\ub78c\ud68c\uc5d0\uc11c \ubc14\ud034\ub97c \uc120\ubcf4\uc778 \uc7a5\uba74\ub3c4 \uc5f0\ud601\uc5d0 \ub2f4\uace0 \uc788\ub2e4. \uacf5\uc2dd \uc124\uba85\uc740 \ubc14\ud034\uc758 \ub4f1\uc7a5\uc744 \ube14\ub85d\uc5d0 \uc6c0\uc9c1\uc784\uc774 \ub354\ud574\uc9c4 \uc804\ud658\uc810\uc73c\ub85c \uc18c\uac1c\ud55c\ub2e4. \uc774\ud6c4 1960\ub144\ub300\uc5d0 \ube14\ub85d\uc73c\ub85c \ub9cc\ub4dc\ub294 \uc790\ub3d9\ucc28\uc640 \uae30\ucc28\uac00 \ub354 \ub9ce\uc774 \ub4f1\uc7a5\ud588\ub2e4. \uac00\ub9cc\ud788 \uc138\uc6cc \ub450\ub358 \ubaa8\uc591\uc774 \uad74\ub7ec\uac00\uba74 \ub180\uc774\uc758 \uc9c8\ubb38\ub3c4 \ub2ec\ub77c\uc9c4\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uae4c\uc5d0 \ub354\ud574, \uc5b4\ub514\ub85c \uc6c0\uc9c1\uc77c\uae4c\ub97c \uc0dd\uac01\ud558\uac8c \ub41c\ub2e4. \uac19\uc740 \ube14\ub85d\uc774 \ubc14\ud034 \uc704\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\ub294\ub2e4. \uc644\uc131\ub41c \uc7a5\ub09c\uac10\uc744 \ubcf4\uba74 \uc804\uccb4\uc758 \uba4b\uc9c4 \ubaa8\uc591\ubd80\ud130 \ubcf4\uc778\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ubaa8\uc2b5\uc744 \uac00\ub2a5\ud558\uac8c \ud55c \ubcc0\ud654\uac00 \uc544\uc8fc \uc791\uc740 \ubd80\ud488\uc5d0 \ub4e4\uc5b4 \uc788\ub294 \uacbd\uc6b0\ub3c4 \uc788\ub2e4. \ubc14\ud034\ub294 \ub208\uc5d0 \uc798 \ub744\uba74\uc11c\ub3c4 \ub108\ubb34 \uc775\uc219\ud574\uc838 \ucd9c\ubc1c\uc810\uc744 \uc78a\uae30 \uc26c\uc6b4 \ubd80\ud488\uc774\ub2e4. \ub808\uace0\uc758 \uc5f0\ud601\uc744 \uc77d\uace0 \ub098\uba74 \ubc14\ud034\ub97c \ub2e8\uc21c\ud788 \ub3d9\uadf8\ub780 \uc7a5\uc2dd\uc73c\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\ub2e4. \uc798 \ub3cc\uc544\uac00\uba74\uc11c\ub3c4 \ub2e4\ub978 \ubd80\ud488\uacfc \ud568\uaed8 \uc791\ub3d9\ud574\uc57c \ud588\ub358, \uc791\uc740 \uc124\uacc4 \ubb38\uc81c\uc758 \ub2f5\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ube14\ub85d \uc790\ub3d9\ucc28\ub97c \uad74\ub824 \ubcf4\uac8c \ub41c\ub2e4\uba74 \ucc28\uccb4 \uc544\ub798\ub3c4 \ud55c\ubc88 \ubcf4\uc790. \uc791\uc740 \uac80\uc740 \ubc14\ud034\uac00 \ubd99\uc740 \uc790\ub9ac\uc5d0\uc11c, \uc313\ub294 \ub180\uc774\ub294 \uc6c0\uc9c1\uc774\ub294 \ub180\uc774\ub85c \ud55c \uac78\uc74c \ub354 \ub098\uc544\uac14\ub2e4."}, {"id": "lego-play-well", "title": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c", "summary": "\uc775\uc219\ud55c \ub124 \uae00\uc790 \uc548\uc5d0 \ub374\ub9c8\ud06c\uc5b4\ub85c \ub180\uc774\uc5d0 \uad00\ud55c \ub73b\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub984\ubd80\ud130 \uba3c\uc800 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ub808\uace0 \uc774\uc57c\uae30.", "category": "companies", "category_title": "Companies", "subcategory": "Technology", "url": "stories/lego-play-well/index.html", "image": "media/lego-play-well.jpg", "alt": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc6d0\ub798 \ubb34\uc2a8 \ub73b\uc77c\uae4c \uc791\uc740 \ube14\ub85d\ubcf4\ub2e4 \uba3c\uc800 \uc788\uc5c8\ub358 \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \ub9d0 \uc775\uc219\ud55c \ub124 \uae00\uc790 \uc548\uc5d0 \ub374\ub9c8\ud06c\uc5b4\ub85c \ub180\uc774\uc5d0 \uad00\ud55c \ub73b\uc774 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub984\ubd80\ud130 \uba3c\uc800 \ub4e4\uc5ec\ub2e4\ubcf4\ub294 \ub808\uace0 \uc774\uc57c\uae30. Technology \uae30\uc5c5 \ub808\uace0 \uc0c1\uc790\ub97c \uc5f4\uba74 \uba3c\uc800 \uc124\uba85\uc11c\ub97c \ucc3e\ub294 \uc0ac\ub78c\uc774 \uc788\ub2e4. \ubc18\ub300\ub85c \ubd80\ud488\ubd80\ud130 \uc3df\uc544 \ub193\uace0 \ub9c8\uc74c\ub300\ub85c \uc313\ub294 \uc0ac\ub78c\ub3c4 \uc788\ub2e4. \uac19\uc740 \ube14\ub85d\uc744 \ubc1b\uc544\ub3c4 \ub178\ub294 \ubc29\ubc95\uc740 \uc870\uae08\uc529 \ub2e4\ub974\ub2e4. \uadf8\ub7f0\ub370 \ub808\uace0\ub77c\ub294 \uc774\ub984 \uc790\uccb4\uc5d0\ub3c4 \ub180\uc774\uc5d0 \uad00\ud55c \ub9d0\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub374\ub9c8\ud06c\uc5b4 \u2018leg godt\u2019\uc5d0\uc11c \uac00\uc838\uc628 \uc774\ub984\uc73c\ub85c, \ud754\ud788 \u2018\uc798 \ub180\uc544\ub77c\u2019 \ub610\ub294 \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \ub73b\uc73c\ub85c \ud480\uc774\ub41c\ub2e4. \ubcf5\uc7a1\ud55c \uc6b0\uc8fc\uc120\uc774\ub098 \ucee4\ub2e4\ub780 \uc131\uc744 \ub9cc\ub4e4\uae30 \uc804\uc5d0, \uc774\ub984\uc774 \uba3c\uc800 \uac74\ub124\ub294 \ub9d0\uc740 \uc758\uc678\ub85c \uac04\ub2e8\ud588\ub358 \uc148\uc774\ub2e4. \ub808\uace0\uc758 \ucc3d\uc5c5\uc790 \uc62c\ub808 \ud0a4\ub974\ud06c \ud06c\ub9ac\uc2a4\ud2f0\uc548\uc13c\uc740 \ub374\ub9c8\ud06c \ube4c\ub8ec\uc5d0\uc11c \ubaa9\uacf5 \uc77c\uc744 \ud558\uba70 \uc7a5\ub09c\uac10\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ucd08\uae30\uc758 \uc81c\ud488\uc740 \uc624\ub298\ub0a0 \uc6b0\ub9ac\uac00 \ub5a0\uc62c\ub9ac\ub294 \ud50c\ub77c\uc2a4\ud2f1 \ube14\ub85d\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uc138\uacc4\uc640 \ub2ec\ub790\ub2e4. \ub098\ubb34 \uc7a5\ub09c\uac10\uc774 \uc788\uc5c8\ub2e4. \ub808\uace0\ub77c\ub294 \uc774\ub984\uc740 \uc624\ub298\ub0a0\uc758 \ud50c\ub77c\uc2a4\ud2f1 \ube14\ub85d \ubaa8\uc591\uc744 \ubcf4\uace0 \uadf8 \ud2b9\uc9d5\uc5d0 \ub9de\ucd94\uc5b4 \uc9c0\uc740 \uac83\uc774 \uc544\ub2c8\uc5c8\ub2e4. \uacf5\uc2dd \uc5f0\ud601\uc740 \ubaa9\uc7ac \uc7a5\ub09c\uac10\uc744 \ub9cc\ub4e4\ub358 \uc2dc\uae30\uc5d0 \ub374\ub9c8\ud06c\uc5b4 LEG GODT\ub97c \uc870\ud569\ud574 \uc774\ub984\uc744 \uc815\ud588\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ub180\uc774\uc5d0 \uad00\ud55c \uc774\ub984\uc744 \uba3c\uc800 \uac16\uace0, \uadf8 \uc544\ub798\uc5d0\uc11c \uc7a5\ub09c\uac10\uc774 \ub2ec\ub77c\uc838 \uac04 \uac83\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 \uc775\uc219\ud55c \uc774\ub984\uc774 \uc870\uae08 \uc0c8\ub86d\uac8c \ub4e4\ub9b0\ub2e4. \uc6b0\ub9ac\ub294 \ubcf4\ud1b5 \ub808\uace0\ub97c \ubcf4\uba74 \ubc14\ub85c \ube14\ub85d\uc744 \ub5a0\uc62c\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub984\uc774 \uc0dd\uacbc\uc744 \ub54c\ubd80\ud130 \uc9c0\uae08\uc758 \ubaa8\ub4e0 \uc81c\ud488\uc774 \uc815\ud574\uc838 \uc788\uc5c8\ub358 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc4f0\uc778 \uc774\ub984\uc5d0\ub294 \uadf8\ub7f0 \uc2dc\uac04\uc774 \uc811\ud600 \uc788\ub2e4. \uc624\ub298\uc758 \ubb3c\uac74\ub9cc \ubcf4\uace0 \uacfc\uac70\uae4c\uc9c0 \uac19\uc740 \ubaa8\uc2b5\uc774\uc5c8\uc744 \uac83\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub193\uce58\ub294 \ubd80\ubd84\uc774\ub2e4. \ub808\uace0\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub984\uc774 \uc7a5\ub09c\uac10\uc758 \uc7ac\ub8cc \ubcc0\ud654\ubcf4\ub2e4 \uc624\ub798 \ub0a8\uc558\ub2e4. \uc9c0\uae08\uc758 \ub808\uace0\ub97c \ub5a0\uc62c\ub9ac\uba74 \uc11c\ub85c \ub9de\ubb3c\ub9ac\ub294 \ub3cc\uae30\uc640 \uad6c\uba4d\uc774 \uc0dd\uac01\ub09c\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \ube14\ub85d \ud55c \uac1c\uc758 \ubaa8\uc591\ub9cc\uc774 \uc544\ub2c8\ub77c, \uc5ec\ub7ec \uac1c\uac00 \uc5f0\uacb0\ub41c\ub2e4\ub294 \uc810\uc774\ub2e4. \ud63c\uc790 \uc788\uc744 \ub54c\ub294 \uc791\uc740 \ubd80\ud488\uc774\uc9c0\ub9cc \ub2e4\ub978 \ubd80\ud488\uc744 \ub9cc\ub098\uba74 \uc9d1\ub3c4 \ub418\uace0 \uc790\ub3d9\ucc28\ub3c4 \ub41c\ub2e4. \ubb3c\ub860 \uc544\ubb34 \uc870\ud569\uc774\ub098 \ub2e4 \uc798 \ub9de\ub294\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc81c\ud488\uc5d0 \ub530\ub77c \uc4f0\ub294 \ubc29\ubc95\uacfc \ud638\ud658 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uadf8\ub798\ub3c4 \ub9ce\uc740 \ube14\ub85d\uc744 \ub2e4\uc2dc \ub5bc\uace0 \uc0c8\ub85c \uc870\ub9bd\ud560 \uc218 \uc788\ub2e4\ub294 \uc810\uc740 \uc774 \ub180\uc774\uc758 \ud070 \ud2b9\uc9d5\uc774\ub2e4. \uc124\uba85\uc11c\ub300\ub85c \uc644\uc131\ud558\ub294 \uc7ac\ubbf8\uc640, \uc644\uc131\ud55c \uac83\uc744 \ub2e4\uc2dc \ubc14\uafb8\ub294 \uc7ac\ubbf8\uac00 \ud568\uaed8 \uc788\ub2e4. \uc9c0\ubd95\uc744 \ub5bc\uc5b4 \ub2e4\ub978 \uacf3\uc5d0 \ubd99\uc5ec \ubcf4\uac70\ub098 \ub0a8\uc740 \ubd80\ud488\uc73c\ub85c \ucc98\uc74c \uacc4\ud68d\uc5d0 \uc5c6\ub358 \ubb3c\uac74\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4. \uc0c1\uc790\uc5d0 \uadf8\ub824\uc9c4 \ubaa8\uc2b5\uc774 \ub180\uc774\uc758 \uc720\uc77c\ud55c \uacb0\ub9d0\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub798\uc11c \u2018\uc798 \ub180\uc790\u2019\ub77c\ub294 \uc774\ub984\uc740 \uaf64 \ub113\uac8c \ub4e4\ub9b0\ub2e4. \uc5ec\uae30\uc11c \uc798\ud55c\ub2e4\ub294 \uac83\uc744 \ub204\uac00 \ub354 \ube68\ub9ac \uc644\uc131\ud588\ub294\uc9c0\ub85c\ub9cc \uc77d\uc744 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uc774\uac83\uc740 \uc774\ub984\uc744 \uc624\ub298\uc758 \uc6b0\ub9ac\uac00 \uc990\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \ucc3d\uc5c5\uc790\uac00 \ubaa8\ub4e0 \uc0ac\uc6a9\uc790\uc758 \ub180\uc774\ub97c \ubbf8\ub9ac \uc0c1\uc0c1\ud588\ub2e4\uace0 \ub9d0\ud558\ub824\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ube0c\ub79c\ub4dc \uc774\ub984\uc744 \ub108\ubb34 \uc790\uc8fc \ubcf4\uba74 \ub73b\uc744 \uc0dd\uac01\ud558\uc9c0 \uc54a\uac8c \ub41c\ub2e4. \uac04\ud310\ucc98\ub7fc \uc54c\uc544\ubcf4\uba74 \ucda9\ubd84\ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uadf8\ub7f0\ub370 \uac00\ub054 \uadf8 \uc774\ub984\uc744 \ucc98\uc74c \ub4e3\ub294 \ub9d0\ucc98\ub7fc \ud480\uc5b4 \ubcf4\uba74 \ubb3c\uac74\uc758 \ub2e4\ub978 \uba74\uc774 \ubcf4\uc778\ub2e4. \ub808\uace0\ub294 \ub374\ub9c8\ud06c\uc758 \uc791\uc740 \uc791\uc5c5\uc7a5\uc5d0\uc11c \ucd9c\ubc1c\ud55c \uc7a5\ub09c\uac10 \ud68c\uc0ac\uc774\uba74\uc11c, \uc9c0\uae08\uc740 \uc5ec\ub7ec \ub098\ub77c\uc758 \uc0ac\ub78c\ub4e4\uc774 \uac01\uc790\uc758 \ubc29\uc2dd\uc73c\ub85c \uac00\uc9c0\uace0 \ub178\ub294 \uc774\ub984\uc774 \ub418\uc5c8\ub2e4. \uadf8 \ubcc0\ud654\ub97c \ub124 \uae00\uc790\ub9cc \ubcf4\uace0 \uc9d0\uc791\ud558\uae30\ub294 \uc5b4\ub835\ub2e4. \ub2e4\uc74c\uc5d0 \ube14\ub85d\uc744 \uc870\ub9bd\ud560 \uc77c\uc774 \uc0dd\uae34\ub2e4\uba74 \uc774\ub984\uc744 \ud55c \ubc88 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc124\uba85\uc11c\uc758 \ub9c8\uc9c0\ub9c9 \uc7a5\uc5d0 \ub3c4\ucc29\ud574\uc57c\ub9cc \ub180\uc774\uac00 \uc644\uc131\ub418\ub294 \uac83\uc740 \uc544\ub2d0\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \uc791\uc740 \ubd80\ud488 \ud558\ub098\uac00 \ub0a8\uc544\uc11c \uc5c9\ub6b1\ud55c \ubb3c\uac74\uc744 \ub9cc\ub4dc\ub294 \uc21c\uac04\ub3c4 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \ud68c\uc0ac \uc774\ub984\uc744 \uacf5\ubd80\ud558\ub7ec \uc2dc\uc791\ud55c \uc774\uc57c\uae30\ub294 \uc544\ub2c8\uc5c8\ub294\ub370, \uc774\ub984\uc744 \ud480\uace0 \ub098\ub2c8 \uacb0\uad6d \ub2e4\uc2dc \ub178\ub294 \uc774\uc57c\uae30\ub85c \ub3cc\uc544\uc654\ub2e4. \ub808\uace0\ub77c\ub294 \ub9d0\uc5d0\ub294 \ucc98\uc74c\ubd80\ud130 \uadf8 \ub2e8\uc11c\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4."}, {"id": "western-union-pasted-message", "title": "\uc804\ubcf4 \ud55c \uc7a5\uc5d0\ub294 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4", "summary": "1959\ub144 \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\uc5d0\uc11c \uc778\uc1c4\ub41c \uc591\uc2dd\uacfc \ub367\ubd99\uc778 \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud574 \ubd05\ub2c8\ub2e4.", "category": "companies", "category_title": "Companies", "subcategory": "Media", "url": "stories/western-union-pasted-message/index.html", "image": "media/western-union-pasted-message.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc804\ubcf4 (Western Union Telegram) \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc804\ubcf4 \ud55c \uc7a5\uc5d0\ub294 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4 \ud68c\uc0ac \uc774\ub984 \uc544\ub798\uc5d0 \ub193\uc778 \uc9e7\uc740 \uc18c\uc2dd 1959\ub144 \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\uc5d0\uc11c \uc778\uc1c4\ub41c \uc591\uc2dd\uacfc \ub367\ubd99\uc778 \uba54\uc2dc\uc9c0\ub97c \uad6c\ubd84\ud574 \ubd05\ub2c8\ub2e4. Media \uae30\uc5c5 \ud654\uba74\uc5d0 \ub72c \uba54\uc2dc\uc9c0\ub294 \uc190\uac00\ub77d\uc73c\ub85c \ub204\ub974\uba74 \uc5f4\ub9b0\ub2e4. \uc885\uc774\ub85c \ubc1b\uc740 \uc18c\uc2dd\uc774\ub77c\uba74 \ubcf4\ud1b5 \ud3b8\uc9c0 \ubd09\ud22c\ub97c \ub5a0\uc62c\ub9b4 \uac83\uc774\ub2e4. \uadf8\ub7f0\ub370 \uc774 \uc624\ub798\ub41c \uc804\ubcf4\ub294 \ub610 \ub2e4\ub974\ub2e4. \ud68c\uc0ac \uc774\ub984\uc774 \uc778\uc1c4\ub41c \uc885\uc774\uc5d0 \uba54\uc2dc\uc9c0 \uc885\uc774\uac00 \ud55c \ubc88 \ub354 \ubd99\uc5b4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc18c\uc7a5\ud55c \uc6e8\uc2a4\ud134\uc720\ub2c8\uc5b8 \uc804\ubcf4\ub2e4. \ub0a0\uc9dc\ub294 1959\ub144 4\uc6d4 13\uc77c\uc774\ub2e4. \ud55c \uc7a5\uc758 \ud1b5\uc2e0\ubb38\uc5d0\ub3c4 \ubbf8\ub9ac \ub9cc\ub4e4\uc5b4 \ub454 \ubd80\ubd84\uacfc \ub098\uc911\uc5d0 \ub354\ud574\uc9c4 \ubd80\ubd84\uc774 \ub098\ub258\uc5b4 \uc788\ub2e4. \uc0ac\uc9c4 \uc704\ucabd\uc5d0\ub294 WESTERN UNION\uc774\ub77c\ub294 \ud68c\uc0ac \uc774\ub984\uc774 \ud06c\uac8c \ubcf4\uc778\ub2e4. \uadf8 \uc544\ub798\ub85c \uae00\uc790\uac00 \uc774\uc5b4\uc9c4\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc740 \ube48\uce78\uc5d0 \uc804\ubcf4 \ub0b4\uc6a9\uc774 \uc801\ud78c \uc885\uc774\uac00 \ubd99\uc5b4 \uc788\ub2e4\uace0 \uc54c\ub824 \uc900\ub2e4. \uc591\uc2dd\uc740 \ud1b5\uc2e0\ud68c\uc0ac\uac00 \ub9c8\ub828\ud55c \uacf5\ud1b5\uc758 \ud2c0\uc774\uace0, \uadf8 \uc548\uc758 \uc18c\uc2dd\uc740 \uac01\uac01 \ub2e4\ub974\ub2e4. \uc624\ub298\ub0a0 \uac19\uc740 \uba54\uc2e0\uc800 \ud654\uba74\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \uba54\uc2dc\uc9c0\ub97c \uc8fc\uace0\ubc1b\ub294 \ubaa8\uc2b5\uc744 \ub5a0\uc62c\ub9b4 \uc218\ub3c4 \uc788\ub2e4. \ud654\uba74 \ub300\uc2e0 \uc885\uc774\uac00 \ub0a8\uc544 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uc190\uc5d0 \uc7a1\ud788\ub294 \ub290\ub08c\uc740 \uc0ac\ubb47 \ub2e4\ub974\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc774 \uc804\ubcf4\uac00 \ub274\uc695 \ube0c\ub8e8\ud074\ub9b0\uc5d0 \uc788\ub358 \uc774\uad6c\uc5d0\uac8c \ubcf4\ub0b8 \uac83\uc73c\ub85c \ubcf4\uc778\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c \uc7a5\uc18c\uc640 \uc774\ub984\uc740 \ud55c \uc904\uc758 \uc8fc\uc18c \uc774\uc0c1\uc774\ub2e4. \uc791\uc740 \uc885\uc774\ub97c \ud2b9\uc815\ud55c \uc0ac\ub78c\uc758 \uc0dd\ud65c\uacfc \uc774\uc5b4 \uc8fc\ub294 \ub2e8\uc11c\uac00 \ub41c\ub2e4. \ub2e4\ub9cc \u2018\ubcf4\uc778\ub2e4\u2019\ub294 \ud310\ub2e8\uc744 \ud655\uc815\ub41c \ubc1c\uc1a1 \uacbd\uc704\ub85c \ubc14\uafb8\uc5b4 \uc77d\uc9c0\ub294 \ub9d0\uc790. \uc774 \uc790\ub8cc\ub294 \uc218\uc2e0\uc790\ub97c \ucd94\uc815\ud558\uace0 \uc788\ub2e4. \ub204\uac00 \uc5b4\ub5a4 \ub9c8\uc74c\uc73c\ub85c \ubcf4\ub0c8\ub294\uc9c0\uae4c\uc9c0 \ub300\ud654\ub97c \ub9cc\ub4e4\uc5b4 \ubd99\uc77c \ud544\uc694\ub294 \uc5c6\ub2e4. \ub0a0\uc9dc\uc640 \uc218\uc2e0\uc9c0, \ub0a8\uc544 \uc788\ub294 \ud615\uc2dd\ub9cc\uc73c\ub85c\ub3c4 \ucda9\ubd84\ud788 \ubcfc\uac70\ub9ac\uac00 \uc788\ub2e4. \uc774 \uc804\ubcf4\ub294 \uc904\ub9ac\uc544 \uba40\ub85d\uc774 \uc77c\uad04 \uae30\uc99d\ud55c \uc790\ub8cc\uc5d0 \ud3ec\ud568\ub41c\ub2e4. \uac1c\uc778\uc774 \uac04\uc9c1\ud558\ub358 \ud1b5\uc2e0\ubb38\uc774 \ubc15\ubb3c\uad00\uc758 \uae30\ub85d\uc774 \ub41c \uac83\uc774\ub2e4. \ud68c\uc0ac\uc758 \uc778\uc1c4 \uc591\uc2dd\uc774 \uc5b4\ub290 \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc790\uc2e0\uc758 \uc18c\uc2dd\uc744 \ub2f4\uc740 \ubb3c\uac74\uc774\uae30\ub3c4 \ud588\ub2e4\ub294 \uc0ac\uc2e4\uc774 \ub290\uaef4\uc9c4\ub2e4. \ub2e4\uc2dc \uc0ac\uc9c4\uc744 \ubcf4\uba74 \ud68c\uc0ac \uc774\ub984\ubcf4\ub2e4 \ub367\ubd99\uc778 \uc885\uc774 \ucabd\uc5d0 \ub208\uc774 \uac08 \uc218 \uc788\ub2e4. \ub611\uac19\uc740 \uc591\uc2dd\uc744 \ub2e8 \ud55c \ubc88\uc758 \uc18c\uc2dd\uc73c\ub85c \ubc14\uafb8\ub294 \ubd80\ubd84\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \uc9e7\uac8c \uc804\ub2ec\ub41c \ub9d0\ub3c4 \ubb3c\uac74\uc73c\ub85c \ub0a8\uc73c\uba74, \uc18c\uc2dd\uc744 \uc8fc\uace0\ubc1b\ub358 \ubc29\uc2dd\uae4c\uc9c0 \ud568\uaed8 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "ai-clothing-labels", "title": "AI\ub294 \uc637 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud560\uae4c", "summary": "AI\uc758 \uc774\ubbf8\uc9c0 \ud559\uc2b5\uc744 \uc637\uc7a5 \uc815\ub9ac\ucc98\ub7fc \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc791\uc740 \ud751\ubc31 \uc0ac\uc9c4\uc5d0\ub3c4 \uc5f0\uc2b5\uacfc \uc2dc\ud5d8\uc774 \ub530\ub85c \uc788\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Artificial-Intelligence", "url": "stories/ai-clothing-labels/index.html", "image": "media/ai-clothing-labels.jpg", "alt": "\ud2f0\uc154\uce20\uc640 \ubc14\uc9c0, \uc6b4\ub3d9\ud654 \uc606\uc5d0 \ud53d\uc140 \uaca9\uc790\ub97c \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "AI\ub294 \uc637 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud560\uae4c \ud2f0\uc154\uce20\uc640 \uc6b4\ub3d9\ud654\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\ub294 \uc791\uc740 \uc608\uc81c AI\uc758 \uc774\ubbf8\uc9c0 \ud559\uc2b5\uc744 \uc637\uc7a5 \uc815\ub9ac\ucc98\ub7fc \ub4e4\uc5ec\ub2e4\ubd05\ub2c8\ub2e4. \uc791\uc740 \ud751\ubc31 \uc0ac\uc9c4\uc5d0\ub3c4 \uc5f0\uc2b5\uacfc \uc2dc\ud5d8\uc774 \ub530\ub85c \uc788\uc2b5\ub2c8\ub2e4. Artificial-Intelligence \ucef4\ud4e8\ud305 \uc0ac\uc9c4\uc744 \ubcf4\uace0 \ud2f0\uc154\uce20\uc778\uc9c0 \uc6b4\ub3d9\ud654\uc778\uc9c0 \uace0\ub974\ub294 \uc77c\uc740 \uc0ac\ub78c\uc5d0\uac8c \ub300\uac1c \uc5b4\ub835\uc9c0 \uc54a\ub2e4. \uadf8\ub7f0\ub370 \ucef4\ud4e8\ud130\uc5d0\uac8c \uac19\uc740 \uc77c\uc744 \ub9e1\uae30\ub824\uba74 \ubb34\uc5c7\uc744 \ubcf4\uc5ec\uc8fc\uc5b4\uc57c \ud560\uae4c. TensorFlow\uc758 \uacf5\uc2dd \uc785\ubb38 \uc608\uc81c\ub294 \uc637\uacfc \uc2e0\ubc1c \ub4f1\uc758 \uc0ac\uc9c4\uc744 \ubd84\ub958\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c\ub2e4. \uac70\ucc3d\ud55c \ud48d\uacbd \uc0ac\uc9c4 \ub300\uc2e0 \uc791\uc740 \ud751\ubc31 \uc774\ubbf8\uc9c0\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \ud2f0\uc154\uce20, \ubc14\uc9c0, \uac00\ubc29, \uc6b4\ub3d9\ud654\ucc98\ub7fc \uc775\uc219\ud55c \ubb3c\uac74\ub4e4\uc774\ub2e4. \uc5b4\ub824\uc6b4 \ucf54\ub4dc\ub97c \ub530\ub77c \ud558\uc9c0 \uc54a\uace0\ub3c4 \uc774 \uc608\uc81c\uac00 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c \uc900\ube44\ub418\uc5b4 \uc788\ub294\uc9c0\ub294 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \uc608\uc81c\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 Fashion-MNIST\uc5d0\ub294 \uc774\ubbf8\uc9c0\uc640 \ud568\uaed8 \uc885\ub958\ub97c \ub098\ud0c0\ub0b4\ub294 \ud45c\uc9c0\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc0ac\ub78c\uc758 \ub208\uc5d0\ub294 \uc637\uc73c\ub85c \ubcf4\uc774\ub294 \uc0ac\uc9c4\uc5d0, \ucef4\ud4e8\ud130\uac00 \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 \uc815\ub2f5\uc744 \ubd99\uc5ec \ub454 \uc148\uc774\ub2e4. \uc774\ubbf8\uc9c0\ub294 \uac00\ub85c\uc640 \uc138\ub85c\uac00 \uac01\uac01 28\uce78\uc778 \uc791\uc740 \uaca9\uc790\ub85c \ud45c\ud604\ub41c\ub2e4. \uac01 \uce78\uc5d0\ub294 \ubc1d\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uc22b\uc790\uac00 \ub4e4\uc5b4\uac04\ub2e4. \ud654\uba74\uc5d0 \ubcf4\uc774\ub294 \uadf8\ub9bc\uc744 \uacc4\uc0b0\ud560 \uc218 \uc788\ub294 \uac12\uc73c\ub85c \ub2e4\ub8e8\ub294 \uac83\uc774\ub2e4. \ubd84\ub958 \ub300\uc0c1\uc740 \uc5f4 \uc885\ub958\ub2e4. \uc774 \uc608\uc81c\uc758 \ubaa8\ub378\uc740 \uba3c\uc800 \uc815\ud574\uc9c4 \uc885\ub958\ub4e4 \uac00\uc6b4\ub370 \uc5b4\ub290 \ucabd\uc5d0 \uac00\uae4c\uc6b4\uc9c0 \uc5f0\uc2b5\ud55c\ub2e4. \uc138\uc0c1\uc758 \ubaa8\ub4e0 \uc637\uc744 \uc790\uc720\ub86d\uac8c \uc124\uba85\ud558\ub294 \uc2dc\uc2a4\ud15c\uc744 \ub9cc\ub4dc\ub294 \uac83\uacfc\ub294 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4. \uacf5\uc2dd \uc608\uc81c\ub294 \ud559\uc2b5\uc5d0 \uc4f0\ub294 \uc774\ubbf8\uc9c0 6\ub9cc \uc7a5\uacfc \ud3c9\uac00\uc5d0 \uc4f0\ub294 \uc774\ubbf8\uc9c0 1\ub9cc \uc7a5\uc744 \uad6c\ubd84\ud55c\ub2e4. \uc5f0\uc2b5\ud560 \ub54c \ubcf4\ub358 \uc0ac\uc9c4\uacfc \ub2e4\ub978 \uc0ac\uc9c4\uc5d0\uc11c\ub3c4 \ubd84\ub958\uac00 \uc798 \ub418\ub294\uc9c0 \ud655\uc778\ud558\ub824\ub294 \uad6c\uc131\uc774\ub2e4. \uc774\ubbf8 \ubcf8 \ubb38\uc81c\uc5d0\uc11c \uc798\ud588\ub2e4\uace0 \uc0c8\ub85c\uc6b4 \ubb38\uc81c\uc5d0\uc11c\ub3c4 \uac19\uc740 \uacb0\uacfc\ub97c \ub0b8\ub2e4\uace0 \uc7a5\ub2f4\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc608\uc81c\ub294 \uc774 \ucc28\uc774\uc640 \uacfc\uc801\ud569\uc774\ub77c\ub294 \ubb38\uc81c\ub3c4 \uc124\uba85\ud55c\ub2e4. \uc5ec\uae30\uc11c\ub294 \ud559\uc2b5\uc6a9 \uc0ac\uc9c4\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\uacfc \uc0c8\ub85c\uc6b4 \uc0ac\uc9c4\uc744 \uc798 \ub9de\ud788\ub294 \uc77c\uc774 \ub2e4\ub974\ub2e4\ub294 \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc774 \uae00\uc5d0\uc11c \ubaa8\ub378\uc744 \uc9c1\uc811 \uc2e4\ud589\ud574 \uc131\ub2a5\uc744 \uce21\uc815\ud55c \uac83\uc740 \uc544\ub2c8\ub2e4. \uacf5\uc2dd \ubb38\uc11c\uac00 \uc5b4\ub5a4 \uc5f0\uc2b5\uacfc \ud3c9\uac00\ub97c \uc548\ub0b4\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uac83\uc774\ub2e4. \ub530\ub77c\uc11c \uc5ec\uae30\uc758 \uc124\uba85\uc774\ub098 \uc0bd\ud654\ub97c \uc2e4\uc81c \uc2e4\ud5d8 \uacb0\uacfc\ub85c \ubc1b\uc544\ub4e4\uc774\uba74 \uc548 \ub41c\ub2e4. \uc608\uc81c\uc5d0\uc11c\ub294 \ubaa8\ub378\uc774 \uac01 \uc885\ub958\uc5d0 \ub300\ud574 \ub0b4\ub193\uc740 \uac12\uc744 \ube44\uad50\ud574 \ub2f5\uc744 \uc0b4\ud540\ub2e4. \ubb38\uc11c\uac00 \ud568\uaed8 \uac15\uc870\ud558\ub294 \uac83\uc740 \uc790\uc2e0 \uc788\uac8c \uace0\ub978 \ub2f5\ub3c4 \ud2c0\ub9b4 \uc218 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774 \uc0ac\uc2e4\uc744 \uc54c\uba74 AI\uac00 \uc774\ubbf8\uc9c0\ub97c \ubd84\ub958\ud55c\ub2e4\ub294 \ub9d0\uc744 \uc870\uae08 \uad6c\uccb4\uc801\uc73c\ub85c \uc774\ud574\ud558\uac8c \ub41c\ub2e4. \uc5b4\ub5a4 \uc0ac\uc9c4\uc73c\ub85c \ubb34\uc5c7\uc744 \uc5f0\uc2b5\ud588\uace0, \uc5b4\ub5a4 \uc885\ub958 \uc911\uc5d0\uc11c \ub2f5\uc744 \uace8\ub790\uc73c\uba70, \uc0c8 \uc0ac\uc9c4\uc73c\ub85c \uc5b4\ub5bb\uac8c \ud655\uc778\ud588\ub294\uc9c0\uae4c\uc9c0 \ubcf4\uac8c \ub41c\ub2e4. \uadf8\ub807\ub2e4\uace0 \uc637 \uc0ac\uc9c4\uc744 \ubcfc \ub54c\ub9c8\ub2e4 \uc22b\uc790 \uaca9\uc790\ub97c \ub5a0\uc62c\ub9b4 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc0ac\ub78c\uc5d0\uac8c \uc775\uc219\ud55c \ubb3c\uac74\ub3c4 \ucef4\ud4e8\ud130\uc758 \uc5f0\uc2b5 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \uc7ac\ubbf8\uc788\ub294 \uc2dc\uc791\uc774\ub2e4. \ub2e4\uc74c\uc5d0 AI\uac00 \uc0ac\uc9c4\uc5d0 \uc774\ub984\uc744 \ubd99\uc774\ub294 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \ub2f5 \ud558\ub098\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \uadf8 \ub4a4\uc758 \uc5f0\uc2b5 \ubb38\uc81c\ub3c4 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc791\uc740 \ud2f0\uc154\uce20 \uc0ac\uc9c4 \ud55c \uc7a5\uc774 \uc758\uc678\ub85c \ub9ce\uc740 \uc900\ube44\ub97c \ud488\uace0 \uc788\ub2e4."}, {"id": "email-at-sign", "title": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c", "summary": "\uba54\uc77c \uc8fc\uc18c\ub97c \ub9d0\ud560 \ub54c \uaf2d \ub4f1\uc7a5\ud558\ub294 @. \uc774\uba54\uc77c\uc744 \uc704\ud574 \uc0c8\ub85c \uadf8\ub9b0 \uae30\ud638\ub294 \uc544\ub2d9\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Internet", "url": "stories/email-at-sign/index.html", "image": "media/email-at-sign.jpg", "alt": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\uc774\uba54\uc77c \uc8fc\uc18c\uc5d0\ub294 \uc65c \uace8\ubc45\uc774\uac00 \ub4e4\uc5b4\uac08\uae4c \uc775\uc219\ud55c \uae30\ud638 \ud558\ub098\uac00 \uc0ac\ub78c\uacfc \ucef4\ud4e8\ud130\ub97c \ub098\ub204\uac8c \ub41c \uc0ac\uc5f0 \uba54\uc77c \uc8fc\uc18c\ub97c \ub9d0\ud560 \ub54c \uaf2d \ub4f1\uc7a5\ud558\ub294 @. \uc774\uba54\uc77c\uc744 \uc704\ud574 \uc0c8\ub85c \uadf8\ub9b0 \uae30\ud638\ub294 \uc544\ub2d9\ub2c8\ub2e4. Internet \ucef4\ud4e8\ud305 \uc804\ud654\ubc88\ud638\ub97c \ubd88\ub7ec\uc904 \ub54c\ub294 \uc22b\uc790\ub97c \uc774\uc5b4 \ub9d0\ud558\uba74 \ub41c\ub2e4. \uc774\uba54\uc77c \uc8fc\uc18c\ub97c \uc54c\ub824\uc904 \ub54c\ub294 \uc911\uac04\uc5d0 \uac11\uc790\uae30 \uc74c\uc2dd \uc774\ub984 \uac19\uc740 \ub9d0\uc774 \ub07c\uc5b4\ub4e0\ub2e4. \uace8\ubc45\uc774. \uc6b0\ub9ac\uac00 \uace8\ubc45\uc774\ub77c\uace0 \ubd80\ub974\ub294 @\ub294 \uba54\uc77c \uc8fc\uc18c\uc5d0\uc11c \uc544\uc8fc \uc775\uc219\ud55c \uae30\ud638\ub2e4. \uc18c\ubb38\uc790 a\ub97c \uc120 \ud558\ub098\uac00 \uac10\uc2f8\uace0 \uc788\ub294 \ubaa8\uc591\uc774\ub2e4. \ucef4\ud4e8\ud130 \ud654\uba74\uc5d0\uc11c\ub9cc \ubcf4\ub358 \uc0ac\ub78c\uc774\ub77c\uba74 \uc774\uba54\uc77c\uacfc \ud568\uaed8 \ud0dc\uc5b4\ub09c \uadf8\ub9bc\ucc98\ub7fc \ub290\ub084 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc774 \uae30\ud638\ub294 \uc774\uba54\uc77c\ubcf4\ub2e4 \ub098\uc774\uac00 \ub9ce\ub2e4. \ub204\uad70\uac00 \uc0c8\ub85c \ub514\uc790\uc778\ud55c \uc791\uc740 \uc778\ud130\ub137 \ub85c\uace0\uac00 \uc544\ub2c8\uc5c8\ub2e4. \ud1b0\ub9b0\uc2a8\uc774 \uc4f0\ub358 \ubaa8\ub378 33 \ud154\ub808\ud0c0\uc774\ud504\uc758 \ud0a4\ubcf4\ub4dc\uc5d0\ub294 \uc774\ubbf8 @\uac00 \uc788\uc5c8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc758 \uc5f0\ud601\uc740 \uadf8\uac00 \uc774 \uae30\uacc4\uc758 \ubb38\uc7a5\ubd80\ud638 \ud0a4 \uac00\uc6b4\ub370\uc11c @\ub97c \uace8\ub790\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc0c8\ub85c\uc6b4 \ud1b5\uc2e0 \ubc29\ubc95\uc744 \ub9cc\ub4e4\uba74\uc11c \ubaa8\ub4e0 \ud45c\uc2dc\uae4c\uc9c0 \uc0c8\ub85c \uadf8\ub9b4 \ud544\uc694\ub294 \uc5c6\uc5c8\ub358 \uac83\uc774\ub2e4. 1971\ub144, \uc11c\ub85c \ub2e4\ub978 \ucef4\ud4e8\ud130 \uc0ac\uc774\uc5d0\uc11c \uc804\uc790\uc6b0\ud3b8\uc744 \ubcf4\ub0b4\ub294 \uc77c\uc744 \uac1c\ubc1c\ud558\ub358 \ub808\uc774 \ud1b0\ub9b0\uc2a8\uc740 \uc8fc\uc18c \uc548\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc774\ub984\uacfc \ucef4\ud4e8\ud130\uc758 \uc774\ub984\uc744 \uad6c\ubd84\ud560 \ud45c\uc2dc\uac00 \ud544\uc694\ud588\ub2e4. \uadf8\uac00 \uace0\ub978 \uac83\uc774 @\uc600\ub2e4. \ud0a4\ubcf4\ub4dc\uc5d0 \uc774\ubbf8 \uc788\uc5c8\uace0, \uc774\ub984\uacfc \uae30\uacc4\uc758 \uc704\uce58\ub97c \ub098\ub204\ub294 \ub370 \uc54c\ub9de\uc558\ub2e4. \uc601\uc5b4\uc758 at\uc774 \uc8fc\ub294 \ub73b\ub3c4 \uc798 \uc5b4\uc6b8\ub838\ub2e4. \uc5b4\ub290 \ucef4\ud4e8\ud130\uc5d0 \uc788\ub294 \ub204\uad6c\ub77c\ub294 \uad00\uacc4\ub97c \ud45c\ud604\ud560 \uc218 \uc788\uc5c8\uae30 \ub54c\ubb38\uc774\ub2e4. \ubcf5\uc7a1\ud55c \uc0c8 \uae30\ud638\ub97c \ub9cc\ub4e4\uc9c0 \uc54a\uace0 \uc788\ub294 \uac83\uc744 \uace8\ub790\ub2e4\ub294 \uc810\uc774 \uc7ac\ubbf8\uc788\ub2e4. \uc9c0\uae08\uc740 \uc778\ud130\ub137\uc744 \ub300\ud45c\ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \ud45c\uc2dc\ub3c4 \ucc98\uc74c\uc5d0\ub294 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud55c \uc791\uc740 \uc120\ud0dd\uc774\uc5c8\ub2e4. \uc544\uc8fc \ub2e8\uc21c\ud55c \uc608\ub85c user@example.org\ub77c\ub294 \uc8fc\uc18c\ub97c \uc0dd\uac01\ud574 \ubcf4\uc790. @ \uc55e\ucabd\uc740 \uba54\uc77c\uc744 \ubc1b\uc744 \uacc4\uc815\uc5d0 \ud574\ub2f9\ud558\uace0, \ub4a4\ucabd\uc740 \uba54\uc77c \uc2dc\uc2a4\ud15c\uc758 \ub3c4\uba54\uc778\uc5d0 \ud574\ub2f9\ud55c\ub2e4. \uc0c1\uc138\ud55c \uae30\uc220\uc740 \ub354 \ubcf5\uc7a1\ud558\uc9c0\ub9cc, \uc8fc\uc18c\ub97c \uc77d\ub294 \uccab\uac78\uc74c\uc73c\ub85c\ub294 \uc774 \uad6c\ubd84\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \uadf8\ub807\ub2e4\uace0 @ \ub4a4\uc5d0 \uc2e4\uc81c \uc0ac\ubb34\uc2e4\uc774\ub098 \uac70\ub9ac \uc8fc\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \uc6f9\uc0ac\uc774\ud2b8 \uc774\ub984\uc73c\ub85c \uc775\uc219\ud558\uac8c \ubcf4\ub294 \uac83\uacfc \uac19\uc740 \uc885\ub958\uc758 \uc774\ub984\uc774\ub2e4. \uc6b0\ud3b8\ubc88\ud638\ub97c \uc801\ub4ef \ud604\uc2e4\uc758 \uc704\uce58\ub97c \uadf8\ub300\ub85c \uc368 \ub123\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ud55c \ucef4\ud4e8\ud130\uc640 \ub2e4\ub978 \ucef4\ud4e8\ud130 \uc0ac\uc774\ub97c \uad6c\ubd84\ud558\ub294 \uc120\ud0dd\uc774\uc5c8\uc9c0\ub9cc, \uc624\ub298\uc758 \uba54\uc77c\uc740 \ud6e8\uc52c \ud070 \uc2dc\uc2a4\ud15c \uc18d\uc5d0\uc11c \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub7fc\uc5d0\ub3c4 \uc774 \uc791\uc740 \ud45c\uc2dc\uac00 \uc8fc\uc18c\uc758 \ub450 \ubd80\ubd84\uc744 \ub098\ub204\ub294 \uc5ed\ud560\uc740 \uc54c\uc544\ubcf4\uae30 \uc27d\uac8c \ub0a8\uc544 \uc788\ub2e4. \ubb3c\ub860 \uc774\uba54\uc77c \uc8fc\uc18c\uc758 \uc138\ubd80 \uaddc\uce59\uae4c\uc9c0 \ubaa8\ub450 \uc774 \ud55c \uc904\ub85c \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc5ec\uae30\uc11c\ub294 \uba54\uc77c\uc744 \ubcf4\ub0b4\ub294 \uae30\uc220\ubcf4\ub2e4, \uc775\uc219\ud55c \ubaa8\uc591\uc774 \uc65c \uadf8 \uc790\ub9ac\uc5d0 \ub193\uc600\ub294\uc9c0\ub97c \ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ud55c\uad6d\uc5b4\uc5d0\uc11c\ub294 \uc774 \uae30\ud638\ub97c \uace8\ubc45\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \ubaa8\uc591\uc744 \ubcf4\uace0 \ubd99\uc778 \uc774\ub984\uc774\ub77c \ud55c \ubc88 \ub4e4\uc73c\uba74 \uc5b4\ub290 \ud45c\uc2dc\uc778\uc9c0 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc601\uc5b4\uc5d0\uc11c\ub294 \ubcf4\ud1b5 at\uc774\ub77c\uace0 \uc77d\ub294\ub2e4. \uc8fc\uc18c\ub97c \ub9d0\ub85c \uc804\ub2ec\ud560 \ub54c \uae30\ud638\uc758 \uc815\uc2dd \uc774\ub984\ubcf4\ub2e4 \ubcc4\uba85\uc774 \ub354 \uc790\uc5f0\uc2a4\ub7ec\uc6b8 \ub54c\uac00 \uc788\ub2e4. \ub208\uc73c\ub85c \ubcf8 \ubaa8\uc591\uc744 \ub9d0\ub85c \uc62e\uae30\ub294 \ubc29\uc2dd\uc774\ub2e4. \uc791\uc740 \uae30\ud638 \ud558\ub098\ub3c4 \uc0ac\uc6a9\ud558\ub294 \uc0ac\ub78c\ub4e4\uc758 \uc5b8\uc5b4 \uc18d\uc73c\ub85c \ub4e4\uc5b4\uc624\uba74 \uc0c8\ub85c\uc6b4 \ud638\uce6d\uc744 \uc5bb\ub294\ub2e4. \uc6b0\ub9ac\ub294 \uba54\uc77c \uc8fc\uc18c\ub97c \uc4f8 \ub54c\ub9c8\ub2e4 \uc774 \ud45c\uc2dc\ub97c \uc9c0\ub098\uac00\uc9c0\ub9cc, \ub9e4\ubc88 \uadf8 \uc5ed\uc0ac\ub97c \uc0dd\uac01\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc798 \uc791\ub3d9\ud558\ub294 \ub3c4\uad6c\ub294 \uc0ac\uc6a9\uc790\uac00 \uc624\ub798 \uace0\ubbfc\ud558\uc9c0 \uc54a\uace0 \uc9c0\ub098\uac08 \uc218 \uc788\uac8c \ud574 \uc900\ub2e4. \ub2e4\uc74c\uc5d0 \uace8\ubc45\uc774\ub97c \uc785\ub825\ud560 \ub54c \uc190\uac00\ub77d\uc744 \uc7a0\uae50 \uba48\ucdb0\ub3c4 \uc88b\uaca0\ub2e4. \uc6d0\ub798 \ub2e4\ub978 \uc77c\uc744 \ud558\ub358 \ud45c\uc2dc\uac00 \uc790\ub9ac\ub97c \uc62e\uaca8, \uc9c0\uae08\uc740 \uc804 \uc138\uacc4 \uc0ac\ub78c\ub4e4\uc758 \uc6b0\ud3b8\ud568\uc744 \ucc3e\uc544\uc8fc\ub294 \uc77c\uc744 \ub3d5\uace0 \uc788\ub2e4. \ud0a4\ubcf4\ub4dc \uc548\uc5d0\uc11c \uaf64 \uc131\uacf5\uc801\uc73c\ub85c \uc804\uc5c5\ud55c \uae30\ud638\ub2e4."}, {"id": "emoji-number-tags", "title": "\uc6c3\ub294 \uc774\ubaa8\uc9c0\uc5d0\ub3c4 \ubc88\ud638\ud45c\uac00 \uc788\ub2e4", "summary": "\ub300\ud654\ucc3d\uc758 \uc6c3\ub294 \uc5bc\uad74\uc744 \ub530\ub77c\uac00\uba74 \uadf8\ub9bc \ub300\uc2e0 \uc22b\uc790\uc640 \uc774\ub984\uc774 \ub098\ub780\ud788 \uc801\ud78c \ubaa9\ub85d\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Software", "url": "stories/emoji-number-tags/index.html", "image": "media/emoji-number-tags.jpg", "alt": "\uc6c3\ub294 \uc5bc\uad74\uacfc \uc5c4\uc9c0\uc190 \uc544\uc774\ucf58, \ube48 \ud45c\uc9c0\ub97c \ud568\uaed8 \ub193\uc740 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\uc6c3\ub294 \uc774\ubaa8\uc9c0\uc5d0\ub3c4 \ubc88\ud638\ud45c\uac00 \uc788\ub2e4 \uc791\uc740 \uc5bc\uad74 \uadf8\ub9bc \ub4a4\uc5d0 \ub193\uc778 \ubb38\uc790 \ubaa9\ub85d \ub300\ud654\ucc3d\uc758 \uc6c3\ub294 \uc5bc\uad74\uc744 \ub530\ub77c\uac00\uba74 \uadf8\ub9bc \ub300\uc2e0 \uc22b\uc790\uc640 \uc774\ub984\uc774 \ub098\ub780\ud788 \uc801\ud78c \ubaa9\ub85d\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4. Software \ucef4\ud4e8\ud305 \uba54\uc2dc\uc9c0 \ub05d\uc5d0 \uc6c3\ub294 \uc5bc\uad74 \ud558\ub098\ub97c \ubd99\uc778\ub2e4. \ub9d0\ub85c \uc4f0\uba74 \uc870\uae08 \ub531\ub531\ud560 \uac83 \uac19\uc740 \ubb38\uc7a5\uc774, \uc791\uc740 \ud45c\uc815 \ud558\ub098\ub85c \ubd80\ub4dc\ub7ec\uc6cc\uc9c4\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \uadf8\ub9bc\uc774\uc9c0\ub9cc \uae00 \uc0ac\uc774\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \ub4e4\uc5b4\uac04\ub2e4. \uadf8 \uc5bc\uad74\uc744 \uc815\ub9ac\ud55c \uacf5\uc2dd \uc790\ub8cc\ub97c \uc5f4\uba74 \uc608\uc0c1\uacfc \ub2e4\ub978 \ubaa8\uc2b5\uc774 \ub098\uc628\ub2e4. \uc608\uc05c \uc2a4\ud2f0\ucee4 \ubaa8\uc74c\ubcf4\ub2e4 \uc22b\uc790\uc640 \uc774\ub984\uc774 \uc774\uc5b4\uc9c4 \ubaa9\ub85d\uc5d0 \uac00\uae5d\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uac00 \uacf5\uac1c\ud55c \uc774\ubaa8\uc9c0 \uc2dc\ud5d8 \uc790\ub8cc\uc5d0\ub294 \ud45c\uc815\ub9c8\ub2e4 \ucf54\ub4dc\uc640 \uc124\uba85\uc774 \ubd99\uc5b4 \uc788\ub2e4. \uc720\ub2c8\ucf54\ub4dc\uc758 \uc774\ubaa8\uc9c0 16.0 \uc2dc\ud5d8 \uc790\ub8cc\uc5d0\uc11c \ud06c\uac8c \uc6c3\ub294 \uc5bc\uad74 \ud558\ub098\ub294 \u20181F600\u2019\uc774\ub77c\ub294 \ucf54\ub4dc\ub85c \uc801\ud600 \uc788\ub2e4. \ub4a4\uc5d0\ub294 \ud65c\uc9dd \uc6c3\ub294 \uc5bc\uad74\uc774\ub77c\ub294 \ub73b\uc758 \uc601\uc5b4 \uc774\ub984\uc774 \ub530\ub77c\uc628\ub2e4. \uc774 \uc22b\uc790\ub97c \uc678\uc6cc\uc11c \uba54\uc2dc\uc9c0\ub97c \uc4f8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc6b0\ub9ac\uac00 \uadf8\ub9bc\uc744 \uace0\ub974\uba74, \uadf8 \ub4a4\uc5d0\uc11c\ub294 \uc5b4\ub5a4 \ubb38\uc790\ub97c \uace0\ub978 \uac83\uc778\uc9c0 \uad6c\ubd84\ud560 \uc218 \uc788\ub294 \uae30\uc900\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uc815\ub3c4\ub85c \ubcf4\uba74 \ub41c\ub2e4. \ud45c\uc815\uc774 \ube44\uc2b7\ud558\ub2e4\uace0 \ubaa8\ub450 \uac19\uc740 \ud56d\ubaa9\ub3c4 \uc544\ub2c8\ub2e4. \uc6c3\ub294 \uc5bc\uad74, \ub208\uae4c\uc9c0 \uc6c3\ub294 \uc5bc\uad74, \uc6c3\ub2e4\uac00 \ub208\ubb3c\uc774 \ub098\ub294 \uc5bc\uad74\uc774 \uac01\uac01\uc758 \uc774\ub984\uc73c\ub85c \ub098\ub25c\ub2e4. \uc0ac\ub78c\uc5d0\uac8c\ub294 \uc791\uc740 \ud45c\uc815 \ucc28\uc774\uc9c0\ub9cc \ubaa9\ub85d\uc5d0\uc11c\ub294 \uad6c\ubd84\ud574\uc57c \ud560 \ucc28\uc774\ub2e4. \ubaa8\ub4e0 \uc774\ubaa8\uc9c0\uac00 \ucf54\ub4dc \ud558\ub098\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uac19\uc740 \uc790\ub8cc\uc5d0\ub294 \uc5c4\uc9c0\ub97c \uc62c\ub9b0 \uc190\uc758 \ucf54\ub4dc \ub4a4\uc5d0 \ud53c\ubd80\uc0c9\uc744 \ub098\ud0c0\ub0b4\ub294 \ucf54\ub4dc\uac00 \ub354\ud574\uc9c4 \ud56d\ubaa9\ub3c4 \ub098\uc628\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \ud558\ub098\uc758 \uc190\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc, \uc790\ub8cc\uc5d0\ub294 \ub458 \uc774\uc0c1\uc758 \ucf54\ub4dc\ub97c \uc774\uc5b4 \uc801\uc744 \uc218 \uc788\ub294 \uac83\uc774\ub2e4. \uacf5\uc2dd \ud30c\uc77c\ub3c4 \ud56d\ubaa9\uc758 \ucf54\ub4dc\uac00 \ud558\ub098 \uc774\uc0c1\uc77c \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub2c8 \ub208\uc55e\uc758 \uadf8\ub9bc \uac1c\uc218\uc640 \ub4a4\uc5d0 \uc801\ud78c \ucf54\ub4dc \uac1c\uc218\uac00 \ud56d\uc0c1 \uac19\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc791\uc740 \uadf8\ub9bc \ud558\ub098\ub97c \ud45c\uc2dc\ud558\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc815\ubcf4\ub97c \ud568\uaed8 \ub450\ub294\uc9c0 \uc5ff\ubcf4\ub294 \ub300\ubaa9\uc774\ub2e4. \uc774 \uc790\ub8cc\ub294 \uc774\ubaa8\uc9c0\uac00 \ud0a4\ubcf4\ub4dc\uc5d0 \ub098\uc624\uace0 \ud654\uba74\uc5d0\uc11c \ucc98\ub9ac\ub418\ub294\uc9c0\ub97c \uc2dc\ud5d8\ud558\uae30 \uc704\ud574 \uacf5\uac1c\ub41c \ubaa9\ub85d\uc774\ub2e4. \ud45c\uc815\ubfd0 \uc544\ub2c8\ub77c \uc0ac\ub78c\uacfc \uc0ac\ubb3c \ub4f1 \uc5ec\ub7ec \ubb36\uc74c\uc73c\ub85c \ub098\ub258\uc5b4 \uc788\ub2e4. \uc790\ub8cc\uc758 \uc124\uba85\uc5d0\ub294 \ubaa9\ub85d\uc774 \ucf54\ub4dc \uc22b\uc790 \uc21c\uc11c\uac00 \uc544\ub2c8\ub77c CLDR\uc758 \uc774\ubaa8\uc9c0 \uc21c\uc11c\ub97c \ub530\ub978\ub2e4\ub294 \ub0b4\uc6a9\ub3c4 \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c \uc0ac\ub78c\ub4e4\uc774 \uace0\ub974\ub294 \uc21c\uc11c\ub97c \uc0dd\uac01\ud558\uba70 \uc815\ub9ac\ud55c \ud754\uc801\uc774 \uacf5\uc2dd \ubaa9\ub85d \uc548\uc5d0\ub3c4 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uba54\uc2dc\uc9c0\uc5d0 \uc6c3\ub294 \uc5bc\uad74\uc744 \ud558\ub098 \ubd99\uc778\ub2e4\uba74, \uadf8 \ub4a4\uc5d0 \ubc88\ud638\ud45c\uc640 \uc774\ub984\ud45c\uac00 \uc788\ub2e4\ub294 \uac83\ub9cc \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc791\uace0 \uac00\ubcbc\uc6b4 \ud45c\uc815\uc744 \uc11c\ub85c \uad6c\ubd84\ud558\uae30 \uc704\ud574, \ubcf4\uc774\uc9c0 \uc54a\ub294 \uacf3\uc5d0\uc11c\ub294 \uaf64 \uaf3c\uaf3c\ud55c \uc815\ub9ac\uac00 \uc774\ub8e8\uc5b4\uc9c0\uace0 \uc788\ub2e4."}, {"id": "engelbart-mouse-demo", "title": "\uc791\uc740 \ub9c8\uc6b0\uc2a4\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud55c \ud070 \uc2dc\uc5f0", "summary": "\ud654\uba74\uc744 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ub3c4\uad6c\ub294 \ud568\uaed8 \uc77c\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub354 \ud070 \uad6c\uc0c1\uc758 \uc77c\ubd80\uc600\uc2b5\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Computers", "url": "stories/engelbart-mouse-demo/index.html", "image": "media/engelbart-mouse-demo.jpg", "alt": "\uc77c\ubc18\ud654\ud55c \uc720\uc120 \ub9c8\uc6b0\uc2a4\uc640 \ud654\uc0b4\ud45c \ucee4\uc11c\uac00 \uc788\ub294 \ud654\uba74\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uc791\uc740 \ub9c8\uc6b0\uc2a4\uac00 \ud568\uaed8 \ub4f1\uc7a5\ud55c \ud070 \uc2dc\uc5f0 1968\ub144\uc758 \ucef4\ud4e8\ud130 \uc2dc\uc5f0\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \ub5a0\uc62c\ub9ac\uae30 \ud654\uba74\uc744 \uac00\ub9ac\ud0a4\ub294 \uc791\uc740 \ub3c4\uad6c\ub294 \ud568\uaed8 \uc77c\ud558\ub294 \ucef4\ud4e8\ud130\ub97c \ubcf4\uc5ec\uc8fc\ub294 \ub354 \ud070 \uad6c\uc0c1\uc758 \uc77c\ubd80\uc600\uc2b5\ub2c8\ub2e4. Computers \ucef4\ud4e8\ud305 \ucef4\ud4e8\ud130 \ub9c8\uc6b0\uc2a4\ub294 \ub108\ubb34 \uc775\uc219\ud574\uc11c \ucc98\uc74c \ub4f1\uc7a5\ud588\uc744 \ub54c\ub97c \uc0c1\uc0c1\ud558\uae30 \uc5b4\ub835\ub2e4. \uc190\uc73c\ub85c \uc870\uae08 \uc6c0\uc9c1\uc774\uba74 \ud654\uba74\uc758 \ud45c\uc2dc\ub3c4 \uc6c0\uc9c1\uc778\ub2e4. \ucc45\uc0c1\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc791\uc740 \ub3d9\uc791\uc774\ub2e4. \uadf8 \uc791\uc740 \ub3c4\uad6c\uc758 \uc5ed\uc0ac\uc5d0\uc11c \uc790\uc8fc \ub9cc\ub098\ub294 \uc774\ub984\uc774 \ub354\uae00\ub7ec\uc2a4 \uc5e5\uac94\ubc14\ud2b8\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uadf8\uac00 \uc774\ub048 \uc5f0\uad6c\ud300\uc758 \uc2dc\uc2a4\ud15c\uc5d0 \ucef4\ud4e8\ud130 \ub9c8\uc6b0\uc2a4 \uac19\uc740 \ucd08\uae30 \ud654\uba74 \uc870\uc791 \ub3c4\uad6c\uac00 \ud3ec\ud568\ub418\uc5b4 \uc788\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud558\uc9c0\ub9cc \ub2f9\uc2dc\uc758 \uad6c\uc0c1\uc740 \ucc45\uc0c1 \uc704\uc758 \ub3c4\uad6c \ud558\ub098\uc5d0\uc11c \ub05d\ub098\uc9c0 \uc54a\uc558\ub2e4. \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\ub97c \ud1b5\ud574 \ud568\uaed8 \uc77c\ud558\ub294 \ubc29\uc2dd\uae4c\uc9c0 \ubcf4\uc5ec\uc8fc\ub824 \ud588\ub2e4. \uc5e5\uac94\ubc14\ud2b8\ub294 \ubbf8\uad6d SRI\uc758 \uc5f0\uad6c\uc18c\uc5d0\uc11c \uc0ac\ub78c\uc758 \uc9c0\uc801 \ud65c\ub3d9\uc744 \ub3d5\ub294 \uc2dc\uc2a4\ud15c\uc744 \uc5f0\uad6c\ud588\ub2e4. \uc5ec\ub7ec \uc0ac\uc6a9\uc790\uac00 \ud654\uba74 \uc55e\uc5d0\uc11c \uc815\ubcf4\ub97c \ub2e4\ub8e8\uba70 \ubb38\uc81c\ub97c \ud568\uaed8 \ud574\uacb0\ud558\ub294 \ubaa8\uc2b5\uc774 \uadf8 \uad6c\uc0c1\uc5d0 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uadf8\uc758 \ud300\uc774 \uac1c\ubc1c\ud55c NLS\uc5d0\ub294 \ud611\uc5c5 \uc18c\ud504\ud2b8\uc6e8\uc5b4\uc640 \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8, \ucd08\uae30 \ud654\uba74 \uc778\ud130\ud398\uc774\uc2a4 \uc694\uc18c\uac00 \ud568\uaed8 \ud3ec\ud568\ub418\uc5c8\ub2e4. \ud558\uc774\ud37c\ud14d\uc2a4\ud2b8\ub294 \uc815\ubcf4\ub97c \uc5f0\uacb0\ud574 \ub530\ub77c\uac00\uac8c \ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uc774\ud574\ud558\uba74 \ub41c\ub2e4. \uc5b4\ub824\uc6b4 \uae30\uc220 \uc774\ub984\uc744 \uc804\ubd80 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc624\ub298 \uc6b0\ub9ac\uac00 \ucef4\ud4e8\ud130\uc5d0\uc11c \ud558\ub294 \uc77c\ub3c4 \ud55c \uac00\uc9c0 \ub3d9\uc791\ub9cc\uc73c\ub85c \uc774\ub8e8\uc5b4\uc9c0\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc0c1\uc744 \uac00\ub9ac\ud0a4\uace0, \ub2e4\ub978 \uc815\ubcf4\ub85c \uc774\ub3d9\ud558\uace0, \ub2e4\ub978 \uc0ac\ub78c\uacfc \ub0b4\uc6a9\uc744 \ub098\ub208\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uadf8\ub7f0 \ud070 \uc791\uc5c5\uc744 \ub3d5\ub294 \ud55c \ubd80\ubd84\uc774\uc5c8\ub2e4. 1968\ub144 \uc5e5\uac94\ubc14\ud2b8\uc640 \uc5f0\uad6c\ud300\uc740 \ucef4\ud4e8\ud130 \ud559\ud68c\uc5d0\uc11c \uc2dc\uc2a4\ud15c\uc744 \uc2dc\uc5f0\ud588\ub2e4. \ub4a4\uc5d0 \uc774 \ubc1c\ud45c\ub294 \u2018\ubaa8\ub4e0 \ub370\ubaa8\uc758 \uc5b4\uba38\ub2c8\u2019\ub77c\ub294 \ubcc4\uba85\uc73c\ub85c \ub110\ub9ac \uc54c\ub824\uc84c\ub2e4. \uc774\ub984\uc774 \uac70\ucc3d\ud574\uc11c \ubaa8\ub4e0 \ud604\ub300 \uae30\uc220\uc774 \uadf8\ub0a0 \uc644\uc131\ub418\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc911\uc694\ud55c \uac83\uc740 \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\uc640 \uc0c1\ud638\uc791\uc6a9\ud558\ub294 \uc5ec\ub7ec \uc544\uc774\ub514\uc5b4\ub97c \uc791\ub3d9\ud558\ub294 \uc2dc\uc2a4\ud15c\uc73c\ub85c \ubcf4\uc5ec\uc8fc\uc5c8\ub2e4\ub294 \uc810\uc774\ub2e4. \uc778\ud130\ub137 \uba85\uc608\uc758 \uc804\ub2f9\uc740 \uc5e5\uac94\ubc14\ud2b8\uac00 \ub9c8\uc6b0\uc2a4\ub97c \ube44\ub86f\ud55c \uc5ec\ub7ec \ud2b9\ud5c8\ub3c4 \ubcf4\uc720\ud588\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub2e4\ub9cc \uadf8\uc758 \uc791\uc5c5\uc744 \uc791\uc740 \uc7a5\uce58 \ud558\ub098\uc758 \ubc1c\uba85\uc73c\ub85c\ub9cc \uc904\uc774\uba74, \ud611\uc5c5\uacfc \uc815\ubcf4 \uc5f0\uacb0\uc5d0 \uad00\ud55c \uad6c\uc0c1\uc774 \ubc30\uacbd\uc73c\ub85c \ubb3c\ub7ec\ub09c\ub2e4. \ub9c8\uc6b0\uc2a4\ub294 \uc0ac\ub78c\uc758 \uc190\uacfc \ud654\uba74 \uc0ac\uc774\ub97c \uc5f0\uacb0\ud558\ub294 \ub3c4\uad6c\ub2e4. \ub108\ubb34 \uc775\uc219\ud574\uc9c4 \ub355\ubd84\uc5d0 \ud3c9\uc18c\uc5d0\ub294 \uadf8 \uad00\uacc4\ub97c \ud2b9\ubcc4\ud788 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294\ub2e4. \ud3b8\ud558\uac8c \uc4f0\uc774\ub294 \ub3c4\uad6c\uc77c\uc218\ub85d \uc0ac\uc6a9 \uc911\uc5d0\ub294 \uc874\uc7ac\ub97c \ub35c \uc758\uc2dd\ud558\uac8c \ub41c\ub2e4. \uc61b \ucef4\ud4e8\ud130\ub97c \ubcfc \ub54c \ud070 \ubcf8\uccb4\uc640 \ud654\uba74\uc5d0 \uba3c\uc800 \ub208\uc774 \uac00\uc9c0\ub9cc, \uc791\uc740 \uc785\ub825 \ub3c4\uad6c\ub3c4 \ud568\uaed8 \uc0b4\ud3b4\ubcfc \ub9cc\ud558\ub2e4. \uc0ac\uc6a9\uc790\uac00 \uc5b4\ub5a4 \ub3d9\uc791\uc73c\ub85c \ucef4\ud4e8\ud130\uc5d0 \uc758\uc0ac\ub97c \uc804\ud588\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc8fc\uae30 \ub54c\ubb38\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \ub9c8\uc6b0\uc2a4\ub85c \ucc3d \ud558\ub098\ub97c \uc62e\uae30\uac70\ub098 \ubb38\uc11c\ub97c \uac00\ub9ac\ud0ac \ub54c \uc7a0\uae50 \ub5a0\uc62c\ub824 \ubcf4\uc790. \uc774 \uc791\uc740 \uc6c0\uc9c1\uc784\uc5d0\ub3c4 \uc0ac\ub78c\ub4e4\uc774 \ucef4\ud4e8\ud130\uc640 \uc77c\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafb8\ub824\ub358 \uae34 \uad6c\uc0c1\uc774 \uc774\uc5b4\uc838 \uc788\ub2e4."}, {"id": "python-comedy-name", "title": "\ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \ucf54\ubbf8\ub514\uc5d0\uc11c \uc654\ub2e4", "summary": "\ucef4\ud4e8\ud130 \uc5b8\uc5b4\uc758 \uc774\ub984\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4.", "category": "computing", "category_title": "Computing", "subcategory": "Programming", "url": "stories/python-comedy-name/index.html", "image": "media/python-comedy-name.jpg", "alt": "\ubb34\ub300 \ucee4\ud2bc\uc774 \ubcf4\uc774\ub294 \uc61b \ud154\ub808\ube44\uc804\uacfc \ube48 \ub300\ubcf8\uc758 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc740 \ucf54\ubbf8\ub514\uc5d0\uc11c \uc654\ub2e4 \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\uc758 \uc774\ub984\uc5d0 \ub0a8\uc740 \uac1c\ubc1c\uc790\uc758 \ucde8\ud5a5 \ucef4\ud4e8\ud130 \uc5b8\uc5b4\uc758 \uc774\ub984\uc744 \ub530\ub77c\uac00\ub2e4 \ubcf4\uba74 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc744 \ub9cc\ub098\uac8c \ub429\ub2c8\ub2e4. Programming \ucef4\ud4e8\ud305 \ud30c\uc774\uc36c\uc774\ub77c\ub294 \uc774\ub984\uc744 \ucc98\uc74c \ub4e4\uc73c\uba74 \ubc40\uc744 \ub5a0\uc62c\ub9ac\uae30 \uc27d\ub2e4. \uc601\uc5b4\ub85c\ub3c4 \ud070 \ubc40\uc744 \uac00\ub9ac\ud0a4\ub294 \ub9d0\uc774\ub2e4. \ucef4\ud4e8\ud130\ub97c \uc798 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc774\ub77c\ub3c4 \uc5b4\ub514\uc120\uac00 \ud55c \ubc88\ucbe4 \ub4e4\uc5b4\ubcf8 \uc774\ub984\uc77c \uc218 \uc788\ub2e4. \uadf8\ub7f0\ub370 \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4 Python\uc758 \uacf5\uc2dd FAQ\ub294 \uc774\ub984\uc758 \ucd9c\ubc1c\uc810\uc744 \uc870\uae08 \ub2e4\ub974\uac8c \uc124\uba85\ud55c\ub2e4. \uac1c\ubc1c\uc790 \uadc0\ub3c4 \ud310 \ub85c\uc12c\uc774 \uc77d\uace0 \uc788\ub358 \uc601\uad6d \ucf54\ubbf8\ub514 \ud504\ub85c\uadf8\ub7a8\uc758 \ub300\ubcf8\uc5d0\uc11c \uac00\uc838\uc654\ub2e4\ub294 \uac83\uc774\ub2e4. \ud504\ub85c\uadf8\ub7a8\uc758 \uc774\ub984\uc740 \u300c\ubaac\ud2f0 \ud30c\uc774\uc120\uc758 \ud50c\ub77c\uc789 \uc11c\ucee4\uc2a4\u300d\uc600\ub2e4. \ucef4\ud4e8\ud130 \uc5b8\uc5b4 \uc774\ub984\uc744 \ub530\ub77c\uc654\ub294\ub370 \uac11\uc790\uae30 \ud154\ub808\ube44\uc804\uc758 \ucf54\ubbf8\ub514 \ubb34\ub300\uac00 \ub098\ud0c0\ub09c\ub2e4. \uacf5\uc2dd \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ud310 \ub85c\uc12c\uc740 \ud30c\uc774\uc36c\uc744 \uad6c\ud604\ud558\ub358 \ubb34\ub835 \uadf8 \ucf54\ubbf8\ub514\uc758 \ucd9c\ud310\ub41c \ub300\ubcf8\uc744 \uc77d\uace0 \uc788\uc5c8\ub2e4. \uc0c8 \uc5b8\uc5b4\uc5d0\ub294 \uc9e7\uace0 \ub3c5\ud2b9\ud558\uba70 \uc870\uae08\uc740 \uc2e0\ube44\ub85c\uc6b4 \ub290\ub08c\uc758 \uc774\ub984\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud588\ub2e4. \uadf8\ub798\uc11c Python\uc774\ub77c\ub294 \uc774\ub984\uc744 \uace8\ub790\ub2e4. \ubaa8\ub4e0 \uc774\ub984\uc774 \uae30\ub2a5\uc744 \uc904\uc5ec \ubd99\uc778 \uc57d\uc790\ub098 \uae30\uc220 \uc6a9\uc5b4\uc5d0\uc11c \ub098\uc624\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub9cc\ub4dc\ub294 \uc0ac\ub78c\uc774 \uc990\uae30\ub358 \ubb38\ud654\uac00 \uc774\ub984\uc758 \uc7ac\ub8cc\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4. \uc5ec\uae30\uc11c \ucf54\ubbf8\ub514\uac00 \ud504\ub85c\uadf8\ub798\ubc0d\uc758 \uc6d0\ub9ac\ub97c \uacb0\uc815\ud588\ub2e4\uace0 \uc124\uba85\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc9c0\uae08 \ud655\uc778\ud560 \uc218 \uc788\ub294 \uac83\uc740 \uc774\ub984\uc744 \uc815\ud55c \uc0ac\uc5f0\uc774\ub2e4. \uc9e7\uc740 \uc774\ub984 \ud558\ub098\uc5d0\ub3c4 \uae30\uc220 \ubc16\uc758 \uacbd\ud5d8\uc774 \ub4e4\uc5b4\uac08 \uc790\ub9ac\uac00 \uc788\uc5c8\ub2e4. \ud765\ubbf8\ub85c\uc6b4 \uac83\uc740 \uc774 \uc0ac\uc5f0\uc774 \ub5a0\ub3c4\ub294 \uc18c\ubb38\uc73c\ub85c\ub9cc \uc804\ud574\uc9c0\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uacf5\uc2dd \uc9c8\ubb38\uacfc \ub2f5\ubcc0 \ubaa9\ub85d\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4\ub294 \uc810\uc774\ub2e4. \uc774\ub984\uc758 \uc720\ub798\ub97c \ubb3b\ub294 \uc9c8\ubb38 \ub2e4\uc74c\uc5d0\ub294 \uadf8 \ucf54\ubbf8\ub514\ub97c \uaf2d \uc88b\uc544\ud574\uc57c \ud558\ub294\uc9c0\ub3c4 \ubb3b\ub294\ub2e4. \ub2f5\ubcc0\ub3c4 \uac00\ubccd\ub2e4. \ubc18\ub4dc\uc2dc \uc88b\uc544\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4\ub294 \ucde8\uc9c0\ub85c \uc9e7\uc740 \ub18d\ub2f4\uc744 \ub367\ubd99\uc778\ub2e4. \uae30\uc220\uc744 \uc124\uba85\ud558\ub294 \ubb38\uc11c \uc548\uc5d0\uc11c\ub3c4 \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\uc758 \ub9d0\ud22c\uc640 \ucde8\ud5a5\uc774 \uc7a0\uae50 \ub4dc\ub7ec\ub098\ub294 \ub300\ubaa9\uc774\ub2e4. \ubb3c\ub860 \ud504\ub85c\uadf8\ub7a8\uc744 \uc4f0\uae30 \uc704\ud574 \ucf54\ubbf8\ub514\ub97c \ubcf4\uc544\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub984\uc758 \ubc30\uacbd\uc744 \ubab0\ub77c\ub3c4 \ub3c4\uad6c\ub294 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub0af\uc124\uace0 \uc804\ubb38\uc801\uc73c\ub85c \ubcf4\uc774\ub358 \uc774\ub984\uc5d0 \uc0dd\ud65c\uc758 \uc791\uc740 \ub2e8\uc11c\uac00 \uc0dd\uae34\ub2e4. \ud504\ub85c\uadf8\ub798\ubc0d \uc5b8\uc5b4\ub294 \ucef4\ud4e8\ud130\uc5d0\uac8c \ud560 \uc77c\uc744 \ud45c\ud604\ud558\ub294 \ub3c4\uad6c\ub2e4. \ucc98\uc74c \uc811\ud558\uba74 \ubb38\ubc95\uacfc \uae30\ud638\uac00 \uba3c\uc800 \ubcf4\uc5ec \uc5b4\ub835\uac8c \ub290\uaef4\uc9c8 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uadf8 \ub3c4\uad6c\ub97c \ub9cc\ub4e0 \uc0ac\ub78c\ub4e4\ub3c4 \ucc45\uc744 \uc77d\uace0 \ud154\ub808\ube44\uc804\uc744 \ubcf4\uba70 \uc774\ub984\uc744 \uace8\ub790\ub2e4. \uc774\uc57c\uae30\ub97c \uc548\ub2e4\uace0 \uace7\ubc14\ub85c \ucf54\ub4dc\ub97c \uc4f8 \uc218 \uc788\uac8c \ub418\uc9c0\ub294 \uc54a\ub294\ub2e4. \uadf8\ub7f4 \ud544\uc694\ub3c4 \uc5c6\ub2e4. \uc774\ubc88\uc5d0\ub294 \uae30\uc220\uc758 \uc0ac\uc6a9\ubc95\ubcf4\ub2e4, \uc775\uc219\ud55c \uc774\ub984 \ud558\ub098\uac00 \ub9cc\ub4e4\uc5b4\uc9c4 \uacfc\uc815\uc744 \uad6c\uacbd\ud558\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \ud30c\uc774\uc36c\uc774\ub77c\ub294 \ub9d0\uc744 \ub9cc\ub098\uba74 \ubc40 \uc606\uc5d0 \uc791\uc740 \ucf54\ubbf8\ub514 \ubb34\ub300\ub3c4 \ud568\uaed8 \ub5a0\uc62c\ub824 \ubcf4\uc790. \ucef4\ud4e8\ud130 \uc138\uacc4\uc758 \uc774\ub984\uc5d0\ub3c4 \ub204\uad70\uac00 \uc7ac\ubbf8\uc788\uac8c \uc77d\ub358 \ub300\ubcf8\uc758 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub2e4."}, {"id": "banknote-plate-fifty-yang", "title": "\ub3c8\uc744 \ub9cc\ub4e4\ub358 \ub098\ubb34\ud310\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc558\uc744\uae4c", "summary": "\uc22b\uc790\uc640 \uae00\uc790\uac00 \ub0a8\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc5d0\uc11c \uc885\uc774\ub3c8\uc758 \ub4b7\ubaa8\uc2b5\uc744 \ub9cc\ub0a9\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Money", "url": "stories/banknote-plate-fifty-yang/index.html", "image": "media/banknote-plate-fifty-yang.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc9c0\ud3d0\uc6d0\ud310 \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ub3c8\uc744 \ub9cc\ub4e4\ub358 \ub098\ubb34\ud310\uc5d0\ub294 \ubb34\uc5c7\uc774 \ub0a8\uc558\uc744\uae4c \uc9c0\ud3d0 \ud55c \uc7a5\ubcf4\ub2e4 \uc55e\uc5d0 \uc788\uc5c8\ub358 \ubb3c\uac74 \uc22b\uc790\uc640 \uae00\uc790\uac00 \ub0a8\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc5d0\uc11c \uc885\uc774\ub3c8\uc758 \ub4b7\ubaa8\uc2b5\uc744 \ub9cc\ub0a9\ub2c8\ub2e4. Money \uae08\uc735 \ub0a1\uc740 \uc9c1\uc0ac\uac01\ud615 \ub098\ubb34\ud310\uc774 \uc788\ub2e4. \uac00\uc6b4\ub370\ub294 \uae38\uac8c \ud30c\uc600\uace0 \uac00\uc7a5\uc790\ub9ac\uc5d0\ub294 \uc791\uc740 \uae00\uc790\uc640 \ubb34\ub2ac\uac00 \ub0a8\uc544 \uc788\ub2e4. \ucc98\uc74c \ubcf4\uba74 \uc0c1\uc790\uc758 \ubd80\ud488 \uac19\uae30\ub3c4 \ud558\ub2e4. \uadf8\ub7f0\ub370 \ubc15\ubb3c\uad00\uc774 \ubd99\uc778 \uc774\ub984\uc740 \uc9c0\ud3d0\uc6d0\ud310\uc774\ub2e4. \ub3c8\uc774\ub77c\uace0 \ud558\uba74 \uc9c0\uac11 \uc18d \uc885\uc774\ub098 \ub3d9\uc804\uc744 \ub5a0\uc62c\ub9ac\uc9c0\ub9cc, \uc774\uac83\uc740 \uadf8 \ub3c8\uc744 \ub9cc\ub4dc\ub294 \ucabd\uc5d0 \uc788\ub358 \ubb3c\uac74\uc774\ub2e4. \uc644\uc131\ub41c \uc9c0\ud3d0\uc5d0\uc11c \ud55c \uac78\uc74c \ub4a4\ub85c \ubb3c\ub7ec\uc11c\ub2c8 \ud3c9\uc18c\uc5d0\ub294 \ubcf4\uc9c0 \ubabb\ud558\ub358 \ubb3c\uac74\uc774 \ub098\uc628\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc758 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc6d0\ud310 \uc704\ucabd\uc5d0\ub294 TAI WHAN SHOU, \uc544\ub798\ucabd\uc5d0\ub294 FIFTY YANG\uc774\ub77c\ub294 \uae00\uc790\uac00 \uc788\ub2e4. \uc544\ub798 \ubb38\uad6c\uc5d0\ub294 \uc624\uc2ed \uc591\uc774\ub77c\ub294 \uc561\uba74\uc744 \uc601\uc5b4\ub85c \ub098\ud0c0\ub0b8 \ud45c\ud604\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ub124 \uadc0\ud241\uc774\uc5d0\ub294 \ub465\uadfc \uad6c\uba4d \uc548\uc5d0 \uc624\uc2ed\uacfc 50\uc774\ub77c\ub294 \uae00\uc790\ub3c4 \ub0a8\uc544 \uc788\ub2e4\uace0 \ud55c\ub2e4. \uac19\uc740 \uc218\uac00 \uae00\uc790\uc640 \uc22b\uc790\ub85c \uac70\ub4ed \ub098\ud0c0\ub098\ub294 \uac83\uc774\ub2e4. \uc791\uc740 \uc7a5\uc2dd\uc73c\ub85c\ub9cc \ubcf4\uc774\ub358 \uc790\ub9ac\uc5d0 \ub3c8\uc758 \uae08\uc561\uc744 \uac00\ub9ac\ud0a4\ub294 \uc815\ubcf4\uac00 \ub4e4\uc5b4 \uc788\uc5c8\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c \uba3c\uc800 \ub208\uc5d0 \ub4e4\uc5b4\uc624\ub294 \ubd80\ubd84\uc740 \uac00\uc6b4\ub370\uc758 \uae38\ucb49\ud55c \ud648\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \uc8fc\ubcc0\uc73c\ub85c \ub369\uad74 \ubaa8\uc591\uc758 \ub2f9\ucd08\ubb38\uc774 \ub458\ub7ec\uc838 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ube44\uc5b4 \uc788\ub294 \uacf5\uac04\uacfc \ucd18\ucd18\ud55c \ubb34\ub2ac\uac00 \ud55c \ud310 \uc548\uc5d0\uc11c \ub098\ub25c\ub2e4. \ub2e4\ub9cc \uc774 \ud648\uc5d0 \uc5b4\ub5a4 \ubd80\ud488\uc774 \ub4e4\uc5b4\uac14\ub294\uc9c0, \uc774 \uc6d0\ud310\uc73c\ub85c \uc2e4\uc81c \uc5bc\ub9c8\ub9cc\ud07c\uc758 \uc9c0\ud3d0\ub97c \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uae4c\uc9c0\ub294 \ud574\ub2f9 \uc124\uba85\uc73c\ub85c \uc54c \uc218 \uc5c6\ub2e4. \uc775\uc219\ud55c \uc778\uc1c4 \uacfc\uc815\uc744 \uac00\uc838\uc640 \ube48\uce78\uc744 \ucc44\uc6b0\uae30\ubcf4\ub2e4, \uc9c0\uae08 \ub0a8\uc544 \uc788\ub294 \ubaa8\uc591\uc5d0\uc11c \uc774\uc57c\uae30\ub97c \uc2dc\uc791\ud574 \ubcf4\uc790. \uc18c\uc7a5\ud488 \uc815\ubcf4\uc5d0 \uc801\ud78c \uac00\ub85c \uae38\uc774\ub294 16.3\uc13c\ud2f0\ubbf8\ud130\ub2e4. \ud654\uba74\uc5d0\uc11c \ud06c\uac8c \ubcf4\uba74 \ubb35\uc9c1\ud55c \ud310\ucc98\ub7fc \ub290\uaef4\uc838\ub3c4 \uc2e4\uc81c \ud06c\uae30\ub97c \uac00\ub2a0\ud558\uba74 \uc190 \uac00\uae4c\uc6b4 \ubb3c\uac74\uc774 \ub41c\ub2e4. \ub3c8\uc758 \uc5ed\uc0ac\uac00 \uaf2d \uac70\ub300\ud55c \uae08\uace0\uc5d0\uc11c\ub9cc \uc2dc\uc791\ub418\ub294 \uac83\uc740 \uc544\ub2cc \uc148\uc774\ub2e4. \uc774 \uc6d0\ud310\uc744 \ubcf4\uace0 \ub098\uba74 \uc9c0\ud3d0 \uc704 \uc22b\uc790\ub3c4 \uc870\uae08 \ub2e4\ub974\uac8c \ubcf4\uc778\ub2e4. \uc885\uc774\uc5d0 \ub098\ud0c0\ub09c \uacb0\uacfc\ub9cc \uc788\uc5c8\ub358 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\ubcf4\ub2e4 \uc55e\uc11c \uae00\uc790\uc640 \ubb34\ub2ac\ub97c \ub9c8\ub828\ud558\ub294 \ubb3c\uac74\uc774 \uc788\uc5c8\ub2e4. \uc624\ub298\uc740 \ub3c8\uc744 \uc4f0\ub294 \ub300\uc2e0 \ub3c8\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \uc804\uc758 \ud55c \uc7a5\uba74\uc744 \ub4e4\uc5ec\ub2e4\ubcf8 \uac83\uc774\ub2e4."}, {"id": "troy-ounce-weight", "title": "\uae08 \ud55c \uc628\uc2a4\uc640 \ubcf4\ud1b5 \ud55c \uc628\uc2a4\ub294 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4", "summary": "\uac19\uc740 \uc628\uc2a4\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc18d\uc758 \ubb34\uac8c\ub97c \uc77d\uc744 \ub54c \ucc59\uae38 \uc791\uc740 \ucc28\uc774\uc785\ub2c8\ub2e4.", "category": "finance", "category_title": "Finance", "subcategory": "Investment", "url": "stories/troy-ounce-weight/index.html", "image": "media/troy-ounce-weight.jpg", "alt": "\uc22b\uc790\ub098 \uc0c1\ud45c\uac00 \uc5c6\ub294 \uae08\ube5b \ub9c9\ub300\uc640 \uc800\uc6b8, \ucd94\ub97c \uadf8\ub9b0 \uc124\uba85\uc6a9 AI \uc0bd\ud654", "text": "\uae08 \ud55c \uc628\uc2a4\uc640 \ubcf4\ud1b5 \ud55c \uc628\uc2a4\ub294 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4 \uadc0\uae08\uc18d\uc5d0\uc11c \ub9cc\ub098\ub294 \ud2b8\ub85c\uc774\uc628\uc2a4 \uc774\uc57c\uae30 \uac19\uc740 \uc628\uc2a4\ub77c\ub294 \ub9d0 \ub4a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uae08\uc18d\uc758 \ubb34\uac8c\ub97c \uc77d\uc744 \ub54c \ucc59\uae38 \uc791\uc740 \ucc28\uc774\uc785\ub2c8\ub2e4. Investment \uae08\uc735 \uae08\uc774\ub098 \uc740\uc758 \ubb34\uac8c\ub97c \uc124\uba85\ud558\ub294 \uae00\uc5d0\uc11c\ub294 \uc628\uc2a4\ub77c\ub294 \ub2e8\uc704\ub97c \uc790\uc8fc \ub9cc\ub09c\ub2e4. \ub2e4\ub978 \ubb3c\uac74\uc758 \ubb34\uac8c\uc5d0\uc11c\ub3c4 \ubcf8 \uc774\ub984\uc774\ub77c \uc775\uc219\ud558\uac8c \uc9c0\ub098\uce58\uae30 \uc27d\ub2e4. \uadf8\ub7f0\ub370 \uc5ec\uae30\uc5d0\ub294 \ud55c \uac00\uc9c0 \ud655\uc778\ud560 \uac83\uc774 \uc788\ub2e4. \uadc0\uae08\uc18d\uc5d0 \ud754\ud788 \uc4f0\ub294 \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc77c\ubc18\uc801\uc778 \uc628\uc2a4\uc640 \ubb34\uac8c\uac00 \ub2e4\ub974\ub2e4. \uac19\uc740 \uc774\ub984\uc758 \ub4b7\ubd80\ubd84\ub9cc \ubcf4\uace0 \uac19\uc740 \uc591\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ucc28\uc774\uac00 \uc0dd\uae34\ub2e4. \uc601\uad6d \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 \uae08\uacfc \uc740 \uac19\uc740 \uadc0\uae08\uc18d\uc774 \ubcf4\ud1b5 \ud2b8\ub85c\uc774\uc628\uc2a4\ub85c \uce21\uc815\ub41c\ub2e4\uace0 \uc548\ub0b4\ud55c\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc124\uba85\uc5d0\uc11c \ud55c \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 31.1035\uadf8\ub7a8\uc774\ub2e4. \ubcf4\ud1b5 \uc628\uc2a4\ub77c\uace0 \ubd80\ub974\ub294 \uc544\ubcf4\uc544\ub4c0\ud3ec\uc544 \uc628\uc2a4\ub294 \uc57d 28.35\uadf8\ub7a8\uc774\ub2e4. \uc18c\uc218\uc810 \uc544\ub798\ub97c \ubaa8\ub450 \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \uc55e\ucabd\uc740 \uc57d 31.1\uadf8\ub7a8\uc774\ub77c\ub294 \uc815\ub3c4\ub9cc \uae30\uc5b5\ud574\ub3c4 \ub458\uc774 \ub2e4\ub974\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\ub2e4. \ub450 \uc218\ub97c \ub098\ub780\ud788 \ub193\uc73c\uba74 \ud2b8\ub85c\uc774\uc628\uc2a4 \ucabd\uc774 \uc870\uae08 \ub354 \ubb34\uac81\ub2e4. \uc628\uc2a4\ub77c\ub294 \ub2e8\uc5b4\uac00 \uac19\ub2e4\uace0 \ud574\uc11c \uc800\uc6b8\uc5d0 \uc62c\ub77c\uac00\ub294 \uc591\ub3c4 \ub611\uac19\uc9c0\ub294 \uc54a\uc740 \uac83\uc774\ub2e4. \ubb3c\ub860 \uc5b4\ub5a4 \uc0c1\ud488\uc774\ub098 \ubb38\uc11c\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub290 \uae30\uc900\uc744 \uc0ac\uc6a9\ud558\ub294\uc9c0\ub294 \ud45c\uc2dc\ub97c \ud655\uc778\ud574\uc57c \ud55c\ub2e4. \uadc0\uae08\uc18d\uc774\uba74 \uc124\uba85 \uc5c6\uc774 \ubb34\uc870\uac74 \uac19\uc740 \uc870\uac74\uc774\ub77c\uace0 \ub118\uaca8\uc9da\uae30\ubcf4\ub2e4, \ub2e8\uc704\uc758 \uc774\ub984\uc744 \ub05d\uae4c\uc9c0 \ubcf4\ub294 \ud3b8\uc774 \uc815\ud655\ud558\ub2e4. \ubb3c\uac74\uc758 \uc591\uc744 \ube44\uad50\ud560 \ub54c \uc22b\uc790\uac00 \ud06c\uac8c \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uadf8\ub7ec\ub098 \uc22b\uc790\ub294 \ub2e8\uc704\uc640 \ud568\uaed8 \uc77d\uc5b4\uc57c \ud55c\ub2e4. 1\uc774\ub77c\ub294 \uc218\uac00 \uac19\uc544\ub3c4 \ubb34\uc5c7\uc744 \ud558\ub098\ub85c \uc138\ub294\uc9c0\uac00 \ub2e4\ub974\uba74 \uc591\uc774 \ub2ec\ub77c\uc9c4\ub2e4. \ud2b8\ub85c\uc774\uc628\uc2a4\ub294 \uc774\ub7f0 \ucc28\uc774\ub97c \ubcf4\uc5ec\uc8fc\ub294 \uc775\uc219\ud558\uc9c0 \uc54a\uc740 \uc608\ub2e4. \ud3c9\uc18c \uadf8\ub7a8\uc5d0 \uc775\uc219\ud55c \uc0ac\ub78c\uc740 \uc628\uc2a4\ub07c\ub9ac \uba3c\uc800 \ube44\uad50\ud558\uae30\ubcf4\ub2e4 \uadf8\ub7a8\uc73c\ub85c \ud480\uc5b4 \ubcf4\uba74 \uc774\ud574\uac00 \uc26c\uc6cc\uc9c4\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\ub3c4 \uadc0\uae08\uc18d \uac00\uaca9\uc774\ub098 \uc0c1\ud488\uc5d0\uc11c \uc628\uc2a4\ub97c \ub9d0\ud560 \ub54c \ubcf4\ud1b5 \ud2b8\ub85c\uc774\uc628\uc2a4\ub97c \ub73b\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uc774 \ub9d0\uc740 \uac00\uaca9 \uc804\ub9dd\uc774 \uc544\ub2c8\ub77c \ud45c\uc2dc\ub97c \uc77d\ub294 \ubc29\ubc95\uc5d0 \uad00\ud55c \uc548\ub0b4\ub2e4. \ubb34\uac8c\ub97c \uc548\ub2e4\uace0 \uac00\uce58\uc758 \ubcc0\ud654\uae4c\uc9c0 \uc54c \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uae08\uc18d\uc744 \uc9c1\uc811 \uac70\ub798\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc774\ub7f0 \ub2e8\uc704\ub294 \ub274\uc2a4\uc640 \uc804\uc2dc \uc124\uba85\uc5d0\uc11c \ub9cc\ub09c\ub2e4. \uadf8\ub54c \ub0af\uc120 \ub9d0\uc744 \ubaa8\ub450 \uacf5\ubd80\ud558\ub824\uace0 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \uac19\uc740 \uc628\uc2a4\uc5d0\ub3c4 \ub2e4\ub978 \uae30\uc900\uc774 \uc788\ub2e4\ub294 \uc0ac\uc2e4\ub9cc \ucc59\uaca8 \ub450\uba74 \ub41c\ub2e4. \uc5ec\ud589\uc9c0\uc5d0\uc11c \uc11c\ub85c \ub2e4\ub978 \ud06c\uae30\uc758 \ucef5\uc744 \ubaa8\ub450 \ud55c \uc794\uc774\ub77c\uace0 \ubd80\ub974\ub294 \uc0c1\ud669\uc744 \ub5a0\uc62c\ub824 \ubcf4\uc544\ub3c4 \uc88b\ub2e4. \uc774\ub984\uc744 \ub9de\ucd94\ub294 \uac83\uacfc \uc2e4\uc81c \uc591\uc744 \ub9de\ucd94\ub294 \uac83\uc740 \ubcc4\uac1c\uc758 \uc77c\uc774\ub2e4. \ub2e8\uc704\uc758 \uae30\uc900\uc740 \uadf8 \ucc28\uc774\ub97c \ubd84\uba85\ud788 \ud558\ub824\uace0 \ud544\uc694\ud558\ub2e4. \ub2e4\uc74c\uc5d0 \uae08 \ud55c \uc628\uc2a4\ub77c\ub294 \ud45c\ud604\uc744 \ub9cc\ub098\uba74 \uc22b\uc790 1 \uc606\uc758 \ub9d0\uc744 \uc7a0\uae50 \uc0b4\ud3b4\ubcf4\uc790. \uc791\uc740 \ub2e8\uc704\uc758 \uc774\ub984\uc774, \uc0dd\uac01\ubcf4\ub2e4 \uc911\uc694\ud55c \ubb34\uac8c\ub97c \uac00\uc9c0\uace0 \uc788\ub2e4."}, {"id": "bowl-sundial", "title": "\uadf8\ub987\ucc98\ub7fc \uc0dd\uae34 \ud574\uc2dc\uacc4\uc5d0\ub294 \ub450 \uc885\ub958\uc758 \uc120\uc774 \uc788\ub2e4", "summary": "\uc624\ubaa9\ud55c \ud574\uc2dc\uacc4 \uc548\uc744 \ubcf4\uba74 \uc5ec\ub7ec \uc120\uc774 \uad50\ucc28\ud569\ub2c8\ub2e4. \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc120\uc740 \uc544\ub2d9\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Engineering", "url": "stories/bowl-sundial/index.html", "image": "media/bowl-sundial.jpg", "alt": "\ubc1b\uce68 \uc704\uc5d0 \ub193\uc778 \uccad\ub3d9 \ubc18\uad6c\ud615 \uc559\ubd80\uc77c\uad6c\uc640 \uc548\ucabd \uc120, \uc601\uce68\uc774 \ubcf4\uc774\ub294 \uc0ac\uc9c4", "text": "\uadf8\ub987\ucc98\ub7fc \uc0dd\uae34 \ud574\uc2dc\uacc4\uc5d0\ub294 \ub450 \uc885\ub958\uc758 \uc120\uc774 \uc788\ub2e4 \uc559\ubd80\uc77c\uad6c \uc548\uc5d0\uc11c \uc2dc\uac04\uacfc \uacc4\uc808\uc744 \uc77d\ub294 \ubc29\ubc95 \uc624\ubaa9\ud55c \ud574\uc2dc\uacc4 \uc548\uc744 \ubcf4\uba74 \uc5ec\ub7ec \uc120\uc774 \uad50\ucc28\ud569\ub2c8\ub2e4. \ubaa8\ub450 \uac19\uc740 \uc77c\uc744 \ud558\ub294 \uc120\uc740 \uc544\ub2d9\ub2c8\ub2e4. Engineering \uacfc\ud559 \ubc15\ubb3c\uad00\uc5d0\uc11c \uc559\ubd80\uc77c\uad6c\ub97c \ubcf4\uba74 \uba3c\uc800 \uadf8\ub987 \uac19\ub2e4\ub294 \uc0dd\uac01\uc774 \ub4e0\ub2e4. \uac00\uc6b4\ub370\uc5d0\ub294 \ubc14\ub298\ucc98\ub7fc \uc0dd\uae34 \ubb3c\uac74\uc774 \ube44\uc2a4\ub4ec\ud788 \uc11c \uc788\uace0, \uc548\ucabd\uc5d0\ub294 \uc5ec\ub7ec \uc904\uc774 \uc0c8\uaca8\uc838 \uc788\ub2e4. \uc774\ub984\uc5d0\ub3c4 \uadf8 \ubaa8\uc2b5\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc559\ubd80\uc77c\uad6c\ub97c \uc1a5 \ubaa8\uc591\uc758 \ud574\uc2dc\uacc4\ub77c\ub294 \ub73b\uc73c\ub85c \uc124\uba85\ud55c\ub2e4. \uc775\uc219\ud55c \ub514\uc9c0\ud138\uc2dc\uacc4\ucc98\ub7fc \uc22b\uc790\uac00 \ucc28\ub840\ub85c \ubc14\ub00c\uc9c0\ub294 \uc54a\ub294\ub2e4. \ub300\uc2e0 \ube5b\uacfc \uadf8\ub9bc\uc790\uac00 \ud45c\uc2dc\ub97c \uc6c0\uc9c1\uc778\ub2e4. \uadf8\ub7f0\ub370 \uc548\ucabd\uc758 \uc120\uc740 \uc2dc\uac04\uc744 \ub098\ub204\uae30 \uc704\ud55c \uac83\ub9cc\uc740 \uc544\ub2c8\ub2e4. \uacc4\uc808\uc744 \uc54c\ub824\uc8fc\ub294 \uc120\ub3c4 \ud568\uaed8 \uc788\ub2e4. \uc559\ubd80\uc77c\uad6c\ub294 \ud574\uadf8\ub9bc\uc790\ub97c \ubc1b\ub294 \uc624\ubaa9\ud55c \uba74\uacfc, \uadf8\ub9bc\uc790\ub97c \ub9cc\ub4e4\uc5b4 \ub0b4\ub294 \ubc14\ub298\ub85c \uc774\ub8e8\uc5b4\uc9c4\ub2e4. \ub3c4\uad6c\ub97c \ubcfc \ub54c\ub294 \ubc14\ub298\ub9cc\ud07c \uadf8\ub9bc\uc790\uac00 \uc5b4\ub514\uc5d0 \ub4dc\ub9ac\uc6cc\uc9c0\ub294\uc9c0\ub3c4 \uc911\uc694\ud558\ub2e4. \ubc15\ubb3c\uad00 \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0\uc11c\ub294 \uc548\ucabd \uba74\uc744 \uc2dc\ubc18, \ubc14\ub298\uc744 \uc601\uce68\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc5b4\ub824\uc6b4 \uc774\ub984\uc744 \uc678\uc6b0\uc9c0 \uc54a\uc544\ub3c4 \uc5ed\ud560\uc740 \ub098\ub204\uc5b4 \ubcfc \uc218 \uc788\ub2e4. \ud558\ub098\ub294 \uadf8\ub9bc\uc790\ub97c \ub9cc\ub4e4\uace0, \ub2e4\ub978 \ud558\ub098\ub294 \uadf8 \uadf8\ub9bc\uc790\ub97c \uc77d\ub294 \uc790\ub9ac\ub2e4. \ube5b\uc774 \ub4e4\uc5b4\uc624\ub294 \uc870\uac74\uc5d0 \ub530\ub77c \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\uac00 \ub193\uc774\ub294 \uc704\uce58\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uc548\ucabd\uc5d0 \uc0c8\uaca8 \ub454 \uc120\ub4e4\uc740 \uadf8 \uc704\uce58\ub97c \uadf8\ub0e5 \uc9c0\ub098\uac00\ub294 \ubaa8\uc591\uc774 \uc544\ub2c8\ub77c \uc815\ubcf4\ub85c \uc77d\uc744 \uc218 \uc788\uac8c \ud55c\ub2e4. \uc18c\uc7a5\ud488 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \uc2dc\uacc4 \uc548\uc5d0\ub294 \uc2dc\uac01\uc744 \ub098\ub204\ub294 \uc120\uacfc \uc808\uae30\ub97c \ub098\ud0c0\ub0b4\ub294 \uac00\ub85c\uc120\uc774 \uc788\ub2e4. \uac19\uc740 \uba74 \uc704\uc5d0 \ub450 \uc885\ub958\uc758 \uae30\uc900\uc744 \uacb9\uccd0 \ub454 \uac83\uc774\ub2e4. \uacc4\uc808\uc5d0 \ub530\ub77c \ud574\uadf8\ub9bc\uc790\uc758 \uae38\uc774\uac00 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ub3d9\uc9c0\uc640 \ud558\uc9c0\uc758 \uadf8\ub9bc\uc790\ub3c4 \uac19\uc740 \uc790\ub9ac\uc5d0 \ub193\uc774\uc9c0 \uc54a\ub294\ub2e4. \ubc15\ubb3c\uad00\uc740 \ub3d9\uc9c0\uc5d0\ub294 \uac00\uc7a5 \ubc14\uae65\ucabd \uacc4\uc808\uc120, \ud558\uc9c0\uc5d0\ub294 \uac00\uc7a5 \uc548\ucabd \uacc4\uc808\uc120\uc5d0 \uadf8\ub9bc\uc790\uac00 \uc704\uce58\ud55c\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub7ec\ub2c8 \ubc14\ub2e5\uc758 \uc120\uc744 \ubaa8\ub450 \ubcf5\uc7a1\ud55c \uc7a5\uc2dd\uc73c\ub85c \ubcfc \ud544\uc694\ub294 \uc5c6\ub2e4. \uc5b4\ub290 \ubc29\ud5a5\uc73c\ub85c \uc2dc\uac04\uc744 \uc77d\uace0 \uc5b4\ub5a4 \uc120\uc73c\ub85c \uacc4\uc808\uc744 \uc0b4\ud53c\ub294\uc9c0 \ub098\ub204\uc5b4 \ubcf4\uba74 \uc870\uae08 \uc815\ub9ac\uac00 \ub41c\ub2e4. \uc22b\uc790\uc640 \uace1\uc120\uc774 \ub9ce\uc740 \uc774\uc720\uac00 \uc788\ub294 \uc148\uc774\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \ud55c \uc7a5\ub9cc \ubcf4\uace0 \uc2e4\uc81c \uc2dc\uac04\uc744 \uc815\ud655\ud558\uac8c \uc77d\uc5b4 \ubcf4\ub824 \ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub193\uc778 \ubc29\ud5a5\uacfc \ube5b\uc758 \uc870\uac74\uc774 \ub9de\uc544\uc57c \ud558\ub294 \ub3c4\uad6c\ub2e4. \uc804\uc2dc\uc7a5\uc5d0\uc11c \ubcf4\ub294 \ubaa8\uc2b5\uacfc \uc2e4\uc81c\ub85c \uc2dc\uac04\uc744 \uc7ac\ub294 \uc0c1\ud669\uc740 \uad6c\ubd84\ud558\ub294 \ud3b8\uc774 \uc88b\ub2e4. \ubc15\ubb3c\uad00\uc740 \uc559\ubd80\uc77c\uad6c\uac00 \uc138\uc885\ub300\uc5d0 \ucc98\uc74c \ub9cc\ub4e4\uc5b4\uc838 \uc11c\uc6b8\uc758 \ud61c\uc815\uad50\uc640 \uc885\ubb18 \ub0a8\ucabd \uac70\ub9ac\ucc98\ub7fc \uc0ac\ub78c\uc774 \ub9ce\uc774 \ub2e4\ub2c8\ub294 \uacf3\uc5d0 \uc124\uce58\ub418\uc5c8\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uac1c\uc778\uc758 \uc791\uc740 \ubb3c\uac74\uc774 \uc544\ub2c8\ub77c \uae38\uc5d0\uc11c \uc2dc\uac04\uc744 \ub9cc\ub098\ub294 \ubc29\uc2dd\ub3c4 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4. \uc9c0\uae08\uc740 \uc8fc\uba38\ub2c8\uc758 \ud654\uba74\ub9cc \uc5f4\uc5b4\ub3c4 \uc2dc\uac04\uc744 \ud655\uc778\ud560 \uc218 \uc788\ub2e4. \uadf8\ub798\uc11c \ud558\ub098\uc758 \uc2dc\uacc4\ub97c \uc5ec\ub7ec \uc0ac\ub78c\uc774 \ubc14\ub77c\ubcf4\ub294 \ud48d\uacbd\uc774 \uc870\uae08 \ub0af\uc124\uac8c \ub290\uaef4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. \uc559\ubd80\uc77c\uad6c\ub97c \ub2e4\uc2dc \ubcf4\uba74 \uadf8\ub987 \uac19\uc740 \ubab8\uccb4 \uc548\uc5d0 \uadf8 \ud48d\uacbd\uc774 \ub4e4\uc5b4 \uc788\ub2e4. \ud574\ub97c \ubcf4\uace0 \ubc14\ub298\uc758 \uadf8\ub9bc\uc790\ub97c \ucc3e\uace0, \uc120\uc744 \ub530\ub77c \uc2dc\uac04\uc744 \uc77d\ub294 \uc0ac\ub78c\ub4e4\uc774\ub2e4. \ub2e4\uc74c\uc5d0 \uc774 \ud574\uc2dc\uacc4\ub97c \ub9cc\ub098\uba74 \ubc14\ub298\uacfc \uace1\uc120\uc744 \ub530\ub85c \ud55c\ubc88 \ubcf4\uc544\ub3c4 \uc88b\uaca0\ub2e4. \ubcf5\uc7a1\ud574 \ubcf4\uc774\ub358 \uc548\ucabd \uba74\uc774, \uc2dc\uac04\uacfc \uacc4\uc808\uc744 \ud568\uaed8 \ud3bc\uccd0 \ub193\uc740 \uc791\uc740 \uc9c0\ub3c4\ucc98\ub7fc \ubcf4\uc77c \uc218 \uc788\ub2e4."}, {"id": "elephant-ear-fan", "title": "\ucf54\ub07c\ub9ac\uac00 \uadc0\ub97c \ud754\ub4dc\ub294 \ub370\uc5d0\ub294 \uc774\uc720\uac00 \uc788\ub2e4", "summary": "\ub290\uae0b\ud558\uac8c \uadc0\ub97c \ud384\ub7ed\uc774\ub294 \ucf54\ub07c\ub9ac. \uadf8 \uc6c0\uc9c1\uc784\uc5d0\ub294 \ub4e3\ub294 \uc77c \ub9d0\uace0\ub3c4 \ub2e4\ub978 \uc5ed\ud560\uc774 \uc788\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/elephant-ear-fan/index.html", "image": "media/elephant-ear-fan.jpg", "alt": "\ub098\ubb34 \uadf8\ub298\uc5d0\uc11c \uadc0\ub97c \uc6c0\uc9c1\uc774\ub294 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ucf54\ub07c\ub9ac\uac00 \uadc0\ub97c \ud754\ub4dc\ub294 \ub370\uc5d0\ub294 \uc774\uc720\uac00 \uc788\ub2e4 \ucee4\ub2e4\ub780 \uadc0\uac00 \ubab8\uc758 \uc5f4\uc744 \uc2dd\ud788\ub294 \ubc29\ubc95 \ub290\uae0b\ud558\uac8c \uadc0\ub97c \ud384\ub7ed\uc774\ub294 \ucf54\ub07c\ub9ac. \uadf8 \uc6c0\uc9c1\uc784\uc5d0\ub294 \ub4e3\ub294 \uc77c \ub9d0\uace0\ub3c4 \ub2e4\ub978 \uc5ed\ud560\uc774 \uc788\uc2b5\ub2c8\ub2e4. Biology \uacfc\ud559 \ucf54\ub07c\ub9ac \uc601\uc0c1\uc744 \ubcf4\ub2e4 \ubcf4\uba74 \uadc0\uac00 \uc790\uafb8 \ub208\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \uc55e\uc73c\ub85c \ud55c \ubc88, \ub4a4\ub85c \ud55c \ubc88. \ubab8\uc740 \uac00\ub9cc\ud788 \uc788\ub294\ub370 \uadc0\ub9cc \ub290\uae0b\ud558\uac8c \uc6c0\uc9c1\uc778\ub2e4. \ucee4\ub2e4\ub780 \ubd80\ucc44 \ub450 \uac1c\ub97c \ub4e4\uace0 \uc788\ub294 \uac83 \uac19\ub2e4. \uc2e4\uc81c\ub85c \uadf8 \uadc0\ub294 \uc18c\ub9ac\ub97c \ub4e3\ub294 \uc77c \uc678\uc5d0 \ubab8\uc744 \uc2dd\ud788\ub294 \ub370\uc5d0\ub3c4 \uc4f0\uc778\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc758 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac \uc548\ub0b4\ub97c \uc77d\uc73c\uba74, \ud384\ub7ed\uc774\ub294 \uadc0 \uc548\ucabd\uc5d0 \uaf64 \ubc14\uc05c \uae38\uc774 \uc788\ub2e4\ub294 \uac83\uc744 \uc54c\uac8c \ub41c\ub2e4. \ud608\uad00\uc774\ub2e4. \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uc758 \uadc0\uc5d0\ub294 \ub9ce\uc740 \ud608\uad00\uc774 \uc788\ub2e4. \ub354\uc6b4 \ub0a0 \uadc0\ub97c \uc6c0\uc9c1\uc774\uba74 \uadf8 \uc548\uc744 \ud750\ub974\ub294 \ud53c\uac00 \uc2dd\uace0, \uc2dd\uc740 \ud53c\uac00 \ub2e4\uc2dc \ubab8\uc744 \ub3cc\uba74\uc11c \uccb4\uc628\uc744 \ub0ae\ucd94\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \ub3d9\ubb3c\uc6d0\uc740 \uc124\uba85\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \ubd80\ucc44\ub97c \ud754\ub4e4 \ub54c\ub294 \uc190\uc774 \ubc14\uc058\uc9c0\ub9cc, \ucf54\ub07c\ub9ac\ub294 \uadc0 \uc790\uccb4\ub97c \uc6c0\uc9c1\uc778\ub2e4. \ub530\ub73b\ud55c \ud53c\uac00 \uc9c0\ub098\ub294 \ub113\uc740 \uc790\ub9ac\ub97c \ubc14\ub78c\uc5d0 \ub0b4\uc5b4\ub193\ub294 \uc148\uc774\ub2e4. \uadf8\ub798\uc11c \uadc0\uc758 \uc6c0\uc9c1\uc784\uc744 \ubcf4\uace0 \uace7\ubc14\ub85c \uae30\ubd84\uc774\ub098 \uc131\uaca9\ub9cc \uc9d0\uc791\ud560 \uc77c\uc740 \uc544\ub2c8\ub2e4. \uadc0\ub294 \uac89\uc73c\ub85c \ubcf4\uc774\ub294 \ud06c\uae30\ub9cc\ud07c\uc774\ub098 \uc548\ucabd\uc758 \uad6c\uc870\ub3c4 \uc911\uc694\ud558\ub2e4. \ub113\uc801\ud55c \ubaa8\uc591\uacfc \ud608\uad00, \ud384\ub7ed\uc774\ub294 \ub3d9\uc791\uc774 \ud568\uaed8 \ubab8\uc758 \uc5f4\uc744 \ub2e4\ub8e8\ub294 \ub370 \uc4f0\uc778\ub2e4. \ucf54\ub07c\ub9ac\uc758 \ud53c\ubd80\ub294 \uc5b4\ub514\ub098 \ub611\uac19\uc774 \ub450\uaecd\uc9c0 \uc54a\ub2e4. \ub3d9\ubb3c\uc6d0\uc740 \ub4f1\ucc98\ub7fc \ub450\uaebc\uc6b4 \uacf3\uc774 \uc788\ub294 \ubc18\uba74, \uadc0 \uc548\ucabd\ucc98\ub7fc \uc544\uc8fc \uc587\uc740 \uacf3\ub3c4 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uba40\ub9ac\uc11c \ubcf8 \ucee4\ub2e4\ub780 \ubab8\uc5d0\ub3c4 \uc12c\uc138\ud55c \ubd80\ubd84\uc774 \uc11e\uc5ec \uc788\ub2e4. \ud53c\ubd80\ub294 \uc2e0\uacbd\uc774 \ud48d\ubd80\ud574 \ubbfc\uac10\ud558\ub2e4. \ucf54\ub07c\ub9ac\uac00 \ud759\uc774\ub098 \ubaa8\ub798, \uc9c4\ud759\uc744 \ubab8\uc5d0 \ub36e\ub294 \ud589\ub3d9\ub3c4 \ud587\ube5b\uacfc \ubc8c\ub808\ub85c\ubd80\ud130 \ud53c\ubd80\ub97c \ubcf4\ud638\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uadc0\ub97c \uc6c0\uc9c1\uc774\uace0 \ubab8\uc5d0 \ud759\uc744 \ubb3b\ud788\ub294 \ubaa8\uc2b5\uc740, \ub354\uc6b4 \ub0a0\uc758 \uc0dd\ud65c\uc744 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \ubcf4\uc5ec\uc900\ub2e4. \ub3d9\ubb3c\uc6d0 \uc548\ub0b4\uc5d0\ub294 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\uac00 \ud558\ub8e8 \uc911 \uac00\uc7a5 \ub354\uc6b4 \uc2dc\uac04\uc5d0 \uc26c\uac70\ub098 \ub0ae\uc7a0\uc744 \uc790\ub294 \uacbd\ud5a5\ub3c4 \ub098\uc628\ub2e4. \uadf8\ub298\uc5d0\uc11c \uc26c\ub294 \ubab8, \uc6c0\uc9c1\uc774\ub294 \uadc0, \ud53c\ubd80\uc5d0 \uc5b9\ud78c \ud759\uc774 \ud55c \uc7a5\uba74 \uc548\uc5d0 \ub193\uc778\ub2e4. \ub3d9\ubb3c\uc740 \ube68\ub9ac \ub2ec\ub9ac\uac70\ub098 \ud06c\uac8c \uc6b8 \ub54c\ub9cc \ubcfc\uac70\ub9ac\ub97c \uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc870\uc6a9\ud788 \uc11c \uc788\uc744 \ub54c\ub3c4 \ubab8\uc758 \uc791\uc740 \ubd80\ubd84\uc740 \uc77c\uc744 \ud558\uace0 \uc788\ub2e4. \uadc0\ub97c \ud55c\ubc88 \uc6c0\uc9c1\uc774\ub294 \ub370\uc5d0\ub3c4 \uc0dd\ud65c\uc758 \uc774\uc720\uac00 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ucf54\ub07c\ub9ac\ub97c \ub9cc\ub098\uba74 \uae34 \ucf54\ub97c \ubcf8 \ub4a4 \uadc0\uc5d0\ub3c4 \uc7a0\uae50 \ub208\uc744 \uc8fc\uc5b4 \ubcf4\uc790. \uc774 \uc774\uc57c\uae30\uac00 \ub2e4\ub8ec \uac83\uc740 \uc544\uc2dc\uc544\ucf54\ub07c\ub9ac\ub2e4. \uadc0\uc758 \ubaa8\uc591\uacfc \ud06c\uae30\ub97c \ub2e4\ub978 \ucf54\ub07c\ub9ac\uc640 \ube44\uad50\ud574 \ubcf4\ub294 \uac83\ub3c4 \uc7ac\ubbf8\uc788\uaca0\uc9c0\ub9cc, \uc6b0\uc120\uc740 \ud55c \ubc88\uc758 \ud384\ub7ed\uc784\uc744 \ucc9c\ucc9c\ud788 \ubcf4\ub294 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4. \ub290\uae0b\ud55c \uc624\ud6c4\ucc98\ub7fc \ubcf4\uc774\ub358 \uc7a5\uba74 \uc548\uc5d0\uc11c, \ucee4\ub2e4\ub780 \ubab8\uc740 \uc790\uae30 \ubc29\uc2dd\uc73c\ub85c \ub354\uc704\ub97c \uacac\ub514\uace0 \uc788\uc5c8\ub358 \uac83\uc774\ub2e4."}, {"id": "flamingo-pink-feathers", "title": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c", "summary": "\ubd84\ud64d\uc0c9 \uc0c8 \ud558\uba74 \ub5a0\uc624\ub974\ub294 \ud50c\ub77c\ubc0d\uace0. \ud558\uc9c0\ub9cc \uadf8 \uc0c9\uc740 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \uc644\uc131\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/flamingo-pink-feathers/index.html", "image": "media/flamingo-pink-feathers.jpg", "alt": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c \u2014 \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ud50c\ub77c\ubc0d\uace0\ub294 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \ubd84\ud64d\uc0c9\uc77c\uae4c \uc6b0\uc544\ud55c \uae43\ud138\uc5d0 \uc228\uc5b4 \uc788\ub294 \uc2dd\uc0ac\uc758 \ud754\uc801 \ubd84\ud64d\uc0c9 \uc0c8 \ud558\uba74 \ub5a0\uc624\ub974\ub294 \ud50c\ub77c\ubc0d\uace0. \ud558\uc9c0\ub9cc \uadf8 \uc0c9\uc740 \ud0dc\uc5b4\ub0a0 \ub54c\ubd80\ud130 \uc644\uc131\ub41c \uac83\uc774 \uc544\ub2d9\ub2c8\ub2e4. Biology \uacfc\ud559 \ud50c\ub77c\ubc0d\uace0\ub97c \uadf8\ub824 \ubcf4\ub77c\uace0 \ud558\uba74 \ubd84\ud64d\uc0c9\ubd80\ud130 \ucc3e\uac8c \ub41c\ub2e4. \uae34 \ub2e4\ub9ac\uc640 \uad7d\uc740 \ubaa9\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc, \uc0c9\uc744 \ube7c\ub193\uc73c\uba74 \uc5b4\uca50\uc9c0 \ub2e4\ub978 \uc0c8\ucc98\ub7fc \ub290\uaef4\uc9c4\ub2e4. \uadf8\ub7f0\ub370 \uc5b4\ub9b0 \ud50c\ub77c\ubc0d\uace0\ub294 \uc6b0\ub9ac\uac00 \ub5a0\uc62c\ub9ac\ub294 \uc120\uba85\ud55c \ubd84\ud64d\uc0c9\uacfc \ub2e4\ub974\ub2e4. \ud68c\uc0c9\ube5b\uc774\ub098 \ud770\ube5b\uc774 \ub3c4\ub294 \uc19c\ud138\ub85c \uc2dc\uc791\ud55c\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc5b4\ub978 \uc0c8\uc640 \ub611\uac19\uc740 \uc0c9\uc758 \uc791\uc740 \ubcf5\uc0ac\ubcf8\uc774 \ud0dc\uc5b4\ub098\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uadf8\ub807\ub2e4\uba74 \uc790\ub77c\uba74\uc11c \ubd84\ud64d\uc0c9\uc740 \uc5b4\ub514\uc5d0\uc11c \uc624\ub294 \uac83\uc77c\uae4c. \ub2f5\uc744 \ucc3e\uc73c\ub824\uba74 \uae43\ud138\ubcf4\ub2e4 \uba3c\uc800 \uba39\uc774\ub97c \ubcf4\uc544\uc57c \ud55c\ub2e4. \ud50c\ub77c\ubc0d\uace0\uac00 \uba39\ub294 \uc870\ub958\ub098 \uc791\uc740 \uac11\uac01\ub958 \ub4f1\uc5d0\ub294 \uce74\ub85c\ud2f0\ub178\uc774\ub4dc\ub77c\ub294 \uc0c9\uc18c\uac00 \ub4e4\uc5b4 \uc788\ub2e4. \uc870\uae08 \ub0af\uc120 \uc774\ub984\uc774\uc9c0\ub9cc \uc790\uc5f0\uc5d0\uc11c \uc5ec\ub7ec \ub178\ub791\u00b7\uc8fc\ud669\u00b7\ubd89\uc740\ube5b\uacfc \uad00\ub828\ub418\ub294 \uc0c9\uc18c \ubb34\ub9ac\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub294 \uba39\uc774\uc5d0\uc11c \uc5bb\uc740 \uc774\ub7f0 \uc131\ubd84\uc744 \ubab8 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud558\uace0, \uadf8 \uacb0\uacfc\uac00 \uae43\ud138\uc758 \uc0c9\uc5d0\ub3c4 \uc601\ud5a5\uc744 \uc900\ub2e4. \uba39\uc740 \uac83\uc744 \ub2e8\uc21c\ud788 \uae43\ud138 \ubc14\uae65\uc5d0 \ubb3b\ud788\ub294 \ubc29\uc2dd\uc740 \uc544\ub2c8\ub2e4. \ubab8\uc758 \uacfc\uc815\uc774 \uc788\uc5b4\uc57c \uba39\uc774\uc640 \uc0c8\uc758 \ubaa8\uc2b5\uc774 \uc5f0\uacb0\ub41c\ub2e4. \uadf8\ub798\uc11c \uc0c8\uc6b0\ub97c \uba39\uc5b4\uc11c \ubd84\ud64d\uc0c9\uc774\ub77c\ub294 \uc124\uba85\uc740 \uae30\uc5b5\ud558\uae30 \uc27d\uc9c0\ub9cc \uc870\uae08 \uc9e7\ub2e4. \ubaa8\ub4e0 \ud50c\ub77c\ubc0d\uace0\uac00 \uac19\uc740 \uba39\uc774\ub97c \uac19\uc740 \ube44\uc728\ub85c \uba39\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc0c9\uc18c\uc758 \uacbd\ub85c\ub3c4 \ud55c \uac00\uc9c0 \uc74c\uc2dd\uc73c\ub85c\ub9cc \uc124\uba85\ub418\uc9c0 \uc54a\ub294\ub2e4. \u5206\ud64d\uc0c9 \uae43\ud138\uc744 \uc774\ud574\ud558\ub824\uba74 \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c8\ub9cc \ubcfc \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0c8\uac00 \uba39\ub294 \uac83\ub3c4 \uc0b4\ud3b4\uc57c \ud55c\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc740 \uba39\uc774\uc758 \uc0c9\uc18c\ub97c \ubab8 \uc548\uc5d0\uc11c \ucc98\ub9ac\ud558\ub294 \uacfc\uc815\uc774 \uae43\ud138\uc758 \ubd84\ud64d\ube5b\uc73c\ub85c \uc774\uc5b4\uc9c4\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud50c\ub77c\ubc0d\uace0 \uc0ac\uc9c4\uc744 \uc5ec\ub7ec \uc7a5 \ub193\uace0 \ubcf4\uba74 \uc0c9\uc774 \ubaa8\ub450 \uac19\uc9c0 \uc54a\ub2e4. \uc5f0\ud55c \ubd84\ud64d\ube5b\uc744 \ub760\ub294 \uc0c8\ub3c4 \uc788\uace0, \ub354 \uc120\uba85\ud55c \ubd89\uc740\ube5b\uc5d0 \uac00\uae4c\uc6b4 \uc0c8\ub3c4 \uc788\ub2e4. \uc885\uacfc \ub098\uc774, \uba39\uc774\uc640 \uae43\ud138\uc758 \uc0c1\ud0dc \uac19\uc740 \uc5ec\ub7ec \uc870\uac74\uc774 \uad00\ub828\ub41c\ub2e4. \uadf8\ub7ec\ubbc0\ub85c \uc0c9\uc774 \uc605\uc740 \uc0c8 \ud55c \ub9c8\ub9ac\ub97c \ubcf4\uace0 \ubc14\ub85c \ubc30\uac00 \uace0\ud504\ub2e4\uac70\ub098 \uac74\uac15\uc5d0 \ubb38\uc81c\uac00 \uc788\ub2e4\uace0 \ud310\ub2e8\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc0ac\uc9c4\uc758 \ube5b\uacfc \ucd2c\uc601 \uc870\uac74\ub3c4 \uc2e4\uc81c\ub85c \ubcf4\uc774\ub294 \uc0c9\uc5d0 \uc601\ud5a5\uc744 \uc900\ub2e4. \uc0c9\uae54 \ud558\ub098\ub85c \uc0c8\uc758 \uc0c1\ud0dc\ub97c \ubaa8\ub450 \uc77d\uc744 \uc218 \uc788\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5b4\ub9b0 \uc0c8\uac00 \uc790\ub77c\uba74\uc11c \uc5b4\ub978\uc758 \uc0c9\uc744 \uac16\ucd94\ub294 \ub370\uc5d0\ub3c4 \uc2dc\uac04\uc774 \ud544\uc694\ud558\ub2e4. \uba39\uc774 \ud55c \ub07c\ub97c \uba39\uace0 \ubc14\ub85c \uc628\ubab8\uc774 \ubb3c\ub4dc\ub294 \ub9cc\ud654 \uac19\uc740 \ubcc0\ud654\ub294 \uc544\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uae43\ud138\uc5d0\ub294 \uadf8 \uc0c8\uac00 \uc0b4\uc544\uc628 \uc2dc\uac04\uc774 \uc870\uae08\uc529 \ubc18\uc601\ub418\uc5b4 \uc788\ub2e4. \uc774\ub807\uac8c \uc0dd\uac01\ud558\uba74 \ubd84\ud64d\uc0c9\uc740 \uc7a5\uc2dd \uc774\uc0c1\uc758 \uac83\uc774 \ub41c\ub2e4. \uc0dd\uae40\uc0c8\ub97c \uc54c\uc544\ubcf4\uac8c \ud558\ub294 \ud2b9\uc9d5\uc774\uba74\uc11c, \uc0c8\uac00 \uc0ac\ub294 \ud658\uacbd\uacfc \uba39\ub294 \uac83\uc744 \ub5a0\uc62c\ub9ac\uac8c \ud558\ub294 \ub2e8\uc11c\uc774\uae30\ub3c4 \ud558\ub2e4. \ud50c\ub77c\ubc0d\uace0\uac00 \ubb3c\uc5d0 \ubd80\ub9ac\ub97c \ub123\uace0 \uc6c0\uc9c1\uc774\ub294 \ubaa8\uc2b5\uc744 \ubcfc \ub54c\uac00 \uc788\ub2e4. \uae34 \ubaa9\uacfc \ub3c5\ud2b9\ud55c \ubd80\ub9ac\ub294 \uc595\uc740 \ubb3c\uc5d0\uc11c \uba39\uc774\ub97c \uc5bb\ub294 \ubc29\uc2dd\uacfc \uc5f0\uacb0\ub41c\ub2e4. \uc6b0\uc544\ud55c \uc790\uc138\ub9cc \ucde8\ud558\uace0 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2dd\uc0ac \uc911\uc77c \uc218 \uc788\ub2e4. \uba40\ub9ac\uc11c \ubc14\ub77c\ubcf4\uba74 \uc6b0\ub9ac\ub294 \ubd84\ud64d\ube5b \ubb34\ub9ac\ub77c\ub294 \ud070 \ud48d\uacbd\uc744 \ubcf8\ub2e4. \uc870\uae08 \ub354 \ub4e4\uc5ec\ub2e4\ubcf4\uba74 \ud55c \ub9c8\ub9ac\ub294 \uba39\uc774\ub97c \ucc3e\uace0, \ub2e4\ub978 \ud55c \ub9c8\ub9ac\ub294 \uae43\ud138\uc744 \uc190\uc9c8\ud55c\ub2e4. \ud3ec\uc2a4\ud130\uc5d0 \uadf8\ub824\uc9c4 \uc0c1\uc9d5\uacfc \ub2ec\ub9ac \uc2e4\uc81c \uc0c8\ub294 \uacc4\uc18d \uc0dd\ud65c\ud558\uace0 \uc788\ub2e4. \ud50c\ub77c\ubc0d\uace0\ub97c \uc88b\uc544\ud55c\ub2e4\uace0 \uc5b4\ub824\uc6b4 \uc0dd\ubb3c\ud559 \uc6a9\uc5b4\ub97c \uc678\uc6b8 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub2e4\ub9cc \uadf8 \ubd84\ud64d\uc0c9\uc774 \ucc98\uc74c\ubd80\ud130 \uc644\uc131\ub41c \ubb3c\uac10\ucc98\ub7fc \uc8fc\uc5b4\uc9c4 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\ub9cc \uc54c\uc544\ub3c4 \ucda9\ubd84\ud788 \uc7ac\ubbf8\uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ubd84\ud64d\uc0c9 \ud50c\ub77c\ubc0d\uace0\ub97c \ub9cc\ub098\uba74 \uae43\ud138\uc744 \ud55c \ubc88, \ubb3c\uc18d\uc758 \ubd80\ub9ac\ub97c \ud55c \ubc88 \ubcf4\uc790. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\uacfc \ub208\uc5d0 \uc798 \ub744\uc9c0 \uc54a\ub294 \uc2dd\uc0ac\uac00 \uac19\uc740 \uc774\uc57c\uae30 \uc548\uc5d0 \ub4e4\uc5b4 \uc788\ub2e4. \uc544\ub984\ub2e4\uc6b4 \uae43\ud138\uc5d0\ub3c4 \ub098\ub984\uc758 \uc2dd\ub2e8\uc774 \uc788\uc5c8\ub358 \uc148\uc774\ub2e4."}, {"id": "magnetic-penny", "title": "\ub2ee\uc740 \ub3d9\uc804\uc778\ub370 \uc65c \ud558\ub098\ub9cc \uc790\uc11d\uc5d0 \ubd99\uc744\uae4c", "summary": "\uac19\uc740 \uc0c9\uc758 \uc601\uad6d \ub3d9\uc804\ub3c4 \uc790\uc11d \uc55e\uc5d0\uc11c\ub294 \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc785\ub2c8\ub2e4. \ube44\ubc00\uc740 \uac89\ubaa8\uc2b5\ubcf4\ub2e4 \uc548\ucabd\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/magnetic-penny/index.html", "image": "media/magnetic-penny.jpg", "alt": "\uc791\uc740 \uc790\uc11d\uacfc \uad6c\ub9ac\ube5b \uc6d0\ubc18\uc73c\ub85c \uc7ac\ub8cc\uc5d0 \ub530\ub978 \ubc18\uc751\uc744 \uc5f0\uc0c1\uc2dc\ud0a4\ub294 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub2ee\uc740 \ub3d9\uc804\uc778\ub370 \uc65c \ud558\ub098\ub9cc \uc790\uc11d\uc5d0 \ubd99\uc744\uae4c \uad6c\ub9ac\ube5b \ud45c\uba74 \uc544\ub798\uc5d0 \uc228\uc5b4 \uc788\ub294 \ub2e4\ub978 \uc7ac\ub8cc \uac19\uc740 \uc0c9\uc758 \uc601\uad6d \ub3d9\uc804\ub3c4 \uc790\uc11d \uc55e\uc5d0\uc11c\ub294 \ub2e4\ub974\uac8c \uc6c0\uc9c1\uc785\ub2c8\ub2e4. \ube44\ubc00\uc740 \uac89\ubaa8\uc2b5\ubcf4\ub2e4 \uc548\ucabd\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \uc11c\ub78d\uc5d0\uc11c \ub3d9\uc804\uc744 \uaebc\ub0b4\ub2e4\uac00 \uc790\uc11d\uc5d0 \ud558\ub098\uac00 \ubd99\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud574 \ubcf4\uc790. \uc606\uc5d0 \uc788\ub358 \ub2e4\ub978 \ub3d9\uc804\uc740 \uadf8\ub300\ub85c\ub2e4. \ub458 \ub2e4 \uad6c\ub9ac\ube5b\uc778\ub370 \ubc18\uc751\uc740 \ub2e4\ub974\ub2e4. \uc601\uad6d\uc758 1\ud398\ub2c8\uc640 2\ud39c\uc2a4 \ub3d9\uc804\uc5d0\ub294 \uc2e4\uc81c\ub85c \uc774\ub7f0 \ucc28\uc774\uac00 \uc788\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \uc548\ub0b4\uc5d0 \ub530\ub974\uba74, \uac89\uc73c\ub85c \ube44\uc2b7\ud574 \ubcf4\uc5ec\ub3c4 \ub9cc\ub4e4\uc5b4\uc9c4 \uc2dc\uae30\uc5d0 \ub530\ub77c \uc548\ucabd \uc7ac\ub8cc\uac00 \ub2e4\ub974\uae30 \ub54c\ubb38\uc774\ub2e4. \uc608\uc804\uc758 \uc601\uad6d 1\ud398\ub2c8\uc640 2\ud39c\uc2a4 \ub3d9\uc804\uc740 \uad6c\ub9ac\uc640 \uc544\uc5f0, \uc8fc\uc11d\uc744 \uc11e\uc740 \uccad\ub3d9\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc740 1992\ub144 9\uc6d4\ubd80\ud130 \uad6c\ub9ac\ub97c \uc785\ud78c \uac15\ucca0\ub85c \uc7ac\ub8cc\ub97c \ubc14\uafb8\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \ud45c\uba74\uc740 \uacc4\uc18d \uad6c\ub9ac\ube5b\uc744 \ub760\uc9c0\ub9cc \uc18d\uc5d0\ub294 \uac15\ucca0\uc774 \ub4e4\uc5b4\uac04\ub2e4. \uc774 \uac15\ucca0 \ub54c\ubb38\uc5d0 \ub098\uc911\uc5d0 \ub9cc\ub4e0 \ub3d9\uc804\uc740 \uc790\uc11d\uc5d0 \ub04c\ub9ac\uace0, \uc774\uc804 \uccad\ub3d9 \ub3d9\uc804\uc740 \uadf8\ub807\uc9c0 \uc54a\ub2e4. \ub208\uc5d0 \ubcf4\uc774\ub294 \uc0c9\ub9cc\uc73c\ub85c\ub294 \ucc28\uc774\ub97c \ub193\uce58\uae30 \uc27d\ub2e4. \uc0c8 \uc7ac\ub8cc\uac00 \ub4e4\uc5b4\uac14\ub2e4\uace0 \ub3d9\uc804\uc774 \uac11\uc790\uae30 \uc804\ud600 \ub2e4\ub978 \ubb3c\uac74\ucc98\ub7fc \ubcf4\uc774\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc655\ub9bd\uc870\ud3d0\uad6d\uc758 \ud574\uc124\uc740 \ub450 \uc885\ub958\uc758 \uc0c9\uacfc \ubb34\uac8c, \uc9c0\ub984, \ub514\uc790\uc778\uc774 \uac19\uc558\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc775\uc219\ud55c \ubaa8\uc2b5\uc744 \uc774\uc5b4 \uac00\uba74\uc11c \ub0b4\ubd80\uc758 \uad6c\uc131\uc774 \ubc14\ub010 \uac83\uc774\ub2e4. \uc5ec\uae30\uc11c \uc7ac\ubbf8\uc788\ub294 \uc810\uc740 \uc790\uc11d\uc774 \uc6b0\ub9ac\uac00 \ubcf4\ub294 \uad6c\ub9ac\ube5b\uc5d0 \ubc18\uc751\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c\ub294 \ub370 \uc788\ub2e4. \uac89\uc73c\ub85c \ube44\uc2b7\ud55c \ubb3c\uac74\ub3c4 \ubb34\uc5c7\uc73c\ub85c \ub9cc\ub4e4\uc5c8\ub294\uc9c0\uc5d0 \ub530\ub77c \uacb0\uacfc\uac00 \ub2ec\ub77c\uc9c4\ub2e4. \uac19\uc740 \uc0c9\uc758 \uadf8\ub987\uc774 \ubaa8\ub450 \uac19\uc740 \uc7ac\ub8cc\ub294 \uc544\ub2c8\ub4ef, \ub3d9\uc804\uc758 \ud45c\uba74\uc0c9\ub3c4 \uc7ac\ub8cc \uc804\uccb4\ub97c \uc54c\ub824\uc8fc\ub294 \uc774\ub984\ud45c\ub294 \uc544\ub2c8\ub2e4. \uc587\uac8c \uc785\ud78c \uae08\uc18d\uacfc \uadf8 \uc548\ucabd\uc758 \uae08\uc18d\uc774 \uc11c\ub85c \ub2e4\ub978 \uc5ed\ud560\uc744 \ub9e1\uc744 \uc218 \uc788\ub2e4. \uc774 \uc774\uc57c\uae30\ub294 \uc601\uad6d\uc758 \ud574\ub2f9 \ub3d9\uc804\uc744 \ub2e4\ub8ec\ub2e4. \ub098\ub77c\uc640 \uc561\uba74\uc774 \ub2ec\ub77c\uc9c0\uba74 \uc7ac\ub8cc\ub3c4 \ub2ec\ub77c\uc9c0\ubbc0\ub85c, \ubaa8\ub4e0 \ub3d9\uc804\uc774 \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c \ubc18\uc751\ud55c\ub2e4\uace0 \ub113\ud600 \uc0dd\uac01\ud560 \ud544\uc694\ub294 \uc5c6\ub2e4. \ub3d9\uc804\uc5d0\ub294 \ucd08\uc0c1\uacfc \uc22b\uc790\ub9cc \uc788\ub294 \uac83 \uac19\uc9c0\ub9cc, \uc7ac\ub8cc\uc758 \uc5ed\uc0ac\ub3c4 \ub4e4\uc5b4 \uc788\ub2e4. \uc190\uc5d0 \uc954 \ub3c8\uc774 \uc5b8\uc81c \uc5b4\ub5a4 \uae08\uc18d\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\ub294\uc9c0 \uc0b4\ud53c\uba74 \ud45c\uba74\uc758 \uadf8\ub9bc\uacfc\ub294 \ub2e4\ub978 \uc774\uc57c\uae30\ub97c \ub9cc\ub098\uac8c \ub41c\ub2e4. \uc790\uc11d\uc5d0 \ubd99\uc740 \ub3d9\uc804\uacfc \ubd99\uc9c0 \uc54a\uc740 \ub3d9\uc804\uc744 \ub098\ub780\ud788 \ub5a0\uc62c\ub9ac\uba74, \ubcf4\uc774\ub294 \ubaa8\uc2b5\uacfc \uc2e4\uc81c \uad6c\uc131\uc774 \ub2e4\ub97c \uc218 \uc788\ub2e4\ub294 \ub9d0\uc774 \uaf64 \uad6c\uccb4\uc801\uc73c\ub85c \ub290\uaef4\uc9c4\ub2e4. \uc5b4\ub824\uc6b4 \uacf5\uc2dd\ubcf4\ub2e4 \uc190\ubc14\ub2e5\uc5d0 \uc62c\ub77c\uc624\ub294 \ubb3c\uac74\uc774 \uba3c\uc800 \uc774\ud574\ub97c \ub3d5\ub294\ub2e4. \ub2e4\uc74c\uc5d0 \uad6c\ub9ac\ube5b \ub3d9\uc804\uc744 \ubcf4\uac8c \ub41c\ub2e4\uba74 \uac89\uc758 \uc0c9\ub9cc\uc73c\ub85c \uc18d\uae4c\uc9c0 \ub2e4 \uc548\ub2e4\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc88b\uaca0\ub2e4. \uc775\uc219\ud55c \ud45c\uba74 \uc544\ub798\uc5d0\uc11c \uc7ac\ub8cc\ub294 \uc774\ubbf8 \ub2e4\ub978 \uc2dc\ub300\ub85c \ub118\uc5b4\uac14\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4."}, {"id": "red-panda-tail", "title": "\ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\ub294 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4", "summary": "\uc904\ubb34\ub2ac \uaf2c\ub9ac\ub294 \uadc0\uc5ec\uc6b4 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ub098\ubb34 \uc704\uc758 \uc0dd\ud65c\uacfc \ucd94\uc6b4 \ub0a0\uc528\uc5d0 \ubaa8\ub450 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Biology", "url": "stories/red-panda-tail/index.html", "image": "media/red-panda-tail.jpg", "alt": "\ub098\ubb47\uac00\uc9c0 \uc704\uc5d0\uc11c \ud48d\uc131\ud55c \uaf2c\ub9ac\ub97c \ubab8 \uac00\uae4c\uc774\uc5d0 \ub454 \ub808\uc11c\ud310\ub2e4\uc758 AI \uc124\uba85\uc6a9 \uc0bd\ud654", "text": "\ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\ub294 \ub2f4\uc694\uac00 \ub418\uae30\ub3c4 \ud55c\ub2e4 \ub098\ubb47\uac00\uc9c0 \uc704\uc5d0\uc11c \ubc1c\uacac\ud558\ub294 \uaf2c\ub9ac\uc758 \ub450 \uac00\uc9c0 \uc4f0\uc784 \uc904\ubb34\ub2ac \uaf2c\ub9ac\ub294 \uadc0\uc5ec\uc6b4 \uc7a5\uc2dd\ub9cc\uc740 \uc544\ub2d9\ub2c8\ub2e4. \ub098\ubb34 \uc704\uc758 \uc0dd\ud65c\uacfc \ucd94\uc6b4 \ub0a0\uc528\uc5d0 \ubaa8\ub450 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4. Biology \uacfc\ud559 \ub808\uc11c\ud310\ub2e4\ub97c \uadf8\ub824 \ubcf4\ub77c\uace0 \ud558\uba74 \ubab8\ubcf4\ub2e4 \uaf2c\ub9ac\ub97c \uba3c\uc800 \ub5a0\uc62c\ub9b4\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \ubd89\uc740 \ud138 \uc0ac\uc774\ub85c \uc605\uc740 \uace0\ub9ac\uac00 \ubc88\uac08\uc544 \uc774\uc5b4\uc9c0\ub294, \uae38\uace0 \ud48d\uc131\ud55c \uaf2c\ub9ac\ub2e4. \ub098\ubb47\uac00\uc9c0\uc5d0 \uc549\uc544 \uc788\uc73c\uba74 \ubab8 \ub4a4\ub85c \ud55c\ucc38 \ub298\uc5b4\uc9c0\uae30\ub3c4 \ud55c\ub2e4. \uc0ac\uc9c4\uc5d0\uc11c\ub294 \uadc0\uc5ec\uc6b4 \ubb34\ub2ac\ubd80\ud130 \ubcf4\uc774\uc9c0\ub9cc, \uadf8 \uaf2c\ub9ac\uc5d0\ub294 \uaf64 \uc2e4\uc6a9\uc801\uc778 \uc4f0\uc784\ub3c4 \uc788\ub2e4. \uc2a4\ubbf8\uc2a4\uc18c\ub2c8\uc5b8 \uad6d\ub9bd\ub3d9\ubb3c\uc6d0\uc740 \ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\uac00 \uade0\ud615\uc744 \uc7a1\uace0 \ucd94\uc704\uc640 \ubc14\ub78c\uc744 \uacac\ub514\ub294 \ub370 \ub3c4\uc6c0\uc744 \uc900\ub2e4\uace0 \uc18c\uac1c\ud55c\ub2e4. \ub808\uc11c\ud310\ub2e4\ub294 \ub098\ubb34\ub97c \uc798 \ud0c4\ub2e4. \ub098\ubb34\ub294 \ubab8\uc744 \uc228\uae30\uace0, \ud3ec\uc2dd\uc790\ub97c \ud53c\ud558\uace0, \uaca8\uc6b8\uc5d0 \ud587\ubcd5\uc744 \ucb10\ub294 \uc7a5\uc18c\uc774\uae30\ub3c4 \ud558\ub2e4. \ub545 \uc704\uc5d0\uc11c\ub9cc \uc0ac\ub294 \ub3d9\ubb3c\uacfc\ub294 \ub2e4\ub978 \uc0dd\ud65c\uc758 \uc790\ub9ac\uac00 \uc788\ub2e4. \uadf8 \uc790\ub9ac\uc5d0\uc11c \uae38\uace0 \ud48d\uc131\ud55c \uaf2c\ub9ac\ub294 \uade0\ud615\uc744 \uc720\uc9c0\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac00\uc9c0\uac00 \ubab8\uc744 \ubc1b\uccd0 \uc900\ub2e4\uace0 \ud574\uc11c \uac77\uace0 \ub3cc\uc544\uc11c\ub294 \uc77c\uc774 \uc800\uc808\ub85c \uc26c\uc6cc\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \ubab8 \ub4a4\uc758 \uae34 \ubd80\ubd84\ub3c4 \ub098\ubb34 \uc704 \uc0dd\ud65c\uc758 \ud55c\ubaab\uc744 \ub9e1\ub294\ub2e4. \ub098\ubb34\ub97c \ub0b4\ub824\uc624\ub294 \ubaa8\uc2b5\ub3c4 \ud765\ubbf8\ub86d\ub2e4. \ub3d9\ubb3c\uc6d0\uc740 \uc720\uc5f0\ud55c \ubc1c\ubaa9 \uad6c\uc870 \ub355\ubd84\uc5d0 \uba38\ub9ac\ub97c \uc544\ub798\ub85c \ud5a5\ud55c \ucc44 \ub098\ubb34\uc904\uae30\ub97c \ub0b4\ub824\uc62c \uc218 \uc788\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uaf2c\ub9ac\ub9cc \ub530\ub85c \ub5bc\uc5b4 \ubcf4\uae30\ubcf4\ub2e4 \ubab8 \uc804\uccb4\uc758 \uc6c0\uc9c1\uc784\uacfc \ud568\uaed8 \ubcf4\uba74 \ub354 \uc7ac\ubbf8\uc788\ub2e4. \ub808\uc11c\ud310\ub2e4\uac00 \uc0ac\ub294 \uacf3\uc5d0\ub294 \ud788\ub9d0\ub77c\uc57c\ub97c \ube44\ub86f\ud55c \ub192\uc740 \uc0b0\uc9c0\uc758 \uc232\uc774 \ud3ec\ud568\ub41c\ub2e4. \uadf8\uacf3\uc5d0\uc11c \ud48d\uc131\ud55c \ud138\uc740 \ubcf4\uae30 \uc88b\uc740 \uc678\ud22c \uc774\uc0c1\uc758 \uc758\ubbf8\ub97c \uac16\ub294\ub2e4. \ubab8\uc5d0\ub294 \ubd80\ub4dc\ub7fd\uace0 \ucd18\ucd18\ud55c \uc18d\ud138\uc774 \uc788\uace0, \uae34 \uaf2c\ub9ac\ub294 \uc2ec\ud55c \ucd94\uc704\uc640 \ubc14\ub78c\uc73c\ub85c\ubd80\ud130 \ubab8\uc744 \ubcf4\ud638\ud558\ub294 \ub370 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \ubc1c\ubc14\ub2e5\ub3c4 \ud138\ub85c \ub36e\uc5ec \uc788\ub2e4. \ud654\uba74\uc5d0\uc11c\ub294 \uc791\uc740 \ub3d9\ubb3c\uc774\uc9c0\ub9cc, \ucd94\uc6b4 \uacf3\uc758 \uc0dd\ud65c\uc5d0 \ud544\uc694\ud55c \ucc28\ub9bc\uc744 \ud558\uace0 \uc788\ub294 \uc148\uc774\ub2e4. \uaf2c\ub9ac\ub97c \ubab8 \uac00\uae4c\uc774\uc5d0 \ub454 \ubaa8\uc2b5\uc744 \ubcf4\uba74 \ub2f4\uc694\ub098 \ubaa9\ub3c4\ub9ac\uac00 \ub5a0\uc624\ub978\ub2e4. \ubb3c\ub860 \uc0ac\ub78c\uc774 \uc9e0 \ubb3c\uac74\uc744 \ub450\ub978 \uac83\uc740 \uc544\ub2c8\ub2e4. \ub530\ub73b\ud55c \ubb3c\uac74\uc5d0 \ube57\ub300\uc5b4 \ubcf4\uba74, \uae34 \ud138\uc774 \uc65c \uc0dd\ud65c\uc5d0 \uc4f8\ubaa8\uac00 \uc788\ub294\uc9c0 \uc870\uae08 \uce5c\uc219\ud558\uac8c \ub290\uaef4\uc9c4\ub2e4. \ub808\uc11c\ud310\ub2e4\uc758 \uaf2c\ub9ac\uc5d0\ub294 \ubd89\uc740\uc0c9\uacfc \uc605\uc740 \uc0c9\uc758 \uace0\ub9ac \ubb34\ub2ac\uac00 \ubc88\uac08\uc544 \ub098\ud0c0\ub09c\ub2e4. \uadf8 \ubb34\ub2ac\ub97c \uc54c\uc544\ubcf4\ub294 \uc990\uac70\uc6c0\uacfc \uaf2c\ub9ac\uc758 \uc4f0\uc784\uc744 \uc544\ub294 \uc990\uac70\uc6c0\uc740 \uc870\uae08 \ub2e4\ub974\ub2e4. \uc774\ub984\uacfc \uc0dd\uae40\uc0c8\ub97c \ub9de\ud78c \ub2e4\uc74c\uc5d0\ub3c4 \uad6c\uacbd\uc740 \uacc4\uc18d\ub41c\ub2e4. \uac00\uc9c0 \uc704\uc5d0\uc11c \ubc29\ud5a5\uc744 \ubc14\uafc0 \ub54c \uaf2c\ub9ac\uac00 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0, \uc26c\ub294 \ub3d9\uc548\uc5d0\ub294 \ubab8\uacfc \uc5bc\ub9c8\ub098 \uac00\uae4c\uc6b4\uc9c0 \uc0b4\ud3b4\ubcfc \uc218 \uc788\ub2e4. \ub2e4\uc74c\uc5d0 \ub808\uc11c\ud310\ub2e4 \uc0ac\uc9c4\uc744 \ubcf8\ub2e4\uba74 \uc5bc\uad74\ub9cc \ud655\ub300\ud558\uc9c0 \ub9d0\uace0 \uaf2c\ub9ac\uae4c\uc9c0 \ub4e4\uc5b4\uc628 \uc7a5\uba74\ub3c4 \uace8\ub77c \ubcf4\uc790. \uc791\uc740 \uc5bc\uad74 \ub4a4\ub85c \ub298\uc5b4\uc9c4 \uae34 \ubd80\ubd84\uc5d0, \ub098\ubb34\ub97c \ud0c0\uace0 \ucd94\uc704\ub97c \uacac\ub514\ub294 \uc0dd\ud65c\uc774 \ud568\uaed8 \ub2ec\ub824 \uc788\ub2e4."}, {"id": "star-map-carved-again", "title": "\ubcc4\uc9c0\ub3c4\ub97c \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uae34 \uc774\uc720", "summary": "\uac19\uc740 \ubcc4\uc9c0\ub3c4\ub97c \uc0c8 \ub3cc\uc5d0 \uc62e\uae34 \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Physics", "url": "stories/star-map-carved-again/index.html", "image": "media/star-map-carved-again.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\ubcc4\uc9c0\ub3c4\ub97c \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uae34 \uc774\uc720 \ub0a1\uc544 \uac00\ub294 \uae30\ub85d\uc744 \uc62e\uaca8 \ub450\ub294 \ubc29\ubc95 \uac19\uc740 \ubcc4\uc9c0\ub3c4\ub97c \uc0c8 \ub3cc\uc5d0 \uc62e\uae34 \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d\uc758 \uc0ac\uc5f0\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Physics \uacfc\ud559 \ubcc4\uc9c0\ub3c4\ub97c \uc0dd\uac01\ud558\uba74 \uc885\uc774\ub098 \ud654\uba74\ubd80\ud130 \ub5a0\uc624\ub978\ub2e4. \uadf8\ub7f0\ub370 \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc5d0\ub294 \ub3cc\uc5d0 \uc0c8\uae34 \ubcc4\uc9c0\ub3c4\uac00 \uc788\ub2e4. \uc774\ub984\uc740 \uae38\ub2e4. \ubcf5\uac01\ucc9c\uc0c1\uc5f4\ucc28\ubd84\uc57c\uc9c0\ub3c4\uac01\uc11d. \uc624\ub298\uc740 \uadf8 \uc774\ub984\uc744 \ub2e4 \uc678\uc6b0\uc9c0 \ub9d0\uace0 \ub9e8 \uc55e\uc758 \ubcf5\uac01\uc5d0\ub9cc \ub208\uae38\uc744 \uc8fc\uc5b4 \ubcf4\uc790. \uc774 \ubb3c\uac74\uc758 \uc7ac\ubbf8\ub294 \ubcc4\uc744 \uba87 \uac1c \uadf8\ub838\ub290\ub0d0\ubcf4\ub2e4 \uc65c \uac19\uc740 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uacbc\ub290\ub0d0\uc5d0 \uc788\ub2e4. \ud558\ub298\uc744 \uae30\ub85d\ud55c \ub3cc\uc5d0\ub3c4 \uc2dc\uac04\uc774 \ud758\ub800\ub358 \uac83\uc774\ub2e4. \ubc15\ubb3c\uad00\uc740 1395\ub144\uc5d0 \ub3cc\uc5d0 \uc0c8\uae34 \ucc9c\ubb38\ub3c4 \uac01\uc11d\uc774 \uc138\uc6d4\uc774 \ud750\ub974\uba70 \ud6fc\uc190\ub418\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub798\uc11c 1687\ub144\uc5d0 \uadf8 \ub0b4\uc6a9\uc744 \ub2e4\ub978 \ub3cc\uc5d0 \ub2e4\uc2dc \uc0c8\uacbc\ub2e4. \uc774\ub54c \ub9cc\ub4e4\uc5b4\uc9c4 \uac83\uc774 \uc0ac\uc9c4\uc758 \ubcf5\uac01\ubcf8\uc774\ub2e4. \uc624\ub798 \ubcf4\uad00\ud558\ub824\uace0 \ub2e8\ub2e8\ud55c \uc7ac\ub8cc\ub97c \uace8\ub77c\ub3c4 \uae30\ub85d\uc774 \uc800\uc808\ub85c \uc601\uc6d0\ud574\uc9c0\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc5ec\uae30\uc11c\ub294 \ub0b4\uc6a9\uc774 \uc0ac\ub77c\uc9c0\uae30 \uc804\uc5d0 \uc0c8\ub85c\uc6b4 \ub3cc\ub85c \uc62e\uae30\ub294 \ubc29\ubc95\uc744 \ud0dd\ud588\ub2e4. \uc190\uc0c1\ub41c \uc885\uc774\ub97c \ub2e4\uc2dc \ubca0\ub07c\ub294 \uc77c\uacfc \ub098\ub780\ud788 \uc0dd\uac01\ud574 \ubcfc \uc218 \uc788\ub294 \ub300\ubaa9\uc774\ub2e4. \uc0c8 \ub3cc\uc5d0 \uc0c8\uacbc\ub2e4\uace0 \uc0c8 \ubcc4\uc790\ub9ac\ub97c \ubc1c\uacac\ud588\ub2e4\ub294 \ub73b\uc740 \uc544\ub2c8\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc758 \uc911\uc2ec\uc740 \uae30\uc874 \ub0b4\uc6a9\uc744 \ub2e4\uc2dc \uc0c8\uaca8 \ubcf4\uc874\ud588\ub2e4\ub294 \ub370 \uc788\ub2e4. \uae30\ub85d\uc758 \ub0b4\uc6a9\uacfc \uadf8 \ub0b4\uc6a9\uc744 \ub2f4\uc740 \ubb3c\uac74\uc758 \uc81c\uc791 \uc2dc\uc810\uc744 \ub098\ub204\uc5b4 \ubcfc \ud544\uc694\uac00 \uc788\ub2e4. \uc0ac\uc9c4\uc758 \ub3cc\uc774 1687\ub144 \uac83\uc774\ub77c\ub294 \uc0ac\uc2e4\uacfc \uc6d0\ub798 \ucc9c\ubb38\ub3c4\uac00 1395\ub144\uc5d0 \uc0c8\uaca8\uc84c\ub2e4\ub294 \uc0ac\uc2e4\uc740 \uadf8\ub798\uc11c \ud568\uaed8 \ub4f1\uc7a5\ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ub450 \ub0a0\uc9dc\uac00 \uc2e4\uc218\ub85c \uc801\ud78c \uac83\uc774 \uc544\ub2c8\ub77c, \uc62e\uaca8 \ub0a8\uae30\ub294 \uacfc\uc815\uc758 \uc55e\ub4a4\ub97c \uc54c\ub824 \uc8fc\ub294 \uac83\uc774\ub2e4. \ubcf5\uac01\ubcf8\uc740 \ucc98\uc74c\uc5d0 \ucc3d\ub355\uad81 \ubc16 \uad00\uc0c1\uac10\uc5d0 \ubcf4\uad00\ub418\uc5c8\ub2e4. \uc774\ud6c4 \uc601\uc870 \ub54c \uc6d0\ub798\uc758 \ud0dc\uc870\ubcf8\uacfc \ud568\uaed8 \ucc3d\ub355\uad81 \ud760\uacbd\uac01\uc73c\ub85c \uc62e\uacbc\ub2e4\uace0 \ubc15\ubb3c\uad00\uc740 \uc18c\uac1c\ud55c\ub2e4. \ub450 \ub3cc\uc740 \ub0b4\uc6a9\uc73c\ub85c \uc774\uc5b4\uc9c0\uba74\uc11c\ub3c4 \uac01\uac01 \ubcf4\uad00 \uc774\ub825\uc744 \uc9c0\ub2cc \ubb3c\uac74\uc774\ub2e4. \uc694\uc998 \ud30c\uc77c\uc744 \ubcf5\uc0ac\ud574 \ub2e4\ub978 \uacf3\uc5d0 \uc800\uc7a5\ud558\ub294 \uc77c\uc774 \ub5a0\uc624\ub97c \uc218\ub3c4 \uc788\ub2e4. \ubc29\ubc95\uc740 \uc544\uc8fc \ub2e4\ub974\uc9c0\ub9cc \uae30\ub85d\uc744 \uc783\uc9c0 \uc54a\uc73c\ub824\ub294 \uc120\ud0dd\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uac00\uae4c\uc774 \ub290\uaef4\uc9c4\ub2e4. \uc774 \ubcc4\uc9c0\ub3c4\ub294 \ud558\ub298\uc744 \uad00\ucc30\ud558\ub358 \uc0ac\ub78c\ub4e4\ubfd0 \uc544\ub2c8\ub77c, \uadf8 \uae30\ub85d\uc744 \ub2e4\uc74c \uc2dc\ub300\ub85c \uc804\ud558\ub824\ub358 \uc0ac\ub78c\ub4e4\uc758 \uc77c\ub3c4 \ubcf4\uc5ec \uc900\ub2e4."}, {"id": "water-clock-floating-turtle", "title": "\uc774 \uac70\ubd81\uc774\ub294 \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc62c\ub790\ub2e4", "summary": "\ub124 \ub0a0\uac1c\uac00 \ub2ec\ub9b0 \uc790\uaca9\ub8e8 \ubd80\ud45c\uc5d0\uc11c \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4.", "category": "science", "category_title": "Science", "subcategory": "Engineering", "url": "stories/water-clock-floating-turtle/index.html", "image": "media/water-clock-floating-turtle.jpg", "alt": "\uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc774 \uc81c\uacf5\ud55c \uc790\uaca9\ub8e8 \ubd80\ud45c \uc18c\uc7a5\ud488 \uc0ac\uc9c4", "text": "\uc774 \uac70\ubd81\uc774\ub294 \ubb3c\uc774 \ucc28\uba74 \ub5a0\uc62c\ub790\ub2e4 \uc790\uaca9\ub8e8\uc5d0\uc11c \uc2dc\uac04\uc744 \uc804\ud558\ub358 \ub465\uadfc \ubd80\ud488 \ub124 \ub0a0\uac1c\uac00 \ub2ec\ub9b0 \uc790\uaca9\ub8e8 \ubd80\ud45c\uc5d0\uc11c \ubb3c\uc758 \uc6c0\uc9c1\uc784\uc744 \uc77d\uc2b5\ub2c8\ub2e4. Engineering \uacfc\ud559 \ub465\uadfc \ubab8\uccb4\uc5d0 \ub0a0\uac1c \uac19\uc740 \ubd80\ubd84\uc774 \ub124 \uac1c \ub2ec\ub838\ub2e4. \uac70\ubd81\uc774\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud558\uace0 \ub69c\uaed1\ucc98\ub7fc \ubcf4\uc774\uae30\ub3c4 \ud55c\ub2e4. \uad6d\ub9bd\uace0\uad81\ubc15\ubb3c\uad00\uc740 \uc774\uac83\uc744 \uc790\uaca9\ub8e8\uc758 \ubd80\ud45c\ub77c\uace0 \uc18c\uac1c\ud55c\ub2e4. \uc2dc\uacc4 \uc804\uccb4\uac00 \uc544\ub2c8\ub77c \uadf8 \uc548\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub358 \ubd80\ud488\uc774\ub2e4. \uac70\ubd81\uc774\ub97c \ub2ee\uc558\ub2e4\uace0 \ubd80\uad6c\ub77c\ub294 \uc774\ub984\uc73c\ub85c\ub3c4 \ubd88\ub800\ub2e4\uace0 \ud55c\ub2e4. \uce5c\uadfc\ud55c \ubcc4\uba85\uc744 \uc54c\uace0 \ub098\uba74 \ub465\uadfc \ubab8\uccb4\uc640 \uc606\uc73c\ub85c \ubed7\uc740 \ubd80\ubd84\uc744 \ub2e4\uc2dc \ubcf4\uac8c \ub41c\ub2e4. \uc774 \ubb3c\uac74\uc5d0\uc11c\ub294 \ubb3c \uc704\uc5d0\uc11c \uc6c0\uc9c1\uc774\ub294 \uc77c\uc774 \uc774\uc57c\uae30\uc758 \uc911\uc2ec\uc774\ub2e4. \ubc15\ubb3c\uad00 \uc124\uba85\uc5d0 \ub530\ub974\uba74 \ubd80\ud45c\ub294 \uc587\uc740 \uad6c\ub9ac\ud310\uc744 \ubd99\uc5ec \ub9cc\ub4e4\uc5c8\ub2e4. \uc6d0\ud615 \ubab8\uccb4\uc758 \uc0ac\ubc29\uc5d0\ub294 \ub0a0\uac1c\uac00 \ud558\ub098\uc529 \ub2ec\ub9ac\uace0, \ud55c\ucabd \uba74\uc758 \uac00\uc6b4\ub370\uc5d0\ub294 \uae38\ucb49\ud55c \uc5f0\uacb0\uad6c\uac00 \uc788\ub2e4. \uc5ec\uae30\uc5d0 \uc7a3\ub300\ub97c \uaf42\uc558\ub2e4. \uc2dc\uacc4\ub97c \ub5a0\uc62c\ub9ac\uba74 \ubc14\ub298\ubd80\ud130 \ucc3e\uac8c \ub418\uc9c0\ub9cc \uc774 \ubd80\ud488\uc5d0\uc11c\ub294 \uc7a3\ub300\uac00 \ub4f1\uc7a5\ud55c\ub2e4. \uac00\uc6b4\ub370\uc758 \uc791\uc740 \uc790\ub9ac\uac00 \ub2e4\ub978 \ubb3c\uac74\uacfc \uc774\uc5b4\uc9c0\ub294 \uc9c0\uc810\uc774\ub77c\ub294 \uac83\uc744 \uc54c\uace0 \ubcf4\uba74, \ud3c9\ubc94\ud55c \uad6c\uba4d \uac19\uc740 \ubd80\ubd84\uc5d0\ub3c4 \ub208\uae38\uc774 \uac04\ub2e4. \ubd80\ud45c\ub294 \ubb3c\uc744 \ubc1b\ub294 \ud1b5\uc778 \uc218\uc218\ud638 \uc548\uc5d0 \ub4e4\uc5b4\uac00\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\ub2e4. \ubc15\ubb3c\uad00\uc740 \uadf8 \ud06c\uae30\ub97c \uc218\uc218\ud638\uc758 \uc18d\ub458\ub808\uc5d0 \ub9de\ucd94\uc5c8\ub2e4\uace0 \uc124\uba85\ud55c\ub2e4. \uadf8\ub987\uacfc \ubd80\ud45c\uac00 \uc544\ubb34\ub807\uac8c\ub098 \ub9cc\ub098\ub294 \uad6c\uc870\uac00 \uc544\ub2c8\uc5c8\ub358 \uac83\uc774\ub2e4. \uc218\uc218\ud638\uc5d0 \ubb3c\uc774 \ucc28\uba74 \ubd80\ud45c\uac00 \ub5a0\uc624\ub974\uace0 \uc7a3\ub300\ub3c4 \ud568\uaed8 \uc62c\ub77c\uac04\ub2e4. \uc624\ub298 \uc774 \uae00\uc5d0\uc11c \uc54c\uc544\ub458 \uc6c0\uc9c1\uc784\uc740 \uc774\uac83\uc774\uba74 \ucda9\ubd84\ud558\ub2e4. \ubb3c\uc774 \ub192\uc544\uc9c0\ub294 \ubcc0\ud654\uac00 \ub2e4\ub978 \ubd80\ud488\uc758 \uc704\uce58 \ubcc0\ud654\ub85c \uc774\uc5b4\uc9c4\ub2e4. \ubcf5\uc7a1\ud55c \uc790\ub3d9 \uc7a5\uce58\uc758 \uc124\uba85\ub3c4 \uc774\ub807\uac8c \uc791\uc740 \uc6c0\uc9c1\uc784 \ud558\ub098\uc5d0\uc11c \uc2dc\uc791\ud560 \uc218 \uc788\ub2e4. \uc774 \ubd80\ud45c\ub9cc\uc73c\ub85c \uc790\uaca9\ub8e8 \uc804\uccb4\uc758 \uc791\ub3d9\uc744 \ubaa8\ub450 \uc124\uba85\ud560 \uc218\ub294 \uc5c6\ub2e4. \uc885\uc774 \uc6b8\ub9ac\ub294 \uacfc\uc815\uc774\ub098 \uc2dc\uac04\uc744 \uc54c\ub9ac\ub294 \uc7a5\uce58\uc5d0\ub294 \ub2e4\ub978 \ubd80\ud488\ub3c4 \ud544\uc694\ud558\ub2e4. \ub2e4\ub9cc \uc0ac\uc9c4 \uc18d \ub465\uadfc \ubb3c\uac74\uc774 \ud63c\uc790 \ub5a0 \uc788\ub294 \uc7a5\uc2dd\ud488\uc774 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc740 \ubd84\uba85\ud574\uc9c4\ub2e4. \uac00\uc6b4\ub370\uc758 \uc5f0\uacb0\uad6c, \uc606\uc73c\ub85c \ub098\uc628 \ub124 \ub0a0\uac1c, \ud1b5\uc5d0 \ub4e4\uc5b4\uac08 \ud06c\uae30. \uadf8\ub7f0 \ud2b9\uc9d5\uc744 \ucc28\ub840\ub85c \ubcf4\uba74 \ubd80\ud488\uc774 \uc65c \uadf8 \ubaa8\uc591\uc778\uc9c0 \uad81\uae08\ud574\uc9c4\ub2e4. \uc2dc\uac04\uc744 \uc7ac\ub294 \ubb3c\uac74 \uc548\uc5d0\ub3c4 \ubb3c \uc704\ub85c \ucc9c\ucc9c\ud788 \ub5a0\uc624\ub974\ub294 \uac70\ubd81\uc774 \uac19\uc740 \ubd80\ud488\uc774 \uc788\uc5c8\ub2e4."}];
